	#[test]
	fn cached_error_tree_matches_uncached_verdicts_for_both_callers() {
		// `enclosing_block_boundaries` rejects any file-level error;
		// `block_range_at` rejects only errors inside the resolved subtree. Both
		// now read that verdict off one shared cached tree, so each must still
		// reach the answer it reached from its own cold parse.
		let code = "function ok() {\n  a();\n}\nfunction broken( {\n";

		clear_parse_cache();
		let cold_boundaries = boundaries(code, "x.ts", &[(1, 1)]);
		clear_parse_cache();
		let cold_range = resolve(code, "x.ts", 1);
		assert_eq!(cold_boundaries, None, "a file-level error disables boundaries");

		clear_parse_cache();
		for pass in 0..2 {
			assert_eq!(boundaries(code, "x.ts", &[(1, 1)]), cold_boundaries, "pass {pass}");
			assert_eq!(resolve(code, "x.ts", 1), cold_range, "pass {pass}");
		}
	}

	#[test]
	fn keys_evicted_past_the_cache_bound_still_answer_correctly() {
		// `f{i}` with `i + 1` body lines closes on line `i + 3`, so the expected
		// boundary for a window on line 1 is a function of `i` — a neighbouring
		// entry's tree would produce a visibly wrong answer.
		let sources: Vec<String> = (0..MAX_ENTRIES * 2)
			.map(|i| format!("function f{i}() {{\n{}}}\n", "  step();\n".repeat(i + 1)))
			.collect();
		let expect = |i: usize| Some(vec![i as u32 + 3]);

		clear_parse_cache();
		for (i, source) in sources.iter().enumerate() {
			assert_eq!(boundaries(source, "x.ts", &[(1, 1)]), expect(i), "cold pass {i}");
		}

		// Source 0 was evicted well before the loop ended (twice `MAX_ENTRIES`
		// distinct sources went through a cache holding `MAX_ENTRIES`), so this
		// re-parses. It must answer correctly rather than serve a survivor.
		assert_eq!(boundaries(&sources[0], "x.ts", &[(1, 1)]), expect(0), "evicted key");
		// And the tail, still resident, must not have been disturbed.
		let last = sources.len() - 1;
		assert_eq!(boundaries(&sources[last], "x.ts", &[(1, 1)]), expect(last), "resident key");
	}

	// ── prune equivalence ─────────────────────────────────────────────────────
	//
	// `collect_boundaries` skips subtrees whose raw line span holds no visible
	// line. That is argued to be exact, but the output feeds hashline block
	// resolution, so a silently dropped line corrupts edits rather than just
	// degrading display. The argument is therefore backed by a differential
	// against the pre-prune traversal over the repository's own sources, not by
	// hand-written expectations.

	use std::path::{Path, PathBuf};

	/// The pre-prune traversal, kept verbatim as the differential reference: it
	/// visits every node in the tree.
	fn collect_boundaries_unpruned(
		cursor: &mut TreeCursor<'_>,
		merged: &[LineRange],
		out: &mut BTreeSet<u32>,
	) {
		let node = cursor.node();
		if node.is_named() && node.parent().is_some() {
			let start = node_start_line(node);
			let end = node_content_end_line(node);
			if end > start {
				let start_visible = is_visible(merged, start);
				let end_visible = is_visible(merged, end);
				if start_visible && !end_visible {
					out.insert(end);
				} else if end_visible && !start_visible {
					out.insert(start);
				}
			}
		}
		if cursor.goto_first_child() {
			loop {
				collect_boundaries_unpruned(cursor, merged, out);
				if !cursor.goto_next_sibling() {
					break;
				}
			}
			cursor.goto_parent();
		}
	}

	/// [`enclosing_block_boundaries`] with the unpruned walk substituted in.
	/// Every early return is reproduced in the same order, so the differential
	/// also covers the empty-code, empty-range, unresolved-language and
	/// `has_error` paths.
	fn boundaries_unpruned(code: &str, path: &str, ranges: &[(u32, u32)]) -> Option<Vec<u32>> {
		let merged = normalize_ranges(
			ranges
				.iter()
				.map(|&(start_line, end_line)| LineRange { start_line, end_line })
				.collect(),
		);
		if code.is_empty() || merged.is_empty() {
			return Some(Vec::new());
		}
		let language = resolve_language(None, Some(path))?;
		let tree = parse_cached(code, language, None).expect("grammar loads")?;
		let root = tree.root_node();
		if root.has_error() {
			return None;
		}
		let mut boundaries = BTreeSet::new();
		let mut cursor = root.walk();
		collect_boundaries_unpruned(&mut cursor, &merged, &mut boundaries);
		Some(boundaries.into_iter().collect())
	}

	/// Range shapes exercised per file: head, middle, tail, a single interior
	/// line, three disjoint windows, the whole file visible, a window entirely
	/// past EOF, and the empty range list.
	fn window_shapes(lines: u32) -> Vec<Vec<(u32, u32)>> {
		let last = lines.max(1);
		let mid = (lines / 2).max(1);
		let tail_start = lines.saturating_sub(20).max(1);
		vec![
			vec![(1, 40.min(last))],
			vec![(mid, (mid + 20).min(last))],
			vec![(tail_start, last)],
			vec![(mid, mid)],
			vec![(1, 5.min(last)), (mid, (mid + 5).min(last)), (tail_start, last)],
			vec![(1, last)],
			vec![(last + 10, last + 20)],
			vec![],
		]
	}

	/// Compare pruned against unpruned output for exact `Option<Vec<u32>>`
	/// equality across every shape. Returns (comparisons, `None` verdicts).
	fn assert_prune_equivalent(code: &str, path: &str) -> (usize, usize) {
		let lines = code.split('\n').count() as u32;
		let mut comparisons = 0;
		let mut none_verdicts = 0;
		for shape in window_shapes(lines) {
			let pruned = boundaries(code, path, &shape);
			let unpruned = boundaries_unpruned(code, path, &shape);
			assert_eq!(pruned, unpruned, "{path} ranges={shape:?}");
			if pruned.is_none() {
				none_verdicts += 1;
			}
			comparisons += 1;
		}
		(comparisons, none_verdicts)
	}

	/// Repository `.ts` / `.py` / `.rs` sources, sorted for determinism. With a
	/// budget, files are taken on a stride so the sample spans the whole tree
	/// instead of one directory, skipping anything over 64 KiB.
	async fn repo_files(byte_budget: Option<usize>) -> Vec<PathBuf> {
		let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
		let opts = pi_walker::walk::Options { gitignore: true, skip_git: true, ..Default::default() };
		let walked =
			pi_walker::walk::collect(&pi_walker::Fs::native(), &root, &opts, false, |_, entry| {
				let wanted = entry.file_type == pi_walker::FileType::File
					&& matches!(
						entry
							.rel_path()
							.extension()
							.and_then(std::ffi::OsStr::to_str),
						Some("ts" | "py" | "rs")
					);
				if wanted {
					pi_walker::walk::Action::Continue
				} else {
					pi_walker::walk::Action::Skip
				}
			})
			.await
			.expect("repository should walk");
		let mut files: Vec<PathBuf> = walked
			.iter()
			.map(|entry| root.join(entry.rel_path()))
			.collect();
		files.sort();
		let Some(budget) = byte_budget else {
			return files;
		};
		let stride = (files.len() / 240).max(1);
		let mut picked = Vec::new();
		let mut used = 0;
		for path in files.iter().step_by(stride) {
			let Ok(meta) = std::fs::metadata(path) else {
				continue;
			};
			let len = meta.len() as usize;
			if len == 0 || len > 64 * 1024 {
				continue;
			}
			if used + len > budget {
				// Later, smaller sources can still broaden the sample within the
				// same budget.
				continue;
			}
			used += len;
			picked.push(path.clone());
		}
		picked
	}

	fn sweep_corpus(files: &[PathBuf]) -> (usize, usize) {
		let mut comparisons = 0;
		let mut none_verdicts = 0;
		for path in files {
			let Ok(code) = std::fs::read_to_string(path) else {
				continue; // non-UTF-8 source; nothing to compare
			};
			let (n, nones) = assert_prune_equivalent(&code, path.to_str().expect("utf-8 path"));
			comparisons += n;
			none_verdicts += nones;
		}
		(comparisons, none_verdicts)
	}

	#[tokio::test(flavor = "multi_thread")]
	async fn pruned_walk_matches_unpruned_on_repo_corpus_sample() {
		// Sandboxed runners (bazel test) stage only this crate's declared inputs,
		// so the repository corpus this sweep samples is absent (or a symlink
		// farm the walker cannot see through). Both surface as an empty scan —
		// skip then. Whenever the scan finds anything, the evidence assert below
		// still guards against a broken/undersized sample.
		let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
		if !root.join("packages").is_dir() {
			eprintln!("skipping: repository corpus unavailable at {}", root.display());
			return;
		}
		let files = repo_files(Some(768 * 1024)).await;
		if files.is_empty() {
			eprintln!("skipping: repository corpus scan found no sources at {}", root.display());
			return;
		}
		assert!(files.len() > 40, "corpus sample too small to be evidence: {}", files.len());
		let (comparisons, _) = sweep_corpus(&files);
		assert!(comparisons > 300, "expected a broad sweep, got {comparisons} comparisons");
	}

	#[tokio::test(flavor = "multi_thread")]
	#[ignore = "full repository sweep; run with `cargo nextest run --release -p pi-ast \
	            --run-ignored ignored-only`"]
	async fn pruned_walk_matches_unpruned_on_full_repo_corpus() {
		let files = repo_files(None).await;
		assert!(files.len() > 3000, "expected the whole corpus, got {}", files.len());
		let (comparisons, _) = sweep_corpus(&files);
		println!("full corpus: {} files, {comparisons} comparisons", files.len());
	}

	#[test]
	fn pruned_walk_matches_unpruned_on_error_and_degenerate_inputs() {
		// The corpus is mostly valid source, so pin the `has_error`,
		// empty-code, empty-range and unresolved-language paths explicitly.
		let cases: &[(&str, &str)] = &[
			("", "x.ts"),
			("\n", "x.ts"),
			("\n\n\n", "x.py"),
			("function broken() {\n  if (y) {\n", "b.ts"),
			("def broken(:\n    pass\n", "b.py"),
			("fn broken( {\n", "b.rs"),
			("function ok() {\n  a();\n}\nfunction broken( {\n", "x.ts"),
			(TS_FN, "x.unknownext"),
		];
		let mut none_verdicts = 0;
		for (code, path) in cases {
			let (_, nones) = assert_prune_equivalent(code, path);
			none_verdicts += nones;
		}
		assert!(none_verdicts > 0, "error / unknown-language cases must exercise the None path");
	}

	/// Large file with a five-level nest in the middle, so a window on the
	/// opening lines has a long chain of closers to surface and the prune has
	/// most of the file to skip. Returns the source and the 1-indexed line of
	/// `function deep() {`.
	fn nested_fixture(pad: usize) -> (String, u32) {
		use std::fmt::Write as _;

		let mut code = String::new();
		for i in 0..pad {
			writeln!(code, "export const pad{i} = {i};").expect("write to String");
		}
		let nest = pad as u32 + 1;
		code.push_str("function deep() {\n");
		code.push_str("\tif (a) {\n");
		code.push_str("\t\twhile (b) {\n");
		code.push_str("\t\t\tfor (;;) {\n");
		code.push_str("\t\t\t\tif (c) {\n");
		code.push_str("\t\t\t\t\tbody();\n");
		code.push_str("\t\t\t\t}\n");
		code.push_str("\t\t\t}\n");
		code.push_str("\t\t}\n");
		code.push_str("\t}\n");
		code.push_str("}\n");
		for i in 0..pad {
			writeln!(code, "export const tail{i} = {i};").expect("write to String");
		}
		(code, nest)
	}

	#[test]
	fn window_deep_inside_nesting_still_returns_the_whole_chain() {
		let (code, nest) = nested_fixture(200);

		// Window covers all five opening lines, which are deep inside a
		// ~411-line file: each construct opens visibly and closes off-window, so
		// the full chain of five closers must come back.
		let openers = [(nest, nest + 4)];
		assert_eq!(
			boundaries(&code, "nested.ts", &openers),
			Some(vec![nest + 6, nest + 7, nest + 8, nest + 9, nest + 10]),
			"closers for every enclosing construct"
		);
		assert_eq!(
			boundaries(&code, "nested.ts", &openers),
			boundaries_unpruned(&code, "nested.ts", &openers)
		);

		// Mirror image: the five closing lines surface the five openers.
		let closers = [(nest + 6, nest + 10)];
		assert_eq!(
			boundaries(&code, "nested.ts", &closers),
			Some(vec![nest, nest + 1, nest + 2, nest + 3, nest + 4])
		);
		assert_eq!(
			boundaries(&code, "nested.ts", &closers),
			boundaries_unpruned(&code, "nested.ts", &closers)
		);

		// A window strictly interior to the nest surfaces nothing — every
		// enclosing node straddles it, so no endpoint is visible. The prune must
		// still descend through those straddling ancestors, which is what the
		// differential over every shape checks.
		assert_eq!(boundaries(&code, "nested.ts", &[(nest + 5, nest + 5)]), Some(vec![]));
		assert_prune_equivalent(&code, "nested.ts");
	}

	/// Count named nodes whose content end line differs from their raw end row,
	/// i.e. nodes ending immediately after a newline.
	fn nodes_with_content_end_before_raw_end(code: &str, path: &str) -> usize {
		let language = resolve_language(None, Some(path)).expect("known language");
		let tree = parse_cached(code, language, None)
			.expect("grammar loads")
			.expect("tree");
		let mut count = 0;
		let mut stack = vec![tree.root_node()];
		while let Some(node) = stack.pop() {
			let raw_end = node.end_position().row.saturating_add(1) as u32;
			if node.is_named() && node_content_end_line(node) != raw_end {
				count += 1;
			}
			for index in 0..node.child_count() {
				stack.push(node.child(index).expect("child in range"));
			}
		}
		count
	}

	#[test]
	fn content_end_line_before_raw_end_is_still_surfaced() {
		// The inner `def` ends right after `return value\n`, so tree-sitter puts
		// its end position at column 0 of the blank line: raw end row 5, content
		// end line 4. The prune tests the *raw* span, so the node survives a
		// window on either line.
		let code = "def outer():\n    def inner():\n        value = 1\n        return value\n\n    \
		            return inner\n";
		assert!(
			nodes_with_content_end_before_raw_end(code, "x.py") > 0,
			"fixture must actually contain a node whose content end precedes its raw end"
		);

		// Only the content end line is visible: the inner def and its block both
		// close there, so both openers come back.
		assert_eq!(boundaries(code, "x.py", &[(4, 4)]), Some(vec![2, 3]));
		assert_eq!(boundaries(code, "x.py", &[(4, 4)]), boundaries_unpruned(code, "x.py", &[(4, 4)]));

		// And the raw end line (the blank one) on its own.
		assert_eq!(boundaries(code, "x.py", &[(5, 5)]), boundaries_unpruned(code, "x.py", &[(5, 5)]));
		assert_prune_equivalent(code, "x.py");
	}
}

//! The shell's locale, as the utility builtins see it.
//!
//! Locale categories are read per invocation from the *shell's* environment
//! (`LC_ALL`, then the category, then `LANG`): uucore's i18n getters read the
//! host process environment once and cache it, which would ignore
//! `LC_ALL=C sort` at the prompt. Nothing here calls `setlocale`, which would
//! change the C locale of the whole host process.
//!
//! Used by `sort` and `comm` (collation), `sort` (numerics), `uniq`, `date`,
//! `du`, `df`, `env`, and `fold`.

#![allow(dead_code, reason = "each utility uses a subset")]

use std::sync::{Arc, LazyLock};

use foldhash::HashMap;
use icu_collator::{
	CollatorBorrowed,
	options::{AlternateHandling, CollatorOptions, Strength},
};
use icu_decimal::provider::{Baked, DecimalSymbolsV1};
use icu_locale_core::Locale;
use icu_provider::{DataIdentifierBorrowed, DataLocale, DataProvider, DataRequest};
use parking_lot::Mutex;

use crate::host::Host;

/// The shell's value for locale category `category` (`"LC_CTYPE"`, …):
/// `LC_ALL`, then the category, then `LANG`, with empty values treated as
/// unset (POSIX). `None` means the C locale.
pub(crate) fn shell_locale<'h>(host: &'h Host, category: &str) -> Option<&'h str> {
	["LC_ALL", category, "LANG"]
		.into_iter()
		.find_map(|key| host.var(key).filter(|value| !value.is_empty()))
}

/// Whether a `language_TERRITORY[.codeset][@modifier]` name has a UTF-8
/// codeset (`C.UTF-8` included).
pub(crate) fn codeset_is_utf8(name: &str) -> bool {
	name.split(['.', '@']).nth(1).is_some_and(|codeset| {
		codeset.eq_ignore_ascii_case("utf-8") || codeset.eq_ignore_ascii_case("utf8")
	})
}

/// Whether the shell's `LC_CTYPE` is a UTF-8 locale the system can load: the
/// multibyte character rules GNU utilities switch on after `setlocale`.
pub(crate) fn ctype_is_utf8(host: &Host) -> bool {
	let Some(name) = shell_locale(host, "LC_CTYPE") else {
		return false;
	};
	#[cfg(unix)]
	if !locale_loadable(name, libc::LC_CTYPE_MASK) {
		return false;
	}
	codeset_is_utf8(name)
}

/// Parses a locale name the way uucore parses the process one:
/// `language_TERRITORY[.codeset][@modifier]` becomes a BCP 47 locale plus
/// whether the codeset is UTF-8. `None` means the C locale: C/POSIX, or a name
/// ICU cannot read.
pub(crate) fn parse_locale_name(name: &str) -> Option<(Locale, bool)> {
	let language = name
		.split(['.', '@'])
		.next()
		.filter(|language| !matches!(*language, "C" | "POSIX"))?;
	let locale = Locale::try_from_str(&language.replace('_', "-"))
		.ok()
		.filter(|locale| *locale != Locale::UNKNOWN)?;
	Some((locale, codeset_is_utf8(name)))
}

/// Collators built so far, by locale. Building one resolves the locale's
/// tailoring through ICU's fallback chain, which repeated calls skip. `None`
/// records a locale ICU could not build a collator for.
static COLLATORS: LazyLock<Mutex<HashMap<Locale, Option<Arc<CollatorBorrowed<'static>>>>>> =
	LazyLock::new(Default::default);

/// The collator for the shell's `LC_COLLATE`, or `None` to compare text by
/// bytes: the locale must be UTF-8 (uucore's rule) and loadable by the system
/// (GNU falls back to byte order otherwise). `sort` orders lines with it and
/// `comm` merges with it, so `sort | comm` agree in every locale.
pub(crate) fn shell_collator(host: &Host) -> Option<Arc<CollatorBorrowed<'static>>> {
	let (locale, utf8) = parse_locale_name(shell_locale(host, "LC_COLLATE")?)?;
	if !utf8 || collation_locale_failed(host) {
		return None;
	}
	collator_for_locale(locale)
}

pub(crate) fn collator_for_locale(locale: Locale) -> Option<Arc<CollatorBorrowed<'static>>> {
	COLLATORS
		.lock()
		.entry(locale)
		.or_insert_with_key(|locale| {
			// Shift punctuation behind letters, but retain its quaternary
			// distinctions for `-u` and `-c` instead of treating paths as equal.
			let mut options = CollatorOptions::default();
			options.alternate_handling = Some(AlternateHandling::Shifted);
			options.strength = Some(Strength::Quaternary);
			CollatorBorrowed::try_new(locale.into(), options)
				.ok()
				.map(Arc::new)
		})
		.clone()
}

/// Whether the shell names an `LC_COLLATE` locale the system cannot load:
/// GNU's "failed to set locale", after which text compares by bytes.
#[cfg(unix)]
pub(crate) fn collation_locale_failed(host: &Host) -> bool {
	shell_locale(host, "LC_COLLATE")
		.is_some_and(|locale| !locale_loadable(locale, libc::LC_COLLATE_MASK))
}

/// Windows has no system locale to load; `LC_ALL=missing` stands in for an
/// unloadable one.
#[cfg(not(unix))]
pub(crate) fn collation_locale_failed(host: &Host) -> bool {
	host.var("LC_ALL") == Some("missing")
}

/// Whether the system can load `locale` for the categories in `mask`, probed
/// with `newlocale` rather than `setlocale`, which would change the C locale
/// of the whole host process.
#[cfg(unix)]
pub(crate) fn locale_loadable(locale: &str, mask: libc::c_int) -> bool {
	let Ok(locale) = std::ffi::CString::new(locale) else {
		return false;
	};
	// SAFETY: `locale` is a valid NUL-terminated string; a non-null result is
	// a fresh locale object owned here and freed immediately.
	unsafe {
		let handle = libc::newlocale(mask, locale.as_ptr(), std::ptr::null_mut());
		if handle.is_null() {
			return false;
		}
		libc::freelocale(handle);
	}
	true
}

/// Single-byte decimal point and thousands separator of a numeric locale.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct NumericSymbols {
	pub decimal_point: u8,
	/// `None` when the locale groups digits with no separator or with a
	/// multibyte one (GNU ignores those too).
	pub thousands_sep: Option<u8>,
}

impl NumericSymbols {
	/// The C locale: `.` and no grouping.
	pub const C: Self = Self { decimal_point: b'.', thousands_sep: None };
}

/// Decimal point and thousands separator for the shell's `LC_NUMERIC`, from
/// ICU's CLDR data for that locale (the data uucore reads for the process
/// locale). C rules apply when it names C, or on Unix a locale the system
/// cannot load (GNU's fallback); Windows has no system locale to probe, so any
/// locale ICU parses uses its CLDR rules.
pub(crate) fn numeric_symbols(host: &Host) -> NumericSymbols {
	let Some(name) = shell_locale(host, "LC_NUMERIC") else {
		return NumericSymbols::C;
	};
	let Some((locale, utf8)) = parse_locale_name(name) else {
		return NumericSymbols::C;
	};
	#[cfg(unix)]
	if !locale_loadable(name, libc::LC_NUMERIC_MASK) {
		return NumericSymbols::C;
	}
	let data_locale = DataLocale::from(&locale);
	let request = DataRequest {
		id:       DataIdentifierBorrowed::for_locale(&data_locale),
		metadata: Default::default(),
	};
	let Ok(response) = DataProvider::<DecimalSymbolsV1>::load(&Baked, request) else {
		return NumericSymbols::C;
	};
	let symbols = response.payload.get();
	NumericSymbols {
		decimal_point: match symbols.decimal_separator().as_bytes().first() {
			Some(b',') => b',',
			_ => b'.',
		},
		// Upstream GNU coreutils ignore multibyte thousands separators
		// (FIXME in C source). We keep the same single-byte behavior.
		thousands_sep: match symbols.grouping_separator().as_bytes() {
			[b] => Some(*b),
			// ICU returns NBSP as UTF-8 (0xC2 0xA0). In non-UTF8 locales like
			// ISO-8859-1, the input byte is 0xA0, so map it to a single byte.
			[0xc2, 0xa0] if !utf8 => Some(0xa0),
			_ => None,
		},
	}
}

//! The shared fixture: a source tree exercising every file type and attribute
//! the comparison observes, plus named tweaks that stage pre-existing
//! destination states. Everything is deterministic: contents come from a fixed
//! PRNG and every timestamp is pinned (with nanoseconds) far from "now", so a
//! timestamp the transfer did not set is distinguishable from one it preserved
//! (see `snapshot::MtimeClass`).

use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt, symlink};
use std::path::Path;
use std::sync::LazyLock;
use std::time::{SystemTime, UNIX_EPOCH};

use crate::rsync::time::system_time;

/// Base of every pinned timestamp (2020-09-13).
const T0: i64 = 1_600_000_000;
/// Nanosecond component of base entries (plus the entry index).
const NS: u32 = 123_456_789;
/// Timestamp of stale destination files.
const OLD: i64 = T0 - 200_000;
/// Timestamp every tweak-created directory ends up with.
const OLD_DIR: i64 = T0 - 300_000;

/// What a base entry is.
enum Kind {
	Dir,
	File(Data),
	/// A hard link to the (already created) path.
	Hardlink(&'static str),
	Symlink(&'static str),
	Fifo,
}

enum Data {
	Bytes(&'static [u8]),
	Big,
	Mid,
	Zeros,
}

/// The base tree, created in order; entry `k` (1-based) gets mtime
/// `T0 + 1000·k` s and `NS + k` ns. Directory modes and times are applied last,
/// deepest first, so creating their children does not disturb them.
const BASE: &[(&str, Kind, u32)] = &[
	("src", Kind::Dir, 0o755),
	("src/empty", Kind::File(Data::Bytes(b"")), 0o644),
	("src/small.txt", Kind::File(Data::Bytes(b"hello world\n")), 0o644),
	("src/exec.sh", Kind::File(Data::Bytes(b"#!/bin/sh\necho hi\n")), 0o755),
	("src/ro.txt", Kind::File(Data::Bytes(b"read only\n")), 0o444),
	("src/private.txt", Kind::File(Data::Bytes(b"secret\n")), 0o600),
	("src/big.bin", Kind::File(Data::Big), 0o644),
	("src/mid.bin", Kind::File(Data::Mid), 0o644),
	("src/zeros.bin", Kind::File(Data::Zeros), 0o644),
	("src/with space.txt", Kind::File(Data::Bytes(b"spaces\n")), 0o644),
	("src/ünï cødé.txt", Kind::File(Data::Bytes(b"unicode\n")), 0o644),
	("src/-dash", Kind::File(Data::Bytes(b"dash\n")), 0o644),
	("src/obj.o", Kind::File(Data::Bytes(b"object\n")), 0o644),
	("src/a.tmp", Kind::File(Data::Bytes(b"temp\n")), 0o644),
	("src/.rsync-filter", Kind::File(Data::Bytes(b"- *.tmp\n")), 0o644),
	("src/hl1", Kind::File(Data::Bytes(b"linked\n")), 0o644),
	("src/hl2", Kind::Hardlink("src/hl1"), 0),
	("src/rel", Kind::Symlink("small.txt"), 0),
	("src/abs", Kind::Symlink("/nonexistent/abs/target"), 0),
	("src/dangling", Kind::Symlink("missing-file"), 0),
	("src/dirlink", Kind::Symlink("sub"), 0),
	("src/sub", Kind::Dir, 0o755),
	("src/sub/inner.txt", Kind::File(Data::Bytes(b"inner\n")), 0o644),
	("src/sub/x.o", Kind::File(Data::Bytes(b"obj\n")), 0o644),
	("src/sub/.rsync-filter", Kind::File(Data::Bytes(b"- inner.txt\n")), 0o644),
	("src/sub/hl3", Kind::Hardlink("src/hl1"), 0),
	("src/sub/unsafe", Kind::Symlink("../../outside.txt"), 0),
	("src/sub/deep", Kind::Dir, 0o700),
	("src/sub/deep/deeper", Kind::Dir, 0o755),
	("src/sub/deep/deeper/leaf.txt", Kind::File(Data::Bytes(b"leaf\n")), 0o644),
	("src/emptydir", Kind::Dir, 0o755),
	("src/sgid", Kind::Dir, 0o2775),
	("src/sgid/f", Kind::File(Data::Bytes(b"g\n")), 0o644),
	("src/fifo", Kind::Fifo, 0o644),
	("outside.txt", Kind::File(Data::Bytes(b"outside\n")), 0o644),
	("list.txt", Kind::File(Data::Bytes(b"small.txt\nsub/inner.txt\nsub/deep\n")), 0o644),
	("list0.txt", Kind::File(Data::Bytes(b"small.txt\0sub/inner.txt\0sub/deep\0")), 0o644),
];

/// xorshift32 bytes: incompressible, reproducible, and identical in every run.
fn noise(seed: u32, len: usize) -> Vec<u8> {
	let mut x = seed;
	(0..len)
		.map(|_| {
			x ^= x << 13;
			x ^= x >> 17;
			x ^= x << 5;
			x as u8
		})
		.collect()
}

/// 1.6 MB: many blocks at the default block size, and more than 1 MiB.
static BIG: LazyLock<Vec<u8>> = LazyLock::new(|| noise(1, 1_600_000));
static MID: LazyLock<Vec<u8>> = LazyLock::new(|| noise(2, 70_000));
/// A long run of zeros between noise, for `--sparse`.
static ZEROS: LazyLock<Vec<u8>> = LazyLock::new(|| {
	let mut data = noise(3, 65_536);
	data.resize(65_536 + 262_144, 0);
	data.extend(noise(4, 65_536));
	data
});

fn data(d: &Data) -> &'static [u8] {
	match d {
		Data::Bytes(b) => *b,
		Data::Big => BIG.as_slice(),
		Data::Mid => MID.as_slice(),
		Data::Zeros => ZEROS.as_slice(),
	}
}

/// Sets atime and mtime without following a final symlink.
fn set_time(path: &Path, secs: i64, nanos: u32) {
	let t = system_time(secs, i64::from(nanos)).unwrap();
	fs::set_times_nofollow(path, fs::FileTimes::new().set_accessed(t).set_modified(t))
		.unwrap_or_else(|e| panic!("{}: {e}", path.display()));
}

fn chmod(path: &Path, mode: u32) {
	fs::set_permissions(path, fs::Permissions::from_mode(mode)).unwrap();
}

fn write_file(path: &Path, content: &[u8], mode: u32, secs: i64, nanos: u32) {
	fs::create_dir_all(path.parent().unwrap()).unwrap();
	fs::write(path, content).unwrap();
	chmod(path, mode);
	set_time(path, secs, nanos);
}

/// Builds the base tree plus `tweaks` (comma-separated) under `w`, then pins
/// the times of every directory the tweaks created.
pub(super) fn build(w: &Path, tweaks: &str) {
	let start = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as i64;
	build_base(w);
	for tweak in tweaks.split(',').filter(|t| !t.is_empty()) {
		apply(w, tweak);
	}
	pin_fresh_dirs(w, start - 5);
}

fn build_base(w: &Path) {
	let mut dirs = Vec::new();
	for (index, (rel, kind, mode)) in BASE.iter().enumerate() {
		let k = index as i64 + 1;
		let (secs, nanos) = (T0 + 1000 * k, NS + k as u32);
		let path = w.join(rel);
		match kind {
			Kind::Dir => {
				fs::create_dir_all(&path).unwrap();
				dirs.push((path, *mode, secs, nanos));
			}
			Kind::File(d) => write_file(&path, data(d), *mode, secs, nanos),
			Kind::Hardlink(target) => fs::hard_link(w.join(target), &path).unwrap(),
			Kind::Symlink(target) => {
				symlink(target, &path).unwrap();
				set_time(&path, secs, nanos);
			}
			Kind::Fifo => {
				nix::unistd::mkfifo(path.as_path(), nix::sys::stat::Mode::from_bits_truncate(0o600)).unwrap();
				chmod(&path, *mode);
				set_time(&path, secs, nanos);
			}
		}
	}
	for (path, mode, secs, nanos) in dirs.iter().rev() {
		chmod(path, *mode);
		set_time(path, *secs, *nanos);
	}
}

/// Copies the regular files and real directories of `w/src` to `w/<dest>`
/// with their contents, modes, and mtimes (hard links become separate files;
/// symlinks and specials are left out).
fn mirror(w: &Path, dest: &str) {
	fn walk(from: &Path, to: &Path, dirs: &mut Vec<(std::path::PathBuf, u32)>) {
		fs::create_dir_all(to).unwrap();
		let mut names: Vec<_> = fs::read_dir(from).unwrap().map(|e| e.unwrap().file_name()).collect();
		names.sort();
		for name in names {
			let (a, b) = (from.join(&name), to.join(&name));
			let meta = fs::symlink_metadata(&a).unwrap();
			if meta.is_dir() {
				walk(&a, &b, dirs);
				dirs.push((b, meta.mode() & 0o7777));
			} else if meta.is_file() {
				fs::write(&b, fs::read(&a).unwrap()).unwrap();
				chmod(&b, meta.mode() & 0o7777);
				set_time(&b, meta.mtime(), meta.mtime_nsec() as u32);
			}
		}
	}
	let mut dirs = Vec::new();
	walk(&w.join("src"), &w.join(dest), &mut dirs);
	for (dir, mode) in dirs {
		chmod(&dir, mode);
	}
}

/// Applies one named destination-state tweak.
fn apply(w: &Path, tweak: &str) {
	let j = |rel: &str| w.join(rel);
	match tweak {
		// A previous, outdated copy: same size and time but different content
		// (small.txt), same content but old time (mid.bin), a delta basis
		// (big.bin), a newer file (with space.txt), a mode change (ro.txt), and
		// extraneous files for the deletion modes (junk.o is excluded by `*.o`).
		"stale" => {
			fs::create_dir_all(j("dst/sub")).unwrap();
			write_file(&j("dst/small.txt"), b"HELLO WORLD\n", 0o644, T0 + 3000, NS + 3);
			write_file(&j("dst/mid.bin"), &MID, 0o644, OLD, 0);
			let mut big = BIG.to_vec();
			big[800_000..800_100].fill(0xaa);
			write_file(&j("dst/big.bin"), &big, 0o644, OLD, 0);
			write_file(&j("dst/with space.txt"), b"newer!\n", 0o644, T0 + 100_000_000, 0);
			write_file(&j("dst/extra.txt"), b"extra\n", 0o644, OLD, 0);
			write_file(&j("dst/extradir/x.txt"), b"x\n", 0o644, OLD, 0);
			write_file(&j("dst/sub/extra2"), b"e\n", 0o644, OLD, 0);
			write_file(&j("dst/junk.o"), b"junk\n", 0o644, OLD, 0);
			write_file(&j("dst/ro.txt"), b"old ro\n", 0o644, OLD, 0);
		}
		// An exact copy of the regular files.
		"copy" => mirror(w, "dst"),
		// Every regular destination file one second newer (`--modify-window`).
		"shift1" => {
			fn walk(dir: &Path) {
				for entry in fs::read_dir(dir).unwrap() {
					let path = entry.unwrap().path();
					let meta = fs::symlink_metadata(&path).unwrap();
					if meta.is_dir() {
						walk(&path);
					} else if meta.is_file() {
						set_time(&path, meta.mtime() + 1, meta.mtime_nsec() as u32);
					}
				}
			}
			walk(&j("dst"));
		}
		// Truncated destination files (`--append`, `--partial`).
		"prefix" => {
			write_file(&j("dst/big.bin"), &BIG[..600_000], 0o644, OLD, 0);
			write_file(&j("dst/mid.bin"), &MID[..30_000], 0o644, OLD, 0);
		}
		// A leftover partial file in a partial dir.
		"partialdir" => write_file(&j("dst/.rsync-partial/big.bin"), &BIG[..800_000], 0o644, OLD, 0),
		// Non-empty directories where the source has a symlink and a file, and a
		// file where it has a directory.
		"conflict" => {
			write_file(&j("dst/rel/f"), b"f\n", 0o644, OLD, 0);
			write_file(&j("dst/small.txt/f"), b"f\n", 0o644, OLD, 0);
			write_file(&j("dst/sub"), b"notadir\n", 0o644, OLD, 0);
		}
		// An earlier backup for the alternate-basis options.
		"prev" => {
			mirror(w, "prev");
			write_file(&j("prev/small.txt"), b"HELLO WORLD\n", 0o644, OLD, 0);
		}
		// A similarly named basis for `--fuzzy`.
		"fuzzy" => {
			let mut big = BIG.to_vec();
			big[100..200].fill(0x55);
			write_file(&j("dst/big-1.bin"), &big, 0o644, OLD, 0);
		}
		// A destination symlink to a directory inside the destination (`-K`).
		"keepdir" | "keepdir_chmod" => {
			fs::create_dir_all(j("dst/realsub")).unwrap();
			// Pin the intended scenario independently of the runner's umask.
			chmod(&j("dst/realsub"), if tweak == "keepdir_chmod" { 0o700 } else { 0o755 });
			symlink("realsub", j("dst/sub")).unwrap();
			set_time(&j("dst/sub"), OLD, 0);
		}
		// A destination symlink to a directory outside the destination.
		"keepdir_out" => {
			fs::create_dir_all(j("elsewhere")).unwrap();
			chmod(&j("elsewhere"), 0o755);
			fs::create_dir_all(j("dst")).unwrap();
			symlink("../elsewhere", j("dst/sub")).unwrap();
			set_time(&j("dst/sub"), OLD, 0);
		}
		// Temp dirs inside and outside the destination.
		"tmpdir" => {
			fs::create_dir_all(j("tmpd")).unwrap();
			fs::create_dir_all(j("dst/.tmpd")).unwrap();
		}
		other => panic!("unknown fixture tweak {other:?}"),
	}
}

/// Gives every real directory under `w` modified at or after `since` the
/// pinned [`OLD_DIR`] time.
fn pin_fresh_dirs(w: &Path, since: i64) {
	for entry in fs::read_dir(w).unwrap() {
		let path = entry.unwrap().path();
		let meta = fs::symlink_metadata(&path).unwrap();
		if meta.is_dir() {
			pin_fresh_dirs(&path, since);
			if meta.mtime() >= since {
				set_time(&path, OLD_DIR, 0);
			}
		}
	}
}

/// Creates the daemon's writable module root with a pinned time.
pub(super) fn module_root(w: &Path) {
	let rw = w.join("rw");
	fs::create_dir_all(&rw).unwrap();
	set_time(&rw, OLD_DIR, 0);
}

//! `--iconv`: file-name charset conversion between the local charset and the
//! UTF-8 the protocol carries.
//!
//! Spec semantics (upstream setup_iconv): `LOCAL,REMOTE` — the client uses
//! `LOCAL`, a server (including the server half of a local copy) uses
//! `REMOTE`; a single charset is used by whichever side has it; an empty
//! charset or `.` means the locale's charset. Names are converted
//! `local → UTF-8` when they go to the wire ([`Iconv::to_wire_io`]) and
//! `UTF-8 → local` when they come from it ([`Iconv::from_wire`]); invalid or
//! incomplete sequences fail the conversion (no lossy substitution), which
//! callers report per file as `[%s] cannot convert filename: %s (%s)`.
//!
//! Unix uses the C library's `iconv(3)` (libiconv on macOS). Windows has no
//! iconv: the type exists so the engine compiles, but [`Iconv::with_locale`] fails the
//! way a build without ICONV_OPTION does (options already refuse `--iconv`).

use std::io;

use crate::rsync::exit::{RERR_UNSUPPORTED, RsyncError};

/// Upstream `UTF8_CHARSET`.
#[cfg(unix)]
const UTF8_CHARSET: &str = "UTF-8";

/// The charset a spec selects for this side (upstream setup_iconv's pick):
/// `""` means "the locale's charset".
pub(crate) fn side_charset(spec: &[u8], am_server: bool) -> &[u8] {
	let part = match spec.iter().position(|&b| b == b',') {
		Some(comma) if am_server => &spec[comma + 1..],
		Some(comma) => &spec[..comma],
		None => spec,
	};
	if part == b"." { b"" } else { part }
}

/// The locale charset from the environment (`LC_ALL`, then `LC_CTYPE`, then
/// `LANG`), the way `nl_langinfo(CODESET)` reports it after
/// `setlocale(LC_CTYPE, "")`: the codeset after `.` (without an `@modifier`),
/// ASCII for the C/POSIX locale, and `""` (iconv's own default) otherwise.
pub(crate) fn locale_charset(env: &dyn Fn(&str) -> Option<String>) -> String {
	let value = ["LC_ALL", "LC_CTYPE", "LANG"]
		.iter()
		.find_map(|key| env(key).filter(|v| !v.is_empty()));
	let Some(value) = value else {
		return ascii_codeset().to_owned();
	};
	if value == "C" || value == "POSIX" {
		return ascii_codeset().to_owned();
	}
	let value = value.split('@').next().unwrap_or("");
	match value.split_once('.') {
		Some((_, codeset)) if !codeset.is_empty() => codeset.to_owned(),
		_ if value.eq_ignore_ascii_case("UTF-8") => "UTF-8".to_owned(),
		_ => String::new(),
	}
}

/// What `nl_langinfo(CODESET)` returns for the C locale.
pub(crate) fn ascii_codeset() -> &'static str {
	if cfg!(target_os = "linux") { "ANSI_X3.4-1968" } else { "US-ASCII" }
}

/// A pair of open conversions for one side of a transfer.
pub(crate) struct Iconv {
	charset: String,
	#[cfg(unix)]
	send: sys::Converter,
	#[cfg(unix)]
	recv: sys::Converter,
}

impl std::fmt::Debug for Iconv {
	fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
		f.debug_struct("Iconv").field("charset", &self.charset).finish()
	}
}

impl Iconv {
	/// Opens the conversions for `spec` (`--iconv` value); `.`/empty select `locale`
	/// (see [`locale_charset`]; None: iconv's own "" default).
	pub(crate) fn with_locale(
		spec: &[u8],
		am_server: bool,
		locale: Option<&str>,
	) -> Result<Self, RsyncError> {
		let chosen = side_charset(spec, am_server);
		let charset = if chosen.is_empty() {
			locale.unwrap_or("").to_owned()
		} else {
			String::from_utf8_lossy(chosen).into_owned()
		};
		Self::open(charset)
	}

	#[cfg(unix)]
	fn open(charset: String) -> Result<Self, RsyncError> {
		let send = sys::Converter::open(UTF8_CHARSET, &charset).map_err(|_| {
			RsyncError::new(
				RERR_UNSUPPORTED,
				format!("iconv_open(\"{UTF8_CHARSET}\", \"{charset}\") failed"),
			)
			.at("rsync.c", 134)
		})?;
		let recv = sys::Converter::open(&charset, UTF8_CHARSET).map_err(|_| {
			RsyncError::new(
				RERR_UNSUPPORTED,
				format!("iconv_open(\"{charset}\", \"{UTF8_CHARSET}\") failed"),
			)
			.at("rsync.c", 140)
		})?;
		Ok(Self { charset, send, recv })
	}

	/// No iconv on this platform: upstream's refusal of an option a build lacks.
	#[cfg(not(unix))]
	fn open(charset: String) -> Result<Self, RsyncError> {
		let _ = charset;
		Err(RsyncError::new(RERR_UNSUPPORTED, "This rsync does not support --iconv".to_owned()))
	}

	/// The `--debug=ICONV1` line: `[%s] charset: %s` (`[LOCALE]` for iconv's default).
	pub(crate) fn debug_line(&self, who: &str) -> String {
		let shown = if self.charset.is_empty() { "[LOCALE]" } else { self.charset.as_str() };
		format!("[{who}] charset: {shown}\n")
	}

	/// Local charset → UTF-8 (`ic_send`); the error carries the errno (EILSEQ,
	/// EINVAL for a truncated sequence).
	pub(crate) fn to_wire_io(&self, name: &[u8]) -> io::Result<Vec<u8>> {
		#[cfg(unix)]
		return self.send.convert(name);
		#[cfg(not(unix))]
		{
			let _ = name;
			Err(io::ErrorKind::Unsupported.into())
		}
	}

	/// UTF-8 → local charset (`ic_recv`).
	pub(crate) fn from_wire_io(&self, name: &[u8]) -> io::Result<Vec<u8>> {
		#[cfg(unix)]
		return self.recv.convert(name);
		#[cfg(not(unix))]
		{
			let _ = name;
			Err(io::ErrorKind::Unsupported.into())
		}
	}

	/// [`Iconv::from_wire_io`] as an `RsyncError` whose message is
	/// `cannot convert filename: NAME (STRERROR)` (callers add the `[role] ` prefix).
	pub(crate) fn from_wire(&self, name: &[u8]) -> Result<Vec<u8>, RsyncError> {
		self.from_wire_io(name).map_err(|e| convert_error(name, &e))
	}
}

fn convert_error(name: &[u8], err: &io::Error) -> RsyncError {
	RsyncError::new(
		crate::rsync::exit::RERR_PARTIAL,
		format!(
			"cannot convert filename: {} ({})",
			String::from_utf8_lossy(name),
			crate::rsync::log::strerror(err)
		),
	)
}

#[cfg(unix)]
mod sys {
	use std::ffi::{CString, c_char, c_void};
	use std::io;
	use std::sync::Mutex;

	use crate::rsync::flists::lock;

	#[allow(non_camel_case_types)]
	type iconv_t = *mut c_void;

	#[cfg_attr(target_vendor = "apple", link(name = "iconv"))]
	unsafe extern "C" {
		fn iconv_open(tocode: *const c_char, fromcode: *const c_char) -> iconv_t;
		fn iconv(
			cd: iconv_t,
			inbuf: *mut *mut c_char,
			inbytesleft: *mut usize,
			outbuf: *mut *mut c_char,
			outbytesleft: *mut usize,
		) -> usize;
		fn iconv_close(cd: iconv_t) -> i32;
	}

	/// One open conversion descriptor. iconv state is per descriptor and not
	/// thread-safe, so every conversion holds the lock.
	pub(super) struct Converter {
		cd: Mutex<Handle>,
	}

	struct Handle(iconv_t);

	// SAFETY: the descriptor is only used while holding the Mutex, so it is never
	// accessed by two threads at once; iconv descriptors are not tied to a thread.
	unsafe impl Send for Handle {}

	impl Drop for Handle {
		fn drop(&mut self) {
			// SAFETY: the descriptor came from a successful iconv_open and is closed once.
			unsafe {
				iconv_close(self.0);
			}
		}
	}

	impl Converter {
		pub(super) fn open(to: &str, from: &str) -> io::Result<Self> {
			let to = CString::new(to).map_err(|_| io::Error::from_raw_os_error(libc::EINVAL))?;
			let from = CString::new(from).map_err(|_| io::Error::from_raw_os_error(libc::EINVAL))?;
			// SAFETY: both arguments are valid NUL-terminated strings.
			let cd = unsafe { iconv_open(to.as_ptr(), from.as_ptr()) };
			if cd as isize == -1 {
				return Err(io::Error::last_os_error());
			}
			Ok(Self { cd: Mutex::new(Handle(cd)) })
		}

		/// Converts all of `input` (state reset first, like ICB_INIT); an invalid or
		/// truncated sequence fails with its errno.
		pub(super) fn convert(&self, input: &[u8]) -> io::Result<Vec<u8>> {
			let guard = lock(&self.cd);
			let cd = guard.0;
			// SAFETY: null buffers reset the conversion state.
			unsafe {
				iconv(cd, std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut());
			}
			let mut out: Vec<u8> = vec![0; input.len() * 2 + 16];
			let mut in_ptr = input.as_ptr() as *mut c_char;
			let mut in_left = input.len();
			let mut done = 0usize;
			while in_left > 0 {
				let mut out_ptr = out[done..].as_mut_ptr() as *mut c_char;
				let mut out_left = out.len() - done;
				// SAFETY: in_ptr/in_left describe the unread rest of `input` (iconv only
				// reads through it despite the mut cast); out_ptr/out_left describe the
				// unused tail of `out`, which outlives the call.
				let rc = unsafe { iconv(cd, &mut in_ptr, &mut in_left, &mut out_ptr, &mut out_left) };
				done = out.len() - out_left;
				if rc == usize::MAX {
					let err = io::Error::last_os_error();
					match err.raw_os_error() {
						Some(libc::E2BIG) => {
							let grow = out.len().max(64);
							out.resize(out.len() + grow, 0);
						},
						Some(libc::EINTR) => {},
						_ => return Err(err),
					}
				}
			}
			// Flush any shift state.
			loop {
				let mut out_ptr = out[done..].as_mut_ptr() as *mut c_char;
				let mut out_left = out.len() - done;
				// SAFETY: a null input flushes; the output range is the unused tail of `out`.
				let rc = unsafe {
					iconv(cd, std::ptr::null_mut(), std::ptr::null_mut(), &mut out_ptr, &mut out_left)
				};
				done = out.len() - out_left;
				if rc == usize::MAX && io::Error::last_os_error().raw_os_error() == Some(libc::E2BIG) {
					let grow = out.len().max(64);
					out.resize(out.len() + grow, 0);
					continue;
				}
				break;
			}
			out.truncate(done);
			Ok(out)
		}
	}
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn side_charset_picks_like_setup_iconv() {
		assert_eq!(side_charset(b"ISO-8859-1,UTF-8", false), b"ISO-8859-1");
		assert_eq!(side_charset(b"ISO-8859-1,UTF-8", true), b"UTF-8");
		assert_eq!(side_charset(b"latin1", true), b"latin1");
		assert_eq!(side_charset(b".", false), b"");
		assert_eq!(side_charset(b"., latin1", false), b"");
		assert_eq!(side_charset(b"", false), b"");
	}

	#[test]
	fn locale_charset_from_env() {
		let env = |pairs: &'static [(&'static str, &'static str)]| {
			move |k: &str| pairs.iter().find(|(n, _)| *n == k).map(|(_, v)| (*v).to_owned())
		};
		assert_eq!(locale_charset(&env(&[("LANG", "en_US.UTF-8")])), "UTF-8");
		assert_eq!(locale_charset(&env(&[("LC_ALL", "de_DE.ISO8859-1@euro"), ("LANG", "x.UTF-8")])), "ISO8859-1");
		assert_eq!(locale_charset(&env(&[("LC_CTYPE", "UTF-8")])), "UTF-8");
		assert_eq!(locale_charset(&env(&[("LANG", "C")])), ascii_codeset());
		assert_eq!(locale_charset(&env(&[])), ascii_codeset());
	}

	#[cfg(unix)]
	#[test]
	fn utf8_latin1_round_trip() {
		let ic = Iconv::with_locale(b"ISO-8859-1", false, None).unwrap();
		let local = b"caf\xe9-\xfc.txt";
		let wire = ic.to_wire_io(local).unwrap();
		assert_eq!(wire, "café-ü.txt".as_bytes());
		assert_eq!(ic.from_wire(&wire).unwrap(), local);
		assert_eq!(ic.debug_line("sender"), "[sender] charset: ISO-8859-1\n");
	}

	#[cfg(unix)]
	#[test]
	fn server_uses_remote_half_of_spec() {
		let ic = Iconv::with_locale(b"UTF-8,ISO-8859-1", true, None).unwrap();
		assert_eq!(ic.debug_line("receiver"), "[receiver] charset: ISO-8859-1\n");
		assert_eq!(ic.from_wire("é".as_bytes()).unwrap(), b"\xe9");
	}

	#[cfg(unix)]
	#[test]
	fn invalid_sequence_is_reported() {
		let ic = Iconv::with_locale(b"ISO-8859-1", false, None).unwrap();
		// Not representable in Latin-1.
		let err = ic.from_wire("snow\u{2603}".as_bytes()).unwrap_err();
		let msg = err.message.unwrap();
		assert!(msg.starts_with("cannot convert filename: snow"), "{msg}");
		// Truncated UTF-8 input.
		assert!(ic.from_wire(b"ab\xc3").is_err());
	}

	#[cfg(unix)]
	#[test]
	fn unknown_charset_fails_like_upstream() {
		let err = Iconv::with_locale(b"NO-SUCH-CHARSET-XYZ", false, Some("UTF-8")).unwrap_err();
		assert_eq!(err.code, RERR_UNSUPPORTED);
		assert_eq!(
			err.message.as_deref(),
			Some("iconv_open(\"UTF-8\", \"NO-SUCH-CHARSET-XYZ\") failed")
		);
	}
}

//! Everything the user sees: message routing (`rprintf`/`rsyserr`), peer
//! messages, the `--log-file`, per-item `--out-format` lines, `--info` /
//! `--debug` levels, and `--stats` rendering.
//!
//! A [`Logger`] is shared by every role of a transfer (cheap clones; the role
//! is per clone). Client loggers write to local stdout/stderr; a server logger
//! hands messages to the peer the way upstream multiplexes them.

mod format;
mod levels;
mod stats;

use std::{
	io::{self, Write},
	sync::{
		Arc, Mutex,
		atomic::{AtomicBool, AtomicU8, AtomicU32, Ordering},
	},
	time::Duration,
};

#[cfg(all(test, unix))]
pub(crate) use format::itemize;
pub(crate) use format::{ItemizeCtx, big_num, log_format_has, permstring, timestring};
use format::{FormatEnv, FormatItem, expand};
pub(crate) use levels::{Debug, Info, OutLevels, Priority, Words};
pub(crate) use stats::Stats;

use crate::rsync::{
	cstr::until_nul,
	flists::lock,
	checksum::CsumType,
	consts::{
		BIGPATHBUFLEN, ITEM_DELETED, ITEM_LOCAL_CHANGE, ITEM_TRANSFER, MAXPATHLEN, S_IFDIR, S_IFREG,
		SIGNIFICANT_ITEM_FLAGS, mode_is_dir, mode_is_reg,
	},
	exit::{self, RsyncError},
};

/// Message classes (upstream `enum logcode`; values equal the MSG_* codes).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum LogCode {
	ErrorXfer = 1,
	Info = 2,
	Error = 3,
	Warning = 4,
	ErrorSocket = 5,
	Log = 6,
	Client = 7,
	ErrorUtf8 = 8,
}

impl LogCode {
	/// The code for a MSG_* tag carrying a log message, if it is one.
	pub(crate) const fn from_u8(tag: u8) -> Option<Self> {
		Some(match tag {
			1 => Self::ErrorXfer,
			2 => Self::Info,
			3 => Self::Error,
			4 => Self::Warning,
			5 => Self::ErrorSocket,
			6 => Self::Log,
			7 => Self::Client,
			8 => Self::ErrorUtf8,
			_ => return None,
		})
	}
}

/// Which part of the transfer is speaking (upstream who_am_i()).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Role {
	Sender,
	Receiver,
	Generator,
	/// Start-up, before roles are assigned, on the client.
	Client,
	/// Start-up, before roles are assigned, on the server.
	Server,
	/// The receiving side before it splits into generator and receiver ("Receiver").
	PreReceiver,
}

impl Role {
	/// Upstream's who_am_i() text.
	pub(crate) const fn name(self) -> &'static str {
		match self {
			Self::Sender => "sender",
			Self::Receiver => "receiver",
			Self::Generator => "generator",
			Self::Client => "client",
			Self::Server => "server",
			Self::PreReceiver => "Receiver",
		}
	}
}

/// `--stderr=errors` (the default): errors to stderr, info to stdout / the peer.
pub(crate) const STDERR_ERRORS: u8 = 0;
/// `--stderr=all` / `--msgs2stderr`: every message to stderr.
pub(crate) const STDERR_ALL: u8 = 1;
/// `--stderr=client` / `--no-msgs2stderr`: a server sends everything to the client.
pub(crate) const STDERR_CLIENT: u8 = 2;

/// Default `--log-file-format`.
pub(crate) const DEFAULT_LOG_FILE_FORMAT: &[u8] = b"%i %n%L";

/// Longest message written to the log file / syslog.
const LOG_MSG_MAX: usize = 2047;

/// Logger settings.
#[derive(Clone, Default)]
pub(crate) struct LogConfig {
	pub levels: OutLevels,
	/// --out-format (or the format implied by -i / -v).
	pub out_format: Option<Vec<u8>>,
	pub log_file: Option<std::path::PathBuf>,
	pub log_file_format: Option<Vec<u8>>,
	/// -h level: 0 = --no-h, 1 = default (separators), 2 = -h (1000), 3 = -hh (1024).
	pub human_readable: u8,
	pub eight_bit_output: bool,
	/// The shell's C/POSIX charset rejects high bytes even when they form valid UTF-8.
	pub ascii_output: bool,
	/// [`STDERR_ERRORS`], [`STDERR_ALL`], or [`STDERR_CLIENT`].
	pub stderr_mode: u8,
	pub am_server: bool,
	pub quiet: bool,
	pub module: Option<Vec<u8>>,
	pub host: Option<Vec<u8>>,
	pub addr: Option<Vec<u8>>,
	pub user: Option<Vec<u8>>,
	/// `%P`: the module path (daemon only; literal `%P` when None).
	pub module_path: Option<Vec<u8>>,
	/// `-i` count (upstream `itemize_changes`), for `stdout_format_has_i`.
	pub itemize_changes: u8,
	pub dry_run: bool,
	/// Both transfer halves run in this process.
	pub local_server: bool,
	pub preserve_mtimes: bool,
	/// The receiver can set symlink times (negotiated).
	pub receiver_symlink_times: bool,
	pub preserve_uid: bool,
	pub preserve_gid: bool,
	/// `-c`: `%C` shows the file-list checksum.
	pub always_checksum: bool,
	/// Zone for `%t`, `%M`, and log-file stamps (the shell's TZ); None = system zone.
	pub time_zone: Option<jiff::tz::TimeZone>,
}

/// Formats and flags derived once from the config (upstream's *_format_has_* globals).
#[derive(Default)]
struct Formats {
	stdout: Option<Vec<u8>>,
	stdout_has_i: u8,
	stdout_has_o_or_i: bool,
	logfile: Option<Vec<u8>>,
	logfile_has_i: bool,
	logfile_has_o_or_i: bool,
}

impl Formats {
	fn new(cfg: &LogConfig) -> Self {
		let mut formats = Self { stdout: cfg.out_format.clone(), ..Self::default() };
		if let Some(format) = &formats.stdout {
			formats.stdout_has_i = if cfg.am_server && log_format_has(format, b'I') {
				2
			} else if log_format_has(format, b'i') {
				cfg.itemize_changes | 1
			} else {
				0
			};
			formats.stdout_has_o_or_i = formats.stdout_has_i != 0 || log_format_has(format, b'o');
		}
		if cfg.log_file.is_some() {
			let format =
				cfg.log_file_format.clone().unwrap_or_else(|| DEFAULT_LOG_FILE_FORMAT.to_vec());
			formats.logfile_has_i = log_format_has(&format, b'i');
			formats.logfile_has_o_or_i = formats.logfile_has_i || log_format_has(&format, b'o');
			formats.logfile = Some(format);
		}
		formats
	}
}

/// Server-side peer sink: sends one message as MSG_<code>.
pub(crate) type RemoteSink = Arc<dyn Fn(LogCode, &[u8]) -> io::Result<()> + Send + Sync>;
/// Server-side MSG_DELETED sink (payload: the name, plus a NUL for directories).
pub(crate) type DeletedSink = Arc<dyn Fn(&[u8]) -> io::Result<()> + Send + Sync>;

enum LogTarget {
	/// No --log-file.
	Off,
	File(Box<dyn Write + Send>),
	/// The log file could not be opened: messages go to syslog (unix) like upstream.
	Syslog,
}

struct Outputs {
	out: Option<Box<dyn Write + Send>>,
	err: Option<Box<dyn Write + Send>>,
	log: LogTarget,
	/// Guards against logging recursion while writing the log file.
	in_block: bool,
}

struct Inner {
	cfg: LogConfig,
	formats: Formats,
	/// `levels` and its negation (files-from silencing).
	levels: [OutLevels; 2],
	negated: AtomicBool,
	tz: jiff::tz::TimeZone,
	remote: Option<RemoteSink>,
	deleted: Mutex<Option<DeletedSink>>,
	outputs: Mutex<Outputs>,
	got_xfer_error: AtomicBool,
	/// Negotiated receiver_symlink_times (starts as `cfg.receiver_symlink_times`).
	receiver_symlink_times: AtomicBool,
	/// Upstream output_needs_newline (1 after a progress line, 2 during flist progress).
	needs_newline: AtomicU8,
	protocol: AtomicU32,
	checksums: Mutex<(CsumType, CsumType)>,
	fatal: Mutex<Option<RsyncError>>,
}

/// Where messages go: local stdout/stderr (client) or the peer (server role).
#[derive(Clone)]
pub(crate) struct Logger {
	inner: Arc<Inner>,
	role: Role,
}

/// Everything the % escapes of --out-format can reference for one item.
#[derive(Clone, Copy, Debug, Default)]
pub(crate) struct LogItem<'a> {
	pub name: &'a [u8],
	pub mode: u32,
	pub size: u64,
	pub mtime: i64,
	pub uid: u32,
	pub gid: u32,
	pub link: Option<&'a [u8]>,
	pub hlink: Option<&'a [u8]>,
	pub iflags: u32,
	pub op: &'static str,
	pub bytes_xfer: u64,
	pub bytes_csum: u64,
	/// `%C` digest bytes (file-list sum under -c, else the transfer sum), raw.
	pub checksum: Option<&'a [u8]>,
	pub is_dir: bool,
	/// Sender-side directory prefix (`F_PATHNAME`) that `%f` joins in front of the name.
	pub dir_prefix: Option<&'a [u8]>,
	/// FLAG_SKIP_GROUP: `%G` prints `DEFAULT`.
	pub skip_group: bool,
}

impl Logger {
	/// A client-side logger writing to local stdout and stderr.
	pub(crate) fn local(
		out: Box<dyn Write + Send>,
		err: Box<dyn Write + Send>,
		cfg: LogConfig,
	) -> Self {
		Self::build(Some(out), Some(err), None, cfg, Role::Client)
	}

	/// Server role with a local stderr: `--stderr=errors`/`all` route there like upstream,
	/// and messages that cannot be multiplexed (yet) fall back to it.
	pub(crate) fn remote_with_stderr(
		sink: RemoteSink,
		err: Box<dyn Write + Send>,
		cfg: LogConfig,
	) -> Self {
		Self::build(None, Some(err), Some(sink), cfg, Role::Server)
	}

	fn build(
		out: Option<Box<dyn Write + Send>>,
		err: Option<Box<dyn Write + Send>>,
		remote: Option<RemoteSink>,
		cfg: LogConfig,
		role: Role,
	) -> Self {
		let mut negated = cfg.levels.clone();
		negated.negate();
		let levels = [cfg.levels.clone(), negated];
		let tz = cfg.time_zone.clone().unwrap_or_else(jiff::tz::TimeZone::system);
		let formats = Formats::new(&cfg);
		let inner = Inner {
			formats,
			levels,
			negated: AtomicBool::new(false),
			tz,
			remote,
			deleted: Mutex::new(None),
			outputs: Mutex::new(Outputs { out, err, log: LogTarget::Off, in_block: false }),
			got_xfer_error: AtomicBool::new(false),
			receiver_symlink_times: AtomicBool::new(cfg.receiver_symlink_times),
			needs_newline: AtomicU8::new(0),
			protocol: AtomicU32::new(33),
			checksums: Mutex::new((CsumType::Md5, CsumType::Md5)),
			fatal: Mutex::new(None),
			cfg,
		};
		Self { inner: Arc::new(inner), role }
	}

	/// The same logger speaking as `role`.
	pub(crate) fn with_role(&self, role: Role) -> Self {
		Self { inner: Arc::clone(&self.inner), role }
	}

	/// Who this clone speaks as.
	pub(crate) fn role(&self) -> Role {
		self.role
	}

	/// Current output levels (all zero while negated).
	pub(crate) fn levels(&self) -> &OutLevels {
		&self.inner.levels[usize::from(self.inner.negated.load(Ordering::Relaxed))]
	}

	/// The settings this logger was built with.
	pub(crate) fn config(&self) -> &LogConfig {
		&self.inner.cfg
	}

	/// Temporarily silences every info/debug level (negate_output_levels).
	pub(crate) fn set_levels_negated(&self, negated: bool) {
		self.inner.negated.store(negated, Ordering::Relaxed);
	}

	/// The negotiated protocol (pre-30 peers get errors as MSG_ERROR_XFER, warnings as info).
	pub(crate) fn set_protocol(&self, version: u32) {
		self.inner.protocol.store(version, Ordering::Relaxed);
	}

	/// Negotiated transfer and file-list checksum kinds (for `%C`).
	pub(crate) fn set_checksums(&self, xfer: CsumType, file: CsumType) {
		*lock(&self.inner.checksums) = (xfer, file);
	}

	/// Server role: how MSG_DELETED reaches the peer (protocol ≥ 29).
	pub(crate) fn set_deleted_sink(&self, sink: Option<DeletedSink>) {
		*lock(&self.inner.deleted) = sink;
	}

	/// The negotiated receiver_symlink_times (itemize: a symlink whose time cannot be set
	/// shows `T`).
	pub(crate) fn set_receiver_symlink_times(&self, on: bool) {
		self.inner.receiver_symlink_times.store(on, Ordering::Relaxed);
	}

	/// Upstream got_xfer_error: an ErrorXfer message was emitted (the run ends with 23).
	pub(crate) fn got_xfer_error(&self) -> bool {
		self.inner.got_xfer_error.load(Ordering::Relaxed)
	}

	/// Upstream output_needs_newline (0, 1 after an unfinished progress line, 2 for
	/// file-list progress).
	pub(crate) fn needs_newline(&self) -> u8 {
		self.inner.needs_newline.load(Ordering::Relaxed)
	}

	/// Sets output_needs_newline.
	pub(crate) fn set_needs_newline(&self, value: u8) {
		self.inner.needs_newline.store(value, Ordering::Relaxed);
	}

	/// A fatal logging condition upstream exits on (RERR_MESSAGEIO), taken once.
	pub(crate) fn take_fatal(&self) -> Option<RsyncError> {
		lock(&self.inner.fatal).take()
	}

	/// Installs an already-opened `--log-file` (append mode, opened by the caller).
	pub(crate) fn set_log_file(&self, file: Box<dyn Write + Send>) {
		lock(&self.inner.outputs).log = LogTarget::File(file);
	}

	/// log_init: opens `config().log_file` for appending through the operator-file walk.
	/// On failure prints upstream's two messages and falls back to syslog.
	pub(crate) fn open_log_file(&self, fs: &pi_vfs::BlockingFs, insecure: bool) {
		let Some(path) = self.inner.cfg.log_file.clone() else {
			return;
		};
		if path.is_empty() {
			lock(&self.inner.outputs).log = LogTarget::Syslog;
			return;
		}
		match crate::rsync::paths::create_operator_file(fs, &path, true, insecure) {
			Ok(file) => self.set_log_file(Box::new(file)),
			Err(err) => {
				let mut text = b"failed to open log-file ".to_vec();
				text.extend_from_slice(&crate::host::os_bytes_lossy(path.as_os_str()));
				self.rsyserr(LogCode::Error, &err, &text);
				self.rprintf(LogCode::Info, b"Ignoring \"log file\" setting.\n");
				lock(&self.inner.outputs).log = LogTarget::Syslog;
			}
		}
	}

	/// rprintf: `text` carries its own trailing newline like upstream's format strings.
	/// One line per call: embedded control characters (including `\n`) are escaped.
	pub(crate) fn rprintf(&self, code: LogCode, text: &[u8]) {
		if text.len() > BIGPATHBUFLEN - 1 {
			let keep = BIGPATHBUFLEN - 1 - 6;
			let mut cut = text[..keep].to_vec();
			cut.extend_from_slice(b"[...]");
			cut.push(if text.ends_with(b"\n") { b'\n' } else { 0 });
			self.emit(code, &cut, false);
		} else {
			self.emit(code, text, false);
		}
	}

	/// rsyserr: "rsync: [<role>] <text>: <strerror> (<errno>)\n".
	pub(crate) fn rsyserr(&self, code: LogCode, err: &io::Error, text: &[u8]) {
		if crate::rsync::paths::is_untrusted_symlink(err) {
			let mut notice = crate::rsync::paths::UNTRUSTED_SYMLINK_NOTICE.as_bytes().to_vec();
			notice.push(b'\n');
			self.rprintf(LogCode::Error, &notice);
		}
		let mut line = format!("rsync: [{}] ", self.role.name()).into_bytes();
		line.extend_from_slice(text);
		line.extend_from_slice(format!(": {}\n", syserr_suffix(err)).as_bytes());
		self.rprintf(code, &line);
	}

	/// A message that arrived from the peer (client prints it; server forwards it).
	pub(crate) fn from_peer(&self, code: LogCode, text: &[u8]) {
		self.emit(code, text, true);
	}

	/// A MSG_DELETED payload from the peer: a trailing NUL marks a directory.
	pub(crate) fn from_peer_deleted(&self, payload: &[u8]) {
		match payload.strip_suffix(b"\0") {
			Some(name) => self.log_delete(until_nul(name), S_IFDIR),
			None => self.log_delete(until_nul(payload), S_IFREG),
		}
	}

	/// Maps a wire-level io::Error with this logger's role filling upstream's EOF text.
	pub(crate) fn io_error(&self, err: &io::Error, code: i32, bytes_read: u64) -> RsyncError {
		RsyncError::from_io_as(err, code, self.role, bytes_read)
	}

	/// End-of-run bookkeeping (exit_cleanup + log_exit): finishes a pending progress line,
	/// writes the log-file totals line, and prints the exit trailer (`rsync error:` at FERROR,
	/// `rsync warning:` for code 24, nothing for 0). `after_error_exit` suppresses the
	/// duplicate trailer after a peer's MSG_ERROR_EXIT.
	pub(crate) fn finish(
		&self,
		code: i32,
		site: Option<(&'static str, u32)>,
		stats: &Stats,
		after_error_exit: bool,
	) {
		if self.inner.needs_newline.swap(0, Ordering::Relaxed) != 0 {
			let mut outputs = lock(&self.inner.outputs);
			if let Some(out) = outputs.out.as_mut() {
				let _ = out.write_all(b"\n");
			}
		}
		let log_active = !matches!(lock(&self.inner.outputs).log, LogTarget::Off);
		let report = (code != 0 && !after_error_exit)
			|| (log_active
				&& (self.inner.cfg.am_server || self.levels().info(Info::Stats) < 1));
		if report {
			if code == 0 || self.role == Role::Sender {
				self.rprintf(LogCode::Log, stats.log_exit_line().as_bytes());
			}
			let server_success = self.inner.cfg.am_server && code == 0;
			if code != 0 && !server_success {
				let level = if code == exit::RERR_VANISHED { LogCode::Warning } else { LogCode::Error };
				self.rprintf(level, exit::exit_trailer(code, site, self.role).as_bytes());
			}
		}
		self.flush();
	}

	/// output_summary: the --stats block and the sent/received summary, per INFO stats level.
	pub(crate) fn output_summary(
		&self,
		stats: &Stats,
		proto: u32,
		elapsed: Option<Duration>,
		dry_run: bool,
		batch_only: bool,
	) {
		let human = self.inner.cfg.human_readable;
		let levels = self.levels().clone();
		if levels.info(Info::Stats) >= 2 {
			self.rprintf(LogCode::Client, b"\n");
			for line in stats.stats_lines(human, proto, &levels) {
				self.rprintf(LogCode::Info, line.as_bytes());
			}
		}
		if levels.info(Info::Stats) >= 1 {
			let suffix = if batch_only {
				" (BATCH ONLY)"
			} else if dry_run {
				" (DRY RUN)"
			} else {
				""
			};
			self.rprintf(LogCode::Client, b"\n");
			for line in stats.summary_lines(human, elapsed, suffix) {
				self.rprintf(LogCode::Info, line.as_bytes());
			}
		}
		self.flush();
	}

	/// log_item: out-format / log-file-format line for one transferred/changed/deleted item.
	pub(crate) fn log_item(&self, code: LogCode, item: &LogItem<'_>) {
		let formats = &self.inner.formats;
		if code != LogCode::Log
			&& !self.inner.cfg.am_server
			&& let Some(format) = &formats.stdout
		{
			self.formatted(LogCode::Client, format, item, false);
		}
		if code != LogCode::Client
			&& let Some(format) = formats.logfile.as_ref().filter(|format| !format.is_empty())
		{
			self.formatted(LogCode::Log, format, item, false);
		}
	}

	/// maybe_log_item: logs an item if itemizing or its changes are significant.
	pub(crate) fn maybe_log_item(&self, item: &LogItem<'_>, itemizing: bool) {
		let formats = &self.inner.formats;
		let significant = item.iflags & SIGNIFICANT_ITEM_FLAGS;
		let hlink = item.hlink.is_some_and(|hlink| !hlink.is_empty());
		let see_item = itemizing
			&& (significant != 0
				|| hlink || formats.stdout_has_i > 1
				|| (self.levels().info(Info::Name) >= 2 && formats.stdout_has_i != 0));
		let local_change = item.iflags & ITEM_LOCAL_CHANGE != 0 && significant != 0;
		if self.inner.cfg.am_server {
			if formats.logfile.is_some()
				&& !self.inner.cfg.dry_run
				&& see_item && (significant != 0 || formats.logfile_has_i)
			{
				self.log_item(LogCode::Log, item);
			}
		} else if see_item
			|| local_change
			|| hlink || ((mode_is_dir(item.mode) || item.is_dir) && significant != 0)
		{
			let code = if significant != 0 || formats.logfile_has_i {
				LogCode::Info
			} else {
				LogCode::Client
			};
			self.log_item(code, item);
		}
	}

	/// log_delete: reports one deletion (`deleting x` / `*deleting  x`), or forwards it to
	/// the client as MSG_DELETED on a server.
	pub(crate) fn log_delete(&self, name: &[u8], mode: u32) {
		let formats = &self.inner.formats;
		let item = LogItem { name, mode, iflags: ITEM_DELETED, op: "del.", ..LogItem::default() };
		let proto = self.inner.protocol.load(Ordering::Relaxed);
		let deleted_sink = lock(&self.inner.deleted).clone();
		if self.inner.cfg.am_server && proto >= 29 && name.len() < MAXPATHLEN {
			if let Some(sink) = deleted_sink {
				let mut payload = name.to_vec();
				if mode_is_dir(mode) {
					payload.push(0);
				}
				let _ = sink(&payload);
			}
		} else if self.levels().info(Info::Del) >= 1 || formats.stdout.is_some() {
			let format: &[u8] = match &formats.stdout {
				Some(format) if formats.stdout_has_o_or_i => format,
				_ => b"deleting %n",
			};
			self.formatted(LogCode::Client, format, &item, true);
		}
		if self.inner.cfg.dry_run {
			return;
		}
		if let Some(logfile) = &formats.logfile {
			let format: &[u8] = if formats.logfile_has_o_or_i { logfile } else { b"deleting %n" };
			self.formatted(LogCode::Log, format, &item, true);
		}
	}

	/// Flushes stdout and stderr (rflush).
	pub(crate) fn flush(&self) {
		let mut outputs = lock(&self.inner.outputs);
		if let Some(out) = outputs.out.as_mut() {
			let _ = out.flush();
		}
		if let Some(err) = outputs.err.as_mut() {
			let _ = err.flush();
		}
		if let LogTarget::File(file) = &mut outputs.log {
			let _ = file.flush();
		}
	}

	fn formatted(&self, code: LogCode, format: &[u8], item: &LogItem<'_>, from_delete: bool) {
		let cfg = &self.inner.cfg;
		let now = jiff::Timestamp::now().as_second();
		let env = FormatEnv {
			itemize: ItemizeCtx {
				local_server: cfg.local_server,
				preserve_mtimes: cfg.preserve_mtimes,
				receiver_symlink_times: self.inner.receiver_symlink_times.load(Ordering::Relaxed),
			},
			preserve_uid: cfg.preserve_uid,
			preserve_gid: cfg.preserve_gid,
			tz: &self.inner.tz,
			now,
			pid: std::process::id(),
			module: cfg.module.as_deref(),
			host: cfg.host.as_deref(),
			addr: cfg.addr.as_deref(),
			user: cfg.user.as_deref(),
			module_path: cfg.module_path.as_deref(),
			checksum: self.checksum_text(item),
		};
		let fitem = FormatItem {
			name: item.name,
			dir_prefix: item.dir_prefix,
			mode: if item.is_dir && item.mode == 0 { S_IFDIR } else { item.mode },
			size: item.size,
			mtime: item.mtime,
			uid: item.uid,
			gid: item.gid,
			skip_group: item.skip_group,
			link: item.link,
			hlink: item.hlink,
			iflags: item.iflags,
			op: item.op,
			bytes_xfer: item.bytes_xfer,
			bytes_csum: item.bytes_csum,
			from_delete,
		};
		match expand(format, &fitem, &env) {
			Ok(line) => self.emit(code, &line, false),
			Err(err) => {
				let mut text = err.message().into_bytes();
				text.push(b'\n');
				self.rprintf(LogCode::Error, &text);
				let mut fatal = lock(&self.inner.fatal);
				if fatal.is_none() {
					*fatal = Some(RsyncError::bare(exit::RERR_MESSAGEIO).at("log.c", 0));
				}
			}
		}
	}

	/// `%C`: the hex digest when one applies, else the blank width.
	fn checksum_text(&self, item: &LogItem<'_>) -> Result<Vec<u8>, usize> {
		let (xfer, file) = *lock(&self.inner.checksums);
		let always = self.inner.cfg.always_checksum;
		let kind = if always { file } else { xfer };
		// csum_len_for_type(kind, always).
		let len = if always { kind.flist_len() } else { kind.digest_len() };
		let regular = mode_is_reg(item.mode) && !item.is_dir;
		let applies = regular
			&& ((always && item.iflags & ITEM_DELETED == 0) || item.iflags & ITEM_TRANSFER != 0);
		if applies
			&& let Some(sum) = item.checksum
			&& let Some(hex) = sum_as_hex(kind, sum, len)
		{
			return Ok(hex);
		}
		Err(len * 2)
	}

	/// rwrite: routes one message.
	fn emit(&self, code: LogCode, buf: &[u8], is_utf8: bool) {
		let inner = &*self.inner;
		let cfg = &inner.cfg;
		let mut code = match code {
			LogCode::ErrorSocket | LogCode::ErrorUtf8 => LogCode::Error,
			other => other,
		};
		// Peer text is only treated differently with --iconv conversion, which this build
		// performs in the file-list layer; display filtering is the same either way.
		let _ = is_utf8;
		let mut outputs = lock(&inner.outputs);
		if code == LogCode::Client {
			code = LogCode::Info;
		} else if !matches!(outputs.log, LogTarget::Off) {
			if !outputs.in_block {
				outputs.in_block = true;
				let text = &buf[..buf.len().min(LOG_MSG_MAX)];
				let info = matches!(code, LogCode::Info | LogCode::Log);
				write_log(&mut outputs.log, text, info, &inner.tz);
				outputs.in_block = false;
			}
			if code == LogCode::Log {
				return;
			}
		} else if code == LogCode::Log {
			return;
		}
		let mut to_stderr = cfg.stderr_mode == STDERR_ALL;
		match code {
			LogCode::ErrorXfer => {
				inner.got_xfer_error.store(true, Ordering::Relaxed);
				to_stderr = true;
			}
			LogCode::Error | LogCode::Warning => to_stderr = true,
			LogCode::Info => {
				if cfg.quiet {
					return;
				}
			}
			_ => return,
		}
		if let Some(sink) = &inner.remote {
			let forward = match cfg.stderr_mode {
				STDERR_ERRORS => !to_stderr || outputs.err.is_none(),
				STDERR_CLIENT => true,
				// STDERR_ALL: nothing goes to the peer.
				_ => false,
			};
			if forward {
				let mut msg = code;
				if inner.protocol.load(Ordering::Relaxed) < 30 {
					msg = match msg {
						LogCode::Error => LogCode::ErrorXfer,
						LogCode::Warning => LogCode::Info,
						other => other,
					};
				}
				drop(outputs);
				if sink(msg, buf).is_ok() {
					return;
				}
				outputs = lock(&inner.outputs);
			}
			to_stderr = true;
		}
		let escape_8bit = !cfg.eight_bit_output;
		let validate_output = escape_8bit && !cfg.am_server && inner.remote.is_none();
		let mut line = Vec::with_capacity(buf.len() + 8);
		if inner.needs_newline.swap(0, Ordering::Relaxed) != 0 {
			line.push(b'\n');
		}
		let (body, trailing) = match buf.last() {
			Some(&last @ (b'\n' | b'\r')) => (&buf[..buf.len() - 1], Some(last)),
			_ => (buf, None),
		};
		let body = match body.split_first() {
			Some((b'\r', rest)) => {
				line.push(b'\r');
				rest
			}
			_ => body,
		};
		if validate_output && cfg.ascii_output {
			for chunk in body.chunk_by(|a, b| a.is_ascii() == b.is_ascii()) {
				if chunk[0].is_ascii() {
					filter_into(&mut line, chunk, false, false);
				} else {
					for &byte in chunk {
						push_octal(&mut line, byte);
					}
				}
			}
		} else if validate_output {
			for chunk in body.utf8_chunks() {
				filter_into(&mut line, chunk.valid().as_bytes(), false, false);
				for &byte in chunk.invalid() {
					push_octal(&mut line, byte);
				}
			}
		} else {
			filter_into(&mut line, body, escape_8bit, false);
		}
		if let Some(last) = trailing {
			line.push(last);
		}
		let use_err = to_stderr || outputs.out.is_none();
		let writer = if use_err { outputs.err.as_mut() } else { outputs.out.as_mut() };
		if let Some(writer) = writer {
			let _ = writer.write_all(&line);
			if trailing.is_some() {
				let _ = writer.flush();
			}
		}
	}
}

fn push_octal(out: &mut Vec<u8>, byte: u8) {
	out.extend_from_slice(format!("\\#{byte:03o}").as_bytes());
}

/// filtered_fwrite: escapes control characters (not tab), optionally non-ASCII-printable
/// bytes or C1 controls, and any literal `\#ddd` so it cannot be mistaken for an escape.
fn filter_into(out: &mut Vec<u8>, data: &[u8], escape_unprintable: bool, escape_c1: bool) {
	for (index, &byte) in data.iter().enumerate() {
		let looks_escaped = byte == b'\\'
			&& data.len() - index > 4
			&& data[index + 1] == b'#'
			&& data[index + 2..index + 5].iter().all(u8::is_ascii_digit);
		let unprintable = byte != b'\t'
			&& (byte < b' '
				|| (escape_unprintable && !(b' '..=b'~').contains(&byte))
				|| (escape_c1 && (0x80..=0x9f).contains(&byte)));
		if looks_escaped || unprintable {
			push_octal(out, byte);
		} else {
			out.push(byte);
		}
	}
}

/// logit: one log-file line `YYYY/MM/DD hh:mm:ss [pid] message` (or a syslog record).
fn write_log(target: &mut LogTarget, text: &[u8], info: bool, tz: &jiff::tz::TimeZone) {
	let (body, trailing) = match text.last() {
		Some(&last @ (b'\n' | b'\r')) => (&text[..text.len() - 1], Some(last)),
		_ => (text, None),
	};
	match target {
		LogTarget::Off => {}
		LogTarget::File(file) => {
			let mut line = format!(
				"{} [{}] ",
				timestring(jiff::Timestamp::now().as_second(), tz),
				std::process::id()
			)
			.into_bytes();
			filter_into(&mut line, body, false, true);
			line.extend(trailing);
			let _ = file.write_all(&line);
			let _ = file.flush();
		}
		LogTarget::Syslog => syslog(body, info),
	}
}

#[cfg(unix)]
fn syslog(text: &[u8], info: bool) {
	let clean: Vec<u8> = text.iter().copied().filter(|&byte| byte != 0).collect();
	let Ok(message) = std::ffi::CString::new(clean) else {
		return;
	};
	let priority = libc::LOG_DAEMON | if info { libc::LOG_INFO } else { libc::LOG_WARNING };
	// SAFETY: both pointers are valid NUL-terminated strings for the duration of the call,
	// and the "%s" format consumes exactly the one string argument passed.
	unsafe { libc::syslog(priority, c"%s".as_ptr(), message.as_ptr()) };
}

#[cfg(windows)]
fn syslog(_text: &[u8], _info: bool) {
	// Windows has no syslog; upstream builds without one drop these records.
}

/// The errno upstream would print for `err`. OS errors keep their own errno on unix (an
/// untrusted-symlink refusal is `ELOOP`, see [`crate::rsync::paths::os_errno`]); errno-less
/// (virtual filesystem) and Windows errors map their kind to the errno it stands for, `EIO`
/// when none does.
pub(crate) fn errno_of(err: &io::Error) -> i32 {
	#[cfg(unix)]
	if let Some(code) = crate::rsync::paths::os_errno(err) {
		return code;
	}
	kind_errno(err.kind()).unwrap_or(libc::EIO)
}

/// The `strerror` text of [`errno_of`]`(err)` on unix; an error without an errno
/// equivalent (and every Windows error) keeps its own text.
pub(crate) fn strerror(err: &io::Error) -> String {
	#[cfg(unix)]
	if let Some(code) =
		crate::rsync::paths::os_errno(err).or_else(|| kind_errno(err.kind()))
	{
		return crate::host::strip_errno(&io::Error::from_raw_os_error(code));
	}
	crate::host::strip_errno(err)
}

/// `strerror (errno)`, the tail of every rsyserr line.
pub(crate) fn syserr_suffix(err: &io::Error) -> String {
	format!("{} ({})", strerror(err), errno_of(err))
}

/// `rsync: [role] TEXT: strerror (errno)`, the text of upstream's rsyserr (for errors that
/// end the run instead of being logged).
pub(crate) fn syserr_text(role: Role, err: &io::Error, text: &str) -> String {
	format!("rsync: [{}] {text}: {}", role.name(), syserr_suffix(err))
}

/// The errno an error kind corresponds to.
fn kind_errno(kind: io::ErrorKind) -> Option<i32> {
	use io::ErrorKind as K;
	Some(match kind {
		K::NotFound => libc::ENOENT,
		K::PermissionDenied => libc::EACCES,
		K::AlreadyExists => libc::EEXIST,
		K::CrossesDevices => libc::EXDEV,
		K::NotADirectory => libc::ENOTDIR,
		K::IsADirectory => libc::EISDIR,
		K::InvalidInput => libc::EINVAL,
		K::FileTooLarge => libc::EFBIG,
		K::StorageFull => libc::ENOSPC,
		K::NotSeekable => libc::ESPIPE,
		K::ReadOnlyFilesystem => libc::EROFS,
		K::TooManyLinks => libc::EMLINK,
		K::BrokenPipe => libc::EPIPE,
		K::Deadlock => libc::EDEADLK,
		K::InvalidFilename => libc::ENAMETOOLONG,
		K::DirectoryNotEmpty => libc::ENOTEMPTY,
		K::Unsupported => libc::ENOSYS,
		K::OutOfMemory => libc::ENOMEM,
		K::ResourceBusy => libc::EBUSY,
		K::Interrupted => libc::EINTR,
		_ => return None,
	})
}

/// sum_as_hex of the first `len` bytes: canonical digests print in their public byte
/// order; seeded MD4 variants have no canonical form.
fn sum_as_hex(kind: CsumType, sum: &[u8], len: usize) -> Option<Vec<u8>> {
	let reversed = match kind {
		CsumType::None | CsumType::Md4Archaic | CsumType::Md4Old | CsumType::Md4Busted => {
			return None;
		}
		CsumType::Md4 | CsumType::Md5 | CsumType::Sha1 => false,
		CsumType::Xxh64 | CsumType::Xxh3 | CsumType::Xxh128 => true,
	};
	let len = len.min(sum.len());
	let bytes = &sum[..len];
	let mut out = Vec::with_capacity(len * 2);
	let mut push = |byte: u8| {
		out.extend_from_slice(format!("{byte:02x}").as_bytes());
	};
	if reversed {
		bytes.iter().rev().copied().for_each(&mut push);
	} else {
		bytes.iter().copied().for_each(&mut push);
	}
	Some(out)
}

#[cfg(test)]
mod tests {
	use super::*;
	use crate::rsync::consts::{ITEM_IS_NEW, ITEM_REPORT_PERMS, ITEM_REPORT_SIZE};

	#[derive(Clone, Default)]
	struct Buf(Arc<Mutex<Vec<u8>>>);

	impl Write for Buf {
		fn write(&mut self, data: &[u8]) -> io::Result<usize> {
			lock(&self.0).extend_from_slice(data);
			Ok(data.len())
		}

		fn flush(&mut self) -> io::Result<()> {
			Ok(())
		}
	}

	impl Buf {
		fn text(&self) -> String {
			String::from_utf8_lossy(&lock(&self.0)).into_owned()
		}

		fn bytes(&self) -> Vec<u8> {
			lock(&self.0).clone()
		}
	}

	fn utc() -> Option<jiff::tz::TimeZone> {
		Some(jiff::tz::TimeZone::UTC)
	}

	fn client(cfg: LogConfig) -> (Logger, Buf, Buf) {
		let (out, err) = (Buf::default(), Buf::default());
		(Logger::local(Box::new(out.clone()), Box::new(err.clone()), cfg), out, err)
	}

	fn base_cfg(format: &str) -> LogConfig {
		LogConfig {
			out_format: Some(format.as_bytes().to_vec()),
			human_readable: 1,
			local_server: true,
			preserve_mtimes: true,
			receiver_symlink_times: true,
			preserve_uid: true,
			preserve_gid: true,
			time_zone: utc(),
			levels: OutLevels::from_verbose(0),
			..LogConfig::default()
		}
	}

	#[test]
	fn routing_info_stdout_errors_stderr() {
		let (logger, out, err) = client(LogConfig::default());
		logger.rprintf(LogCode::Info, b"hello\n");
		logger.rprintf(LogCode::Error, b"bad\n");
		logger.rprintf(LogCode::Warning, b"warn\n");
		logger.rprintf(LogCode::Log, b"only the log\n");
		logger.rprintf(LogCode::Client, b"client\n");
		assert_eq!(out.text(), "hello\nclient\n");
		assert_eq!(err.text(), "bad\nwarn\n");
		assert!(!logger.got_xfer_error());
		logger.with_role(Role::Generator).rprintf(LogCode::ErrorXfer, b"x\n");
		assert!(logger.got_xfer_error());
	}

	#[test]
	fn quiet_and_stderr_all() {
		let (logger, out, err) = client(LogConfig { quiet: true, ..LogConfig::default() });
		logger.rprintf(LogCode::Info, b"hidden\n");
		logger.rprintf(LogCode::Error, b"shown\n");
		assert_eq!((out.text(), err.text()), (String::new(), "shown\n".to_owned()));
		let (logger, out, err) =
			client(LogConfig { stderr_mode: STDERR_ALL, ..LogConfig::default() });
		logger.rprintf(LogCode::Info, b"info\n");
		assert_eq!((out.text(), err.text()), (String::new(), "info\n".to_owned()));
	}

