	fn c_locale_escapes_high_bytes_unless_eight_bit_output_is_requested() {
		let (logger, out, _) = client(LogConfig { ascii_output: true, ..LogConfig::default() });
		logger.rprintf(LogCode::Info, "caf\u{e9}\t\u{7f}\\#123\u{1}\n".as_bytes());
