		);
		logger.log_item(LogCode::Info, &sample(b".", 0o040_755, 0));
		logger.set_checksums(CsumType::Xxh64, CsumType::Xxh64);
		logger.log_item(
			LogCode::Info,
			&LogItem { checksum: Some(&digest[..8]), ..sample(b"b", 0o100_644, ITEM_TRANSFER) },
		);
