	Serialize,
	Deserialize,
	strum::EnumString,
	strum::VariantNames,
	strum::EnumIter,
	strum::FromRepr,
)]
#[strum(serialize_all = "UPPERCASE")]
#[repr(u8)]
#[expect(missing_docs, reason = "each variant is the POSIX signal SIG<NAME>")]
pub enum Signal {
	Hup,
	Int,
	Quit,
	Ill,
	Trap,
	Abrt,
	Bus,
	Fpe,
