	std::fs::create_dir_all(&cwd).expect("cwd dir");
	let cwd_str = cwd.to_str().expect("utf8 cwd path");

	let mut env = HashMap::new();
	env.insert("HOME".to_string(), home.to_string_lossy().to_string());
	let config = ShellConfig {
