	let read = |name: &str| std::fs::read_to_string(tmp.join(name)).unwrap_or_default();

	// sort: reads piped stdin, parallel sort, writes sorted output.
	session
		.run_test("printf 'c\\na\\nb\\n' | sort > sort.txt", &params)
		.await
		.expect("sort");
