/// A restored embedded shell must retain the receiving host's env policy.
#[cfg(any(target_os = "linux", target_os = "macos"))]
#[tokio::test(flavor = "multi_thread")]
async fn fork_retains_env_policy_and_scoped_environment() {
	let _guard = shell_test_lock().lock().await;
	let dir = tempfile::tempdir().expect("scratch directory");
	let parent = Shell::new(None);
	async fn run(
		shell: &Shell,
		command: &str,
		cwd: &std::path::Path,
		env: Option<HashMap<String, String>>,
	) -> (ShellRunResult, String) {
		let (tx, rx) = flume::unbounded();
		let result = shell
			.run(
				ShellRunOptions {
					command: command.into(),
					cwd: Some(cwd.to_string_lossy().into_owned()),
					env,
					..Default::default()
				},
				Some(tx),
				CancelToken::default(),
			)
			.await
			.expect("run");
		(result, rx.drain().collect())
	}
	let (result, _) = run(&parent, "OMP_FORK_PERSIST=parent", dir.path(), None).await;
	assert_eq!(result.exit_code, Some(0));
	let (result, output) = run(
		&parent,
		"printf %s \"$OMP_FORK_TEMP\"",
		dir.path(),
		Some(HashMap::from([("OMP_FORK_TEMP".into(), "temporary".into())])),
	)
	.await;
	assert_eq!(result.exit_code, Some(0));
	assert_eq!(output, "temporary");
	let child = parent.fork();
	let grandchild = child.fork();
	for shell in [&parent, &child, &grandchild] {
		let (result, output) = run(
			shell,
			"printf '%s|%s' \"$OMP_FORK_PERSIST\" \"${OMP_FORK_TEMP-unset}\"",
			dir.path(),
			None,
		)
		.await;
		assert_eq!(result.exit_code, Some(0));
		assert_eq!(output, "parent|unset");
		let (result, _) =
			run(shell, "enable env; PATH= command env -i OMP_ENV_ONLY=1", dir.path(), None).await;
		assert_eq!(result.exit_code, Some(127), "embedded env must remain withheld");
		let (result, output) = run(
			shell,
			"PATH=/usr/bin:/bin; f() { :; }; export -f f; env -i /usr/bin/env",
			dir.path(),
			None,
		)
		.await;
		assert_eq!(result.exit_code, Some(0));
		assert_eq!(output, "", "external env must still clear inherited exports");
	}
	let (result, _) = run(&child, "OMP_FORK_PERSIST=child", dir.path(), None).await;
	assert_eq!(result.exit_code, Some(0));
	let (_, output) = run(&parent, "printf %s \"$OMP_FORK_PERSIST\"", dir.path(), None).await;
	assert_eq!(output, "parent");
}

//! `timeout`, `nohup` and `kill` through a [`Session`]: the engine, pi's
//! host and the tools' drive loop, with real processes.

#![cfg(unix)]

use std::{
	io::{Read as _, Seek as _},
	os::unix::{ffi::OsStrExt as _, process::ExitStatusExt as _},
	path::Path,
	time::{Duration, Instant},
};

use bstr::BString;
use tokio_util::sync::CancellationToken;

use crate::session::{RunOptions, RunStdio, Session, SessionConfig};

fn session() -> Session {
	let env = std::env::vars_os()
		.filter(|(name, _)| name != "PI_DISABLE_NOHUP_BUILTIN")
		.map(|(k, v)| (BString::from(k.as_bytes()), BString::from(v.as_bytes())))
		.collect();
	let cwd = std::env::current_dir().unwrap();
	Session::new(SessionConfig {
		env,
		cwd: BString::from(cwd.as_os_str().as_bytes()),
		fs: Box::new(crate::sys::StdFs::default()),
		vfs: None,
		runtime: tokio::runtime::Handle::current(),
		output_decoding: None,
	})
	.unwrap()
}

struct Ran {
	status:  i32,
	stdout:  String,
	stderr:  String,
	elapsed: Duration,
}

fn read_back(mut file: std::fs::File) -> String {
	file.rewind().unwrap();
	let mut text = String::new();
	file.read_to_string(&mut text).unwrap();
	text
}

async fn run_with(s: &mut Session, command: &str, cancel: CancellationToken) -> Ran {
	let (out, err) = (tempfile::tempfile().unwrap(), tempfile::tempfile().unwrap());
	let stdio = RunStdio {
		stdin:  Some(std::fs::File::open("/dev/null").unwrap()),
		stdout: Some(out.try_clone().unwrap()),
		stderr: Some(err.try_clone().unwrap()),
	};
	let started = Instant::now();
	let outcome = s
		.run_with(RunOptions::new(command), stdio, cancel)
		.await
		.unwrap();
	Ran {
		status:  outcome.status,
		stdout:  read_back(out),
		stderr:  read_back(err),
		elapsed: started.elapsed(),
	}
}

async fn run(s: &mut Session, command: &str) -> Ran {
	run_with(s, command, CancellationToken::new()).await
}

#[path = "../../test-support/child_reaper.rs"]
mod child_reaper;
#[cfg(target_os = "linux")]
use child_reaper::ChildReaper;
use child_reaper::alive;

/// Waits (bounded) for `pid` to be gone; whether it is.
async fn gone(pid: i32, within: Duration) -> bool {
	let start = Instant::now();
	while alive(pid) && start.elapsed() < within {
		tokio::time::sleep(Duration::from_millis(20)).await;
	}
	!alive(pid)
}

/// The pid an operand wrote to `file`, once it is there.
async fn pid_in(file: &Path) -> i32 {
	let start = Instant::now();
	loop {
		if let Some(pid) = std::fs::read_to_string(file)
			.ok()
			.and_then(|t| t.trim().parse().ok())
		{
			return pid;
		}
		assert!(start.elapsed() < Duration::from_secs(10), "no pid in {}", file.display());
		tokio::time::sleep(Duration::from_millis(10)).await;
	}
}

#[tokio::test(flavor = "multi_thread")]
async fn timeout_expires_with_124_and_leaves_no_process() {
	let mut s = session();
	let r = run(&mut s, "timeout 0.2 sleep 5").await;
	assert_eq!(r.status, 124, "{}", r.stderr);
