fn stat_of(node: &Node) -> Stat {
	let (kind, mode, size) = match node {
		Node::File { data, mode } => (StatKind::File, *mode, data.lock().len() as u64),
		Node::Dir { mode } => (StatKind::Dir, *mode, 0),
		Node::Null => (StatKind::CharDev, 0o666, 0),
		Node::Link { target } => (StatKind::Symlink, 0o755, target.len() as u64),
	};
	Stat {
		kind,
		mode,
		size,
		uid: 0,
		gid: 0,
		dev: 1,
		ino: 0,
		nlink: 1,
		mtime_ns: 0,
		atime_ns: 0,
		ctime_ns: 0,
		blocks: size.div_ceil(512),
		rdev: 0,
		blksize: 4096,
	}
}

impl Fs for MemFs {
	fn open(&mut self, path: &BStr, flags: OpenFlags, mode: u32) -> FsPoll<Box<dyn File>> {
		let res = self.open_now(path, flags, mode);
		self.answer(res)
	}

	fn stat(&mut self, path: &BStr, follow: bool) -> FsPoll<Stat> {
		let node = if follow {
			self.node(path)
		} else {
			self.lnode(path)
		};
		let res = node.map(|n| stat_of(&n));
		self.answer(res)
	}

	fn access(&mut self, path: &BStr, mode: Access) -> FsPoll<()> {
		let res = self.node(path).and_then(|n| {
			let bits = match n {
				Node::File { mode, .. } | Node::Dir { mode } => mode,
				Node::Null => 0o666,
				Node::Link { .. } => 0,
			};
			let need = [(Access::READ, 0o444), (Access::WRITE, 0o222), (Access::EXEC, 0o111)];
			if need
				.iter()
				.all(|&(a, b)| !mode.contains(a) || bits & b != 0)
			{
				Ok(())
			} else {
				Err(io::ErrorKind::PermissionDenied.into())
			}
		});
		self.answer(res)
	}

	fn read_dir(&mut self, path: &BStr) -> FsPoll<Box<dyn DirIter>> {
		let dir = trim(path);
		let res = match self.node(dir) {
			Ok(Node::Dir { .. }) => {
				let mut prefix = BString::from(dir);
				if !prefix.ends_with(b"/") {
					prefix.push(b'/');
				}
				let entries: VecDeque<DirEntry> = self
					.nodes
					.lock()
					.iter()
					.filter_map(|(p, n)| {
						let name = p.strip_prefix(prefix.as_slice())?;
						(!name.is_empty() && !name.contains(&b'/'))
							.then(|| DirEntry { name: BString::from(name), kind: Some(stat_of(n).kind) })
					})
					.collect();
				Ok(Box::new(MemDir(entries)) as Box<dyn DirIter>)
			},
			Ok(Node::File { .. } | Node::Null | Node::Link { .. }) => {
				Err(io::ErrorKind::NotADirectory.into())
			},
			Err(e) => Err(e),
		};
		self.answer(res)
	}

	fn readlink(&mut self, path: &BStr) -> FsPoll<BString> {
		let res = match self.lnode(path) {
			Ok(Node::Link { target }) => Ok(target),
			Ok(_) => Err(io::ErrorKind::InvalidInput.into()),
			Err(e) => Err(e),
		};
		self.answer(res)
	}

	fn realpath(&mut self, path: &BStr) -> FsPoll<BString> {
		let res = self.node(path).map(|_| BString::from(trim(path)));
		self.answer(res)
	}

	fn mkfifo_or_temp(&mut self, _purpose: TempPurpose) -> FsPoll<TempNode> {
		let n = self.temp_seq.fetch_add(1, Ordering::Relaxed);
		let path = format!("/tmp/obash-mem-{n}");
		self.add_file(&path, b"", 0o600);
		self.answer(Ok(TempNode { path: path.into(), fifo: false }))
	}

	fn chdir_check(&mut self, path: &BStr) -> FsPoll<()> {
		let res = match self.node(path) {
			Ok(Node::Dir { .. }) => Ok(()),
			Ok(Node::File { .. } | Node::Null | Node::Link { .. }) => {
				Err(io::ErrorKind::NotADirectory.into())
			},
			Err(e) => Err(e),
		};
		self.answer(res)
	}

	fn unlink(&mut self, path: &BStr) -> FsPoll<()> {
		let res = {
			let mut nodes = self.nodes.lock();
			match nodes.get(trim(path)) {
				Some(Node::Dir { .. }) => Err(io::ErrorKind::IsADirectory.into()),
				Some(_) => {
					nodes.remove(trim(path));
					Ok(())
				},
				None => Err(io::ErrorKind::NotFound.into()),
			}
		};
		self.answer(res)
	}

	fn rename(&mut self, from: &BStr, to: &BStr) -> FsPoll<()> {
		let res = {
			let (from, to) = (trim(from), trim(to));
			let mut nodes = self.nodes.lock();
			match (nodes.get(from), nodes.get(to)) {
				(None, _) => Err(io::ErrorKind::NotFound.into()),
				_ if !matches!(nodes.get(parent(to)), Some(Node::Dir { .. })) => {
					Err(io::ErrorKind::NotFound.into())
				},
				(Some(Node::Dir { .. }), Some(n)) if !matches!(n, Node::Dir { .. }) => {
					Err(io::ErrorKind::NotADirectory.into())
				},
				(Some(n), Some(Node::Dir { .. })) if !matches!(n, Node::Dir { .. }) => {
					Err(io::ErrorKind::IsADirectory.into())
				},
				(Some(Node::Dir { .. }), Some(Node::Dir { .. })) if has_children(&nodes, to) => {
					Err(io::ErrorKind::DirectoryNotEmpty.into())
				},
				_ if to.starts_with(from) && to.get(from.len()) == Some(&b'/') => {
					Err(io::ErrorKind::InvalidInput.into())
				},
				_ => {
					// The node and, for a directory, everything under it.
					let mut prefix = BString::from(from);
					prefix.push(b'/');
					let moved: Vec<BString> = nodes
						.keys()
						.filter(|k| k.as_slice() == from || k.starts_with(prefix.as_slice()))
						.cloned()
						.collect();
					for key in moved {
						if let Some(node) = nodes.remove(&key) {
							let mut dest = BString::from(to);
							dest.extend_from_slice(&key[from.len()..]);
							nodes.insert(dest, node);
						}
					}
					Ok(())
				},
			}
		};
		self.answer(res)
	}

	fn symlink(&mut self, target: &BStr, path: &BStr) -> FsPoll<()> {
		let res = {
			let mut nodes = self.nodes.lock();
			if nodes.contains_key(trim(path)) {
				Err(io::ErrorKind::AlreadyExists.into())
			} else if !matches!(nodes.get(parent(path)), Some(Node::Dir { .. })) {
				Err(io::ErrorKind::NotFound.into())
			} else {
				nodes.insert(BString::from(trim(path)), Node::Link { target: BString::from(target) });
				Ok(())
			}
		};
		self.answer(res)
	}

	fn link(&mut self, from: &BStr, to: &BStr) -> FsPoll<()> {
		let res = match self.lnode(from) {
			Ok(node) => {
				let mut nodes = self.nodes.lock();
				if nodes.contains_key(trim(to)) {
					Err(io::ErrorKind::AlreadyExists.into())
				} else {
					// Files share their data, as hard links do.
					nodes.insert(BString::from(trim(to)), node);
					Ok(())
				}
			},
			Err(e) => Err(e),
		};
		self.answer(res)
	}

	fn mkdir(&mut self, path: &BStr, mode: u32) -> FsPoll<()> {
		let res = {
			let path = trim(path);
			let mut nodes = self.nodes.lock();
			if nodes.contains_key(path) {
				Err(io::ErrorKind::AlreadyExists.into())
			} else {
				match nodes.get(parent(path)) {
					Some(Node::Dir { .. }) => {
						nodes.insert(BString::from(path), Node::Dir { mode: mode & 0o7777 });
						Ok(())
					},
					Some(_) => Err(io::ErrorKind::NotADirectory.into()),
					None => Err(io::ErrorKind::NotFound.into()),
				}
			}
		};
		self.answer(res)
	}

	fn rmdir(&mut self, path: &BStr) -> FsPoll<()> {
		let res = {
			let path = trim(path);
			let mut nodes = self.nodes.lock();
			match nodes.get(path) {
				Some(Node::Dir { .. }) if has_children(&nodes, path) => {
					Err(io::ErrorKind::DirectoryNotEmpty.into())
				},
				Some(Node::Dir { .. }) => {
					nodes.remove(path);
					Ok(())
				},
				Some(_) => Err(io::ErrorKind::NotADirectory.into()),
				None => Err(io::ErrorKind::NotFound.into()),
			}
		};
		self.answer(res)
	}

	fn chmod(&mut self, path: &BStr, mode: u32) -> FsPoll<()> {
		let res = self.update(path, |node| match node {
			Node::File { mode: m, .. } | Node::Dir { mode: m } => {
				*m = mode & 0o7777;
				Ok(())
			},
			// `/dev/null` keeps its bits; a dangling link has no target.
			Node::Null => Ok(()),
			Node::Link { .. } => Err(io::ErrorKind::NotFound.into()),
		});
		self.answer(res)
	}

	fn sync(&mut self) -> FsPoll<()> {
		// Nothing is buffered on the way to memory.
		self.answer(Ok(()))
	}

	fn lock(&mut self, path: &BStr) -> FsPoll<Box<dyn File>> {
		let resolved = self.resolve_links(path);
		let res = if self.locks.lock().contains(&resolved) {
			Err(io::ErrorKind::WouldBlock.into())
		} else {
			self
				.open_now(&resolved, OpenFlags::READ.with(OpenFlags::WRITE), 0)
				.map(|file| {
					self.locks.lock().insert(resolved.clone());
					Box::new(LockedFile { file, locks: Arc::clone(&self.locks), path: resolved })
						as Box<dyn File>
				})
		};
		self.answer(res)
	}
}

/// A file a [`Fs::lock`] holds; dropping it releases the lock.
struct LockedFile {
	file:  Box<dyn File>,
	locks: Arc<Mutex<std::collections::BTreeSet<BString>>>,
	path:  BString,
}

impl Drop for LockedFile {
	fn drop(&mut self) {
		self.locks.lock().remove(&self.path);
	}
}

impl File for LockedFile {
	fn poll_read(&mut self, cx: &mut Context<'_>, buf: &mut [u8]) -> Poll<io::Result<usize>> {
		self.file.poll_read(cx, buf)
	}

	fn poll_write(&mut self, cx: &mut Context<'_>, buf: &[u8]) -> Poll<io::Result<usize>> {
		self.file.poll_write(cx, buf)
	}

	fn poll_flush(&mut self, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
		self.file.poll_flush(cx)
	}

	fn seek(&mut self, pos: SeekFrom) -> io::Result<u64> {
		self.file.seek(pos)
	}

	fn kind(&self) -> FileKind {
		FileKind::Regular
	}

	fn os_handle(&self) -> Option<OsHandle> {
		None
	}

	fn dup(&self) -> io::Result<Box<dyn File>> {
		self.file.dup()
	}
}

#[cfg(test)]
mod tests {
	use std::task::Wake;

	use super::*;

	struct Unpark(thread::Thread);

	impl Wake for Unpark {
		fn wake(self: Arc<Self>) {
			self.0.unpark();
		}
	}

	fn resolve<T>(p: FsPoll<T>) -> io::Result<T> {
		match p {
			FsPoll::Ready(r) => r,
			FsPoll::Pending(mut f) => {
				let waker = Waker::from(Arc::new(Unpark(thread::current())));
				let mut cx = Context::from_waker(&waker);
				loop {
					if let Poll::Ready(r) = f.poll(&mut cx) {
						return r;
					}
					thread::park_timeout(Duration::from_millis(20));
				}
			},
		}
	}

	#[test]
	fn forced_pending_poll_yields_and_wakes_even_after_the_timer_is_ready() {
		struct CountWake(AtomicU64);
		impl Wake for CountWake {
			fn wake(self: Arc<Self>) {
				self.0.fetch_add(1, Ordering::Relaxed);
			}
		}
		let wakes = Arc::new(CountWake(AtomicU64::new(0)));
		let waker = Waker::from(Arc::clone(&wakes));
		let mut cx = Context::from_waker(&waker);
		let mut delayed = Delayed::start(Ok(7), 0, true);
		// Model a timer that completed before the engine's first poll, without
		// sleeping.
		delayed.ready.store(true, Ordering::Release);
		assert!(delayed.poll(&mut cx).is_pending());
		assert_eq!(wakes.0.load(Ordering::Relaxed), 1);
		assert!(matches!(delayed.poll(&mut cx), Poll::Ready(Ok(7))));
	}

	#[test]
	fn full_latency_makes_every_operation_pending_but_correct() {
		let mut fs = MemFs::with_latency(7, 1.0, 3);
		fs.add_file("/bin/tool", b"x", 0o755);
		assert!(matches!(fs.stat(b"/bin/tool".as_bstr(), true), FsPoll::Pending(_)));
		assert_eq!(resolve(fs.stat(b"/bin/tool".as_bstr(), true)).unwrap().kind, StatKind::File);
		assert!(resolve(fs.access(b"/bin/tool".as_bstr(), Access::EXEC)).is_ok());
		assert_eq!(
			resolve(fs.stat(b"/nope".as_bstr(), true))
				.unwrap_err()
				.kind(),
			io::ErrorKind::NotFound
		);
		assert_eq!(fs.pending_count(), 4);
	}

	#[test]
	fn access_checks_mode_bits() {
		let mut fs = MemFs::new();
		fs.add_file("/a", b"", 0o644);
		assert_eq!(
			resolve(fs.access(b"/a".as_bstr(), Access::EXEC))
				.unwrap_err()
				.kind(),
			io::ErrorKind::PermissionDenied
		);
		assert!(resolve(fs.access(b"/a".as_bstr(), Access::READ)).is_ok());
	}

	#[test]
	fn injected_faults_surface_as_their_errno_text() {
		let mut fs = MemFs::new().with_faults(1.0, &[FaultKind::Eio]);
		let err = resolve(fs.stat(b"/".as_bstr(), true)).unwrap_err();
		assert_eq!(crate::bash::diag::strerror(&err), "Input/output error");
		let mut fs = MemFs::new().with_faults(1.0, &[FaultKind::Enospc]);
		let err = resolve(fs.stat(b"/".as_bstr(), true)).unwrap_err();
		assert_eq!(crate::bash::diag::strerror(&err), "No space left on device");
	}

	#[test]
	fn directories_list_direct_children_only() {
		let mut fs = MemFs::new();
		fs.add_file("/d/a", b"", 0o644);
		fs.add_file("/d/sub/b", b"", 0o644);
		let mut it = resolve(fs.read_dir(b"/d".as_bstr())).unwrap();
		let waker = Waker::noop();
		let mut cx = Context::from_waker(waker);
		let mut names = Vec::new();
		while let Poll::Ready(Some(Ok(e))) = it.poll_next(&mut cx) {
			names.push(e.name.to_string());
		}
		assert_eq!(names, ["a", "sub"]);
	}

	#[test]
	fn create_truncate_and_append() {
		let mut fs = MemFs::new();
		let waker = Waker::noop();
		let mut cx = Context::from_waker(waker);
		let w = OpenFlags::WRITE.with(OpenFlags::CREATE);
		let mut f = resolve(fs.open(b"/tmp/x".as_bstr(), w.with(OpenFlags::TRUNC), 0o644)).unwrap();
		let _ = f.poll_write(&mut cx, b"abc");
		let mut f = resolve(fs.open(b"/tmp/x".as_bstr(), w.with(OpenFlags::APPEND), 0o644)).unwrap();
		let _ = f.poll_write(&mut cx, b"de");
		assert_eq!(fs.read("/tmp/x").unwrap(), b"abcde");
		assert!(resolve(fs.open(b"/missing/x".as_bstr(), w, 0o644)).is_err());
	}
}

//! A background job that is just one external program is known by that
//! program's OS pid, as in bash (whose subshell `exec`s it): `$!`, `jobs
//! -l`/`-p`/`-x` show it, and `kill`, `wait`, `wait -n -p` and `disown`
//! take it. Compound jobs keep their virtual pids. A signal to such a job
//! (or to a pipeline job's stages) reaches the program, which may trap it,
//! and the job ends with the program's real status once it exited. A lone
//! external's redirection whose open would wait (a FIFO) is left to the
//! process when the host allows it (`Host::child_opens`), so `$!` never
//! waits on that rendezvous. References: bash 5.3.20 (`bash -c`).

use std::{
	io,
	sync::{
		Arc,
		atomic::{AtomicU32, Ordering},
	},
	task::{Context, Poll, Waker},
};

use bstr::BString;
use parking_lot::Mutex;

use crate::{
	bash::{
		Budget, CallId, CallOutcome, ChildRedir, ChildRedirs, Cx, ExitStatus, ExtProc, Lineage,
		OpenFlags, RunId, Script, ShellApi, Signal, SpawnSpec, Step, Vpid,
	},
	testkit::{FakeHost, Fault, MemFs, Rig, fault::skeleton_init, run::wait_runnable, run_script},
};

/// First OS pid the fake spawner hands out.
const FIRST: u32 = 5001;

/// Every redirection list a spawn was handed, by argv[0].
type RedirLog = Arc<Mutex<Vec<(BString, Option<ChildRedirs>)>>>;

/// What the fake externals saw: every signal delivered, by pid, and the
/// redirections each spawn left to its process.
#[derive(Clone, Default)]
struct World {
	next:    Arc<AtomicU32>,
	signals: Arc<Mutex<Vec<(u32, Signal)>>>,
	redirs:  RedirLog,
}

impl World {
	fn new() -> Self {
		let w = Self::default();
		w.next.store(FIRST, Ordering::SeqCst);
		w
	}

	/// A host whose externals are fakes by name: `/x/true` exits 0 at once,
	/// `/x/trap42` and `/x/trap43` exit 42 or 43 on `TERM` (a trap), any
	/// other runs until a terminating signal kills it.
	fn host(&self) -> FakeHost {
		let world = self.clone();
		FakeHost::new().with_spawner(Box::new(move |spec: SpawnSpec<'_>| {
			let pid = world.next.fetch_add(1, Ordering::SeqCst);
			world
				.redirs
				.lock()
				.push((spec.argv[0].clone(), spec.redirs.clone()));
			let (status, trap) = match spec.argv[0].as_slice() {
				b"/x/true" => (Some(ExitStatus::Exited(0)), None),
				b"/x/trap42" => (None, Some(42)),
				b"/x/trap43" => (None, Some(43)),
				_ => (None, None),
			};
			let signals = Arc::clone(&world.signals);
			Ok(Box::new(Fake { pid, status, trap, signals, waker: None }) as Box<dyn ExtProc>)
		}))
	}

	/// The signals pid `pid` got.
	fn got(&self, pid: u32) -> Vec<Signal> {
		self
			.signals
			.lock()
			.iter()
			.filter(|(p, _)| *p == pid)
			.map(|(_, sig)| *sig)
			.collect()
	}
}

/// A fake external process.
struct Fake {
	pid:     u32,
	status:  Option<ExitStatus>,
	/// Exit status a `TERM` trap exits with.
	trap:    Option<i32>,
	signals: Arc<Mutex<Vec<(u32, Signal)>>>,
	waker:   Option<Waker>,
}

impl ExtProc for Fake {
	fn pid(&self) -> u32 {
		self.pid
	}

	fn poll_wait(&mut self, cx: &mut Context<'_>) -> Poll<ExitStatus> {
		if let Some(status) = self.status {
			Poll::Ready(status)
		} else {
			self.waker = Some(cx.waker().clone());
			Poll::Pending
		}
	}

	fn signal(&mut self, sig: Signal) -> io::Result<()> {
		self.signals.lock().push((self.pid, sig));
		if matches!(sig, Signal::Term | Signal::Kill) && self.status.is_none() {
			self.status = Some(match self.trap {
				Some(code) if sig == Signal::Term => ExitStatus::Exited(code),
				_ => ExitStatus::Signaled(sig),
			});
			if let Some(waker) = self.waker.take() {
				waker.wake();
			}
		}
		Ok(())
	}

	fn stop(&mut self) -> io::Result<()> {
		Ok(())
	}

	fn cont(&mut self) -> io::Result<()> {
		Ok(())
	}
}

/// Run `src` on a fresh rig over `host`: its stdout and status.
fn run(host: FakeHost, src: &str) -> (String, i32) {
	let out = run_script(host, src.as_bytes(), &[], Fault::None);
	(String::from_utf8_lossy(&out.stdout).into_owned(), out.status)
}

/// Enough work for the shell's slices to let a pipeline job start its
/// stages' programs (a pipeline's `$!` does not wait for them).
const BUSY: &str = "n=0; while (( n < 3000 )); do n=$((n + 1)); done";

/// Whether `word` is a virtual pid.
fn is_virtual(word: &str) -> bool {
	word.parse::<u32>().is_ok_and(|pid| pid >= Vpid::BASE)
}

// Failure mode: `$!` of `cmd &` is the job's virtual pid, so the pid the
// program reports (`/bin/sh -c 'echo $$'`) is not the one the shell shows,
// and `kill`/`wait` of the program's pid miss the job.
#[test]
fn a_lone_external_job_is_known_by_its_os_pid() {
	let world = World::new();
	let (out, status) = run(
		world.host(),
		"/x/sleeper & echo \"$!\"; jobs -p; jobs -l; kill \"$!\"; wait \"$!\"; echo \"st=$? \
		 last=$!\"",
	);
	assert_eq!(status, 0, "{out}");
	let lines: Vec<&str> = out.lines().collect();
	assert_eq!(lines[0], "5001", "{out}");
	assert_eq!(lines[1], "5001", "{out}");
	assert!(lines[2].starts_with("[1]+  5001 Running"), "{out}");
	assert_eq!(lines[3], "st=143 last=5001", "{out}");
	assert_eq!(world.got(FIRST), [Signal::Term]);
}

// Failure mode: prefix assignments, redirections, `command`, `exec` in a
// group or a function hide the program behind the job's virtual pid.
#[test]
fn assignments_redirections_and_exec_keep_the_os_pid() {
	let world = World::new();
	let (out, _) = run(
		world.host(),
		"FOO=1 /x/true >out & a=$!; { exec /x/true; } & b=$!; f() { exec /x/true; }; f & c=$!; \
		 command /x/true & d=$!; wait; echo $a $b $c $d",
	);
	assert_eq!(out, "5001 5002 5003 5004\n");
}

// Failure mode: a compound job, a builtin, a function running its external
// as one command of its own, or a subshell group reports the pid of one of
// the programs it runs.
#[test]
fn compound_and_builtin_jobs_keep_virtual_pids() {
	let world = World::new();
	let (out, _) = run(
		world.host(),
		"{ :; /x/true; } & a=$!; : & b=$!; f() { /x/true; }; f & c=$!; ( /x/true ) & e=$!; { \
		 /x/true; } & g=$!; wait; echo $a $b $c $e $g",
	);
	let pids: Vec<&str> = out.split_whitespace().collect();
	assert_eq!(pids.len(), 5, "{out}");
	assert!(pids.iter().all(|p| is_virtual(p)), "{out}");
}

// Failure mode: a background pipeline's `$!` is the shell's virtual pid,
// which `kill` cannot reach as a program, instead of its last program's
// (bash: `kill $!` signals that program), also under `!` and `time`.
#[test]
fn a_background_pipeline_is_known_by_its_last_program() {
	for prefix in ["", "! ", "time "] {
		let world = World::new();
		let (out, _) =
			run(world.host(), &format!("{prefix}/x/true | /x/trap42 & p=$!; kill $p; wait; echo $p"));
		let last = world
			.redirs
			.lock()
			.iter()
			.position(|(argv0, _)| argv0.as_slice() == b"/x/trap42")
			.expect("the last stage ran");
		let pid = FIRST + last as u32;
		assert_eq!(out, format!("{pid}\n"), "{prefix:?}");
		assert_eq!(world.got(pid), [Signal::Term], "{prefix:?}");
	}
}

// Failure mode: once a pipeline's last program ended, `kill` of its pid
// (`$!`) still reaches the job its other stages keep running (bash: no
// such process, status 1).
#[test]
fn an_ended_last_stage_is_no_longer_signalled() {
	let world = World::new();
	let (out, _) = run(
		world.host(),
		&format!("/x/sleeper | /x/true & p=$!; {BUSY}; kill -0 $p; echo $?; kill %1; wait"),
	);
	assert_eq!(out, "1\n");
	assert_eq!(world.got(FIRST), [Signal::Term], "only `kill %1` reached the first stage");
}

// Failure mode: `wait -n -p` names the virtual pid while `$!` showed the OS
// pid, `disown` of the OS pid finds no job, or `kill`/`wait` of a disowned
// job's OS pid no longer reach it.
#[test]
fn wait_p_and_disown_take_the_os_pid() {
	let world = World::new();
	let (out, _) = run(
		world.host(),
		"/x/true & p=$!; wait -n -p v; echo \"$v $p\"; /x/sleeper & q=$!; disown \"$q\"; echo \
		 \"disown=$? jobs=$(jobs -p)\"; kill \"$q\"; wait \"$q\"; echo $?",
	);
	assert_eq!(out, "5001 5001\ndisown=0 jobs=\n143\n");
}

// Failure mode: a job whose program traps `TERM` is marked done (143) when
// the shell signals it, though the program goes on and exits 43 later
// (bash: `st=43`).
#[test]
fn a_signalled_lone_external_ends_with_its_own_status() {
	let world = World::new();
	let (out, _) = run(
		world.host(),
		// `: $!` waits until the job runs its program (as bash's job has by
		// the time it traps).
		"/x/trap43 & : $!; kill %1; wait %1; echo \"job=$?\"; /x/trap43 & kill $!; wait $!; echo \
		 \"pid=$?\"",
	);
	assert_eq!(out, "job=43\npid=43\n");
	assert_eq!(world.got(FIRST), [Signal::Term], "one TERM, not one per path");
	assert_eq!(world.got(FIRST + 1), [Signal::Term]);
}

// Failure mode: `kill %1` of a pipeline job ends the job at once with 143
// while its stages run on (bash: the stages' own statuses, `42 43`).
#[test]
fn a_signalled_pipeline_job_ends_with_its_stages_statuses() {
	let world = World::new();
	let (out, _) = run(
		world.host(),
		&format!(
			"/x/trap42 | /x/trap43 & {BUSY}; kill -STOP %1; kill -CONT %1; kill %1; wait %1; echo $?"
		),
	);
	assert_eq!(out, "43\n");
	for pid in [FIRST, FIRST + 1] {
		let terms = world
			.got(pid)
			.iter()
			.filter(|&&s| s == Signal::Term)
			.count();
		assert_eq!(terms, 1, "stage {pid}: {:?}", world.got(pid));
	}
}

// Failure mode: a restored shell forgets the OS pid its job is known by
// (`$!`, `jobs -p`), or a snapshot taken while a job decides loses that
// decision.
#[test]
fn the_os_pid_survives_snapshots() {
	let world = World::new();
	let mut r = Rig::new(world.host(), skeleton_init(&[]));
	assert_eq!(r.run(Script::command(&b"/x/sleeper &"[..]), Fault::None), 0);
	// Let the job reach its external.
	let (shell, host, store) = r.parts();
	while let Step::Yield | Step::Done { .. } =
		shell.step(&mut Cx { host: &mut *host, store: &mut *store }, Budget::default())
	{}
	r.snapshot();
	assert_eq!(r.run(Script::command(&b"echo $!; jobs -p"[..]), Fault::None), 0);
	assert_eq!(r.host.stdout.bytes(), b"5001\n5001\n");

	let base =
		run_script(World::new().host(), b"/x/true & echo $!; wait $!; echo $?", &[], Fault::None);
	let hit = run_script(
		World::new().host(),
		b"/x/true & echo $!; wait $!; echo $?",
		&[],
		Fault::Snapshot { every: 1 },
	);
	assert!(hit.snapshots > 0, "no snapshot landed");
	assert_eq!((hit.stdout.as_slice(), hit.status), (&b"5001\n0\n"[..], 0));
	assert_eq!(hit.stdout, base.stdout);
}

/// Runs `src`, answering each call of `tool` by running its operands in a
/// subshell: with [`ShellApi::exec_subshell_in`] (a `nohup` that `exec`s)
/// when `exec`, else [`ShellApi::run_subshell_in`].
fn drive(world: &World, tool: &str, exec: bool, src: &str) -> String {
	let mut host = world.host();
	host.tool(
		tool,
		Arc::new(|_: &mut ShellApi<'_, '_>, _: &[BString]| -> CallOutcome {
			unreachable!("the test driver answers the tool")
		}),
	);
	let mut r = Rig::new(host, skeleton_init(&[]));
	let (shell, host, store) = r.parts();
	let main = shell.submit(Script::command(src.as_bytes().to_vec()));
	let mut pending: Vec<(CallId, RunId)> = Vec::new();
	loop {
		match shell.step(&mut Cx { host: &mut *host, store: &mut *store }, Budget::default()) {
			Step::Done { run, status } if run == main => {
				assert_eq!(status, 0);
				break;
			},
			Step::Done { run, status } => {
				if let Some(at) = pending.iter().position(|&(_, r)| r == run) {
					let (id, _) = pending.remove(at);
					shell.complete(id, CallOutcome::Exit(status));
				}
			},
			Step::Call { id, call } => {
				let mut cx = Cx { host: &mut *host, store: &mut *store };
				let mut api = shell.api(&mut cx, id).expect("call is outstanding");
				let mut script = Script::command(&b"\"$@\""[..]);
				script.args = Some(call.argv[1..].to_vec());
				let lineage = Lineage { label: 0, detached: exec };
				let run = if exec {
					api.exec_subshell_in(script, lineage)
				} else {
					api.run_subshell_in(script, lineage)
				};
				pending.push((id, run));
			},
			Step::Yield => {},
			Step::Blocked => {
				if !host.fire_next_timer() {
					wait_runnable(&shell.control());
				}
			},
			other => panic!("{other:?} while `{src}` runs"),
		}
	}
	String::from_utf8_lossy(&r.host.stdout.bytes()).into_owned()
}

// Failure mode: `nohup cmd &` (a host callout that runs its operand in a
// subshell, as `nohup` `exec`s it) shows the callout's virtual pid instead of
// the program's, or any other callout's job claims its subshell's program.
#[test]
fn an_exec_like_callout_hands_its_job_to_the_program() {
	let world = World::new();
	assert_eq!(drive(&world, "nohup", true, "nohup /x/true & echo $!; wait"), "5001\n");
	let other = World::new();
	let out = drive(&other, "wrap", false, "wrap /x/true & echo $!; wait");
	assert!(is_virtual(out.trim()), "{out}");
}

// Failure mode: `cmd > fifo & bg=$!` never returns: the job opened the FIFO
// before spawning its program, and `$!` waited for that open, whose other
// end is the shell's next command. The open is left to the process (bash's
// forked child opens it); without the host's consent the job keeps its
// virtual pid rather than wait.
#[test]
fn a_redirection_that_would_wait_is_left_to_the_process() {
	let world = World::new();
	let fs = MemFs::with_latency(7, 1.0, 1).with_pending_first_poll();
	let host = world.host().with_fs(fs).with_child_opens();
	let (out, _) = run(host, "/x/sleeper > /f 2>&1 & echo $!; kill $!; wait $!; echo $?");
	assert_eq!(out, "5001\n143\n");
	let seen = world.redirs.lock().clone();
	let Some((name, Some(redirs))) = seen.first() else {
		panic!("the spawn got no redirections: {seen:?}");
	};
	assert_eq!(name, "/x/sleeper");
	let [ChildRedir::Open { fds, path, flags, mode, diag }, ChildRedir::Dup { fd: 2, src: 1, .. }] =
		redirs.list.as_slice()
	else {
		panic!("{redirs:?}");
	};
	assert_eq!((fds.as_slice(), path.as_slice(), *mode), (&[1][..], &b"/f"[..], 0o644));
	assert_eq!(
		*flags,
		OpenFlags::WRITE
			.with(OpenFlags::CREATE)
			.with(OpenFlags::TRUNC)
	);
	assert!(diag.ends_with(b"/f: ") && diag.starts_with(b"bash: "), "{diag}");
	assert!(redirs.exec_diag.ends_with(b"/x/sleeper: "), "{}", redirs.exec_diag);

	// A builtin opens it here: the job keeps its virtual pid at once.
	let fs = MemFs::with_latency(7, 1.0, 1).with_pending_first_poll();
	fs.add_file("/g", b"line\n", 0o644);
	let host = World::new().host().with_fs(fs).with_child_opens();
	let (out, _) = run(host, "read x < /g & echo $!; wait");
	assert!(is_virtual(out.trim()), "{out}");

	// Without the host's consent the engine opens it: virtual pid, no wait.
	let world = World::new();
	let host = world
		.host()
		.with_fs(MemFs::with_latency(7, 1.0, 1).with_pending_first_poll());
	let (out, _) = run(host, "/x/true > /f & echo $!; wait");
	assert!(is_virtual(out.trim()), "{out}");
	assert!(world.redirs.lock().iter().all(|(_, r)| r.is_none()));
}

//! pi's commands that need more than argv and stdio: host callouts
//! ([`Resolved::Tool`](crate::bash::Resolved::Tool)) that run their operands in
//! subshells of the caller through the engine.
//!
//! - `timeout`: runs its command in a labeled subshell
//!   ([`ShellApi::run_subshell_in`]), signals that tree at the deadline
//!   ([`SigTarget::Label`](crate::bash::SigTarget::Label)), waits for it and
//!   the externals it started, and escalates to `KILL` after `-k`.
//! - `nohup`: runs its command in a detached tree ([`Lineage::detached`]): the
//!   shell's cancel spares it and the spawner leaves its externals running when
//!   the shell is torn down.
//! - `git` (with `PI_SMART_GIT` or `PI_GIT_GUARD`): the [`crate::git`] layers
//!   on a worker thread, then the git binary found on `PATH`, by absolute path
//!   so it never resolves back to the tool.
//! - pi's extras that run command lines (`env`, `ifne`, `xargs`, `find`): the
//!   utility runs on the session's runtime, and each command it runs is a
//!   subshell of the caller ([`crate::extras`] for the other extras).
//!
//! The engine reports a callout as [`Step::Call`](crate::bash::Step::Call);
//! the session driver owns a [`ToolCalls`] and hands it every call, every
//! [`Step::Done`](crate::bash::Step::Done) of a run that is not its own, and a
//! [`ToolCalls::poll`] on each turn, parking no longer than
//! [`ToolCalls::next_deadline`]. A tool's subshells are ordinary runs of the
//! engine: functions, builtins and externals run as anywhere else, and the
//! tool only watches their `Done`.
//!
//! The `kill` builtin is the engine's intrinsic (`%job` operands stay on the
//! virtual signal bus); the host's policy for OS pids is
//! [`crate::host::check_signal_target`].

mod extra;
mod git;
mod nohup;
mod timeout;

use std::{collections::VecDeque, sync::Arc, task::Waker, time::Duration};

use bstr::{BStr, BString, ByteSlice};
use parking_lot::Mutex;

use crate::{
	bash::{
		CallId, CallOutcome, ControlHandle, Cx, IoPoll, Lineage, NativeRef, RunId, Script, Shell,
		ShellApi, ToolCall, ToolRef,
	},
	extras::{ExtrasGate, ReportedError},
	git::{GitLayers, flag_on},
	vfs::VfsFs,
};

const TIMEOUT: ToolRef = ToolRef(1);
const NOHUP: ToolRef = ToolRef(2);
const GIT: ToolRef = ToolRef(3);
/// Every extra that runs command lines; `argv[0]` names it.
const EXTRA: ToolRef = ToolRef(4);

/// Which tools a session offers; fixed when the session starts, as pi
/// registers its builtins once per shell.
#[derive(Clone, Default)]
pub struct ToolConfig {
	/// Withhold the in-process env wrapper at the embedded Shell boundary.
	pub withhold_env:   bool,
	/// `nohup` is the tool (off with `PI_DISABLE_NOHUP_BUILTIN`: the system
	/// binary runs).
	pub nohup:          bool,
	/// The `git` layers on at the start; `git` is the binary when none is.
	/// Each call reads the layers again from its own environment, so a
	/// command can turn one off (`PI_GIT_GUARD=0 git …`).
	pub git:            GitLayers,
	/// The session's filesystem slot ([`VfsFs::filesystem`], read per call):
	/// what pi's extras run on, and whose native paths in-process `git
	/// worktree add` may touch. `None` when every path is native (`StdFs`).
	pub vfs:            Option<VfsFs>,
	/// pi's extras the shell offers (`PI_DISABLE_UUTILS_*`).
	pub extras:         ExtrasGate,
	/// Where the extras that run command lines run; without one they fail.
	pub runtime:        Option<tokio::runtime::Handle>,
	/// The reported-error flag of the command in flight, for the extras.
	pub reported_error: ReportedError,
}

impl ToolConfig {
	/// The tools and extras a shell started with environment `env` offers,
	/// on the filesystem slot `vfs`, running extras on `runtime`.
	pub fn from_env(
		env: &[(BString, BString)],
		vfs: Option<VfsFs>,
		runtime: tokio::runtime::Handle,
	) -> Self {
		let var = |name: &str| {
			env.iter()
				.rev()
				.find(|(k, _)| k == name.as_bytes())
				.and_then(|(_, v)| v.to_str().ok())
		};
		Self {
			withhold_env: false,
			nohup: !flag_on(var("PI_DISABLE_NOHUP_BUILTIN")),
			git: GitLayers::from_env(var),
			vfs,
			extras: ExtrasGate::from_env(var),
			runtime: Some(runtime),
			reported_error: ReportedError::default(),
		}
	}

	/// The tool `name` resolves to, if it is one of these.
	pub fn lookup(&self, name: &BStr) -> Option<ToolRef> {
		match name.as_bytes() {
			// Preserve the fork embedding policy through the shell-engine
			// migration. Use the system env until the new in-process path is
			// independently validated.
			b"env" if self.withhold_env => None,
			b"timeout" => Some(TIMEOUT),
			b"nohup" if self.nohup => Some(NOHUP),
			b"git" if self.git.any() => Some(GIT),
			_ if self.extras.runs_commands(name) => Some(EXTRA),
			_ => None,
		}
	}

	/// The extra `name` resolves to when it is an offered extra that runs
	/// as a task ([`crate::extras::ExtraTask`]).
	pub fn native_extra(&self, name: &BStr) -> Option<NativeRef> {
		self.extras.native(name)
	}

	/// The filesystem extras started now run on.
	pub fn filesystem(&self) -> pi_vfs::Fs {
		self
			.vfs
			.as_ref()
			.map_or_else(pi_vfs::Fs::native, VfsFs::filesystem)
	}

	/// Whether `path` is a plain host filesystem object.
	fn native(&self, path: &std::path::Path) -> bool {
		self
			.vfs
			.as_ref()
			.is_none_or(|fs| fs.filesystem().is_native_local(path))
	}
}

/// The externals spawned in labeled subshell trees: `(label, pid)`.
///
/// The host records each spawn whose [`Lineage::label`] is set
/// ([`SpawnLog::record`]); `timeout` waits for and escalates on its own. Cheap
/// to clone; clones share the log.
#[derive(Clone, Default)]
pub struct SpawnLog(Arc<Mutex<Vec<(u32, u32)>>>);

impl SpawnLog {
	/// `pid` was spawned with `lineage`.
	pub fn record(&self, lineage: Lineage, pid: u32) {
		if lineage.label != 0 {
			self.0.lock().push((lineage.label, pid));
		}
	}

	/// The recorded externals of `labels` that are still running.
	fn live(&self, labels: &[u32]) -> Vec<u32> {
		self
			.0
			.lock()
			.iter()
			.filter(|&&(label, pid)| labels.contains(&label) && running(pid))
			.map(|&(_, pid)| pid)
			.collect()
	}

	fn forget(&self, labels: &[u32]) {
		self.0.lock().retain(|(label, _)| !labels.contains(label));
	}
}

/// Whether `pid` runs (exited but unreaped counts as gone).
#[cfg(unix)]
fn running(pid: u32) -> bool {
	i32::try_from(pid)
		.ok()
		.and_then(crate::sys::proc::info)
		.is_some_and(|p| p.state != crate::sys::proc::ProcState::Zombie)
}

/// Externals off Unix are not watched: their process tree is the Job
/// Object's, which the spawner ends with the subshell.
#[cfg(not(unix))]
const fn running(_pid: u32) -> bool {
	false
}

/// Send `signal` to `pid`'s process group (each external leads its own),
/// or to `pid` alone.
#[cfg(unix)]
fn signal_os(pid: u32, signal: crate::bash::Signal, group: bool) {
	let Ok(pid) = i32::try_from(pid) else {
		return;
	};
	let number = i32::from(signal.number(crate::bash::Platform::current()));
	let target = if group { -pid } else { pid };
	// SAFETY: plain syscall without pointer arguments.
	unsafe { libc::kill(target, number) };
}

#[cfg(not(unix))]
const fn signal_os(_pid: u32, _signal: crate::bash::Signal, _group: bool) {}

/// Lineage labels handed out to tool subshells, and which label each was
/// started under (a `timeout` inside another one's command).
#[derive(Default)]
struct Labels {
	last:    u32,
	parents: Vec<(u32, u32)>,
}

impl Labels {
	/// A fresh label for a subshell of a caller labeled `parent`.
	fn fresh(&mut self, parent: u32) -> u32 {
		self.last = self.last.wrapping_add(1).max(1);
		if parent != 0 {
			self.parents.push((self.last, parent));
		}
		self.last
	}

	/// `label` and every label started below it.
	fn group(&self, label: u32) -> Vec<u32> {
		let mut group = vec![label];
		let mut at = 0;
		while let Some(&parent) = group.get(at) {
			group.extend(
				self
					.parents
					.iter()
					.filter(|&&(_, p)| p == parent)
					.map(|&(child, _)| child),
			);
			at += 1;
		}
		group
	}

	fn release(&mut self, group: &[u32]) {
		self.parents.retain(|(child, _)| !group.contains(child));
	}
}

/// What a tool sees on each turn ([`Tool::advance`]).
struct Turn<'a> {
	/// [`crate::bash::Host::now_ns`].
	now:    u64,
	ctl:    &'a ControlHandle,
	log:    &'a SpawnLog,
	/// The tool's label and those below it ([`Labels::group`]).
	group:  &'a [u32],
	/// A vproc of `group` still exists.
	live:   bool,
	labels: &'a mut Labels,
	/// Wakes the driver (worker threads).
	waker:  &'a Waker,
	config: &'a ToolConfig,
}

/// One running tool call.
enum Tool {
	Timeout(timeout::Timeout),
	Nohup(nohup::Nohup),
	Git(git::Git),
	Extra(extra::Extra),
}

impl Tool {
	fn start(call: ToolCall) -> Option<Self> {
		Some(match call.tool {
			TIMEOUT => Self::Timeout(timeout::Timeout::new(call)),
			NOHUP => Self::Nohup(nohup::Nohup::new(call)),
			GIT => Self::Git(git::Git::new(call)),
			EXTRA => Self::Extra(extra::Extra::new(call)),
			_ => return None,
		})
	}

	/// Make progress; the outcome once the call is answered.
	fn advance(&mut self, api: &mut ShellApi<'_, '_>, turn: &mut Turn<'_>) -> Option<CallOutcome> {
		match self {
			Self::Timeout(t) => t.advance(api, turn),
			Self::Nohup(t) => t.advance(api, turn),
			Self::Git(t) => t.advance(api, turn),
			Self::Extra(t) => t.advance(api, turn),
		}
	}

	/// `run` (one of the tool's subshells) ended; `false` when it is not
	/// the tool's.
	fn on_done(&mut self, run: RunId, status: i32, signal: Option<i32>) -> bool {
		let child = match self {
			Self::Timeout(t) => &mut t.child,
			Self::Nohup(t) => &mut t.child,
			Self::Git(t) => &mut t.child,
			Self::Extra(t) => return t.on_done(run, status, signal),
		};
		child.on_done(run, status)
	}

	const fn child(&self) -> &Child {
		match self {
			Self::Timeout(t) => &t.child,
			Self::Nohup(t) => &t.child,
			Self::Git(t) => &t.child,
			Self::Extra(t) => &t.child,
		}
	}

	/// The tool's subshells whose `Done` is still to come.
	fn pending(&self) -> Vec<RunId> {
		match self {
			Self::Extra(t) => t.pending(),
			_ => self.child().pending().into_iter().collect(),
		}
	}

	/// When the tool must be advanced even if nothing wakes the driver.
	fn deadline(&self) -> Option<u64> {
		match self {
			Self::Timeout(t) => t.deadline(),
			Self::Nohup(_) | Self::Git(_) | Self::Extra(_) => None,
		}
	}
}

/// A tool's subshell: its run and label, and its status once it ended.
#[derive(Default)]
struct Child {
	run:    Option<RunId>,
	label:  u32,
	status: Option<i32>,
}

impl Child {
	/// Run `argv` (`"$@"`, so functions, builtins and externals run as
	/// anywhere) in a subshell of the caller under a fresh label;
	/// `redirect` is appended to the command (`>&2`).
	fn start(
		&mut self,
		api: &mut ShellApi<'_, '_>,
		turn: &mut Turn<'_>,
		call: &ToolCall,
		argv: Vec<BString>,
		detached: bool,
		redirect: &str,
	) {
		self.label = turn.labels.fresh(api.lineage().label);
		let mut script = Script::command(format!("\"$@\"{redirect}").into_bytes());
		script.args = Some(argv);
		// The command's environment, per-command assignments included.
		script.env = call
			.env
			.iter()
			.map(|(name, value)| (BString::from(name), BString::from(value)))
			.collect();
		self.status = None;
		let lineage = Lineage { label: self.label, detached };
		// `nohup` (the detached tool) execs its operand: its subshell stands
		// for the command, so `$!` of `nohup cmd &` is the program's pid.
		self.run = Some(if detached {
			api.exec_subshell_in(script, lineage)
		} else {
			api.run_subshell_in(script, lineage)
		});
	}

	fn on_done(&mut self, run: RunId, status: i32) -> bool {
		if self.run != Some(run) || self.status.is_some() {
			return false;
		}
		self.status = Some(status);
		true
	}

	/// The run, while its `Done` is still to come.
	fn pending(&self) -> Option<RunId> {
		self.run.filter(|_| self.status.is_none())
	}
}

/// Output a tool writes to the caller's fds, in order, without blocking.
#[derive(Default)]
struct Out(VecDeque<(i32, Vec<u8>)>);

impl Out {
	fn push(&mut self, fd: i32, bytes: impl Into<Vec<u8>>) {
		let bytes = bytes.into();
		if !bytes.is_empty() {
			self.0.push_back((fd, bytes));
		}
	}

	/// Write what fits; `true` once everything is written (or failed: a
	/// closed stderr loses the message, as it would for any command).
	fn flush(&mut self, api: &mut ShellApi<'_, '_>) -> bool {
		while let Some((fd, bytes)) = self.0.front_mut() {
			match api.write(*fd, bytes) {
				IoPoll::Ready(Ok(n)) if n > 0 && n < bytes.len() => {
					bytes.drain(..n);
				},
				IoPoll::Ready(_) => {
					self.0.pop_front();
				},
				IoPoll::WouldBlock(_) => return false,
			}
		}
		true
	}
}

/// The host callouts in flight; owned by the session driver.
pub struct ToolCalls {
	active:  Vec<(CallId, Tool)>,
	/// Runs of tools that ended before them (an abandoned call): their
	/// `Done` is swallowed.
	orphans: Vec<RunId>,
	labels:  Labels,
	log:     SpawnLog,
	waker:   Waker,
	config:  ToolConfig,
}

impl ToolCalls {
	/// Tools of a shell with `config`, whose host records labeled spawns in
	/// `log`; worker threads wake the driver with `waker`.
	pub fn new(config: ToolConfig, log: SpawnLog, waker: Waker) -> Self {
		Self {
			active: Vec::new(),
			orphans: Vec::new(),
			labels: Labels::default(),
			log,
			waker,
			config,
		}
	}

	/// Start the callout `id` the engine returned.
	pub fn on_call(&mut self, shell: &mut Shell, cx: &mut Cx<'_>, id: CallId, call: ToolCall) {
		let name = call.argv.first().cloned().unwrap_or_default();
		if let Some(tool) = Tool::start(call) {
			self.active.push((id, tool));
			self.poll(shell, cx);
		} else {
			let mut msg = BString::from("not a pi tool: ");
			msg.extend_from_slice(&name);
			shell.complete(id, CallOutcome::Error(msg));
		}
	}

	/// A run that is not the session's own ended; `true` when it belonged
	/// to a tool (the driver ignores it then). `signal` is the actual
	/// signal death of a command replacing the run, not an exit code.
	pub fn on_done(&mut self, run: RunId, status: i32, signal: Option<i32>) -> bool {
		if self
			.active
			.iter_mut()
			.any(|(_, tool)| tool.on_done(run, status, signal))
		{
			return true;
		}
		match self.orphans.iter().position(|&r| r == run) {
			Some(at) => {
				self.orphans.swap_remove(at);
				true
			},
			None => false,
		}
	}

	/// Advance every tool; answer the calls that finished and drop those
	/// the engine abandoned (their caller was cancelled or killed).
	pub fn poll(&mut self, shell: &mut Shell, cx: &mut Cx<'_>) {
		if self.active.is_empty() {
			return;
		}
		let now = cx.host.now_ns();
		let ctl = shell.control();
		let mut at = 0;
		while at < self.active.len() {
			let (id, tool) = &mut self.active[at];
			let id = *id;
			let group = self.labels.group(tool.child().label);
			let live = tool.child().label != 0 && group.iter().any(|&l| shell.label_live(l));
			let outcome = match shell.api(cx, id) {
				Some(mut api) => {
					let mut turn = Turn {
						now,
						ctl: &ctl,
						log: &self.log,
						group: &group,
						live,
						labels: &mut self.labels,
						waker: &self.waker,
						config: &self.config,
					};
					tool.advance(&mut api, &mut turn).map(Some)
				},
				// Abandoned: nothing awaits the answer any more.
				None => Some(None),
			};
			let Some(answer) = outcome else {
				at += 1;
				continue;
			};
			let (_, tool) = self.active.swap_remove(at);
			self.orphans.extend(tool.pending());
			self.log.forget(&group);
			self.labels.release(&group);
			if let Some(outcome) = answer {
				shell.complete(id, outcome);
			}
		}
	}

	/// The earliest host time ([`crate::bash::Host::now_ns`]) a tool must be
	/// polled at even if nothing wakes the driver.
	pub fn next_deadline(&self) -> Option<u64> {
		self
			.active
			.iter()
			.filter_map(|(_, tool)| tool.deadline())
			.min()
	}
}

/// `d` in host nanoseconds (saturating: "never").
fn nanos(d: Duration) -> u64 {
	u64::try_from(d.as_nanos()).unwrap_or(u64::MAX)
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn labels_group_their_nested_trees() {
		let mut labels = Labels::default();
		let outer = labels.fresh(0);
		let inner = labels.fresh(outer);
		let innermost = labels.fresh(inner);
		let other = labels.fresh(0);
		assert_eq!(labels.group(outer), [outer, inner, innermost]);
		assert_eq!(labels.group(other), [other]);
		labels.release(&labels.group(inner));
		assert_eq!(labels.group(outer), [outer]);
	}

	#[test]
	fn tools_follow_the_session_environment() {
		let env = |pairs: &[(&str, &str)]| -> Vec<(BString, BString)> {
			pairs.iter().map(|&(k, v)| (k.into(), v.into())).collect()
		};
		let runtime = tokio::runtime::Builder::new_current_thread()
			.build()
			.expect("runtime");
		let config =
			|pairs: &[(&str, &str)]| ToolConfig::from_env(&env(pairs), None, runtime.handle().clone());
		let plain = config(&[]);
		assert_eq!(plain.lookup("timeout".into()), Some(TIMEOUT));
		assert_eq!(plain.lookup("nohup".into()), Some(NOHUP));
		assert_eq!(plain.lookup("git".into()), None);
		assert_eq!(plain.lookup("xargs".into()), Some(EXTRA));
		assert_eq!(plain.lookup("sort".into()), None);
		assert!(plain.native_extra("sort".into()).is_some());
		let layered = config(&[("PI_GIT_GUARD", "1"), ("PI_DISABLE_NOHUP_BUILTIN", "true")]);
		assert_eq!(layered.lookup("git".into()), Some(GIT));
		assert_eq!(layered.lookup("nohup".into()), None);
		let off = config(&[("PI_SMART_GIT", "false"), ("PI_GIT_GUARD", "0")]);
		assert_eq!(off.lookup("git".into()), None);
		let no_utils = config(&[("PI_DISABLE_UUTILS_BUILTINS", "1")]);
		assert_eq!(no_utils.lookup("xargs".into()), None);
		assert!(no_utils.native_extra("sort".into()).is_none());
		assert_eq!(no_utils.lookup("timeout".into()), Some(TIMEOUT));
	}
}

// A container's PID 1 may never reap orphaned grandchildren. Adopt them in
// this test process so the unchanged disappearance assertion can observe an
// actually reaped process rather than mistaking a zombie for a live command.
#[cfg(target_os = "linux")]
pub struct ChildReaper(i32);

#[cfg(target_os = "linux")]
impl ChildReaper {
	pub fn new() -> Self {
		let mut previous = 0;
		// SAFETY: GET writes one initialized integer; SET affects this process.
		unsafe {
			assert_eq!(libc::prctl(libc::PR_GET_CHILD_SUBREAPER, &raw mut previous), 0);
			assert_eq!(libc::prctl(libc::PR_SET_CHILD_SUBREAPER, 1), 0);
		}
		Self(previous)
	}
}

#[cfg(target_os = "linux")]
impl Drop for ChildReaper {
	fn drop(&mut self) {
		// SAFETY: restore this process's previous subreaper setting.
		unsafe {
			libc::prctl(libc::PR_SET_CHILD_SUBREAPER, self.0);
		}
	}
}

pub fn alive(pid: i32) -> bool {
	#[cfg(target_os = "linux")]
	// SAFETY: only reap this exact PID if it is our already-exited child;
	// WNOHANG cannot terminate or block on a still-running process.
	unsafe {
		libc::waitpid(pid, std::ptr::null_mut(), libc::WNOHANG);
	}

	// SAFETY: signal 0 only probes existence.
	unsafe { libc::kill(pid, 0) == 0 }
}

//! Shared pieces of the completion PTY tests (`zsh_comp_*`): which shell
//! runs (obash as `zsh`, or `/bin/zsh` as the oracle), where zsh 5.9's
//! completion functions live, the colour transcript of terminal output, and
//! the port of zsh's `Test/comptest` harness ([`comptest`]).
//!
//! Environment switches (both crates read them):
//! - `PI_COMP_ORACLE=1` runs `/bin/zsh` instead of obash, checking the stored
//!   expectations against zsh itself.
//! - `PI_COMP_BLESS=1` (with `PI_COMP_ORACLE=1`) rewrites the stored screen
//!   snapshots of `zsh_comp_pty` from `/bin/zsh`.
//! - `PI_COMP_QUIET_MS` how long output must stay quiet before a screen is read
//!   (default 400).

#![allow(dead_code, reason = "each test crate uses a subset")]

pub mod comptest;

use std::{env, path::PathBuf, time::Duration};

use crate::pty_support::{REAL_ZSH, Spawn, have_real_zsh};

/// Whether `/bin/zsh` runs instead of obash (`PI_COMP_ORACLE`).
#[must_use]
pub fn oracle() -> bool {
	flag("PI_COMP_ORACLE")
}

/// Whether stored snapshots are rewritten from the run (`PI_COMP_BLESS`).
#[must_use]
pub fn bless() -> bool {
	flag("PI_COMP_BLESS")
}

fn flag(name: &str) -> bool {
	env::var_os(name).is_some_and(|v| !v.is_empty() && v != "0")
}

/// How long output must stay quiet before a screen is read.
#[must_use]
pub fn quiet() -> Duration {
	let ms = env::var("PI_COMP_QUIET_MS")
		.ok()
		.and_then(|v| v.parse().ok())
		.unwrap_or(400);
	Duration::from_millis(ms)
}

/// The shell under test: obash as `zsh`, or the real zsh in oracle mode.
///
/// # Panics
///
/// In oracle mode without `/bin/zsh`.
#[must_use]
pub fn shell() -> Spawn {
	if oracle() {
		assert!(have_real_zsh(), "PI_COMP_ORACLE needs {REAL_ZSH}");
		Spawn::real_zsh()
	} else {
		Spawn::zsh()
	}
}

pub use pi_shell::sys::zsh::function_dirs as compsys_fpath;

/// `fpath=( ... )` words for [`compsys_fpath`] (the paths need no quoting).
#[must_use]
pub fn fpath_words(dirs: &[PathBuf]) -> String {
	let words: Vec<String> = dirs.iter().map(|d| d.display().to_string()).collect();
	words.join(" ")
}

/// The text and colours of terminal output: printable text as is, `\n`
/// for line feeds, `^G` for bells, `{params}` for each SGR sequence
/// (`ESC [ params m`); every other control sequence (cursor motion, erase,
/// OSC strings, charset selection) and control character is dropped.
#[must_use]
pub fn sgr_transcript(out: &str) -> String {
	let mut text = String::new();
	let mut chars = out.chars().peekable();
	while let Some(c) = chars.next() {
		match c {
			'\x1b' => match chars.next() {
				Some('[') => {
					let mut params = String::new();
					while let Some(&p) = chars.peek() {
						if ('\x20'..='\x3f').contains(&p) {
							params.push(p);
							chars.next();
						} else {
							break;
						}
					}
					if chars.next() == Some('m') {
						text.push('{');
						text.push_str(&params);
						text.push('}');
					}
				},
				Some(']' | 'P' | '_' | '^' | 'X') => {
					// A string up to BEL or ST (`ESC \`).
					while let Some(s) = chars.next() {
						if s == '\x07' || (s == '\x1b' && chars.next_if_eq(&'\\').is_some()) {
							break;
						}
					}
				},
				Some('(' | ')' | '*' | '+' | '#' | '%') => {
					chars.next();
				},
				_ => {},
			},
			'\n' => text.push('\n'),
			'\x07' => text.push_str("^G"),
			c if c < ' ' || c == '\x7f' => {},
			c => text.push(c),
		}
	}
	text
}

//! Acceptance through the `obash` binary: output, golden events, the
//! fault flag, `--ir` and `--print`.

mod obash_support;

use std::{fmt::Write as _, fs, path::PathBuf};
#[cfg(unix)]
use std::{os::unix::process::CommandExt, time::UNIX_EPOCH};

use pi_shell::testkit::golden;

use crate::obash_support::{obash, output};

const LOOP: &str = "for i in 1 2; do echo $i; done";

fn events_fixture(name: &str) -> PathBuf {
	PathBuf::from(env!("CARGO_MANIFEST_DIR"))
		.join("src/testkit/fixtures/events")
		.join(name)
}

#[test]
fn for_loop_prints_one_two() {
	let out = output(obash().args(["-c", LOOP]));
	assert_eq!(String::from_utf8_lossy(&out.stdout), "1\n2\n");
	assert!(out.stderr.is_empty(), "{}", String::from_utf8_lossy(&out.stderr));
	assert!(out.status.success());
}

/// The drive loop's parker waits for the externals (Linux: their pidfds): a
/// foreground external, a pipeline, a command substitution, and a background
/// external whose exit a busy foreground loop notices without parking; obash
/// exits cleanly with and without externals (a debug build aborts at exit
/// when an fd is closed twice).
#[cfg(unix)]
#[test]
fn externals_are_awaited_and_obash_exits_cleanly() {
	let script = r#"/bin/echo fg; /bin/echo pipe | /bin/cat; x=$(/bin/echo sub); echo "$x"
/bin/sleep 0.05 & i=0
while kill -0 $! 2>/dev/null && [ "$i" -lt 1000000 ]; do i=$((i+1)); done
[ "$i" -lt 1000000 ] && echo noticed
wait; echo "status $?""#;
	let cases = [(":", ""), (LOOP, "1\n2\n"), (script, "fg\npipe\nsub\nnoticed\nstatus 0\n")];
	for (src, expected) in cases {
		let out = output(obash().args(["-c", src]));
		assert_eq!(String::from_utf8_lossy(&out.stdout), expected, "{src}");
		assert!(out.stderr.is_empty(), "{src}: {}", String::from_utf8_lossy(&out.stderr));
		assert!(out.status.success(), "{src}: {:?}", out.status);
	}
}

/// `OBASH_BLESS=1` rewrites the golden from the actual stream (review the
/// diff).
#[test]
fn events_golden() {
	let dir = tempfile::tempdir().unwrap();
	let path = dir.path().join("events.jsonl");
	let out = output(obash().args([
		"--events=jsonl",
		&format!("--events-out={}", path.display()),
		"-c",
		LOOP,
	]));
	assert_eq!(out.stdout, b"1\n2\n");
	let actual =
		golden::normalize(&golden::parse_jsonl(&fs::read_to_string(&path).unwrap()).unwrap());
	let golden_path = events_fixture("for-loop.jsonl");
	if std::env::var_os("OBASH_BLESS").is_some() {
		let text = actual.iter().fold(String::new(), |mut text, e| {
			let _ = writeln!(text, "{e}");
			text
		});
		fs::write(&golden_path, text).unwrap();
	}
	let expected = golden::parse_jsonl(&fs::read_to_string(&golden_path).unwrap()).unwrap();
	if let Some(d) = golden::diff(&actual, &expected) {
		panic!("{d}");
	}
	let kinds: Vec<&str> = actual.iter().map(|e| e["kind"].as_str().unwrap()).collect();
	assert_eq!(kinds.first(), Some(&"RunStart"));
	assert_eq!(kinds.last(), Some(&"RunEnd"));
}

