		 <$BUFFER>\" >>~/log }}\nzle -N w\nbindkey '^T' w\n"
	);
	// Up from a buffer equal to the line above skips it; skipping off the
	// oldest line fails.
	same_log(&rc, "git status\x14\x14\x1b<\x0e\x15. ~/.zshrc\x14");
}

