//! Job control of `obash` invoked as an interactive `zsh -f -i`, against the
//! real `/bin/zsh` on the same pty sessions: `^Z` on a foreground external,
//! `jobs`, `bg`, `fg` and `^C`, the terminal modes after a suspension, and
//! `exit` with a stopped job. Only the job lines are compared (`zsh: …`,
//! `[n] …`) with pids masked: the prompts are the line editor's.

#![cfg(unix)]

mod pty_support;

use std::{io, thread, time::Duration};

use pty_support::{Pty, Spawn, TIMEOUT, have_real_zsh};

/// How long a just-typed external gets to start before a key signals it.
const START: Duration = Duration::from_millis(600);

/// An interactive `zsh -f` on a fresh pty: obash as `zsh`, or the real one.
fn shell(real: bool) -> io::Result<Pty> {
	let spawn = if real {
		Spawn::real_zsh()
	} else {
		Spawn::zsh()
	};
	spawn.args(["-f", "-i"]).env("PS1", "").spawn()
}

/// Type `line` and a return.
fn line(pty: &mut Pty, text: &str) -> io::Result<()> {
	pty.write(format!("{text}\r"))
}

/// The job lines of `out` (`zsh: suspended  …`, `[1]  + running    …`,
/// `zsh: you have …`), the pid of `[1]  + 12345 …` and the pids of
/// `[1] 12345 12346` replaced by `PID`.
fn job_lines(out: &str) -> Vec<String> {
	out.split('\n')
		.map(|l| {
			// What a line shows: the text after its last carriage return.
			let l = l.trim_end_matches('\r');
			let l = l.rsplit('\r').next().unwrap_or(l).trim_end();
			// The terminal's echo of `^Z` when no newline followed it.
			l.strip_prefix("^Z").unwrap_or(l).to_owned()
		})
		.filter(|l| l.starts_with("zsh: ") || l.starts_with('['))
		.map(|l| {
			let job = l.starts_with('[');
			let is_pid = |w: &str| !w.is_empty() && w.bytes().all(|b| b.is_ascii_digit());
			// `[n] pid…`: a background job's start, one pid per process.
			let start = job && l.split(' ').skip(1).all(is_pid);
			let words: Vec<&str> = l
				.split(' ')
				.enumerate()
				.map(|(i, w)| {
					if is_pid(w) && job && (start || i == 3) {
						"PID"
					} else {
						w
					}
				})
				.collect();
			words.join(" ")
		})
		.collect()
}

/// Run `drive` against obash and, when present, the real zsh; the job
/// lines of each.
fn both(
	drive: impl Fn(&mut Pty) -> io::Result<()>,
) -> io::Result<(Vec<String>, Option<Vec<String>>)> {
	let mut ours = shell(false)?;
	drive(&mut ours).map_err(|e| io::Error::new(e.kind(), format!("obash: {e}")))?;
	let ours = job_lines(&ours.output());
	if !have_real_zsh() {
		return Ok((ours, None));
	}
	let mut real = shell(true)?;
	drive(&mut real).map_err(|e| io::Error::new(e.kind(), format!("real-zsh: {e}")))?;
	Ok((ours, Some(job_lines(&real.output()))))
}

/// `^Z` on `sleep 100` prints `zsh: suspended  sleep 100`, `jobs` lists the
/// stopped job, and `kill -9 %1` reports it killed before the next command.
#[test]
fn ctrl_z_suspends_a_foreground_job_and_jobs_lists_it() -> io::Result<()> {
	let (ours, real) = both(|pty| {
		line(pty, "sleep 100")?;
		thread::sleep(START);
		pty.write("\x1a")?;
		pty.read_until("suspended  sleep 100", TIMEOUT)?;
		line(pty, "jobs")?;
		pty.read_until("[1]  + suspended  sleep 100", TIMEOUT)?;
		line(pty, "jobs -l")?;
		pty.read_until("suspended  sleep 100", TIMEOUT)?;
		line(pty, "kill -9 %1")?;
		line(pty, "echo next")?;
		pty.read_until("killed     sleep 100", TIMEOUT)?;
		pty.settle(Duration::from_millis(300), TIMEOUT)
	})?;
	assert_eq!(ours, [
		"zsh: suspended  sleep 100",
		"[1]  + suspended  sleep 100",
		"[1]  + PID suspended  sleep 100",
		"[1]  + killed     sleep 100",
	]);
	if let Some(real) = real {
		assert_eq!(ours, real);
	}
	Ok(())
}

/// `bg` continues the stopped job (`[1]  + continued  sleep 100`), `fg`
/// brings it back to the terminal, and `^C` interrupts it: `$?` is 130.
#[test]
fn bg_then_fg_then_ctrl_c() -> io::Result<()> {
	let (ours, real) = both(|pty| {
		line(pty, "sleep 100")?;
		thread::sleep(START);
		pty.write("\x1a")?;
		pty.read_until("suspended  sleep 100", TIMEOUT)?;
		line(pty, "bg")?;
		pty.read_until("continued  sleep 100", TIMEOUT)?;
		line(pty, "jobs")?;
		pty.read_until("running    sleep 100", TIMEOUT)?;
		line(pty, "fg")?;
		pty.read_until("running    sleep 100", TIMEOUT)?;
		thread::sleep(START);
		pty.write("\x03")?;
		line(pty, "echo st=$?")?;
		pty.read_until("st=130", TIMEOUT)?;
		Ok(())
	})?;
	if let Some(real) = real {
		assert_eq!(ours, real);
	}
	Ok(())
}

/// A background pipeline's start line names each of its processes, as
/// zsh's does (`[1] 1846 1847`), not only the one `$!` names.
#[test]
fn a_background_pipeline_names_each_process() -> io::Result<()> {
	let (ours, real) = both(|pty| {
		line(pty, "sleep 100 | sleep 100 &")?;
		thread::sleep(START);
		line(pty, "kill %1")?;
		line(pty, "echo next")?;
		pty.read_until("terminated", TIMEOUT)?;
		pty.settle(Duration::from_millis(300), TIMEOUT)
	})?;
	assert_eq!(ours.first().map(String::as_str), Some("[1] PID PID"), "{ours:?}");
	if let Some(real) = real {
		assert_eq!(ours, real);
	}
	Ok(())
}

/// A pipeline suspends as one job (`sleep 100 | cat`, its last stage run
/// by the shell itself); `fg` continues both, `^C` ends both.
#[test]
fn a_suspended_pipeline_is_one_job() -> io::Result<()> {
	let (ours, real) = both(|pty| {
		line(pty, "sleep 100 | cat")?;
		thread::sleep(START);
		pty.write("\x1a")?;
		pty.read_until("suspended  sleep 100 | cat", TIMEOUT)?;
		line(pty, "jobs")?;
		pty.read_until("[1]  + suspended  sleep 100 | cat", TIMEOUT)?;
		line(pty, "fg")?;
		pty.read_until("continued  sleep 100 | cat", TIMEOUT)?;
		thread::sleep(START);
		pty.write("\x03")?;
		line(pty, "echo st=$?")?;
		pty.read_until("st=130", TIMEOUT)?;
		Ok(())
	})?;
	assert_eq!(ours, [
		"zsh: suspended  sleep 100 | cat",
		"[1]  + suspended  sleep 100 | cat",
		"[1]  + continued  sleep 100 | cat",
	]);
	if let Some(real) = real {
		assert_eq!(ours, real);
	}
	Ok(())
}

/// `^Z` inside a loop suspends the rest of the loop with it (zsh forks the
/// construct): the next iteration does not run until `fg`, the rest of the
/// command line is dropped, and the finished job is named by the loop.
#[test]
fn a_suspended_loop_takes_the_rest_of_the_loop_with_it() -> io::Result<()> {
	let (ours, real) = both(|pty| {
		line(pty, "for i in 1 2; do sleep 100; echo it$i; done; echo after")?;
		thread::sleep(START);
		pty.write("\x1a")?;
		pty.read_until("suspended  sleep 100", TIMEOUT)?;
		line(pty, "jobs")?;
		pty.read_until("[1]  + suspended  sleep 100", TIMEOUT)?;
		line(pty, "kill -9 %1")?;
		line(pty, "echo done")?;
		pty.read_until("killed", TIMEOUT)?;
		pty.settle(Duration::from_millis(300), TIMEOUT)
	})?;
	assert_eq!(ours, [
		"zsh: suspended  sleep 100",
		"[1]  + suspended  sleep 100",
		"[1]  + killed     for i in 1 2; do; sleep 100; echo it$i; done",
	]);
	if let Some(real) = real {
		assert_eq!(ours, real);
	}
	Ok(())
}

/// A job that turned echo off and was suspended leaves the terminal as the
/// shell had it: the next command sees `echo` on.
#[test]
fn a_suspended_job_does_not_leave_its_terminal_modes() -> io::Result<()> {
	for real in [false, true] {
		if real && !have_real_zsh() {
			continue;
		}
		let mut pty = shell(real)?;
		line(&mut pty, "sh -c 'stty -echo; sleep 100'")?;
		thread::sleep(START);
		pty.write("\x1a")?;
		pty.read_until("suspended  sh -c", TIMEOUT)?;
		line(&mut pty, "stty -a | tr ' ' '\\n' | grep -x -e echo -e -echo | sed 's/^/mode=/'")?;
		let seen = pty.read_until("\nmode=", TIMEOUT)?;
		let rest = pty.read_until("\n", TIMEOUT)?;
		assert_eq!(rest.trim_end(), "echo", "real zsh: {real}; {seen}");
	}
	Ok(())
}

/// `exit` with a stopped job warns once (`zsh: you have suspended jobs.`);
/// an `exit` right after leaves.
#[test]
fn exit_with_a_stopped_job_warns_once() -> io::Result<()> {
	let (ours, real) = both(|pty| {
		line(pty, "sleep 100")?;
		thread::sleep(START);
		pty.write("\x1a")?;
		pty.read_until("suspended  sleep 100", TIMEOUT)?;
		line(pty, "exit")?;
		pty.read_until("you have suspended jobs.", TIMEOUT)?;
		line(pty, "exit")?;
		pty.wait(TIMEOUT)?;
		Ok(())
	})?;
	assert_eq!(ours, ["zsh: suspended  sleep 100", "zsh: you have suspended jobs."]);
	if let Some(real) = real {
		assert_eq!(ours, real);
	}
	Ok(())
}

//! zsh/files, zsh/stat, zsh/attr and zsh/mapfile on the real filesystem,
//! through the obash binary run as `zsh -f -c SCRIPT` in a fresh temporary
//! directory. Expected output from `/bin/zsh -f -c SCRIPT` 5.9 in the same
//! setup (macOS); the user- and group-name checks compare with `/bin/zsh`
//! live, as names depend on the account running the tests.

#![cfg(unix)]

mod obash_support;

use std::{os::unix::process::CommandExt, path::Path, process::Command};

use crate::obash_support::{command, obash, output};

/// Run `script` as `zsh -f -c script` with `shell` in a new empty
/// directory: stdout, stderr, status.
fn run_in_tempdir(mut shell: Command, script: &str) -> (String, String, i32) {
	let dir = tempfile::tempdir().unwrap();
	// The expected mode bytes below describe a 022 creation mask, independent
	// of the test runner's inherited mask. Only the child shell changes it.
	let script = format!("umask 022; {script}");
	let out = output(shell.current_dir(dir.path()).args(["-f", "-c", &script]));
	(
		String::from_utf8_lossy(&out.stdout).into_owned(),
		String::from_utf8_lossy(&out.stderr).into_owned(),
		out.status.code().unwrap_or(-1),
	)
}

fn zsh(script: &str) -> (String, String, i32) {
	let mut cmd = obash();
	cmd.arg0("zsh");
	run_in_tempdir(cmd, script)
}

#[test]
fn zsh_mod_files_moves_links_modes_and_removes() {
	let (out, err, st) = zsh(
		"zmodload zsh/files zsh/stat
mkdir -p src/sub dst; print -n data > src/sub/f; print -n x > src/g
mv src/sub dst; print -l dst/*/*
mv src/g dst/sub/; print -l dst/sub/*
ln -s sub/f dst/link; zstat +link dst/link; zstat +mode dst/link; zstat +size dst/link
ln dst/sub/f hard; zstat +nlink hard
chmod 640 hard; zstat -s +mode dst/sub/f
chmod -R 700 dst; zstat -o +mode dst/sub dst/sub/g
rm -r dst; echo $?; print -l *
zstat +size hard nonexist; echo $?
zstat -rs +mode hard
rmdir src; echo $?; rmdir src; echo $?",
	);
	assert_eq!(
		out,
		"dst/sub/f\ndst/sub/f\ndst/sub/g\nsub/f\n33188\n4\n2\n-rw-r-----\ndst/sub 040700\ndst/sub/g \
		 0100700\n0\nhard\nsrc\nhard 4\n1\n33216 (-rwx------)\n0\n1\n"
	);
	assert_eq!(
		err,
		"zsh:zstat:10: nonexist: no such file or directory
zsh:rmdir:12: cannot remove directory `src': no such file or directory
"
	);
	assert_eq!(st, 0);
}

/// `zstat -s` names and `chown`/`chgrp` lookups go through the host's user
/// database: the same as `/bin/zsh` for whoever runs the tests.
#[test]
fn zsh_mod_files_owners_match_zsh() {
	let script = "zmodload zsh/files zsh/stat
print > f; zstat -s +uid f; zstat -s +gid f; zstat -sr +uid f
chown $UID f; echo $?; chown :$GID f; echo $?; chgrp $GID f; echo $?
chown $USERNAME: f; echo $?; chown -h $UID:$GID f; echo $?
chown nosuchuserxyz f; chgrp nosuchgroupxyz f; chown 4294967: f
chown -R $UID d; echo $?";
	let ours = zsh(script);
	assert_eq!(
		ours.1,
		"zsh:chown:5: nosuchuserxyz: no such user
zsh:chgrp:5: nosuchgroupxyz: no such group
zsh:chown:5: 4294967: no such user
zsh:chown:6: d: no such file or directory
"
	);
	if Path::new("/bin/zsh").exists() {
		assert_eq!(ours, run_in_tempdir(command("/bin/zsh"), script));
	}
}

#[test]
fn zsh_mod_files_mapfile_on_disk() {
	let (out, err, st) = zsh(
		"zmodload zsh/mapfile zsh/stat
umask 027; mapfile[f]=hello; zstat -o +mode f; print -r -- $mapfile[f]
mapfile[f]=; print -r -- $mapfile[f]; unset 'mapfile[f]'; print -l *(N)",
	);
	assert_eq!(out, "0100640\nhello\nhello\n\n");
	assert_eq!(err, "");
	assert_eq!(st, 0);
}

