//! `zcompile` through the obash binary run as `zsh`, against `/bin/zsh`
//! 5.9 itself: every file of a corpus compiled by both gives the same dump
//! (padding aside: zsh writes heap garbage after each program's strings)
//! or the same failure, messages included. The corpus is zsh's own
//! `Functions` and `Completion` trees (`$PI_ZSH_SRC`, default
//! `/work/.ref/zsh-5.9`) and the `*.zsh`/`*.zsh-theme` files of
//! `~/powerlevel10k` and `~/.oh-my-zsh`, whichever exist. Every test is
//! skipped (passes without checking) when `/bin/zsh` is not zsh 5.9.

#![cfg(unix)]

mod obash_support;

use std::{
	fs,
	os::unix::process::CommandExt,
	path::{Path, PathBuf},
	process::Command,
	time::Duration,
};

use crate::obash_support::{command, finish, obash};

/// Whether `/bin/zsh` is the oracle.
fn have_zsh() -> bool {
	let Ok(out) = Command::new("/bin/zsh").arg("--version").output() else {
		return false;
	};
	String::from_utf8_lossy(&out.stdout).starts_with("zsh 5.9 ")
}

/// A scratch directory of its own.
fn scratch(tag: &str) -> PathBuf {
	let dir = std::env::temp_dir().join(format!("pi-zcompile-{tag}-{}", std::process::id()));
	let _ = fs::remove_dir_all(&dir);
	fs::create_dir_all(&dir).unwrap();
	dir
}

/// Run `script` with `args` as `zsh -f -c script zsh args…` under the real
/// zsh (`real`) or obash: stdout, stderr, status.
fn run(real: bool, script: &str, args: &[String]) -> (String, String, i32) {
	let mut cmd = if real {
		command("/bin/zsh")
	} else {
		let mut c = obash();
		c.arg0("zsh");
		c
	};
	cmd.args(["-f", "-c", script, "zsh"]).args(args);
	let out = finish(cmd.spawn().unwrap(), Duration::from_secs(600));
	(
		String::from_utf8_lossy(&out.stdout).into_owned(),
		String::from_utf8_lossy(&out.stderr).into_owned(),
		out.status.code().unwrap_or(-1),
	)
}

/// A dump with the padding after each program's strings zeroed, in both
/// halves (the first in the host's byte order, the other swapped).
fn masked(mut b: Vec<u8>) -> Vec<u8> {
	if b.len() < 52 {
		return b;
	}
	let other = usize::from(b[5]) | (usize::from(b[6]) << 8) | (usize::from(b[7]) << 16);
	for (off, swap) in [(0, false), (other, true)] {
		let word = |b: &[u8], i: usize| -> usize {
			let at = off + 4 * i;
			let Some(c) = b.get(at..at + 4) else { return 0 };
			let w = u32::from_ne_bytes([c[0], c[1], c[2], c[3]]);
			(if swap { w.swap_bytes() } else { w }) as usize
		};
		let hlen = word(&b, 12);
		let mut at = 12;
		while at < hlen {
			let (start, len, head) = (word(&b, at), word(&b, at + 1), word(&b, at + 4));
			let base = off + start * 4;
			for i in base + len..base + len.div_ceil(4) * 4 {
				if let Some(x) = b.get_mut(i) {
					*x = 0;
				}
			}
			if head == 0 {
				break;
			}
			at += head;
		}
	}
	b
}

/// The corpus files that exist here.
fn corpus() -> Vec<String> {
	fn walk(dir: &Path, keep: &dyn Fn(&Path) -> bool, out: &mut Vec<String>) {
		let Ok(entries) = fs::read_dir(dir) else {
			return;
		};
		let mut entries: Vec<_> = entries.flatten().map(|e| e.path()).collect();
		entries.sort();
		for p in entries {
			if p.is_dir() {
				walk(&p, keep, out);
			} else if p.is_file() && keep(&p) {
				out.push(p.to_string_lossy().into_owned());
			}
		}
	}
	let src = std::env::var("PI_ZSH_SRC").unwrap_or_else(|_| "/work/.ref/zsh-5.9".into());
	let mut files = Vec::new();
	for sub in ["Functions", "Completion"] {
		walk(&Path::new(&src).join(sub), &|_| true, &mut files);
	}
	if let Some(home) = std::env::var_os("HOME") {
		let shell_file = |p: &Path| {
			p.extension()
				.is_some_and(|e| e == "zsh" || e == "zsh-theme")
		};
		for sub in ["powerlevel10k", ".oh-my-zsh"] {
			walk(&Path::new(&home).join(sub), &shell_file, &mut files);
		}
	}
	if files.is_empty() {
		// Distribution packages install the same function corpus without the
		// developer's source checkout. Never let compilation pass vacuously.
		walk(Path::new("/usr/share/zsh/functions"), &|p| p.extension().is_none(), &mut files);
		if files.is_empty() {
			walk(Path::new("/usr/share/zsh/5.9/functions"), &|p| p.extension().is_none(), &mut files);
		}
	}
	assert!(files.len() >= 3, "zcompile requires an installed or PI_ZSH_SRC function corpus");
	files
}

/// Compiles each of `$@` into `$OUT/N.zwc` (`N` counting from 1) with
/// `zcompile $FLAGS`, its stderr in `$OUT/N.err`, printing `N status`.
/// zsh's two built-in aliases (`run-help`, `which-command`) are removed
/// first: aliases are expanded at compile time, and these compare the
/// compiler, not the alias table.
const COMPILE_ALL: &str = r#"unalias run-help which-command 2>/dev/null
out=$OUT; i=0
for f in "$@"; do
  i=$((i+1))
  zcompile ${=FLAGS} $out/$i.zwc $f 2>$out/$i.err
  print -r -- "$i $?"
done"#;

/// Compile `files` with both shells under `flags`; the differences.
fn differences(tag: &str, flags: &str, files: &[String]) -> Vec<String> {
	let mut diffs = Vec::new();
	let dirs = [scratch(&format!("{tag}-real")), scratch(&format!("{tag}-ours"))];
	for chunk in files.chunks(200) {
		let mut outs = Vec::new();
		for (real, dir) in [(true, &dirs[0]), (false, &dirs[1])] {
			let script = format!("OUT={} FLAGS='{flags}'\n{COMPILE_ALL}", dir.display());
			let (out, err, st) = run(real, &script, chunk);
			assert_eq!((err.as_str(), st), ("", 0), "{} driver", if real { "zsh" } else { "obash" });
			outs.push(out);
		}
		for (i, file) in chunk.iter().enumerate() {
			let n = i + 1;
			let read = |d: &Path, ext: &str| fs::read(d.join(format!("{n}.{ext}"))).ok();
			let status = |out: &str| {
				out.lines()
					.find_map(|l| l.strip_prefix(&format!("{n} ")).map(str::to_owned))
			};
			let (st_real, st_ours) = (status(&outs[0]), status(&outs[1]));
			let (err_real, err_ours) = (read(&dirs[0], "err"), read(&dirs[1], "err"));
			let (zwc_real, zwc_ours) = (read(&dirs[0], "zwc"), read(&dirs[1], "zwc"));
			if st_real != st_ours || err_real != err_ours {
				diffs.push(format!(
					"{file}: zsh status {st_real:?} stderr {:?}; obash status {st_ours:?} stderr {:?}",
					err_real.map(|e| String::from_utf8_lossy(&e).into_owned()),
					err_ours.map(|e| String::from_utf8_lossy(&e).into_owned()),
				));
			} else if zwc_real.map(masked) != zwc_ours.map(masked) {
				diffs.push(format!("{file}: the dumps differ"));
			}
			for d in &dirs {
				let _ = fs::remove_file(d.join(format!("{n}.zwc")));
				let _ = fs::remove_file(d.join(format!("{n}.err")));
			}
		}
	}
	for d in &dirs {
		let _ = fs::remove_dir_all(d);
	}
	diffs
}

fn assert_none(diffs: &[String]) {
	assert!(
		diffs.is_empty(),
		"{} files differ:\n{}",
		diffs.len(),
		diffs
			.iter()
			.take(40)
			.cloned()
			.collect::<Vec<_>>()
			.join("\n")
	);
}

/// Every corpus file, with `-R` (the user's `.zshrc` and powerlevel10k
/// compile so).
#[test]
fn zcompile_corpus_matches_zsh() {
	if !have_zsh() {
		return;
	}
	let files = corpus();
	assert_none(&differences("corpus", "-R", &files));
}

/// The load and map switches on a few corpus files: the flag bits of the
/// header and the entries.
#[test]
fn zcompile_switches_match_zsh() {
	if !have_zsh() {
		return;
	}
	let files: Vec<String> = corpus().into_iter().step_by(97).collect();
	for flags in ["", "-U", "-M", "-k", "-z", "-Uz -M"] {
		assert_none(&differences(&format!("flags{}", flags.len()), flags, &files));
	}
}

/// One digest of several files with the in-list `-k`/`-z` switches, and
/// its `-t` listing.
#[test]
fn zcompile_digest_and_listing_match_zsh() {
	if !have_zsh() {
		return;
	}
	let files: Vec<String> = corpus().into_iter().step_by(131).take(12).collect();
	let mut outs = Vec::new();
	for real in [true, false] {
		let dir = scratch(if real { "digest-real" } else { "digest-ours" });
		let script = format!(
			r#"unalias run-help which-command 2>/dev/null; d={}/all.zwc
zcompile $d $1 -k $2 $3 -z ${{@[4,-1]}}; print $?
zcompile -t $d; print $?
zcompile -t $d ${{1:t}} ${{2:t}}; print $?
zcompile -t $d ${{1:t}} nope; print $?"#,
			dir.display()
		);
		let (out, err, st) = run(real, &script, &files);
		let dump = fs::read(dir.join("all.zwc")).ok().map(masked);
		let _ = fs::remove_dir_all(&dir);
		outs.push((out, err, st, dump));
	}
	let ours = &outs[1];
	let real = &outs[0];
	assert_eq!((&ours.0, &ours.1, ours.2), (&real.0, &real.1, real.2));
	assert!(ours.3 == real.3, "the digests differ");
}

/// `zcompile -t` lists a dump zsh wrote, and finds its names.
#[test]
fn zcompile_lists_dumps_zsh_wrote() {
	if !have_zsh() {
		return;
	}
	let files: Vec<String> = corpus().into_iter().step_by(211).take(5).collect();
	let dir = scratch("list");
	let d = dir.join("x.zwc").display().to_string();
	let (_, err, st) = run(true, &format!("zcompile -M {d} \"$@\""), &files);
	assert_eq!((err.as_str(), st), ("", 0));
	let script = format!(
		"zcompile -t {d}; print $?; zcompile -t {d} ${{1:t}}; print $?; zcompile -t {d} nope; print \
		 $?"
	);
	let real = run(true, &script, &files);
	let ours = run(false, &script, &files);
	let _ = fs::remove_dir_all(&dir);
	assert_eq!(ours, real);
}

/// A function found only in a digest (`DIR.zwc` beside `$fpath`'s `DIR`,
/// or a digest named in `$fpath`): zsh autoloads its word code, the engine
/// fails loudly.
#[test]
fn zcompile_digest_only_autoload_fails_loudly() {
	if !have_zsh() {
		return;
	}
	let dir = scratch("autoload");
	fs::create_dir_all(dir.join("fn")).unwrap();
	let script = "cd $1; zcompile $1/fn.zwc $1/fn/g; rm fn/g
fpath=($1/fn); autoload g; g; print st=$?
unfunction g; fpath=($1/fn.zwc); autoload g; g; print st=$?";
	let mut outs = Vec::new();
	for real in [true, false] {
		fs::write(dir.join("fn/g"), "echo from-g\n").unwrap();
		let _ = fs::remove_file(dir.join("fn.zwc"));
		outs.push(run(real, script, &[dir.display().to_string()]));
	}
	let _ = fs::remove_dir_all(&dir);
	assert_eq!(outs[0].0, "from-g\nst=0\nfrom-g\nst=0\n");
	assert_eq!(outs[1].0, "st=1\nst=1\n");
	assert_eq!(
		outs[1]
			.1
			.matches("not supported by this engine yet")
			.count(),
		2,
		"{}",
		outs[1].1
	);
}

/// `source ./x` when only `x.zwc` exists: zsh runs the word code, the
/// engine (which runs source text) fails loudly; with the source file
/// present both run it.
#[test]
fn zcompile_source_prefers_text_and_refuses_word_code_alone() {
	if !have_zsh() {
		return;
	}
	let dir = scratch("source");
	fs::write(dir.join("x"), "print sourced\n").unwrap();
	let script = "cd $1; zcompile x && source ./x; rm -f x; source ./x; print st=$?";
	let real = run(true, script, &[dir.display().to_string()]);
	fs::write(dir.join("x"), "print sourced\n").unwrap();
	let _ = fs::remove_file(dir.join("x.zwc"));
	let (out, err, _) = run(false, script, &[dir.display().to_string()]);
	let _ = fs::remove_dir_all(&dir);
	assert_eq!(real.0, "sourced\nsourced\nst=0\n");
	assert_eq!(out, "sourced\nst=1\n");
	assert!(err.contains("x.zwc") && err.contains("not supported by this engine yet"), "{err}");
}

import { afterEach, describe, expect, it } from "bun:test";
import { stream } from "@oh-my-pi/pi-ai/stream";
import { resolveAnthropicPrewarmTarget } from "@oh-my-pi/pi-ai/providers/anthropic-http-options";
import { prewarmModelConnection, resetConnectionPrewarmForTesting } from "@oh-my-pi/pi-ai/providers/connection-prewarm";
import type { FetchImpl, Model } from "@oh-my-pi/pi-ai/types";
import { resetDispatchOriginsForTesting, transportFetch } from "@oh-my-pi/pi-ai/utils/transport-fetch";
import { buildModel } from "@oh-my-pi/pi-catalog/build";
import type { Api } from "@oh-my-pi/pi-catalog/types";
import { withEnv, withOfficialAnthropicEndpoint } from "./helpers";

function model<TApi extends Api>(provider: string, api: TApi, baseUrl: string): Model<TApi> {
	return buildModel({
		id: "test-model",
		name: "Test Model",
		api,
		provider,
		baseUrl,
		reasoning: false,
		input: ["text"],
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		contextWindow: 200_000,
		maxTokens: 8_192,
	});
}

const ANTHROPIC = model("anthropic", "anthropic-messages", "https://api.anthropic.com");
// Bundled host; the Copilot credential routes requests to the account's plan host.
const COPILOT = model("github-copilot", "openai-completions", "https://api.githubcopilot.com");
const COPILOT_PLAN_URL = "https://api.business.githubcopilot.com/chat/completions";

function captureFetch(): { calls: Array<{ url: string; init: RequestInit & { tls?: unknown } }>; fetch: FetchImpl } {
	const calls: Array<{ url: string; init: RequestInit & { tls?: unknown } }> = [];
	const fetch: FetchImpl = async (input, init) => {
		calls.push({ url: String(input), init: init ?? {} });
		return new Response(null, { status: 404 });
	};
	return { calls, fetch };
}

/** Sends one inference request for {@link target} through the shared transport, as a turn would. */
async function dispatch(target: Model<Api>, url: string): Promise<void> {
	await transportFetch(target, async () => new Response("{}"))(url, { method: "POST", body: "{}" });
}

withOfficialAnthropicEndpoint();
afterEach(() => {
	resetConnectionPrewarmForTesting();
	resetDispatchOriginsForTesting();
});

describe("prewarmModelConnection", () => {
	it("warms official Anthropic with the real request's TLS options and no credentials", async () => {
		const { calls, fetch } = captureFetch();
		await prewarmModelConnection(ANTHROPIC, { fetch });

		// Capture an actual inference request after the public stream entry point's
		// transport processing, including inherited NODE_EXTRA_CA_CERTS. The mock
		// 404 terminates the request without network access or retryable errors.
		const real = captureFetch();
		const result = await stream(
			ANTHROPIC,
			{ messages: [{ role: "user", content: "Hi", timestamp: 0 }] },
			{ apiKey: "sk-ant-oat-test", fetch: real.fetch },
		).result();
		expect(result.stopReason).toBe("error");
		expect(real.calls).toHaveLength(1);
		expect(new URL(real.calls[0].url).origin).toBe("https://api.anthropic.com");
		expect(real.calls[0].init.method).toBe("POST");
		expect(new Headers(real.calls[0].init.headers).get("authorization")).toBe("Bearer sk-ant-oat-test");
		expect(calls).toHaveLength(1);
		expect(calls[0].url).toBe("https://api.anthropic.com");
		expect(calls[0].init.method).toBe("HEAD");
		expect(calls[0].init.tls).toEqual(real.calls[0].init.tls);
		expect(calls[0].init.tls).toMatchObject({ rejectUnauthorized: true, serverName: "api.anthropic.com" });
		const headers = new Headers(calls[0].init.headers);
		expect([headers.get("authorization"), headers.get("x-api-key")]).toEqual([null, null]);
	});

	it("warms the origin the model's last request reached, never a guess from baseUrl", async () => {
		const { calls, fetch } = captureFetch();
		await prewarmModelConnection(COPILOT, { fetch });
		await dispatch(COPILOT, COPILOT_PLAN_URL);
		await prewarmModelConnection(COPILOT, { fetch });

		expect(calls.map(call => [call.url, call.init.method])).toEqual([
			["https://api.business.githubcopilot.com", "HEAD"],
		]);
	});

	it("throttles repeat warm-ups per origin, not globally", async () => {
		const { calls, fetch } = captureFetch();
		await dispatch(COPILOT, COPILOT_PLAN_URL);
		await prewarmModelConnection(ANTHROPIC, { fetch });
		await prewarmModelConnection(ANTHROPIC, { fetch });
		await prewarmModelConnection(COPILOT, { fetch });
		await prewarmModelConnection(COPILOT, { fetch });

		expect(calls.map(call => call.url)).toEqual([
			"https://api.anthropic.com",
			"https://api.business.githubcopilot.com",
		]);
	});

	it("never probes custom providers, built-in ids routed to a gateway, or Anthropic gateways", async () => {
		const { calls, fetch } = captureFetch();
		const custom = model("corp-gateway", "openai-completions", "https://llm.corp.example/v1");
		await dispatch(custom, "https://llm.corp.example/v1/chat/completions");
		await prewarmModelConnection(custom, { fetch });
		// models.yml `provider: openai` with a gateway baseUrl.
		const overridden = model("openai", "openai-responses", "https://gateway.internal.example/v1");
		await dispatch(overridden, "https://gateway.internal.example/v1/responses");
		await prewarmModelConnection(overridden, { fetch });
		// Bundled xAI row rerouted at dispatch (XAI_BASE_URL).
		const rerouted = model("xai", "openai-completions", "https://api.x.ai/v1");
		await dispatch(rerouted, "https://xai-proxy.example/v1/chat/completions");
		await prewarmModelConnection(rerouted, { fetch });
		await prewarmModelConnection(model("anthropic", "anthropic-messages", "https://opencode.ai/zen"), { fetch });
		await withEnv({ ANTHROPIC_BASE_URL: "https://llm-gateway.corp.example" }, () =>
			prewarmModelConnection(ANTHROPIC, { fetch }),
		);

		expect(calls).toHaveLength(0);
	});

	it("settles quietly when resolving Anthropic's TLS options throws", async () => {
		const { calls, fetch } = captureFetch();
		await withEnv(
			{
				CLAUDE_CODE_USE_FOUNDRY: "1",
				FOUNDRY_BASE_URL: undefined,
				CLAUDE_CODE_CLIENT_CERT: "/nonexistent/client.pem",
			},
			async () => {
				expect(() => resolveAnthropicPrewarmTarget(ANTHROPIC)).toThrow();
				await expect(prewarmModelConnection(ANTHROPIC, { fetch })).resolves.toBeUndefined();
			},
		);

		expect(calls).toHaveLength(0);
	});
});

/**
 * Minimal ambient declarations for the Chrome extension APIs the relay
 * extension uses (promise-based MV3 forms only). Declared as a typed const —
 * not namespaces — because `debugger` is a reserved namespace name. Kept
 * local so the package stays dependency-free; extend as the worker grows.
 */

/** Chrome extension event surface (subset). */
interface ChromeEvent<T extends (...args: never[]) => void> {
	addListener(callback: T): void;
	removeListener(callback: T): void;
}

interface ChromeTab {
	id?: number;
	url?: string;
	pendingUrl?: string;
	title?: string;
	active: boolean;
	/** Chrome discarded this tab; it reloads when activated. */
	discarded: boolean;
	windowId: number;
	pinned: boolean;
	/** -1 when ungrouped. */
	groupId: number;
}

interface ChromeWindow {
	id?: number;
	focused: boolean;
	/** "minimized" windows are still valid tab destinations. */
	state?: "normal" | "minimized" | "maximized" | "fullscreen" | "locked-fullscreen";
}

interface ChromeTabChangeInfo {
	url?: string;
	title?: string;
	status?: string;
}

/** Debuggee with the Chrome 125+ flat-session extension. */
interface ChromeDebuggerSession {
	tabId?: number;
	sessionId?: string;
}

interface ChromeDebuggerTargetInfo {
	id: string;
	type: string;
	attached: boolean;
	tabId?: number;
	title?: string;
	url?: string;
}

declare const chrome: {
	tabs: {
		query(queryInfo: { url?: string; groupId?: number }): Promise<ChromeTab[]>;
		get(tabId: number): Promise<ChromeTab>;
