/**
 * Second `renderCall` argument that satisfies both the omp and the upstream-pi
 * renderer contracts.
 *
 * omp invokes renderers as `renderCall(args, options, theme)` (see
 * `packages/tui/src/tools/renderer.ts`), while pi-era renderers — including
 * every third-party plugin written against pi's published example — are
 * declared `renderCall(args, theme, context)`. Both shapes take three
 * parameters, so arity cannot discriminate them. The returned value carries
 * both instead: own keys stay the render options, every other property
 * resolves against the live theme. `Theme` keeps its state in `#private`
 * fields, so delegated methods are bound to the theme instance rather than to
 * the proxy.
 */
function renderOptionsWithTheme<T extends object>(options: T, theme: Theme): T & Theme {
	const delegates = new Map<PropertyKey, unknown>();
	return new Proxy(options, {
		get(target, prop, receiver) {
			if (Object.hasOwn(target, prop)) return Reflect.get(target, prop, receiver);
			const delegate = delegates.get(prop);
			if (delegate !== undefined) return delegate;
			const value = Reflect.get(theme, prop, theme);
			if (typeof value !== "function") return value;
			const bound = value.bind(theme);
			delegates.set(prop, bound);
			return bound;
		},
	}) as T & Theme;
}

/**
 * Adapts a RegisteredTool into an AgentTool.
 */
export class RegisteredToolAdapter implements AgentTool<any, any, any> {
	declare name: string;
	get description(): string {
		const description = this.registeredTool.definition.description;
		const guidance = this.runner.getNativeDelegationGuidance(this.name);
		return guidance
			? prompt.render(nativeDelegationTemplate, { description, name: this.name, guidance })
			: description;
	}
	declare parameters: any;
	declare label: string;
	declare strict: boolean;

	renderCall?: (args: any, options: any, theme: any) => any;
	renderResult?: (result: any, options: any, theme: any, args?: any) => any;
	readonly loadMode: ToolLoadMode;

	constructor(
		private registeredTool: RegisteredTool,
		private runner: ExtensionRunner,
	) {
		applyToolProxy(registeredTool.definition, this);
		this.loadMode = defaultLoadModeForToolName(registeredTool.definition.name, registeredTool.definition.loadMode);

		// Only define render methods when the underlying definition provides them.
		// If these exist unconditionally on the prototype, ToolExecutionComponent
		// enters the custom-renderer path, gets undefined back, and silently
		// discards tool result text (extensions without renderers show blank).
		if (registeredTool.definition.renderCall) {
			this.renderCall = (args: any, options: any, theme: any) =>
				registeredTool.definition.renderCall!(
					args,
					renderOptionsWithTheme(options, theme as Theme),
					theme as Theme,
				);
		}
		if (registeredTool.definition.renderResult) {
			this.renderResult = (result: any, options: any, theme: any, args?: any) =>
				registeredTool.definition.renderResult!(
					result,
					{ expanded: options.expanded, isPartial: options.isPartial, spinnerFrame: options.spinnerFrame },
					theme as Theme,
					args,
				);
		}
	}

	async execute(
		toolCallId: string,
		params: any,
		signal?: AbortSignal,
		onUpdate?: AgentToolUpdateCallback<any>,
		context?: AgentToolContext,
	) {
		// Bind the extension context to this tool's own name so `ctx.invokeTool` delegates to the
		// native built-in of the same name (present only when this tool re-registers a built-in). The
		// wrapper's own context, abort signal, and progress callback are inherited by the delegated
		// call, so a bare `ctx.invokeTool(params)` keeps the caller's `toolCall`/provider metadata
		// (write/edit LSP batching, computer safety acknowledgement), stops when the outer call is
		// aborted, and still streams native progress.
		return this.registeredTool.definition.execute(
			toolCallId,
			params,
			signal,
			onUpdate,
			this.runner.createContext(undefined, {
				toolName: this.registeredTool.definition.name,
				context,
				signal,
				onUpdate,
			}),
		);
	}
}

/**
 * Backward-compatible factory function wrapper.
 */
export function wrapRegisteredTool(registeredTool: RegisteredTool, runner: ExtensionRunner): AgentTool {
	return new RegisteredToolAdapter(registeredTool, runner);
}

/**
 * Wrap all registered tools into AgentTools.
 */
export function wrapRegisteredTools(registeredTools: RegisteredTool[], runner: ExtensionRunner): AgentTool[] {
	return registeredTools.map(rt => wrapRegisteredTool(rt, runner));
}

const LOOP_DISPATCH_CONTEXT = Symbol("omp.loop-dispatch");
type LoopAwareToolContext = AgentToolContext & { [LOOP_DISPATCH_CONTEXT]?: true };

function computerSafetyChecks(context: AgentToolContext | undefined): ComputerSafetyCheck[] {
	const metadata = context?.toolCall?.providerMetadata;
	return metadata?.type === "computer" ? metadata.pendingSafetyChecks : [];
}

function approvalArgs(params: unknown, context: AgentToolContext | undefined): unknown {
	const metadata = context?.toolCall?.providerMetadata;
	return metadata?.type === "computer" ? { actions: metadata.actions } : params;
}

function toolEventArgs(params: unknown, context: AgentToolContext | undefined): Record<string, unknown> {
	const metadata = context?.toolCall?.providerMetadata;
	if (metadata?.type === "computer") {
		return {
			actions: metadata.actions,
			pendingSafetyChecks: metadata.pendingSafetyChecks,
		};
	}
	return params as Record<string, unknown>;
}

function approvalData(value: string): string {
	const sanitized = sanitizeText(value)
		.replace(/[\r\n\t]+/g, " ")
		.trim();
	const truncated = truncateForPrompt(sanitized, 500);
	return truncated.replace(/([\\`*_{}[\]()<>#+\-.!|])/g, "\\$1");
}

function safetyCheckLines(checks: readonly ComputerSafetyCheck[]): string[] {
	return checks.map((check, index) => {
		const value = check.message || check.code || check.id;
		return `${index + 1}. ${approvalData(value)}`;
	});
}

/**
 * Wraps a tool with extension callbacks for interception.
 * - Emits tool_call event before execution (can block)
 * - Emits tool_result event after execution (can modify result)
 *
 * `agent` overrides the runner's own `ctx.agent` for those events when the tool
 * runs on behalf of a different agent than the runner's session — the advisor's
 * toolset shares the primary session's runner (for approval enforcement) but
 * must not be reported as the primary agent.
 */
export class ExtensionToolWrapper<TParameters extends TSchema = TSchema, TDetails = unknown> implements AgentTool<
	TParameters,
	TDetails
> {
	declare name: string;
	declare description: string;
	declare parameters: TParameters;
	declare label: string;
	declare strict: boolean;
	readonly #agent: ExtensionAgentIdentity | undefined;

	constructor(
		private tool: AgentTool<TParameters, TDetails>,
		private runner: ExtensionRunner,
		agent?: ExtensionAgentIdentity,
	) {
		this.#agent = agent;
		applyToolProxy(tool, this);
	}

	/**
	 * Forward browser mode changes when available.
	 */
	restartForModeChange(): Promise<void> {
		const target = this.tool as { restartForModeChange?: () => Promise<void> };
		if (!target.restartForModeChange) return Promise.resolve();
		return target.restartForModeChange();
	}

	async execute(
		toolCallId: string,
		params: Static<TParameters>,
		signal?: AbortSignal,
		onUpdate?: AgentToolUpdateCallback<TDetails, TParameters>,
		context?: AgentToolContext,
	): Promise<AgentToolResult<TDetails, TParameters>> {
		return withToolApprovalScope(() => this.#execute(toolCallId, params, signal, onUpdate, context));
	}

	async #execute(
		toolCallId: string,
		params: Static<TParameters>,
		signal?: AbortSignal,
		onUpdate?: AgentToolUpdateCallback<TDetails, TParameters>,
		context?: AgentToolContext,
	): Promise<AgentToolResult<TDetails, TParameters>> {
		const executionSessionId = this.runner.sessionId;
		const executionApprovalEpoch = this.runner.getSessionApprovalEpoch();
		const contextSessionId = context?.sessionManager?.getSessionId();
		// The agent loop emits `tool_call` at arg-prep time (session
		// `beforeToolCall` wiring) so a handler revision lands before concurrency
		// scheduling and `tool_execution_start`. Consume the marker
		// unconditionally so it cannot go stale; emit here only for dispatches
		// the loop never saw — nested xd:// device dispatches and direct
		// (non-loop) execution such as Cursor exec handlers.
		const inheritedLoopDispatch = (context as LoopAwareToolContext | undefined)?.[LOOP_DISPATCH_CONTEXT] === true;
		const loopDispatchedToolCall =
			(this.runner.consumeLoopToolCall?.(toolCallId, this.tool.name) ?? false) || inheritedLoopDispatch;
		if (loopDispatchedToolCall && context && !inheritedLoopDispatch) {
			(context as LoopAwareToolContext)[LOOP_DISPATCH_CONTEXT] = true;
		}
		const loopEmittedToolCall = this.runner.consumeToolCallEmitted(toolCallId, this.tool.name);
		// Resolve approval settings up front. A `deny` on the original input short-circuits before the
		// runner is touched — an already-denied tool never emits `tool_call` — while the full gate below
		// re-resolves against the (possibly revised) input so a handler cannot rewrite into a denied or
		// newly prompt-gated command and have it run unapproved.
		const approvalSettings = context?.settings ?? this.runner.sessionSettings;
		const { approvalMode, userPolicies } = resolveApprovalFromContext(
			context ?? (approvalSettings ? { settings: approvalSettings } : undefined),
		);
		// `always-ask-cached` grants for this conversation, shared by the pre-check, the full gate,
		// and the record after an approval.
		const approvalGrants =
			approvalMode === "always-ask-cached"
				? getApprovalGrants(approvalSettings?.getAgentDir(), this.runner.sessionId)
				: undefined;
		const restrictions = approvalRestrictions(approvalSettings, this.runner.cwd);
		const preResolved = resolveApproval(
			this.tool,
			approvalArgs(params, context),
			approvalMode,
			userPolicies,
			approvalGrants,
			restrictions,
			context,
		);
		if (preResolved.policy === "deny") {
			throw denyError(preResolved, this.tool.name);
		}

		// 1. Emit tool_call event first - extensions can block execution or revise the input the tool
		// runs with. Doing this BEFORE the approval gate means approval (below) resolves against the
		// input that actually executes, closing the "approve one thing, run another" gap: the prompt
		// text, policy resolution, and provider safety checks all see `effectiveParams`.
		// Passive context collected here is forwarded only once the call has run
		// and produced a non-error result: a block, deny, user reject, fail-closed
		// safety refusal, or failed execution never injects instructions. This
		// matches the loop's rule for context prepared at arg-prep time.
		let pendingAdditionalContext: string | undefined;
		let effectiveParams = params;
		const cancelPreflight = (): void => {
			if (!loopDispatchedToolCall) this.runner.cancelToolCallPreflight?.(toolCallId);
		};
		const assertCurrentExecution = (): void => {
			try {
				signal?.throwIfAborted();
				if (
					this.runner.sessionId !== executionSessionId ||
					this.runner.getSessionApprovalEpoch() !== executionApprovalEpoch ||
					context?.sessionManager?.getSessionId() !== contextSessionId
				) {
					throw new Error("Tool call cancelled because its session changed");
				}
			} catch (error) {
				cancelPreflight();
				throw error;
			}
		};
		assertCurrentExecution();
		if (!loopEmittedToolCall && this.runner.hasHandlers("tool_call")) {
			try {
				const callResult = (await this.runner.emitToolCall(
					{
						type: "tool_call",
						toolName: this.tool.name,
						toolCallId,
						input: normalizeToolEventInput(
							this.tool.name,
							resolveToolEventInput(this.tool, toolEventArgs(params, context)),
						),
					},
					signal,
					this.#agent,
				)) as ToolCallEventResult | undefined;

				if (callResult?.block) {
					const reason = callResult.reason || "Tool execution was blocked by an extension";
					throw new Error(reason);
				}
				if (isNonBlankContext(callResult?.additionalContext)) {
					pendingAdditionalContext = callResult.additionalContext;
				}
				// A non-blocking handler may replace the execution input. The returned object is the raw
				// input passed to `execute` (handler-owned; not re-normalized). Skipped for `computer`
				// tool calls, whose event input is a synthetic {actions,pendingSafetyChecks} view
				// (see toolEventArgs) rather than the real execution params.
				if (callResult?.input !== undefined && context?.toolCall?.providerMetadata?.type !== "computer") {
					effectiveParams = callResult.input as typeof params;
				}
			} catch (err) {
				if (err instanceof Error) {
					throw err;
				}
				throw new Error(`Extension failed, blocking execution: ${String(err)}`);
			}
		}
		if (!loopDispatchedToolCall) {
			const preflight = await this.runner.runToolCallPreflightBefore?.(
				toolCallId,
				this.tool,
				effectiveParams,
				context,
			);
			if (preflight?.block) {
				throw new Error(preflight.reason || "Tool execution was blocked by a preflight rule");
			}
		}

		assertCurrentExecution();

		// 2. Full approval gate against the (possibly revised) input that will actually run — resolves
		// policy and prompts on `effectiveParams`, so the user approves exactly what executes. A revised
		// input that newly resolves to `deny` is caught here even though the original passed the
		// short-circuit above.
		const resolvedArgs = approvalArgs(effectiveParams, context);
		this.tool.bindApprovalTargets?.(resolvedArgs);
		const resolved = resolveApproval(
			this.tool,
			resolvedArgs,
			approvalMode,
			userPolicies,
			approvalGrants,
			restrictions,
			context,
		);
		context?.xdevTierResolved?.(resolved.tier);
		if (resolved.policy === "deny") {
			cancelPreflight();
			throw denyError(resolved, this.tool.name);
		}
		const pendingSafetyChecks = computerSafetyChecks(context);
		// Outer approvals only cover the original input. `xd://` approval skips
		// tier-only prompts, and an explicit prompt under the policy key the outer
		// gate already asked about, while the same object flows through; ACP
		// approval also satisfies explicit prompts, but compares against a deep
		// snapshot because handlers can mutate the original argument object in
		// place. Denies were enforced above, and provider safety checks remain
		// independently required.
		const policyKey = resolved.policyKey ?? this.tool.name;
		const explicitPrompt =
			resolved.override || (Object.hasOwn(userPolicies, policyKey) && policyKey !== context?.xdevPolicyKey);
		const xdevBypass = context?.xdevPolicyKey !== undefined && effectiveParams === params;
		const acpBypass =
			context !== undefined &&
			Object.hasOwn(context, "acpApprovedArgs") &&
			Bun.deepEquals(effectiveParams, context.acpApprovedArgs);
		// Only a prompt `always-ask-cached` itself raised can be remembered by target; provider safety
		// checks are per-call, so they never offer a grant of any kind.
		const grantable =
			approvalGrants !== undefined &&
			resolved.policy === "prompt" &&
			resolved.source === "mode" &&
			pendingSafetyChecks.length === 0;
		const cacheTargets = grantable ? (this.tool.approvalCacheTargets?.(resolvedArgs)?.length ?? 0) > 0 : false;
		// A prompt the approval mode raised can be approved for the rest of the session — unless the call
		// can be remembered by target instead, which keeps the grant to what it touches.
		const sessionScope =
			pendingSafetyChecks.length === 0 && !cacheTargets ? sessionApprovalScope(resolved, this.tool.name) : undefined;
		const sessionApproved = sessionScope !== undefined && this.runner.hasSessionApproval(sessionScope.key);
		const approvalCheck = {
			required:
				pendingSafetyChecks.length > 0 ||
				(resolved.policy === "prompt" && !acpBypass && !sessionApproved && (explicitPrompt || !xdevBypass)),
			reason: resolved.reason,
		};

		if (approvalCheck.required) {
			const scheduledCall = context?.toolCall?.toolCalls[context.toolCall.index];
			if (
				scheduledCall?.id === toolCallId &&
				(scheduledCall.name === this.tool.name || scheduledCall.name === this.tool.customWireName)
			) {
				await untilAborted(signal, () => this.runner.waitForToolApprovalPreview(toolCallId));
			}

			const hasApprovalHandlers =
				this.runner.hasHandlers("tool_approval_requested") || this.runner.hasHandlers("tool_approval_resolved");
			const sessionId = context?.sessionManager?.getSessionId() ?? "";
			if (hasApprovalHandlers) {
				await this.runner.emit({
					type: "tool_approval_requested",
					sessionId,
					toolName: this.tool.name,
					toolCallId,
					...(approvalCheck.reason ? { reason: approvalCheck.reason } : {}),
					approvalMode,
				});
			}

			const emitApprovalResolved = async (approved: boolean, reason?: string) => {
				if (!hasApprovalHandlers) return;
				await this.runner.emit({
					type: "tool_approval_resolved",
					sessionId,
					toolName: this.tool.name,
					toolCallId,
					approved,
					...(reason ? { reason } : {}),
				});
			};

			// Provider safety checks fail closed without an interactive prompt. Unlike
			// ordinary tier approval, no setting or yolo mode may bypass this gate.
			if (!this.runner.hasUI()) {
				const reason = "no interactive UI available";
				await emitApprovalResolved(false, reason);
				cancelPreflight();
				if (pendingSafetyChecks.length > 0) {
					throw new Error(
						`Tool "${this.tool.name}" has pending provider safety checks but no interactive UI is available.`,
					);
				}
				if (resolved.source === "restriction") {
					throw new Error(
						`Tool "${this.tool.name}" requires approval but no interactive UI available.\n` +
							`Reason: ${resolved.reason}\n` +
							`A restricted folder (tools.restrictedFolders) asks in every approval mode.`,
					);
				}
				throw new Error(
					`Tool "${this.tool.name}" requires approval but no interactive UI available.\n` +
						`Options:\n` +
						`  1. Set tools.approvalMode: yolo in /settings\n` +
						`  2. Add tools.approval.${this.tool.name}: allow to config\n` +
						`  3. Use an interactive UI to approve the tool call`,
				);
			}

			const uiContext = this.runner.getUIContext();
			const safetyAppendix =
				pendingSafetyChecks.length > 0 ? ["Provider safety checks:", ...safetyCheckLines(pendingSafetyChecks)] : [];
			let approved: boolean;
			let answer: ExtensionApprovalAnswer;
			try {
				assertCurrentExecution();
				answer = await untilAborted(signal, () =>
					requestApproval(uiContext, this.tool, resolvedArgs, {
						reason: approvalCheck.reason,
						appendix: safetyAppendix,
						sessionSubject: sessionScope?.subject,
						grants: cacheTargets,
					}),
				);
				assertCurrentExecution();
				approved = answer !== "deny";
			} catch (err) {
				await emitApprovalResolved(false, err instanceof Error ? err.message : "approval aborted");
				cancelPreflight();
				throw err;
			}
			await emitApprovalResolved(approved, approved ? undefined : "denied by user");
			assertCurrentExecution();
			if (!approved) {
				cancelPreflight();
				throw new Error(`Tool call denied by user: ${this.tool.name}`);
			}
			if (answer === "session" && sessionScope) this.runner.grantSessionApproval(sessionScope.key);
			if (typeof answer === "object" && approvalGrants) {
				recordApprovalGrant(this.tool, resolvedArgs, approvalGrants, resolved.tier, answer);
			}
			if (pendingSafetyChecks.length > 0) {
				if (!context) {
					cancelPreflight();
					throw new Error("Provider safety approval context is unavailable");
				}
				context.providerSafetyApproved = true;
			}
		}

		assertCurrentExecution();

		// Execute the actual tool
		let result: AgentToolResult<TDetails, TParameters>;
		let executionError: Error | undefined;

		try {
			// Name the owning session for process-wide file-mutation fallbacks and
			// expose its settings to registered tools and any fallback handlers they
			// trigger. `sdk.ts` wraps the whole tool registry with this class whenever
			// a runner exists.
			result = await this.runner.runScoped(() =>
				withFileMutationSession(this.runner.sessionId, () =>
					this.tool.execute(toolCallId, effectiveParams, signal, onUpdate, context),
				),
			);
		} catch (err) {
			executionError = toError(err);
			result = {
				content: [{ type: "text", text: executionError.message }],
				details: undefined as TDetails,
			};
		}
		if (!loopDispatchedToolCall) {
			const postflight = await this.runner.runToolCallPreflightAfter?.(toolCallId, result, context);
			if (postflight) result = postflight as AgentToolResult<TDetails, TParameters>;
		}

		// Emit tool_result event - extensions can modify the result and error status
		if (this.runner.hasHandlers("tool_result")) {
			const resultResult = await this.runner.emitToolResult(
				{
					type: "tool_result",
					toolName: this.tool.name,
					toolCallId,
					input: normalizeToolEventInput(
						this.tool.name,
						resolveToolEventInput(this.tool, toolEventArgs(effectiveParams, context)),
					),
					content: result.content,
					details: result.details,
					isError: !!executionError || result.isError === true,
				},
				this.#agent,
			);

			// Handler context reports into this call's sink like tool-authored
			// context: it is delivered even for a failed call (the handler saw
			// `isError`), and precedes any pending `tool_call` context.
			if (resultResult?.additionalContext !== undefined) {
				context?.addAdditionalContext?.(resultResult.additionalContext);
			}

			// `content` is present only when a handler modified the result.
			if (resultResult?.content !== undefined) {
				const modifiedContent: (TextContent | ImageContent)[] = resultResult.content;
				const modifiedDetails = (resultResult.details ?? result.details) as TDetails;

				// Effective error state: an explicit handler override wins; otherwise the
				// original execution outcome stands. This lets a handler rewrite a failed
				// call's model-visible content/details while keeping it an error, flip a
				// failure to success, or flag a success as an error.
				const effectiveError = resultResult.isError ?? !!executionError;
				if (!effectiveError && pendingAdditionalContext !== undefined) {
					context?.addAdditionalContext?.(pendingAdditionalContext);
				}

				// Return the (possibly modified) result carrying the error flag rather than
				// rethrowing the original exception. The agent loop honors
				// `AgentToolResult.isError` and surfaces it as a tool error on the wire (see
				// `coerceToolResult` in agent-loop), so replacement failure content reaches
				// the model while the call remains an error — the original exception text is
				// no longer forced through, which previously discarded the replacement.
				return {
					content: modifiedContent,
					details: modifiedDetails,
					providerMetadata: result.providerMetadata,
					...(effectiveError ? { isError: true } : {}),
				};
			}
		}

		// No extension modification
		if (executionError) {
			throw executionError;
		}
		if (result.isError !== true && pendingAdditionalContext !== undefined) {
			context?.addAdditionalContext?.(pendingAdditionalContext);
		}
		return result;
	}
}

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { isEnoent, sanitizeText, tryAcquireFileLock, withFileLock } from "@oh-my-pi/pi-utils";
import type { MemoryWriteScope } from "../memory-backend/global-scope";
import { redactMemorySecrets } from "../memory-backend/redact";
import { writeFileAtomically } from "../utils/atomic-file";
import { type HindsightClientApi, HindsightError } from "./client";

const QUARANTINE_DIR = "quarantine";
/** Undelivered events older than this are quarantined, so a destination no session drains anymore cannot keep them forever. */
const EVENT_TTL_MS = 7 * 24 * 60 * 60 * 1000;
/** Quarantined events stay this long for manual review. */
const QUARANTINE_TTL_MS = 30 * 24 * 60 * 60 * 1000;
/** Undelivered events per destination; past it, writes fail instead of evicting. */
const MAX_EVENTS = 1000;
const BATCH_SIZE = 16;
const EVENT_FILE = /^omp-retain-[a-f0-9]{32}\.json$/;
/** Statuses that refuse the request body itself; every other failure is retried. */
const REJECTED_PAYLOAD_STATUSES = new Set([400, 413, 422]);

export interface RetainInput {
	content: string;
	context?: string;
	scope?: MemoryWriteScope;
}

/** A published event file. Never rewritten, so its mtime is its enqueue time. */
export interface OutboxEvent {
	version: 1;
	/** Also the server `document_id`, so a resend replaces instead of duplicating. */
	id: string;
	scope: MemoryWriteScope;
	tags: string[];
	timestamp: string;
	content: string;
	context: string;
	sessionId: string;
	/** Stable same-call tie break for equal publication mtimes; absent on legacy v1 events. */
	deliveryOrder?: { batch: string; index: number };
}

export interface RetainCall {
	sessionId: string;
	toolCallId: string;
	/** Context for items without their own. */
	context: string;
	/** Tags of project-scoped items; global items are retained untagged. */
	tags: string[] | undefined;
}

export interface DrainResult {
	/** Another holder is draining this destination, or an enqueue is mid-batch; nothing was sent. */
	busy: boolean;
	delivered: number;
	/** Events refused by the server, malformed, or past their TTL, across all destinations. */
	quarantined: number;
	/** Set when a retryable failure stopped delivery; `kept` events remain for retry. */
	error?: string;
	kept: number;
}

export interface HindsightOutboxOptions {
	agentDir: string;
	apiUrl: string;
	bankId: string;
	apiToken: string | null;
	client: HindsightClientApi;
	ensureBank: () => Promise<void>;
}

interface Pending {
	file: string;
	event: OutboxEvent;
	/** Publication time (mtime); delivery follows it. */
	published: number;
}

type SendOutcome = "accepted" | "rejected" | { error: string };

/** A total order: only equal mtimes use the persisted batch/item tie break.
 * Legacy ties are deterministic but their lost original input order cannot be recovered.
 */
function comparePending(a: Pending, b: Pending): number {
	const time = a.published - b.published;
	if (time) return time;
	const aBatch = a.event.deliveryOrder?.batch ?? a.event.id;
	const bBatch = b.event.deliveryOrder?.batch ?? b.event.id;
	if (aBatch !== bBatch) return aBatch < bBatch ? -1 : 1;
	const index = (a.event.deliveryOrder?.index ?? 0) - (b.event.deliveryOrder?.index ?? 0);
	if (index) return index;
	return a.event.id === b.event.id ? 0 : a.event.id < b.event.id ? -1 : 1;
}

function validDeliveryOrder(value: unknown): boolean {
	if (value === undefined) return true;
	if (typeof value !== "object" || value === null) return false;
	const order = value as { batch?: unknown; index?: unknown };
	return (
		typeof order.batch === "string" &&
		/^[a-f0-9]{64}$/.test(order.batch) &&
		typeof order.index === "number" &&
		Number.isSafeInteger(order.index) &&
		order.index >= 0
	);
}

/**
 * Durable queue of tool-initiated retains: one immutable file per memory under
 * `<agentDir>/hindsight-outbox/<destination>/`. A 2xx response deletes the event; it
 * means server acceptance, not completed extraction.
 *
 * Concurrency: a per-destination queue lock serializes capacity checks and
 * publication, and the drainer takes it for the instant it lists and reads
 * events, so a snapshot never lands inside a batch that may still roll back; a
 * per-destination drain lease, released by the OS when its process exits, lets
 * exactly one holder send and delete events. Event files are never rewritten,
 * so writers and the drainer never contend for one file.
 */
export class HindsightOutbox {
	readonly #root: string;
	readonly #dir: string;
	readonly #options: HindsightOutboxOptions;

	constructor(options: HindsightOutboxOptions) {
		this.#options = options;
		this.#root = path.join(options.agentDir, "hindsight-outbox");
		this.#dir = path.join(this.#root, destinationKey(options.apiUrl, options.bankId));
	}

	/** Where refused, malformed, and expired events go for review. */
	get quarantineDir(): string {
		return path.join(this.#root, QUARANTINE_DIR);
	}

	/**
	 * Persists one tool call's items, all or none, before resolving. Returns how many
	 * events are new: a retried call has the same ids and publishes nothing again.
	 */
	async enqueue(call: RetainCall, items: RetainInput[]): Promise<number> {
		if (!call.sessionId || !call.toolCallId) throw new Error("Hindsight retain requires a session and tool call id.");
		const events = items.map((item, index) => this.#event(call, item, index));
		// Compute from the complete call before deduplication. Existing files are
		// never rewritten, so retries preserve their metadata and publication time.
		const batch = new Bun.CryptoHasher("sha256").update(JSON.stringify(events.map(event => event.id))).digest("hex");
		for (const [index, event] of events.entries()) event.deliveryOrder = { batch, index };
		await fs.mkdir(this.#dir, { recursive: true, mode: 0o700 });
		return withFileLock(path.join(this.#dir, "queue"), async () => {
			const existing = new Set(await eventFiles(this.#dir));
			const fresh = events.filter(event => !existing.has(eventFile(event.id)));
			if (existing.size + fresh.length > MAX_EVENTS) {
				throw new Error(`Hindsight outbox full (${existing.size} undelivered memories); memory NOT queued.`);
			}
			const written: string[] = [];
			try {
				for (const event of fresh) {
					const file = path.join(this.#dir, eventFile(event.id));
					await writeFileAtomically(file, JSON.stringify(event));
					written.push(file);
				}
				await syncDirectory(this.#dir);
			} catch (error) {
				await Promise.all(written.map(file => fs.rm(file, { force: true })));
				throw new Error("Hindsight outbox write failed; memory NOT queued.", { cause: error });
			}
			return fresh.length;
		});
	}

	/**
	 * Sends this destination's events and quarantines every destination's expired
	 * ones. Stops at the first retryable failure; events stay on disk for the next drain.
	 */
	async drain(): Promise<DrainResult> {
		const result: DrainResult = { busy: false, delivered: 0, quarantined: 0, kept: 0 };
		let destinations: string[];
		try {
			destinations = (await fs.readdir(this.#root, { withFileTypes: true }))
				.filter(entry => entry.isDirectory() && entry.name !== QUARANTINE_DIR)
				.map(entry => path.join(this.#root, entry.name));
		} catch (error) {
			if (isEnoent(error)) return result;
			throw error;
		}
		for (const dir of destinations) {
			const lease = tryAcquireFileLock(path.join(dir, "drain"));
			if (!lease) {
				if (dir === this.#dir) result.busy = true;
				continue;
			}
			try {
				if (dir === this.#dir) await this.#deliver(result);
				else await this.#expire(dir, result);
			} finally {
				lease.release();
			}
		}
		return result;
	}

	#event(call: RetainCall, item: RetainInput, index: number): OutboxEvent {
		const scope = item.scope ?? "project";
		const context = this.#clean(item.context ?? call.context);
		const content = this.#clean(item.content);
		// Tool call ids are not guaranteed unique, so the persisted fields are part of the
		// identity: a reused id with new content is a new document, not a replacement.
		const identity = JSON.stringify([call.sessionId, call.toolCallId, index, scope, context, content]);
		return {
			version: 1,
			id: `omp-retain-${new Bun.CryptoHasher("sha256").update(identity).digest("hex").slice(0, 32)}`,
			scope,
			tags: scope === "global" ? [] : (call.tags ?? []).map(tag => this.#clean(tag)),
			timestamp: new Date().toISOString(),
			content,
			context,
			sessionId: this.#clean(call.sessionId),
		};
	}

	/** Events are stored at rest: strip terminal controls, the bearer token, and recognizable secrets. */
	#clean(text: string): string {
		const token = this.#options.apiToken;
		return redactMemorySecrets(sanitizeText(token ? text.replaceAll(token, "[REDACTED]") : text));
	}

	async #deliver(result: DrainResult): Promise<void> {
		// The snapshot must land between batches, never inside one: an enqueue that
		// fails midway rolls its files back, and what a drain already sent cannot be
		// unsent. The queue lock enqueue holds across publication and rollback keeps
		// this snapshot out of that window; when it is taken, defer like drain-lease
		// contention, since delivery always retries.
		const lease = tryAcquireFileLock(path.join(this.#dir, "queue"));
		if (!lease) {
			result.busy = true;
			return;
		}
		const invalid: string[] = [];
		const pending: Pending[] = [];
		try {
			const now = Date.now();
			for (const name of await eventFiles(this.#dir)) {
				const file = path.join(this.#dir, name);
				const entry = await readEvent(file, now);
				if (entry) pending.push(entry);
				else invalid.push(file);
			}
		} finally {
			lease.release();
		}
		// Hindsight unions a request's item tags onto its document(s): one request per tag set, so
		// untagged global memories never share a request with project-tagged ones.
		const groups = new Map<string, Pending[]>();
		for (const entry of pending.sort(comparePending)) {
			const key = JSON.stringify(entry.event.tags.toSorted());
			const group = groups.get(key);
			if (group) group.push(entry);
			else groups.set(key, [entry]);
		}
		result.quarantined += await this.#quarantine(invalid);
		if (groups.size === 0) return;
		await this.#options.ensureBank();
		for (const group of groups.values()) {
			for (let start = 0; start < group.length; start += BATCH_SIZE) {
				if (!(await this.#deliverBatch(group.slice(start, start + BATCH_SIZE), result))) {
					result.kept = (await eventFiles(this.#dir)).length;
					return;
				}
			}
		}
	}

	/** Returns false when a retryable failure should stop this drain. */
	async #deliverBatch(batch: Pending[], result: DrainResult): Promise<boolean> {
		const outcome = await this.#send(batch);
		if (outcome === "accepted") {
			await Promise.all(batch.map(({ file }) => fs.rm(file, { force: true })));
			result.delivered += batch.length;
			return true;
		}
		if (outcome !== "rejected") {
			result.error = outcome.error;
			return false;
		}
		if (batch.length === 1) {
			result.quarantined += await this.#quarantine([batch[0].file]);
			return true;
		}
		// One refused item fails the whole request; resend singly so only refused items are quarantined.
		for (const pending of batch) {
			if (!(await this.#deliverBatch([pending], result))) return false;
		}
		return true;
	}

	async #send(batch: Pending[]): Promise<SendOutcome> {
		try {
			await this.#options.client.retainBatch(
				this.#options.bankId,
				batch.map(({ event }) => ({
					content: event.content,
					context: event.context,
					timestamp: new Date(event.timestamp),
					metadata: { session_id: event.sessionId },
					tags: event.tags.length > 0 ? event.tags : undefined,
					documentId: event.id,
					updateMode: "replace",
				})),
				{ async: true },
			);
			return "accepted";
		} catch (error) {
			if (error instanceof HindsightError && REJECTED_PAYLOAD_STATUSES.has(error.statusCode ?? 0)) return "rejected";
			return { error: error instanceof Error ? error.message : String(error) };
		}
	}

	/** Quarantines another destination's expired events; their owner may never drain again. */
	async #expire(dir: string, result: DrainResult): Promise<void> {
		const cutoff = Date.now() - EVENT_TTL_MS;
		const expired: string[] = [];
		for (const name of await eventFiles(dir)) {
			const file = path.join(dir, name);
			if ((await fs.stat(file)).mtimeMs < cutoff) expired.push(file);
		}
		result.quarantined += await this.#quarantine(expired);
	}

	/** Moves `files` to quarantine, then deletes quarantined events past their review period. */
	async #quarantine(files: string[]): Promise<number> {
		if (files.length === 0) return 0;
		const dir = this.quarantineDir;
		await fs.mkdir(dir, { recursive: true, mode: 0o700 });
		const now = new Date();
		for (const file of files) {
			const target = path.join(dir, path.basename(file));
			await fs.rename(file, target);
			// The review period starts now, not at enqueue.
			await fs.utimes(target, now, now);
		}
		const cutoff = now.getTime() - QUARANTINE_TTL_MS;
		for (const name of await fs.readdir(dir)) {
			const file = path.join(dir, name);
			if ((await fs.stat(file)).mtimeMs < cutoff) await fs.rm(file, { force: true });
		}
		return files.length;
	}
}

function eventFile(id: string): string {
	return `${id}.json`;
}

async function eventFiles(dir: string): Promise<string[]> {
	return (await fs.readdir(dir)).filter(name => EVENT_FILE.test(name));
}

/** Credential-free: query, fragment, and userinfo never reach the directory name. */
function destinationKey(apiUrl: string, bankId: string): string {
	const url = new URL(apiUrl);
	const identity = `${url.origin}${url.pathname.replace(/\/+$/, "")}\0${bankId}`;
	return new Bun.CryptoHasher("sha256").update(identity).digest("hex").slice(0, 16);
}

/** The pending event, or `undefined` when it is malformed or past its TTL. */
async function readEvent(file: string, now: number): Promise<Pending | undefined> {
	const published = (await fs.stat(file)).mtimeMs;
	if (published < now - EVENT_TTL_MS) return undefined;
	try {
		const event = (await Bun.file(file).json()) as OutboxEvent;
		const valid =
			event.version === 1 &&
			validDeliveryOrder(event.deliveryOrder) &&
			eventFile(event.id) === path.basename(file) &&
			(event.scope === "project" || event.scope === "global") &&
			Array.isArray(event.tags) &&
			event.tags.every(tag => typeof tag === "string") &&
			Number.isFinite(Date.parse(event.timestamp)) &&
			typeof event.content === "string" &&
			typeof event.context === "string" &&
			typeof event.sessionId === "string";
		return valid ? { file, event, published } : undefined;
	} catch {
		return undefined;
	}
}

async function syncDirectory(dir: string): Promise<void> {
	// Windows cannot open a directory for fsync; file contents are still synced before rename.
	if (process.platform === "win32") return;
	const handle = await fs.open(dir, "r");
	try {
		await handle.sync();
	} finally {
		await handle.close();
	}
}

