/**
 * Ambient context the reviver needs at revive time. The top-level session is
 * kept LIVE (cwd / artifact manager read on demand) so a later `/new` or cwd
 * move is followed rather than snapshotted; auth/models/settings are
 * process-stable and captured by reference.
 */
export interface PersistedSubagentReviveContext {
	session: AgentSession;
	authStorage: AuthStorage;
	modelRegistry: ModelRegistry;
	settings: Settings;
	/** LSP policy of the top-level session; revived subagents inherit it rather than defaulting on. */
	enableLsp: boolean;
	/**
	 * Shared event bus feeding RPC/collab subagent subscriptions. Passed through
	 * to the wake-turn monitor so an IRC send to a cold-revived subagent emits
	 * the same lifecycle/progress frames a live run does.
	 */
	eventBus?: EventBus;
	/** Root-scoped observability bus the revived run's frames also publish to. */
	subagentEventBus?: EventBus;
}

/**
 * Everything one cold revive of a persisted subagent needs, built on main per revive and
 * cloneable (live objects cross as their bridged proxies), so the session can be created
 * on main or inside a pooled worker alike.
 */
export interface PersistedReviveSpec {
	readonly id: string;
	readonly displayName: string;
	readonly parentId: string | undefined;
	readonly sessionFile: string;
	/** Depth derived from the persisted parent chain (drives capability gating). */
	readonly taskDepth: number;
	/** The consulted source of a persisted seance session. */
	readonly restoredSeance: RestoredSeanceSession | undefined;
	/** The live top-level session revived agents join (cwd, extension roots, parent grants). */
	readonly root: AgentSessionHandle;
	/** Registry id of {@link root}. */
	readonly rootAgentId: string;
	readonly costGate: CostGateApi;
	readonly asyncJobManager: AsyncJobManagerApi | undefined;
	/** The root's artifact manager at revive time; a revived non-seance agent adopts it. */
	readonly artifactManager: ArtifactManagerApi | undefined;
	readonly preparedExtensions: readonly PreparedExtension[] | undefined;
	readonly authStorage: AuthStorage;
	readonly modelRegistry: ModelRegistry;
	readonly settings: Settings;
	readonly enableLsp: boolean;
	readonly eventBus: EventBus | undefined;
	readonly subagentEventBus: EventBus | undefined;
}

/**
 * Durable agent definition name (`scout`, `reviewer`, …) of a persisted subagent.
 * Cold-revived refs register with `displayName: id` (`registry/persisted-agents.ts`),
 * so a generated task id would silently drop agent-scoped rules and budgets.
 * `init.agent` carries the real name; only files predating that field fall back to
 * `displayName`. A parked transcript may also predate the `main`/`sub` definition-name
 * reservation (`discovery/helpers.ts`): a persisted `init.agent` of either sentinel
 * value from such a legacy custom agent must not masquerade as that sentinel, so it
 * falls back to `displayName` too, keeping it scoped as an ordinary subagent under its
 * generated id instead of `main` or the shared `sub` bucket.
 */
export function persistedAgentName(displayName: string, init: PersistedSessionInit): string {
	const normalized = init.agent?.trim().toLowerCase();
	return init.agent && normalized !== MAIN_AGENT_RULE_NAME && normalized !== SUB_AGENT_RULE_NAME
		? init.agent
		: displayName;
}

/**
 * The agent definition a cold-revived subagent's monitored turns report (IRC wakes,
 * `omp --restore`): persisted files predate an agent-source field, so frames carry
 * the runtime-neutral `user` source; the name is the registry ref's.
 */
export function persistedAgentDefinition(displayName: string, init: PersistedSessionInit): AgentDefinition {
	return {
		name: displayName,
		description: "",
		systemPrompt: init.systemPrompt.join("\n\n"),
		source: "user",
	};
}

/**
 * Build the factory the {@link AgentLifecycleManager} uses to cold-revive a
 * `parked` subagent ref restored from disk (Agent Hub scan, collab mirror, or a
 * resumed process). Such a ref carries a sessionFile but no in-memory adoption —
 * the executor's live reviver closure died with the process/turn that spawned
 * it — so `ensureLive` (IRC sends, hub focus) would otherwise refuse it.
 *
 * This rebuilds the subagent the same way `--resume` rebuilds a session: reopen
 * the JSONL and replay it through {@link createAgentSession}. The catch is that
 * resume restores only conversation/model from the file — the runtime contract
 * (tools / system prompt / output schema / kind) is built from options, so a
 * bare reopen would resurrect a wrong (top-level) session. We source that
 * contract from the persisted `session_init` entry instead, and mirror the
 * executor's subagent wiring (MCP proxy tools, depth-derived gating,
 * yield-required, active-tool clamp, registry status sync).
 */
export function createPersistedSubagentReviverFactory(
	ctx: PersistedSubagentReviveContext,
): PersistedSubagentReviverFactory {
	const registry = AgentRegistry.global();
	return async ref => {
		const sessionFile = ref.sessionFile;
		if (!sessionFile) return undefined;
		const peek = await SessionManager.peekSessionInit(sessionFile);
		// No persisted contract (pre-session_init file) or the recorded workspace
		// is gone (isolated/merged worktree, moved dir): leave it transcript-only
		// (history://) rather than resurrect a wrong or broken session.
		if (!peek?.init) return undefined;
		let restoredSeance: RestoredSeanceSession | undefined;
		if (peek.seanceSource !== undefined) {
			try {
				restoredSeance = await restoreSeanceSession({
					init: peek.init,
					cwd: peek.cwd,
					modelRegistry: ctx.modelRegistry,
				});
			} catch (error) {
				logger.warn("Unable to restore persisted seance session", {
					sessionFile,
					error: error instanceof Error ? error.message : String(error),
				});
				return undefined;
			}
			if (!restoredSeance) return undefined;
		}
		// Isolated runs are never resumable: their worktree is merged + cleaned,
		// and the parent was told messaging is impossible. A retained workspace
		// (capture/persist failure) still exists on disk and would pass the cwd
		// probe below, so gate on the stamped contract instead — otherwise a
		// restart + peer message revives the agent outside isolation, in the
		// parent cwd, contradicting the delivery notice.
		if (peek.init.isolated) return undefined;
		try {
			await fs.stat(restoredSeance?.cwd ?? peek.cwd);
		} catch {
			return undefined;
		}
		// taskDepth drives real capability gating (task-spawn allowance, memory
		// startup, …); derive it from the persisted parent chain rather than
		// assuming a fixed level.
		let taskDepth = 1;
		let parentId = ref.parentId;
		const seen = new Set<string>();
		while (parentId && parentId !== MAIN_AGENT_ID && !seen.has(parentId)) {
			seen.add(parentId);
			taskDepth++;
			parentId = registry.get(parentId)?.parentId;
		}
		return async (expectedRef, options) => {
			// Live root state is read per revive, so a later `/new` or cwd move is followed.
			const spec: PersistedReviveSpec = {
				id: ref.id,
				displayName: ref.displayName,
				parentId: ref.parentId,
				sessionFile,
				taskDepth,
				restoredSeance,
				root: ctx.session,
				rootAgentId: ctx.session.getAgentId?.() ?? MAIN_AGENT_ID,
				costGate: ctx.session.costGate,
				asyncJobManager: ctx.session.asyncJobManager,
				artifactManager: ctx.session.sessionManager.getArtifactManager() ?? undefined,
				preparedExtensions: ctx.session.preparedExtensions,
				authStorage: ctx.authStorage,
				modelRegistry: ctx.modelRegistry,
				settings: ctx.settings,
				enableLsp: ctx.enableLsp,
				eventBus: ctx.eventBus,
				subagentEventBus: ctx.subagentEventBus,
			};
			// Worker mode: a revival is placed like a fresh spawn (main thread or a worker).
			const pool = options?.placement === "local" ? undefined : subagentWorkerPool(ctx.settings);
			return pool
				? revivePersistedPlaced(pool, spec, expectedRef, revivePersistedSubagent)
				: revivePersistedSubagent(spec, expectedRef);
		};
	};
}

/**
 * Rebuild the persisted subagent of `spec` on the calling thread (main, or the pooled
 * worker that will home it) and claim `expectedRef` for it.
 */
export async function revivePersistedSubagent(spec: PersistedReviveSpec, expectedRef: AgentRef): Promise<AgentSession> {
	const ref = { id: spec.id, displayName: spec.displayName, parentId: spec.parentId };
	const { sessionFile, taskDepth, restoredSeance } = spec;
	const seanceOptions = restoredSeance ? seanceIsolationOptions(restoredSeance.cwd) : {};
	const registry = AgentRegistry.global();
	// Re-open fresh on every revive: park closes the writer, so this takes
	// the single-writer lock cleanly and restores the full message history.
	const reopened = await SessionManager.open(sessionFile, undefined, undefined, {
		suppressBreadcrumb: true,
		throwIfMissing: true,
	});
	const entries = reopened.getEntries();
	const init = extractSessionInit(entries);
	if (!init) {
		await reopened.close();
		throw new Error(
			`Cannot revive subagent "${ref.id}": session file "${sessionFile}" has no persisted session contract. The agent was not revived.`,
		);
	}
	if (!hasConversationalHistory(entries)) {
		await reopened.close();
		throw new Error(
			`Cannot revive subagent "${ref.id}": session file "${sessionFile}" has no message history (truncated to header/session_init). The agent was not revived.`,
		);
	}
	const resolveParentSession = () =>
		ref.parentId === spec.rootAgentId ? spec.root : registry.get(ref.parentId ?? "")?.session;
	const parentSession = resolveParentSession();
	let perCallModel: Model | undefined;
	let assertApprovedModel: ((model: Model) => void) | undefined;
	if (init.perCallModel) {
		try {
			if (!init.perCallModelIdentity || init.perCallThinkingLevel === undefined) {
				throw new PerCallModelError(
					`Cannot revive subagent "${ref.id}": its per-call model identity and thinking level were not recorded separately, so they cannot be restored exactly. The agent was not revived.`,
				);
			}
			await spec.modelRegistry.awaitBackgroundRefresh();
			perCallModel = resolveExactModelIdentity(init.perCallModelIdentity, spec.modelRegistry);
			if (!perCallModel) {
				throw new PerCallModelError(
					`Cannot revive subagent "${ref.id}": its per-call model ${init.perCallModelIdentity} is no longer available. A per-call worker revives only on its exact saved model.`,
				);
			}
			// File definitions follow the live parent's discovery scope; a missing parent
			// can use current root file discovery, never unrelated root-local pseudonyms.
			const discoverySession = parentSession ?? spec.root;
			const configuredAgent = init.agent
				? getAgent(
						[
							...(
								await discoverAgents(
									discoverySession.sessionManager.getCwd(),
									undefined,
									discoverySession.effectiveExtensionRoots,
								)
							).agents,
							...(parentSession?.getSessionAgents() ?? []),
						],
						init.agent,
					)
				: undefined;
			const matchPreferences = structuredClone(getModelMatchPreferences(spec.settings.grantAuthority()));
			// One grants object per live parent model keeps approval decisions cached across requests.
			const grantsByParentModel = new Map<string | undefined, PerCallModelGrants>();
			const grantsFor = (parentModelPattern: string | undefined): PerCallModelGrants => {
				let grants = grantsByParentModel.get(parentModelPattern);
				if (!grants) {
					grants = {
						settings: spec.settings,
						agentName: init.agent ?? ref.displayName,
						agentModel: configuredAgent?.model,
						agentSource: configuredAgent?.source,
						agentRemoved: configuredAgent === undefined,
						parentModelPattern,
						matchPreferences,
					};
					grantsByParentModel.set(parentModelPattern, grants);
				}
				return grants;
			};
			assertApprovedModel = model => {
				// Parent models grant only while the real parent is live, including
				// after this revival; transcript metadata never substitutes for it.
				const liveParentSession = resolveParentSession();
				const parentModel = liveParentSession?.model;
				try {
					assertPerCallModelApproved(
						model,
						grantsFor(parentModel ? parentModelGrantPattern(parentModel) : undefined),
						spec.modelRegistry,
					);
				} catch (error) {
					// Only an approval denial depends on the parent; an unavailable model is refused either way.
					if (
						liveParentSession ||
						!(error instanceof PerCallModelError) ||
						error instanceof PerCallModelUnavailableError
					)
						throw error;
					throw new PerCallModelError(
						`${error.message} Parent agent "${ref.parentId ?? "unknown"}" of revived subagent "${ref.id}" is not live; its model grants nothing and its parent-local agent grants are unavailable until the parent is revived.`,
					);
				}
			};
			assertApprovedModel(perCallModel);
			assertModelSupportsEffortCeiling(perCallModel, cfgTaskMaxEffort.get(spec.settings));
		} catch (error) {
			await reopened.close();
			throw error;
		}
	}
	// Rebuild the same advisor opt-in the original spawn resolved: `"on"` =
	// advisor-role model, anything else = the pattern stamped onto this
	// session's `modelRoles.advisor`. Spawn persists it already expanded
	// against the spawning owner's roles (a parent subagent may override
	// them); expanding again is a no-op for those and only resolves aliases
	// in files written before that. Absent = unadvised (the
	// createSubagentSettings default).
	const subagentSettings = createSubagentSettings(spec.settings, {
		...(init.readSummarize === false ? { "read.summarize.enabled": false } : undefined),
		...(init.advisor
			? {
					"advisor.enabled": true,
					...(init.advisor !== "on"
						? {
								modelRoles: {
									...spec.settings.getModelRoles(),
									advisor: resolveAgentAdvisorRolePattern(init.advisor, spec.settings),
								},
							}
						: undefined),
				}
			: undefined),
		...compactionThresholdSettings(init.compactionThreshold),
	});
	// Restore the `subagent:<id>` fallback chain the spawn installed; the
	// transcript alone cannot rebuild it (multi-model agent patterns and
	// inherited role chains are resolved only at spawn).
	if (init.retryFallback) {
		installRetryFallbackRole(subagentSettings, subagentRetryFallbackRole(ref.id), init.retryFallback);
	}
	// Account pools are owner policy, like the extension roots below: take the
	// live exact-name `task.agentAccountPools` entry, never a transcript copy.
	const agentAccountPools = validateAgentAccountPools(cfgTaskAgentAccountPools.get(spec.settings));
	const oauthAccountPools =
		init.agent && Object.hasOwn(agentAccountPools, init.agent) ? agentAccountPools[init.agent] : undefined;
	const spawnModelPattern = restoredSeance
		? restoredSeance.modelPattern
		: init.modelRole && init.modelRole !== "default"
			? [formatModelRoleAlias(init.modelRole), ...(init.resolvedModel ? [init.resolvedModel] : [])]
			: init.resolvedModel;
	// A session-local switch since spawn (a prewalk handoff) is the model the agent
	// was working on; the spawn selection only backs it up when it is unavailable. A
	// seance fork's selections belong to its source run, never to the consult.
	const sessionLocalModel = restoredSeance ? undefined : reopened.getSessionLocalModelChange()?.model;
	// A per-call worker revives only onto its exact saved model: no role alias, no auth fallback.
	const persistedModelPattern = init.perCallModel
		? undefined
		: sessionLocalModel
			? [sessionLocalModel, ...(spawnModelPattern === undefined ? [] : [spawnModelPattern].flat())]
			: spawnModelPattern;
	// Older session files persisted the synthetic xd:// write transport in the
	// enabled set. A read-only agent definition could never grant full write,
	// so remove that transport name before replaying tools as explicit grants.
	const revivedToolNames = restoredSeance
		? restoredSeance.toolNames
		: init.readOnly === true && init.tools.includes("write")
			? init.tools.filter(name => name !== "write")
			: init.tools;
	const artifactManager = spec.artifactManager;
	if (artifactManager && !restoredSeance) reopened.adoptArtifactManager(artifactManager);
	// A restricted persisted contract must not consult process-global MCP
	// state: same-name MCP tools are untrusted capability sources.
	const restrictToolNames = restoredSeance !== undefined || init.restrictToolNames === true;
	// The spawn's result contract: a session persisted without `yield` returned its final message.
	const structured = revivedToolNames.includes("yield");
	const mcpManager = restrictToolNames ? undefined : MCPManager.instance();
	// Subscribe before minting proxies so a manager change during startup is replayed on bind.
	// The revived session reopens its own view, keeping the tools its earlier requests rendered.
	const mcpFollower = mcpManager ? followMCPTools(mcpManager, { scope: reopened.getSessionId() }) : undefined;
	const mcpProxyTools = mcpFollower?.proxyTools() ?? [];

	let session: AgentSession;
	try {
		({ session } = await createAgentSession({
			cwd: restoredSeance?.cwd ?? spec.root.sessionManager.getCwd(),
			costGate: spec.costGate,
			authStorage: spec.authStorage,
			// Revived agents join the root session tree, so their observability
			// frames ride the same bus the RPC/collab surfaces subscribed to.
			subagentEventBus: spec.subagentEventBus,
			modelRegistry: spec.modelRegistry,
			...(perCallModel ? { model: perCallModel, thinkingLevel: init.perCallThinkingLevel ?? undefined } : {}),
			...(persistedModelPattern ? { modelPattern: persistedModelPattern } : {}),
			modelPatternAuthFallback: restoredSeance || init.perCallModel ? undefined : init.resolvedModel,
			settings: subagentSettings,
			sessionManager: reopened,
			agentId: ref.id,
			agentDisplayName: ref.displayName,
			// `agents` rule scoping keys on the durable definition name (see `persistedAgentName`).
			agentName: persistedAgentName(ref.displayName, init),
			parentTaskPrefix: ref.id,
			asyncJobManager: spec.asyncJobManager,
			parentAgentId: ref.parentId,
			oauthAccountPools,
			// A per-call model is held to the operator's current grants, not the transcript's,
			// never switches models, and keeps the live task.maxEffort ceiling the spawn ran under.
			...(assertApprovedModel
				? {
						thinkingLevelCeiling: cfgTaskMaxEffort.get(spec.settings),
						disableModelFallback: true,
						disableServerSideFallback: true,
						assertDispatchModel: (model: Model) => {
							assertApprovedModel(model);
							assertModelSupportsEffortCeiling(model, cfgTaskMaxEffort.get(spec.settings));
						},
					}
				: {}),
			expectedAgentRef: expectedRef,
			taskDepth,
			toolNames: revivedToolNames,
			// `revivedToolNames` is the enabled set, devices included: keep those devices,
			// or they come back as top-level tools and change the replayed tool list.
			mountedToolNames: restoredSeance ? undefined : init.mountedTools,
			outputSchema: init.outputSchema,
			outputSchemaMode: init.outputSchemaMode,
			restrictToolNames: restrictToolNames || undefined,
			requireYieldTool: structured,
			systemPrompt: () => [...init.systemPrompt],
			// Inherit current owner policy, never extension authority from a transcript.
			extensionRoots: () => spec.root.effectiveExtensionRoots,
			preloadedPreparedExtensions: spec.preparedExtensions,
			// Old files predate persisted spawns: deny re-spawning rather than let
			// createAgentSession default to wildcard ("*").
			spawns: init.spawns ?? "",
			hasUI: false,
			enableLsp: restrictToolNames ? false : spec.enableLsp,
			...(restrictToolNames
				? {
						enableIrc: false,
						enableMCP: false,
						preloadedExtensionPaths: [],
						preloadedCustomToolPaths: [],
					}
				: {
						enableMCP: !mcpManager,
						mcpManager,
						mcpTools: mcpProxyTools.length > 0 ? mcpProxyTools : undefined,
						mcpToolScope: mcpFollower?.scope,
					}),
			...seanceOptions,
		}));
	} catch (error) {
		mcpFollower?.dispose();
		throw error;
	}
	// A per-call worker runs only on its exact saved model, never a similarly named survivor.
	if (init.perCallModel) {
		try {
			const saved = init.perCallModelIdentity!;
			const identity = session.model ? formatModelStringWithRouting(session.model) : undefined;
			if (identity !== saved) {
				throw new PerCallModelError(
					`Cannot revive subagent "${ref.id}": its per-call model ${saved} is no longer available${identity ? ` (resolution found ${identity})` : ""}. A per-call worker revives only on its exact saved model.`,
				);
			}
			// An explicit unset selector must not inherit a new default while reviving.
			if (init.perCallThinkingLevel === null) session.setThinkingLevel(undefined);
		} catch (error) {
			mcpFollower?.dispose();
			await session.dispose();
			throw error;
		}
	}
	mcpFollower?.bind(session);
	// Clamp the active set to the persisted list: createAgentSession's
	// `alwaysInclude` can re-add non-defaultInactive extension/custom tools
	// the original run didn't carry. Unknown/missing names are ignored.
	await session.setActiveToolsByName(
		restoredSeance ? revivedToolNames : [...revivedToolNames, ...session.getMountedXdevToolNames()],
	);
	// The yield tool's schema carries the last batch's items; the replayed prefix must match it.
	if (init.workPoolYieldItems) await session.setWorkPoolYieldItems(init.workPoolYieldItems);
	// Wire the extension runtime exactly as the live executor does. Without
	// this the runner stays pre-init, every action method throws
	// `ExtensionRuntimeNotInitializedError`, and a `tool_call` handler that
	// touches a runtime action trips the fail-closed gate in `emitToolCall`,
	// blocking every tool — including the hidden `yield` — in the revived
	// agent. `session_start` also re-runs so extensions restore per-session
	// state (issue #8824).
	await initializeExtensions(session, {
		reportSendError: (action, err) => logger.error("Extension send failed", { action, error: err.message }),
		reportRuntimeError: err => logger.error("Extension error", { path: err.extensionPath, error: err.error }),
	});
	await replayRevivedAgentStart(session);
	// Cold revives must drive registry status themselves — createAgentSession
	// doesn't wire this generically (the live path does it in the executor).
	// The internal run-state signal precedes deferrable public `agent_end`,
	// keeping idle-TTL ownership synchronized even while prompts unwind.
	registry.syncSessionStatus(ref.id, session);
	attachIrcWakeTurnMonitor(session, {
		id: ref.id,
		agent: persistedAgentDefinition(ref.displayName, init),
		completionProbe: isCompletionProbeEnabled(spec.settings, taskDepth - 1),
		...softRequestBudgetFor(persistedAgentName(ref.displayName, init), spec.settings),
		eventBus: spec.eventBus,
		subagentEventBus: spec.subagentEventBus,
		sessionFile,
		structured,
		outputSchema: init.outputSchema,
		outputSchemaMode: init.outputSchemaMode,
		// Anchor artifacts to the revived ref's own dir (its parent's children
		// dir), not the live root session's, matching the spawn callers (#11563).
		artifactsDir: path.dirname(sessionFile),
	});
	return session;
}

import * as fs from "node:fs/promises";
import * as net from "node:net";
import * as path from "node:path";
import { Process, ProcessStatus } from "@oh-my-pi/pi-natives";
import { getBrowserProfilesDir, isRecord, untilAborted } from "@oh-my-pi/pi-utils";
import type { Socket } from "bun";
import type { Browser, Page, Target } from "puppeteer-core";
import { throwIfAborted } from "../tool-errors";
import { ToolError } from "@oh-my-pi/pi-tui/tools/tool-errors";
import { isPuppeteerTimeout } from "./launch";

const ATTACH_TARGET_SKIP_PATTERN =
	/request[\s_-]?handler|devtools|background[\s_-]?(?:page|host)|service[\s_-]?worker/i;

/**
 * Allocate an unused TCP port on 127.0.0.1 by binding to port 0 and reading
 * back the kernel-assigned port. There's a small race between close and the
 * subsequent bind in the launched app, but Chromium's listener will retry.
 */
export async function findFreeCdpPort(): Promise<number> {
	const { promise, resolve, reject } = Promise.withResolvers<number>();
	const server = net.createServer();
	server.unref();
	server.once("error", reject);
	server.listen(0, "127.0.0.1", () => {
		const addr = server.address();
		if (addr && typeof addr === "object" && typeof addr.port === "number") {
			const port = addr.port;
			server.close(closeErr => (closeErr ? reject(closeErr) : resolve(port)));
		} else {
			server.close();
			reject(new Error("Failed to allocate ephemeral CDP port"));
		}
	});
	return promise;
}

/** Status line plus body of a {@link probeCdpResponse} answer. */
export interface CdpProbeResponse {
	status: number;
	body: string;
}

interface RawGetOptions {
	timeoutMs: number;
	signal?: AbortSignal;
	/** Resolve after the body arrives (Content-Length or peer close) instead of on the status line. */
	readBody: boolean;
}

/**
 * Loopback HTTP/1.1 GET that never routes through a proxy. Resolves null when
 * the endpoint is unreachable, aborted, malformed, or slow past `timeoutMs`.
 *
 * Chrome's DevTools endpoint listens on loopback and speaks plain HTTP/1.1.
 * Both `fetch` and Bun's `node:http` honor `HTTP_PROXY`/`HTTPS_PROXY` and
 * forward even `127.0.0.1` requests to the proxy unless `NO_PROXY` covers them,
 * so a local proxy that 502s internal addresses makes a healthy daemon look
 * dead and the CDP readiness checks tear it down (issue #8567). Talking to the
 * socket over raw TCP sidesteps proxy env entirely.
 */
async function rawHttpGet(url: string, opts: RawGetOptions): Promise<CdpProbeResponse | null> {
	let target: URL;
	try {
		target = new URL(url);
	} catch {
		return null;
	}
	if (opts.signal?.aborted) return null;
	const port = target.port ? Number(target.port) : 80;
	const requestPath = `${target.pathname}${target.search}` || "/";
	const { promise, resolve } = Promise.withResolvers<CdpProbeResponse | null>();
	let socket: Socket<undefined> | undefined;
	let settled = false;
	const finish = (response: CdpProbeResponse | null) => {
		if (settled) return;
		settled = true;
		clearTimeout(timer);
		opts.signal?.removeEventListener("abort", onAbort);
		try {
			socket?.end();
		} catch {
			// socket already torn down
		}
		resolve(response);
	};
	const onAbort = () => finish(null);
	const timer = setTimeout(() => finish(null), opts.timeoutMs);
	opts.signal?.addEventListener("abort", onAbort, { once: true });
	let buffered = "";
	let status: number | null = null;
	// Offset of the header/body separator once the header block is complete.
	let headerEnd = -1;
	let contentLength: number | null = null;
	const bodySoFar = () => buffered.slice(headerEnd + 4);
	try {
		socket = await Bun.connect({
			hostname: target.hostname,
			port,
			socket: {
				open(s) {
					s.write(`GET ${requestPath} HTTP/1.1\r\nHost: ${target.hostname}:${port}\r\nConnection: close\r\n\r\n`);
				},
				data(_s, chunk) {
					buffered += chunk.toString("latin1");
					if (status === null) {
						const match = /^HTTP\/\d(?:\.\d)? (\d{3})/.exec(buffered);
						if (!match) return;
						status = Number(match[1]);
						if (!opts.readBody) {
							finish({ status, body: "" });
							return;
						}
					}
					if (headerEnd === -1) {
						headerEnd = buffered.indexOf("\r\n\r\n");
						if (headerEnd === -1) return;
						const lengthHeader = /\r\ncontent-length:\s*(\d+)/i.exec(buffered.slice(0, headerEnd));
						contentLength = lengthHeader ? Number(lengthHeader[1]) : null;
					}
					if (contentLength !== null && bodySoFar().length >= contentLength) {
						finish({ status, body: bodySoFar().slice(0, contentLength) });
					}
				},
				error() {
					finish(null);
				},
				close() {
					// Without Content-Length the peer's close delimits the body.
					finish(status !== null && headerEnd !== -1 ? { status, body: bodySoFar() } : null);
				},
			},
		});
	} catch {
		finish(null);
	}
	return promise;
}

/**
 * Proxy-proof loopback probe resolving to the response status code, or null
 * when the endpoint is unreachable, aborted, malformed, or slow past `timeoutMs`.
 */
export async function probeCdpStatus(
	url: string,
	opts: { timeoutMs: number; signal?: AbortSignal },
): Promise<number | null> {
	const response = await rawHttpGet(url, { ...opts, readBody: false });
	return response?.status ?? null;
}

/**
 * Proxy-proof loopback probe that also reads the response body (for endpoints
 * whose non-2xx answer carries state, like the relay's 503). Null on the same
 * conditions as {@link probeCdpStatus}.
 */
export function probeCdpResponse(
	url: string,
	opts: { timeoutMs: number; signal?: AbortSignal },
): Promise<CdpProbeResponse | null> {
	return rawHttpGet(url, { ...opts, readBody: true });
}

/** Poll `${cdpUrl}/json/version` until it responds with 200, with abort + timeout support. */
export async function waitForCdp(cdpUrl: string, timeoutMs: number, signal?: AbortSignal): Promise<void> {
	const deadline = Date.now() + timeoutMs;
	const probeUrl = `${cdpUrl.replace(/\/+$/, "")}/json/version`;
	let lastStatus: number | null = null;
	while (Date.now() < deadline) {
		throwIfAborted(signal);
		const status = await probeCdpStatus(probeUrl, { timeoutMs: 2000, signal });
		if (status !== null && status >= 200 && status < 300) return;
		lastStatus = status;
		await Bun.sleep(150);
	}
	throwIfAborted(signal);
	throw new ToolError(
		`Timed out waiting for CDP endpoint ${cdpUrl}${lastStatus !== null ? `: HTTP ${lastStatus}` : ""}`,
	);
}

/**
 * Pull a `--remote-debugging-port=<n>` value out of an argv array (Chromium
 * accepts both `--flag=value` and `--flag value`). Returns null if absent or
 * malformed.
 */
function findCdpPortInArgs(args: string[]): number | null {
	for (const arg of args) {
		const m = /^--remote-debugging-port=(\d+)$/.exec(arg);
		if (m) {
			const port = Number.parseInt(m[1]!, 10);
			if (Number.isFinite(port) && port > 0) return port;
		}
	}
	for (let i = 0; i < args.length - 1; i++) {
		if (args[i] === "--remote-debugging-port") {
			const port = Number.parseInt(args[i + 1]!, 10);
			if (Number.isFinite(port) && port > 0) return port;
		}
	}
	return null;
}

export function findUserDataDirInArgs(args: string[] | undefined): string | null {
	if (!args) return null;
	let result: string | null = null;
	const inlinePrefix = "--user-data-dir=";
	for (let index = 0; index < args.length; index++) {
		const arg = args[index]!;
		if (arg.startsWith(inlinePrefix)) {
			result = arg.length > inlinePrefix.length ? arg.slice(inlinePrefix.length) : null;
			continue;
		}
		if (arg !== "--user-data-dir") continue;
		const value = args[index + 1];
		result = value !== undefined && value.length > 0 && !value.startsWith("--") ? value : null;
		if (result !== null) index++;
	}
	return result;
}

/**
 * Executable basenames of Chromium-family browsers (release channels and
 * vendor suffixes included), as opposed to Electron apps that also speak CDP.
 * Matched against the basename without `.exe`.
 */
const CHROMIUM_BROWSER_BASENAME =
	/^(?:google[ -]chrome|chrome|chromium|microsoft[ -]edge|msedge|brave|vivaldi|opera|thorium|ungoogled[ -]chromium)(?:[ -](?:beta|dev|canary|unstable|stable|nightly|snapshot|browser|gx|for[ -]testing))*$/i;
const CHROMIUM_FLATPAK_IDS: Record<string, true> = {
	"com.google.Chrome": true,
	"org.chromium.Chromium": true,
	"io.github.ungoogled_software.ungoogled_chromium": true,
};
/** Whether an app executable is a Chromium browser rather than an Electron application. */
export function isChromiumBrowserExecutable(exe: string): boolean {
	const base = path.basename(exe).replace(/\.exe$/i, "");
	return CHROMIUM_BROWSER_BASENAME.test(base) || Object.hasOwn(CHROMIUM_FLATPAK_IDS, base);
}

/**
 * Launch argv for a spawned executable. Chrome 136+ silently ignores
 * `--remote-debugging-port` when the default user-data-dir is in use: the
 * browser opens as usual, nothing listens, and attach waits out its timeout.
 * Chromium-family browsers therefore get a stable omp-owned profile under
 * `~/.omp/browser-profiles/<exe slug>` unless the caller already picked one.
 * That profile is also what lets a second instance start beside the user's
 * running default-profile browser instead of handing off to it. Electron apps
 * are left untouched: `--user-data-dir` would relocate their app data.
 *
 * An omp-owned profile also bypasses the OS keystore (`--use-mock-keychain`,
 * `--password-store=basic`, the same pair puppeteer's launcher sets): Chromium
 * otherwise derives its cookie-encryption key from the login keychain and
 * macOS blocks on a "wants to use your confidential information" dialog for
 * every fresh binary. A caller-supplied profile keeps the real keystore; its
 * existing cookies are encrypted with that key and a mock one would corrupt them.
 */
export function resolveSpawnArgs(exe: string, appArgs: string[] | undefined, cwd = process.cwd()): string[] {
	const args = appArgs ?? [];
	if (!isChromiumBrowserExecutable(exe)) return args;
	const requestedProfile = findUserDataDirInArgs(args);
	if (requestedProfile !== null) {
		// Chromium accepts switch values as --name=value, not a separate argv
		// item. Canonicalize both spellings so reuse and process launch agree.
		const launchArgs: string[] = [];
		for (let index = 0; index < args.length; index++) {
			const arg = args[index]!;
			if (arg === "--user-data-dir") {
				if (args[index + 1] && !args[index + 1]!.startsWith("--")) index++;
			} else if (!arg.startsWith("--user-data-dir=")) {
				launchArgs.push(arg);
			}
		}
		launchArgs.push(`--user-data-dir=${path.resolve(cwd, requestedProfile)}`);
		return launchArgs;
	}
	const slug = path
		.basename(exe)
		.replace(/\.exe$/i, "")
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-");
	const hash = Bun.hash.wyhash(exe).toString(16).padStart(16, "0");
	const launchArgs = [...args];
	// A fresh profile otherwise opens the welcome tour and default-browser
	// prompt as extra page targets, which attach may adopt instead of ours.
	for (const flag of ["--no-first-run", "--no-default-browser-check", "--use-mock-keychain"]) {
		if (!args.includes(flag)) launchArgs.push(flag);
	}
	if (!args.some(arg => arg.startsWith("--password-store"))) launchArgs.push("--password-store=basic");
	launchArgs.push(`--user-data-dir=${path.join(getBrowserProfilesDir(), `${slug}-${hash}`)}`);
	return launchArgs;
}

function normalizeUserDataDir(userDataDir: string): string {
	const normalized = path.resolve(userDataDir);
	return process.platform === "win32" ? normalized.toLowerCase() : normalized;
}

/** One-shot probe: returns true when `/json/version` answers 200 within the timeout. */
async function probeCdpAt(port: number, signal?: AbortSignal): Promise<boolean> {
	const status = await probeCdpStatus(`http://127.0.0.1:${port}/json/version`, { timeoutMs: 1500, signal });
	return status !== null && status >= 200 && status < 300;
}

/**
 * Resolve a distro wrapper script to its exec target (e.g.
 * /opt/google/chrome/google-chrome is bash ending in
 * `exec -a "$0" "$HERE/chrome" "$@"` with $HERE = dirname of the wrapper).
 * Scans line-by-line for the final `exec ... $HERE/...` command so helper
 * invocations are never mistaken for the application. Returns null for
 * binaries and wrappers without an exec command. Size-guarded so real
 * binaries are never read into memory.
 */
async function resolveWrapperTarget(wrapperPath: string): Promise<string | null> {
	if (process.platform !== "linux") return null;
	const stat = await fs.stat(wrapperPath).catch(() => null);
	if (!stat || !stat.isFile() || stat.size > 65_536) return null;
	const content = await Bun.file(wrapperPath)
		.text()
		.catch(() => null);
	if (!content || content.charCodeAt(0) === 0x7f) return null;
	let target: string | null = null;
	const execRegex = /^\s*exec\s+(?:-a\s+(?:"[^"]*"|'[^']*'|\S+)\s+)?["']?\$(?:HERE|\{HERE\})\/([^\s"'`;}]+)/;
	for (const line of content.split("\n")) {
		const match = execRegex.exec(line);
		if (match?.[1]) target = match[1];
	}
	let joined: string;
	if (target) {
		joined = path.join(path.dirname(wrapperPath), target);
	} else {
		// Debian's launcher uses APPNAME/LIBDIR rather than HERE. Read only
		// single, literal assignments; never evaluate the wrapper as shell code.
		const names = content.match(/^\s*(?:export\s+)?APPNAME=.*$/gm) ?? [];
		const directories = content.match(/^\s*(?:export\s+)?LIBDIR=.*$/gm) ?? [];
		if (names.length !== 1 || directories.length !== 1) return null;
		// Reject additional writes on compound/export/readonly lines too. This
		// remains a static hint: sourced distro configuration is not evaluated.
		if ((content.match(/\b(?:APPNAME|LIBDIR)=/g) ?? []).length !== 2) return null;
		const name = /^\s*APPNAME=(["']?)([A-Za-z0-9_-]+)\1\s*$/.exec(names[0]!)?.[2];
		const directory = /^\s*LIBDIR=("?)(\/[A-Za-z0-9_./${}-]+)\1\s*$/.exec(directories[0]!)?.[2];
		if (!name || !directory) return null;
		const expanded = directory.replace(/\$(?:APPNAME(?![A-Za-z0-9_])|\{APPNAME\})/g, name);
		if (!/^\/[A-Za-z0-9_./-]+$/.test(expanded)) return null;
		if (!/^\s*exec\s+("?)\$(?:LIBDIR|\{LIBDIR\})\/\$(?:APPNAME|\{APPNAME\})\1(?:\s|$)/m.test(content)) return null;
		joined = path.join(expanded, name);
	}
	return fs.realpath(joined).catch(() => joined);
}

/**
 * Normalize candidate argv for kernels that serve /proc/<pid>/cmdline
 * space-joined instead of NUL-separated. A glued first word (the whole
 * command line in argv[0]) would otherwise hide --user-data-dir and
 * --remote-debugging-port from the matchers below.
 */
function normalizeCandidateArgs(args: string[]): string[] {
	if (args.length !== 1 || !args[0]!.includes(" --")) return args;
	const word = args[0]!;
	const split = word.trim().split(/\s+/);
	if (split.length <= 1) return args;

	// Invariant: ungluing is only safe when splitting preserves exact argument
	// boundaries without corrupting switch values (e.g. splitting a profile path
	// containing spaces into multiple argv elements, which risks cross-profile reuse).
	// Every --user-data-dir flag must re-parse to the identical value.
	const flagRegex = /(?:^|\s)--user-data-dir(?:=(.*?)|(?:\s+(.*?))?)(?=\s--|$)/g;
	const rawMatches = [...word.trim().replace(/\s+/g, " ").matchAll(flagRegex)];
	if (rawMatches.length > 0) {
		let matchIndex = 0;
		for (let i = 0; i < split.length; i++) {
			const arg = split[i]!;
			if (arg.startsWith("--user-data-dir=")) {
				const expected = rawMatches[matchIndex]?.[1] ?? rawMatches[matchIndex]?.[2] ?? "";
				const actual = findUserDataDirInArgs(split.slice(i, i + 1));
				if (actual !== expected) return args;
				matchIndex++;
			} else if (arg === "--user-data-dir") {
				const expected = rawMatches[matchIndex]?.[1] ?? rawMatches[matchIndex]?.[2] ?? "";
				const actual = findUserDataDirInArgs(split.slice(i, i + 2));
				if (actual !== expected) return args;
				matchIndex++;
				i++;
			}
		}
		if (matchIndex !== rawMatches.length) return args;
	}

	return split;
}

/**
 * Return a reusable CDP endpoint for `exe`, or null when no instance is
 * running. Refuse to replace an occupied instance unless the caller can
 * launch an isolated profile.
 */
export async function findReusableCdp(
	exe: string,
	options: { signal?: AbortSignal; appArgs?: string[] } = {},
): Promise<{ cdpUrl: string; pid: number } | null> {
	const requestedUserDataDir = findUserDataDirInArgs(options.appArgs);
	const normalizedRequestedUserDataDir =
		requestedUserDataDir !== null && path.isAbsolute(requestedUserDataDir)
			? normalizeUserDataDir(requestedUserDataDir)
			: null;
	// Process paths use the executable real path, not its launcher symlink. A distro
	// wrapper script defeats realpath, so resolve through the wrapper exec target
	// for Chromium-family browsers on Linux.
	const executablePath = await fs.realpath(exe).catch(() => exe);
	const isChromium = isChromiumBrowserExecutable(exe);
	const wrapperTarget = process.platform === "linux" && isChromium ? await resolveWrapperTarget(executablePath) : null;
	// A static wrapper target is a lookup hint, not a replacement for the
	// launcher identity. Keep both sets and still verify profile and live CDP.
	const candidates = [
		...new Map(
			[...Process.fromPath(executablePath), ...(wrapperTarget ? Process.fromPath(wrapperTarget) : [])].map(
				candidate => [candidate.pid, candidate] as const,
			),
		).values(),
	].filter(candidate => candidate.status() === ProcessStatus.Running);
	const candidateArgs: string[][] = [];
	let hasUnreadableCandidate = false;
	for (const process of candidates) {
		let args: string[];
		try {
			args = normalizeCandidateArgs(process.args());
		} catch {
			hasUnreadableCandidate = true;
			continue;
		}
		candidateArgs.push(args);
		const candidateProfile = findUserDataDirInArgs(args);
		if (
			requestedUserDataDir !== null &&
			(normalizedRequestedUserDataDir === null ||
				candidateProfile === null ||
				!path.isAbsolute(candidateProfile) ||
				normalizeUserDataDir(candidateProfile) !== normalizedRequestedUserDataDir)
		) {
			continue;
		}
		const port = findCdpPortInArgs(args);
		if (port === null) continue;
		if (await probeCdpAt(port, options.signal)) {
			return { cdpUrl: `http://127.0.0.1:${port}`, pid: process.pid };
		}
	}
	const canLaunchIsolatedProfile =
		normalizedRequestedUserDataDir !== null &&
		!hasUnreadableCandidate &&
		candidateArgs.every(args => {
			const existingUserDataDir = findUserDataDirInArgs(args);
			return (
				existingUserDataDir === null ||
				(path.isAbsolute(existingUserDataDir) &&
					normalizeUserDataDir(existingUserDataDir) !== normalizedRequestedUserDataDir)
			);
		});
	if (!canLaunchIsolatedProfile && candidates.length > 0) {
		const name = path.basename(exe);
		throw new ToolError(
			`Cannot launch ${name} because it is already running without a reusable CDP endpoint. Close ${name}, relaunch it with --remote-debugging-port, or pass app.cdp_url for an existing endpoint.`,
		);
	}
	return null;
}

export interface PickTargetOptions {
	matcher?: string;
	preferVisible?: boolean;
	/** Relay /json endpoint (e.g. http://127.0.0.1:9224); enables metadata-first target selection. */
	relayJson?: string;
	signal?: AbortSignal;
}

const PAGE_ATTACH_TIMEOUT_MS = 10_000;
const FRAME_READY_TIMEOUT_MS = 8_000;
const FRAME_READY_POLL_MS = 120;
const RELAY_JSON_TIMEOUT_MS = 3_000;
const RELAY_VISIBILITY_TIMEOUT_MS = 1_000;
// A tab opened outside omp reaches the relay's /json, and gets its URL, a few ms after Chrome reports it created.
const RELAY_MATCH_SETTLE_MS = 2_000;
const RELAY_MATCH_POLL_MS = 100;

async function abortable<T>(signal: AbortSignal | undefined, operation: () => Promise<T>): Promise<T> {
	try {
		return await untilAborted(signal, operation);
	} catch (error) {
		throwIfAborted(signal);
		throw error;
	}
}

interface RelayJsonEntry {
	id: string;
	type: string;
	title: string;
	url: string;
	active?: string;
	discarded?: string;
}

/** Attach to one target under a deadline; unresponsive targets resolve to null. */
export async function attachPageWithTimeout(
	target: Target,
	timeoutMs = PAGE_ATTACH_TIMEOUT_MS,
	signal?: AbortSignal,
): Promise<Page | null> {
	throwIfAborted(signal);
	const timeout = Promise.withResolvers<Page | null>();
	const timer = setTimeout(() => timeout.resolve(null), timeoutMs);
	try {
		return await untilAborted(signal, () => {
			const page = Promise.resolve()
				.then(() => target.page())
				.then(value => value ?? null)
				.catch(() => null);
			return Promise.race([page, timeout.promise]);
		});
	} catch {
		throwIfAborted(signal);
		return null;
	} finally {
		clearTimeout(timer);
	}
}

/**
 * Puppeteer throws "Requesting main frame too early!" when a Page's
 * frameTree has not arrived yet — common right after adopting a relay tab
 * whose CDP session was synthesized. Poll until mainFrame serves or the
 * deadline passes.
 */
export async function waitForMainFrame(
	page: Page,
	timeoutMs = FRAME_READY_TIMEOUT_MS,
	signal?: AbortSignal,
): Promise<boolean> {
	const deadline = Date.now() + timeoutMs;
	for (;;) {
		throwIfAborted(signal);
		try {
			page.url();
			return true;
		} catch (err) {
			if (!/too early/i.test(err instanceof Error ? err.message : String(err))) return false;
		}
		if (Date.now() >= deadline) return false;
		try {
			await untilAborted(signal, () => Bun.sleep(FRAME_READY_POLL_MS));
		} catch (error) {
			throwIfAborted(signal);
			throw error;
		}
	}
}
async function fetchRelayEntries(
	relayJson: string,
	signal?: AbortSignal,
	timeoutMs = RELAY_JSON_TIMEOUT_MS,
): Promise<RelayJsonEntry[] | null> {
	try {
		const res = await probeCdpResponse(`${relayJson.replace(/\/$/, "")}/json`, {
			timeoutMs,
			signal,
		});
		if (!res || res.status < 200 || res.status >= 300) return null;
		const body: unknown = JSON.parse(Buffer.from(res.body, "latin1").toString("utf8"));
		return Array.isArray(body) ? (body as RelayJsonEntry[]) : null;
	} catch {
		throwIfAborted(signal);
		return null;
	}
}

/** A relay page `app.target` may pick: not discarded by Chrome, and not internal (devtools, service workers…). */
function isAdoptableRelayEntry(entry: RelayJsonEntry): boolean {
	return (
		entry.discarded !== "true" &&
		!ATTACH_TARGET_SKIP_PATTERN.test(entry.url) &&
		!ATTACH_TARGET_SKIP_PATTERN.test(entry.title)
	);
}

/** One of the user's Chrome tabs as `browser.targets()` lists it: `app.target` adopts it by `target` (its URL). */
export interface RelayTarget {
	/** The page URL, as `app.target` takes it (a URL/title substring). */
	target: string;
	title: string;
	url: string;
	/** Whether it is the active tab of its Chrome window. */
	shown: boolean;
}

/** The adoptable pages among relay `/json` entries; malformed, discarded, and internal entries are skipped. */
export function relayTargets(entries: readonly unknown[]): RelayTarget[] {
	const targets: RelayTarget[] = [];
	for (const raw of entries) {
		if (!isRecord(raw) || raw.type !== "page" || typeof raw.url !== "string") continue;
		const entry: RelayJsonEntry = {
			id: typeof raw.id === "string" ? raw.id : "",
			type: raw.type,
			url: raw.url,
			title: typeof raw.title === "string" ? raw.title : "",
			active: typeof raw.active === "string" ? raw.active : undefined,
			discarded: typeof raw.discarded === "string" ? raw.discarded : undefined,
		};
		if (!isAdoptableRelayEntry(entry)) continue;
		targets.push({ target: entry.url, title: entry.title, url: entry.url, shown: entry.active === "true" });
	}
	return targets;
}

/** The `browser.targets()` listing of relay pages: `- "Title" https://… (active)`. */
export function describeRelayTargets(targets: readonly RelayTarget[]): string {
	if (targets.length === 0) return "The relay lists no Chrome pages to adopt.";
	const list = targets
		.map(entry => `- ${JSON.stringify(entry.title)} ${entry.url}${entry.shown ? " (active)" : ""}`)
		.join("\n");
	return `Chrome pages via the relay (adopt one with app.target set to its URL or a title substring):\n${list}`;
}

/** The pages of the user's Chrome the relay at `relayJson` can adopt. */
export async function listRelayTargets(relayJson: string, signal?: AbortSignal): Promise<RelayTarget[]> {
	const entries = await fetchRelayEntries(relayJson, signal);
	if (!entries) throw new ToolError(`omp browser relay at ${relayJson} did not list its pages (GET /json failed).`);
	return relayTargets(entries);
}

function relayEntryMatches(entry: RelayJsonEntry, matcher: string): boolean {
	const needle = matcher.toLowerCase();
	return (
		entry.id === matcher || entry.url.toLowerCase().includes(needle) || entry.title.toLowerCase().includes(needle)
	);
}

function selectRelayEntry(entries: RelayJsonEntry[], options: PickTargetOptions): RelayJsonEntry | null {
	const matcher = options.matcher;
	if (matcher) {
		const exact = entries.find(e => e.id === matcher);
		const hits = exact ? [exact] : entries.filter(e => relayEntryMatches(e, matcher));
		const live = hits.filter(e => e.discarded !== "true");
		if (live.length > 0) return live[0]!;
		if (hits.length > 0) {
			throw new ToolError(
				`The tab matching ${JSON.stringify(options.matcher)} was discarded by Chrome. Click it to reload, then retry.`,
			);
		}
		const summary = entries.map(e => `- ${e.id}  ${e.title || "(untitled)"}  ${e.url}`).join("\n");
		throw new ToolError(
			`No page target matched ${JSON.stringify(options.matcher)} after waiting ${RELAY_MATCH_SETTLE_MS / 1000}s for a newly opened tab. Pass a target id, URL or title substring (browser.targets() lists URLs before adopting), or omit it to use the active tab. Available pages:\n${summary}`,
		);
	}
	const usable = entries.filter(isAdoptableRelayEntry);
	return usable.find(e => e.active === "true") ?? usable[0] ?? null;
}

/** Select relay pages from /json metadata before probing pages; enumerate targets when metadata offers no selection. */
export async function pickElectronTarget(browser: Browser, options: PickTargetOptions = {}): Promise<Page> {
	throwIfAborted(options.signal);
	if (options.relayJson) {
		let entries = await fetchRelayEntries(options.relayJson, options.signal);
		const matcher = options.matcher;
		const settleDeadline = Date.now() + RELAY_MATCH_SETTLE_MS;
		// Without page metadata, target enumeration below decides at once, as before.
		while (
			matcher &&
			entries?.some(e => e.type === "page") &&
			!entries.some(e => e.type === "page" && relayEntryMatches(e, matcher)) &&
			Date.now() < settleDeadline
		) {
			await abortable(options.signal, () => Bun.sleep(Math.min(RELAY_MATCH_POLL_MS, settleDeadline - Date.now())));
			const polled = await fetchRelayEntries(
				options.relayJson,
				options.signal,
				Math.max(1, settleDeadline - Date.now()),
			);
			throwIfAborted(options.signal);
			entries = polled ?? entries;
		}
		if (entries) {
			const pageEntries = entries.filter(e => e.type === "page");
			const selected = pageEntries.length > 0 ? selectRelayEntry(pageEntries, options) : null;
			const targets = browser.targets();
			if (options.preferVisible && !options.matcher) {
				const active = pageEntries.filter(e => e.active === "true" && isAdoptableRelayEntry(e));
				if (active.length > 1) {
					let firstPage: Page | null = null;
					let unreadableActive = false;
					for (const entry of active) {
						const target = targets.find(t => (t as Target & { _targetId?: string })._targetId === entry.id);
						if (!target) {
							unreadableActive = true;
							continue;
						}
						const page = await attachPageWithTimeout(target, PAGE_ATTACH_TIMEOUT_MS, options.signal);
						if (!page || !(await waitForMainFrame(page, FRAME_READY_TIMEOUT_MS, options.signal))) {
							unreadableActive = true;
							continue;
						}
						firstPage ??= page;
						const visible = await abortable(options.signal, () =>
							Promise.race([
								page.evaluate(() => document.visibilityState === "visible").catch(() => false),
								Bun.sleep(RELAY_VISIBILITY_TIMEOUT_MS).then(() => false),
							]),
						);
						if (visible) return page;
					}
					if (unreadableActive) throw new ToolError("An active tab is not ready; retry after it loads");
					if (firstPage) return firstPage;
				}
			}
			if (selected) {
				const isSelected = (t: Target) => (t as Target & { _targetId?: string })._targetId === selected.id;
				const attachDeadline = Date.now() + PAGE_ATTACH_TIMEOUT_MS;
				let target = targets.find(isSelected);
				if (!target) {
					// Puppeteer learns of a tab from the relay's targetCreated event, which can trail /json.
					try {
						target = await abortable(options.signal, () =>
							browser.waitForTarget(isSelected, { timeout: PAGE_ATTACH_TIMEOUT_MS, signal: options.signal }),
						);
					} catch (error) {
						throwIfAborted(options.signal);
						if (isPuppeteerTimeout(error)) {
							throw new ToolError(
								"Selected tab did not become available before omp could attach; retry, or reopen it if it closed",
							);
						}
						throw error;
					}
				}
				const page = await attachPageWithTimeout(target, attachDeadline - Date.now(), options.signal);
				if (!page || !(await waitForMainFrame(page, FRAME_READY_TIMEOUT_MS, options.signal)))
					throw new ToolError("Selected tab is not ready; retry after it loads");
				return page;
			}
		}
	}

	let targets = browser.targets();
	if (!targets.some(target => String(target.type()) === "page")) {
		const pages = await abortable(options.signal, () => browser.pages());
		if (pages.length > 0) return pickPageFromList(pages, options);
		// CDP discovery can start answering before Chromium or Electron has
		// created its first window. Wait for the page, never create a tab in a
		// borrowed browser or mistake endpoint readiness for page readiness.
		try {
			await abortable(options.signal, () =>
				browser.waitForTarget(target => String(target.type()) === "page", {
					timeout: PAGE_ATTACH_TIMEOUT_MS,
					signal: options.signal,
				}),
			);
		} catch (error) {
			throwIfAborted(options.signal);
			if (isPuppeteerTimeout(error)) {
				throw new ToolError("No page targets available on the attached browser");
			}
			throw error;
		}
		targets = browser.targets();
	}
	let hasUnreadablePage = false;
	const discoveredPages = await Promise.all(
		targets.map(async target => {
			if (String(target.type()) !== "page") return null;
			const page = await attachPageWithTimeout(target, PAGE_ATTACH_TIMEOUT_MS, options.signal);
			if (!page || !(await waitForMainFrame(page, FRAME_READY_TIMEOUT_MS, options.signal))) {
				hasUnreadablePage = true;
				return null;
			}
			return page;
		}),
	);
	const usablePages = discoveredPages.filter((page): page is Page => page !== null);
	if (hasUnreadablePage && (options.preferVisible || options.matcher)) {
		if (options.preferVisible && !options.matcher) {
			const visible = await firstVisiblePage(usablePages, options.signal);
			if (visible) return visible;
		}
		throw new ToolError("A browser tab is not ready; retry after it loads to avoid selecting a different tab");
	}
	if (usablePages.length > 0) return pickPageFromList(usablePages, options);

	const fallbackPages = await abortable(options.signal, () => browser.pages());
	if (!fallbackPages.length) {
		throw new ToolError("No page targets available on the attached browser");
	}
	return pickPageFromList(fallbackPages, options);
}

/** Result of {@link resolveAttachTarget}: the page to drive, and whether omp created it. */
export interface ResolvedAttachTarget {
	page: Page;
	/** True when omp created this page itself rather than adopting one that already existed. */
	ownsTarget: boolean;
}

/**
 * Resolve the page an attach-mode tab worker should drive, choosing between
 * adopting an existing tab and forcing a brand-new one.
 *
 * `forceFresh` is for the relay's default (no `app.target`) path: instead of
 * guessing at "the visible tab" — which silently hijacks whatever the user or
 * another concurrent omp session happens to be looking at — open a tab omp
 * owns outright, mirroring how Claude in Chrome always drives a tab it opened
 * itself. `Target.createTarget` temporarily puts the new tab in "omp"; the
 * worker moves it to its owning session's group. An explicit `matcher` instead
 * deliberately attaches an existing tab.
 */
export async function resolveAttachTarget(
	browser: Browser,
	options: PickTargetOptions & { forceFresh?: boolean } = {},
): Promise<ResolvedAttachTarget> {
	throwIfAborted(options.signal);
	if (options.forceFresh && !options.matcher) {
		return { page: await browser.newPage(), ownsTarget: true };
	}
	return { page: await pickElectronTarget(browser, options), ownsTarget: false };
}

async function enrichPages(
	pages: Page[],
	signal?: AbortSignal,
): Promise<Array<{ page: Page; id: string; url: string; title: string }>> {
	return await Promise.all(
		pages.map(async page => {
			await waitForMainFrame(page, FRAME_READY_TIMEOUT_MS, signal);
			const id = (page.target() as Target & { _targetId?: string })._targetId ?? "";
			let url = "";
			try {
				url = page.url();
			} catch {
				url = "";
			}
			const title = ((await abortable(signal, () => page.title().catch(() => ""))) ?? "").trim();
			return { page, id, url, title };
		}),
	);
}

async function firstVisiblePage(pages: Page[], signal?: AbortSignal): Promise<Page | null> {
	const visibility = await Promise.all(
		pages.map(
			async page =>
				await abortable(signal, () =>
					Promise.race([
						page.evaluate(() => document.visibilityState === "visible").catch(() => false),
						Bun.sleep(RELAY_VISIBILITY_TIMEOUT_MS).then(() => false),
					]),
				),
		),
	);
	const foreground = visibility.indexOf(true);
	return foreground >= 0 ? pages[foreground]! : null;
}

async function pickPageFromList(pages: Page[], options: PickTargetOptions): Promise<Page> {
	const enriched = await enrichPages(pages, options.signal);
	if (options.matcher) {
		const exact = enriched.find(p => p.id === options.matcher);
		if (exact) return exact.page;
		const needle = options.matcher.toLowerCase();
		const hit = enriched.find(p => p.url.toLowerCase().includes(needle) || p.title.toLowerCase().includes(needle));
		if (hit) return hit.page;
		const summary = enriched.map(p => `- ${p.id}  ${p.title || "(untitled)"}  ${p.url}`).join("\n");
		throw new ToolError(`No page target matched ${JSON.stringify(options.matcher)}. Available pages:\n${summary}`);
	}
	const usable = enriched.filter(
		p => !ATTACH_TARGET_SKIP_PATTERN.test(p.url) && !ATTACH_TARGET_SKIP_PATTERN.test(p.title),
	);
	if (options.preferVisible && usable.length > 1) {
		const foreground = await firstVisiblePage(
			usable.map(entry => entry.page),
			options.signal,
		);
		if (foreground) return foreground;
	}
	return usable[0]?.page ?? enriched[0]!.page;
}

/**
 * SIGTERM the process tree, wait briefly, then SIGKILL anything still alive.
 * Single-process variant for our own spawned children.
 */
export async function gracefulKillTreeOnce(pid: number, gracePeriodMs = 2000): Promise<void> {
	const process = Process.fromPid(pid);
	if (!process) return;
	await process.terminate({ gracefulMs: gracePeriodMs, timeoutMs: 500 });
}

import * as fs from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import { hasFsCode, isEnoent, toError, untilAborted } from "@oh-my-pi/pi-utils";
import type { Browser, CDPSession, Page } from "puppeteer-core";
import { ToolError } from "@oh-my-pi/pi-tui/tools/tool-errors";
import { replaceFileAcrossDevices, replaceFileAtomically } from "../../utils/atomic-file";
import { devtoolsFrameId } from "./frames";

/** Completed download metadata returned by tab download helpers. */
export interface BrowserDownload {
	path: string;
	suggestedFilename: string;
	url: string;
	bytes: number;
}

interface DownloadStarted {
	guid: string;
	url: string;
	suggestedFilename: string;
}

interface DownloadProgress {
	guid: string;
	state: "inProgress" | "completed" | "canceled";
	receivedBytes: number;
	/** Saved location on completion, in whichever folder Chromium was pointed at last. */
	filePath?: string;
}

interface PendingDownload extends DownloadStarted {
	receivedBytes: number;
}

interface DownloadWaiter {
	resolve(value: BrowserDownload): void;
	reject(error: unknown): void;
	signal?: AbortSignal;
	onAbort?: () => void;
}

/** Chromium names an `allowAndName` download after its GUID, a lowercase UUID. */
const DOWNLOAD_GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Owns tab-scoped Chromium download behavior and completion events. */
export class DownloadManager {
	readonly #browser: Browser;
	readonly #page: Page;
	readonly #defaultDirectory: string;
	readonly #perTab: boolean;
	readonly #relay: boolean;
	#directory?: string;
	#arming?: Promise<void>;
	#session?: CDPSession;
	readonly #pending = new Map<string, PendingDownload>();
	readonly #completed: BrowserDownload[] = [];
	readonly #unclaimed: BrowserDownload[] = [];
	readonly #waiters: DownloadWaiter[] = [];
	#willBegin?: (event: DownloadStarted & { frameId: string }) => void;
	#progress?: (event: DownloadProgress) => void;

	/**
	 * `perTab` gives each tab its own folder by saving under download GUIDs and moving each tab's own files. Leave it off
	 * for a browser the user drives (connected, relay): there the folder also receives the user's own downloads, which
	 * would otherwise be saved under bare GUIDs nobody renames.
	 */
	constructor(browser: Browser, page: Page, tabId: string, options: { perTab: boolean; relay?: boolean }) {
		this.#browser = browser;
		this.#page = page;
		this.#defaultDirectory = path.join(os.tmpdir(), `omp-downloads-${tabId}`);
		this.#perTab = options.perTab;
		this.#relay = options.relay === true;
	}

	/**
	 * Point the browser's one download folder at this tab's folder. Per tab, files are saved under their download GUID
	 * so tabs never overwrite each other's, and each tab moves its own into its folder under the suggested name.
	 */
	async enable(directory?: string): Promise<void> {
		this.#requireSupportedDownloads();
		const resolved = path.resolve(directory ?? this.#defaultDirectory);
		await fs.mkdir(resolved, { recursive: true });
		if (!this.#session) await this.#attach();
		const context = this.#page.browserContext() as { id?: string };
		await this.#session!.send("Browser.setDownloadBehavior", {
			behavior: this.#perTab ? "allowAndName" : "allow",
			downloadPath: resolved,
			eventsEnabled: true,
			...(context.id ? { browserContextId: context.id } : {}),
		});
		this.#directory = resolved;
	}

	#requireSupportedDownloads(): void {
		if (this.#relay) {
			throw new ToolError(
				"Relay download tracking is unavailable in this fork because the extension keeps its existing permissions. Use an explicitly selected non-relay browser for download tracking.",
			);
		}
	}

	/** Enabling started by a `wait()` that has not yet applied; settles once downloads are tracked. */
	get arming(): Promise<void> | undefined {
		return this.#arming;
	}

	/** Wait for the next unclaimed completed download. */
	async wait(signal?: AbortSignal): Promise<BrowserDownload> {
		this.#requireSupportedDownloads();
		if (this.#unclaimed.length === 0) {
			// A rejected `arming` nobody awaits would surface as an unhandled rejection.
			if (signal?.aborted) throw signal.reason;
			// The tab that pointed Chromium last resets it to the browser's default folder when it closes, so re-point it.
			const arming = (this.#arming ??= this.enable(this.#directory).finally(() => {
				this.#arming = undefined;
			}));
			try {
				await untilAborted(signal, arming);
			} catch (error) {
				// Abort with the caller's reason, as the waits below do.
				if (signal?.aborted) throw signal.reason;
				throw error;
			}
		}
		const ready = this.#unclaimed.shift();
		if (ready) return { ...ready };
		if (signal?.aborted) throw signal.reason;
		return await new Promise<BrowserDownload>((resolve, reject) => {
			const waiter: DownloadWaiter = { resolve, reject, signal };
			if (signal) {
				waiter.onAbort = () => {
					this.#removeWaiter(waiter);
					reject(signal.reason);
				};
				signal.addEventListener("abort", waiter.onAbort, { once: true });
			}
			this.#waiters.push(waiter);
		});
	}

	/** Return every completed download for this tab. */
	list(): BrowserDownload[] {
		this.#requireSupportedDownloads();
		return this.#completed.map(download => ({ ...download }));
	}

	/** Detach event listeners and reject outstanding waits. */
	async close(): Promise<void> {
		const session = this.#session;
		if (!session) return;
		if (this.#willBegin) session.off("Browser.downloadWillBegin", this.#willBegin);
		if (this.#progress) session.off("Browser.downloadProgress", this.#progress);
		for (const waiter of this.#waiters.splice(0)) {
			if (waiter.signal && waiter.onAbort) waiter.signal.removeEventListener("abort", waiter.onAbort);
			waiter.reject(new ToolError("Tab closed while waiting for a download"));
		}
		this.#session = undefined;
		await session.detach().catch(() => undefined);
	}

	async #attach(): Promise<void> {
		const session = await this.#browser.target().createCDPSession();
		this.#willBegin = event => {
			// Every session hears every download in the browser; keep the ones this tab's frames started.
			if (!this.#page.frames().some(frame => devtoolsFrameId(frame) === event.frameId)) return;
			this.#pending.set(event.guid, { ...event, receivedBytes: 0 });
		};
		this.#progress = event => {
			const pending = this.#pending.get(event.guid);
			if (!pending) return;
			pending.receivedBytes = event.receivedBytes;
			if (event.state === "inProgress") return;
			this.#pending.delete(event.guid);
			if (event.state === "canceled") {
				this.#rejectNext(new ToolError(`Download canceled: ${pending.url}`));
				return;
			}
			void this.#complete(pending, event.filePath).catch(error => {
				this.#rejectNext(new ToolError(`Download failed: ${pending.url}: ${toError(error).message}`));
			});
		};
		session.on("Browser.downloadWillBegin", this.#willBegin);
		session.on("Browser.downloadProgress", this.#progress);
		this.#session = session;
	}

	async #complete(pending: PendingDownload, filePath: string | undefined): Promise<void> {
		const directory = this.#directory ?? this.#defaultDirectory;
		const source = filePath ?? path.join(directory, this.#perTab ? pending.guid : pending.suggestedFilename);
		for (let attempt = 0; attempt < 100; attempt++) {
			try {
				await fs.stat(source);
				break;
			} catch {
				await Bun.sleep(10);
			}
		}
		const name = typeof pending.suggestedFilename === "string" ? path.basename(pending.suggestedFilename) : "";
		const target = path.join(directory, name);
		// Only the last segment of the suggested name is used; anything else, or a download that cannot be moved, is
		// reported where Chromium saved it.
		const movable =
			this.#perTab &&
			name !== "" &&
			name !== "." &&
			name !== ".." &&
			(await canMoveDownload(source, pending.guid, target));
		const downloadPath = movable
			? await moveDownload(source, target).then(
					() => target,
					() => source,
				)
			: source;
		const download: BrowserDownload = {
			path: downloadPath,
			suggestedFilename: pending.suggestedFilename,
			url: pending.url,
			bytes: pending.receivedBytes,
		};
		this.#completed.push(download);
		const waiter = this.#waiters.shift();
		if (!waiter) {
			this.#unclaimed.push(download);
			return;
		}
		if (waiter.signal && waiter.onAbort) waiter.signal.removeEventListener("abort", waiter.onAbort);
		waiter.resolve({ ...download });
	}

	#rejectNext(error: ToolError): void {
		const waiter = this.#waiters.shift();
		if (!waiter) return;
		if (waiter.signal && waiter.onAbort) waiter.signal.removeEventListener("abort", waiter.onAbort);
		waiter.reject(error);
	}

	#removeWaiter(waiter: DownloadWaiter): void {
		const index = this.#waiters.indexOf(waiter);
		if (index >= 0) this.#waiters.splice(index, 1);
	}
}

/**
 * Whether `source` is a regular file saved under a UUID-shaped download GUID, and `target` is free or a file it may
 * replace. The peer names the GUID, the saved path and the suggested name, so a symlink or directory stays where it is.
 */
async function canMoveDownload(source: string, guid: string, target: string): Promise<boolean> {
	if (!DOWNLOAD_GUID.test(guid) || path.basename(source) !== guid) return false;
	return (await entryKind(source)) === "file" && (await entryKind(target)) !== "other";
}

/** What a path names, without following a symlink there. */
async function entryKind(file: string): Promise<"file" | "missing" | "other"> {
	try {
		return (await fs.lstat(file)).isFile() ? "file" : "other";
	} catch (error) {
		return isEnoent(error) ? "missing" : "other";
	}
}

/** Move a completed download into a tab's folder, replacing a same-named file as Chromium's own saves do. */
async function moveDownload(source: string, target: string): Promise<void> {
	await fs.mkdir(path.dirname(target), { recursive: true });
	try {
		await replaceFileAtomically(source, target);
	} catch (error) {
		if (!hasFsCode(error, "EXDEV")) throw error;
		await replaceFileAcrossDevices(source, target);
	}
}

{
	"manifest_version": 3,
	"name": "OMP Browser Relay",
	"version": "0.1.0",
	"description": "Lets the omp coding agent drive your existing tabs through a local CDP relay.",
	"author": "Stencil Labs, Inc.",
	"homepage_url": "https://omp.sh",
	"permissions": ["debugger", "tabs", "tabGroups", "storage", "alarms"],
	"background": {
		"service_worker": "background.js"
	},
	"options_page": "options.html",
	"action": {
		"default_title": "OMP Browser Relay (click for settings)"
	}
}

/**
 * HTTP + WebSocket server for the browser relay.
 *
 * Impersonates Chrome's CDP discovery endpoint so the omp browser tool (and
 * any puppeteer client) can connect with a plain `browserURL`:
 * - `GET /json/version` → 200 with `webSocketDebuggerUrl` once the extension
 *   is connected, 503 with a {@link RelayUnavailableInfo} body before that
 *   (`waitForRelayExtension` decides from it whether polling is worthwhile).
 * - `GET /json` / `/json/list` → attachable page targets (debugging aid).
 * - `WS /cdp` → downstream CDP clients (puppeteer).
 * - `WS /ext` → the Chrome extension (token-gated when configured).
 *
 * Binds loopback only: anything that can reach this port can drive the
 * user's logged-in browser.
 */
import { macOSFrontApp } from "@oh-my-pi/pi-natives";
import { parseFlag } from "@oh-my-pi/pi-utils";
import { VERSION } from "@oh-my-pi/pi-utils/dirs";
import { RelayBridge, type RelayBridgeExtensionUpdater } from "./bridge";
import {
	defaultRelayExtensionDir,
	installedRelayExtensionVersion,
	unpackedExtensionId,
	writeRelayExtension,
} from "./extension-files";
import { isOlderOmpVersion } from "./protocol";

/** Options for {@link startRelayServer}. */
export interface RelayServerOptions {
	port: number;
	/** Shared secret the extension must present as `?token=`; unset disables the check. */
	token?: string;
	/** Group tabs the agent actively drives under one per-window Chrome tab group (default on); `false` disables. */
	group?: boolean | { title: string; color: string };
	/**
	 * The extension copy this relay keeps current: an older extension Chrome loaded from here is rewritten and
	 * reloaded (default: `omp browser-relay install`'s directory).
	 */
	extensionDir?: string;
	log?: (message: string, data?: Record<string, unknown>) => void;
}

/**
 * Updates the extension when Chrome loaded it from `dir`: an extension loaded from elsewhere (`install --dir`, a
 * development build) is not this relay's to rewrite, and files a newer omp wrote are left for that omp's relay.
 * Calls run one at a time: Chrome profiles that load the same folder share its files, and a later call finds them
 * already current.
 */
function extensionUpdaterFor(dir: string): RelayBridgeExtensionUpdater {
	let queue: Promise<unknown> = Promise.resolve();
	const update = async (extensionId: string) => {
		if ((await unpackedExtensionId(dir)) !== extensionId) return false;
		if (isOlderOmpVersion(VERSION, await installedRelayExtensionVersion(dir))) return false;
		await writeRelayExtension(dir, VERSION);
		return true;
	};
	return extensionId => {
		const result = queue.then(() => update(extensionId));
		queue = result.catch(() => {});
		return result;
	};
}

/** `chrome-extension://<id>` → `<id>`; anything else → undefined. */
const EXTENSION_ORIGIN = /^chrome-extension:\/\/([a-p]{32})$/;

/** Body of the 503 `/json/version` answer while no extension is connected. */
export interface RelayUnavailableInfo {
	/** Version of the OMP binary serving this relay. */
	ompRelayVersion: string;
	error: string;
	/** An extension completed the hello handshake at least once in this server's lifetime. */
	extensionSeen: boolean;
	/** Milliseconds this server has been listening. */
	uptimeMs: number;
	/** Downstream CDP clients connected to this relay. */
	ompRelayCdpClients: number;
	/** Milliseconds since the last connected extension went away; absent if none has connected yet. */
	disconnectedMs?: number;
}

/** A running relay server. */
export interface RelayServer {
	bridge: RelayBridge;
	port: number;
	stop(): void;
}

interface SocketData {
	role: "cdp" | "ext";
	connId?: number;
	/** The Chrome extension id an `ext` upgrade's `Origin` named. */
	extensionId?: string;
}

type RelayWebSocket = Bun.ServerWebSocket<SocketData>;

const WS_KEEPALIVE_MS = 30_000;
/** Screenshots travel base64-encoded through both websocket legs. */
const MAX_PAYLOAD_BYTES = 256 * 1024 * 1024;
/** Default appearance of the omp tab group. */
const DEFAULT_GROUP = { title: "omp", color: "cyan" } as const;
/** True when `raw` can serve as the authority of a `ws://` URL: no whitespace,
 *  slashes, userinfo, fragments, or control characters, and URL-parseable. */
function isWsAuthority(raw: string): boolean {
	if (/[\s/\\@#?]|[\x00-\x1f]/.test(raw)) return false;
	try {
		return new URL(`ws://${raw}`).host.length > 0;
	} catch {
		return false;
	}
}

/** Start the relay server on 127.0.0.1. Throws if the port is taken. */
export function startRelayServer(opts: RelayServerOptions): RelayServer {
	const log = opts.log ?? (() => {});
	const group =
		opts.group === false ? null : opts.group === true || opts.group === undefined ? DEFAULT_GROUP : opts.group;
	const updateExtension = extensionUpdaterFor(opts.extensionDir ?? defaultRelayExtensionDir());
	const bridge = new RelayBridge({ log, group, updateExtension });
	const sockets = new Set<RelayWebSocket>();
	const startedAt = Date.now();
	// Only macOS can hand the front app back; elsewhere the relay never reads it.
	if (process.platform === "darwin" && parseFlag(process.env.PI_BROWSER_RELAY_KEEP_FRONT, true)) {
		bridge.keepFrontAppWith(macOSFrontApp);
	}

	const server = Bun.serve({
		hostname: "127.0.0.1",
		port: opts.port,
		fetch(req, srv): Response | undefined {
			const fallback = `127.0.0.1:${opts.port}`;
			const rawHost = req.headers.get("host")?.trim();
			const host = rawHost && isWsAuthority(rawHost) ? rawHost : fallback;
			const requestUrl =
				rawHost && rawHost !== host && req.url.startsWith(`http://${rawHost}`)
					? req.url.slice(`http://${rawHost}`.length)
					: req.url;
			const url = new URL(requestUrl, `http://${fallback}`);
			const path = url.pathname.replace(/\/+$/, "") || "/";
			if (path === "/cdp") {
				// Browsers set Origin on websocket upgrades; native CDP clients
				// don't. Reject any Origin so a web page can't drive the relay.
				if (req.headers.get("origin")) return new Response("Forbidden", { status: 403 });
				const data: SocketData = { role: "cdp" };
				if (srv.upgrade(req, { data })) return undefined;
				return new Response("websocket upgrade required", { status: 426 });
			}
			if (path === "/ext") {
				const origin = req.headers.get("origin");
				if (origin && !origin.startsWith("chrome-extension://")) {
					return new Response("Forbidden", { status: 403 });
				}
				if (opts.token && url.searchParams.get("token") !== opts.token) {
					return new Response("Unauthorized", { status: 401 });
				}
				const data: SocketData = { role: "ext", extensionId: origin?.match(EXTENSION_ORIGIN)?.[1] };
				if (srv.upgrade(req, { data })) return undefined;
				return new Response("websocket upgrade required", { status: 426 });
			}
			if (req.method !== "GET") return new Response("Method not allowed", { status: 405 });
			if (path === "/json/version") {
				if (!bridge.ready) {
					const disconnectedMs = bridge.extensionGoneForMs;
					const info: RelayUnavailableInfo = {
						ompRelayVersion: VERSION,
						error: "relay extension is not connected",
						extensionSeen: bridge.extensionSeen,
						uptimeMs: Date.now() - startedAt,
						ompRelayCdpClients: bridge.cdpClientCount,
						...(disconnectedMs === null ? {} : { disconnectedMs }),
					};
					return Response.json(info, { status: 503 });
				}
				return Response.json(bridge.versionInfo(`ws://${host}/cdp`));
			}
			if (path === "/json" || path === "/json/list") {
				return Response.json(bridge.listTargets());
			}
			return new Response("Not found", { status: 404 });
		},
		websocket: {
			maxPayloadLength: MAX_PAYLOAD_BYTES,
			// Disabled: Bun caps idleTimeout at 255s, and the keepalive pings
			// below already detect dead peers via the websocket close path.
			idleTimeout: 0,
			open(ws: RelayWebSocket): void {
				sockets.add(ws);
				if (ws.data.role === "ext") {
					bridge.extConnected(ws, ws.data.extensionId);
				} else {
					ws.data.connId = bridge.cdpConnected(ws);
				}
			},
			message(ws: RelayWebSocket, message: string | Buffer): void {
				const text = typeof message === "string" ? message : new TextDecoder().decode(message);
				if (ws.data.role === "ext") {
					bridge.extMessage(ws, text);
				} else if (ws.data.connId !== undefined) {
					bridge.cdpMessage(ws.data.connId, text);
				}
			},
			close(ws: RelayWebSocket): void {
				sockets.delete(ws);
				if (ws.data.role === "ext") {
					bridge.extClosed(ws);
				} else if (ws.data.connId !== undefined) {
					bridge.cdpClosed(ws.data.connId);
				}
			},
		},
	});

	// Puppeteer connections go silent while the agent is idle; protocol-level
	// pings count as activity and keep them under the idle timeout.
	const keepalive = setInterval(() => {
		for (const ws of sockets) ws.ping();
	}, WS_KEEPALIVE_MS);
	keepalive.unref();

	log("relay listening", { port: opts.port });
	return {
		bridge,
		port: opts.port,
		stop() {
			clearInterval(keepalive);
			server.stop(true);
		},
	};
}

import type { ImageContent, TextContent } from "@oh-my-pi/pi-ai";

export type Transferable = Bun.Transferable;

export interface ObservationEntry {
	id: number;
	role: string;
	name?: string;
	value?: string | number;
	description?: string;
	keyshortcuts?: string;
	states: string[];
}

export interface Observation {
	url: string;
	title?: string;
	viewport: { width: number; height: number; deviceScaleFactor?: number };
	scroll: {
		x: number;
		y: number;
		width: number;
		height: number;
		scrollWidth: number;
		scrollHeight: number;
	};
	elements: ObservationEntry[];
}

export interface ScreenshotResult {
	dest: string;
	mimeType: string;
	bytes: number;
	width: number;
	height: number;
}

export interface SessionSnapshot {
	cwd: string;
	browserScreenshotDir?: string;
	/** Force non-WebP screenshot encoding (e.g. for Ollama). Unset honors `OMP_NO_WEBP`. */
	excludeWebP?: boolean;
}

/**
 * The page an attach worker drives. `create`: open and own a background tab in a
 * spawned browser or relay; `nearTargetId` selects the relay browser when given.
 * `owned`: an omp tab adopted after recycle. `borrowed`: a user's page, never closed.
 */
export type AttachPage = { kind: "create"; nearTargetId?: string } | { kind: "owned" | "borrowed"; targetId: string };

/** omp created the payload's page: closing the tab closes the page. */
export function ownsPage(payload: WorkerInitPayload): boolean {
	return payload.mode === "headless" || payload.page.kind !== "borrowed";
}

export type WorkerInitPayload =
	| {
			mode: "headless";
			browserWSEndpoint: string;
			safeDir: string;
			/** The tab's upload staging folder, which outlives a recycled worker; see `UploadStaging`. */
			uploadDir: string;
			/** Keep the page tied to an OMP-owned worker without pinning a visible window's layout viewport. */
			emulateViewport?: boolean;
			viewport?: { width: number; height: number; deviceScaleFactor?: number };
			dialogs?: "accept" | "dismiss";
			/** Hostname patterns allowed for every page request. */
			allowedDomains?: string[];
			/** Document-start JavaScript sources registered before navigation. */
			initScripts?: string[];
			/** Absolute directory enabled for completed downloads. */
			downloadsPath?: string;
			/** Explicit tab user agent applied during worker initialization. */
			userAgent?: string;
			/** Ignore invalid HTTPS certificates for this page. */
			ignoreHttpsErrors?: boolean;
	  }
	| {
			mode: "attach";
			browserWSEndpoint: string;
			safeDir: string;
			/** The tab's upload staging folder, which outlives a recycled worker; see `UploadStaging`. */
			uploadDir: string;
			page: AttachPage;
			viewport?: { width: number; height: number; deviceScaleFactor?: number };
			dialogs?: "accept" | "dismiss";
			/** Hostname patterns allowed for every page request. */
			allowedDomains?: string[];
			/** Document-start JavaScript sources registered before navigation. */
			initScripts?: string[];
			/** Absolute directory enabled for completed downloads. */
			downloadsPath?: string;
			/** Explicit tab user agent applied during worker initialization. */
			userAgent?: string;
			/** Ignore invalid HTTPS certificates for this page. */
			ignoreHttpsErrors?: boolean;
			/**
			 * Post-timeout recycle: before adopting the page, dismiss any open JS dialog and
			 * stop a pending navigation so a blocked target cannot stall worker init (which
			 * previously force-killed the tab). Never set for first-time Electron attach.
			 */
			recover?: boolean;
			/** Owning session label used to group omp-owned relay tabs. */
			groupLabel?: string;
			/**
			 * The user drives this browser (connected, relay): downloads keep its one browser-wide folder and real file
			 * names, since the user's own downloads land there too. Unset means an OMP-launched browser.
			 */
			userDriven?: boolean;
			/** The browser is the restricted omp relay, which does not support download tracking. */
			relay?: boolean;
	  };

/** Result of one host tool requested by browser-run JavaScript. */
export type ToolReply = { ok: true; value: unknown } | { ok: false; error: RunErrorPayload };

export type WorkerInbound =
	| { type: "init"; payload: WorkerInitPayload }
	| { type: "run"; id: string; name: string; code: string; timeoutMs: number; session: SessionSnapshot }
	| { type: "abort"; id: string; expectedCleanup?: boolean }
	| { type: "tool-reply"; id: string; reply: ToolReply }
	/** `keepPage` leaves a page omp created open in its browser; only the worker's hold on it goes. */
	| { type: "close"; keepPage?: boolean };

export interface ReadyInfo {
	url: string;
	title?: string;
	viewport: { width: number; height: number; deviceScaleFactor?: number };
	targetId: string;
}

export interface RunResultOk {
	displays: Array<TextContent | ImageContent>;
	returnValue: unknown;
	screenshots: ScreenshotResult[];
	/** The run finished but tab-scoped browser state was not restored; the tab must be recycled. */
	recoverTab?: boolean;
}

export interface RunErrorPayload {
	name: string;
	message: string;
	stack?: string;
	isToolError: boolean;
	isAbort: boolean;
	/** The worker could not restore tab-scoped browser state and must be recycled. */
	recoverTab?: boolean;
	/** `tab.goto` outlasted its budget; the page stays on what loaded. */
	navigationTimeout?: boolean;
	/** The page's renderer crashed; the worker runs nothing more and must be recycled. */
	rendererCrashed?: boolean;
	/**
	 * Chrome ended the debugger attachment the page is driven through (omp browser relay) `during` this run, after
	 * its code started, or `before` it, so nothing ran; the worker runs nothing more. `reason` is Chrome's
	 * (`target_closed`, `canceled_by_user`): after a user cancel the relay hides the tab, otherwise it is re-adopted.
	 */
	debuggerDetached?: { when: "during" | "before"; reason: string };
}

export type WorkerOutbound =
	| {
			/**
			 * Puppeteer loaded, browser connected. Sent before page acquisition so the supervisor's cold-start budget
			 * bounds only the realm setup (cold import + connect); page creation runs under the ready wait.
			 */
			type: "setup";
	  }
	| {
			/**
			 * The headless page was created (before the potentially slow post-creation CDP work such as stealth and
			 * viewport). Lets the supervisor close exactly this target if it kills the worker during init — a killed
			 * worker can't clean up after itself.
			 */
			type: "page-created";
			targetId: string;
	  }
	| { type: "ready"; info: ReadyInfo }
	| { type: "init-failed"; error: RunErrorPayload }
	| { type: "result"; id: string; ok: true; payload: RunResultOk }
	| { type: "result"; id: string; ok: false; error: RunErrorPayload }
	| { type: "tool-call"; id: string; runId: string; name: string; args: unknown }
	| { type: "log"; level: "debug" | "warn" | "error"; msg: string; meta?: Record<string, unknown> }
	| { type: "closed" };

export interface Transport {
	send(msg: WorkerOutbound | WorkerInbound, transferList?: Transferable[]): void;
	onMessage(handler: (msg: WorkerOutbound | WorkerInbound) => void): () => void;
	close(): void;
}

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { __ompSetGrammarDir, type WasmGrammarInfo, type WasmGrammarQuery, wasmGrammarFor } from "@oh-my-pi/pi-natives";
import { getNativeGrammarsDir, logger, withFileLock } from "@oh-my-pi/pi-utils";
import { withDownload } from "../downloads/activity";
import { downloadFile } from "./tools-manager";

/**
 * On-demand tree-sitter grammars. Less common languages ship as WebAssembly
 * grammars attached to a GitHub release instead of being linked into the
 * native addon; the addon loads `<natives dir>/grammars/<file>` lazily on next
 * use (the natives loader configures that directory), so installing is just
 * placing the verified `.wasm` there.
 *
 * Asset URL: `${PI_GRAMMARS_URL ?? GitHub releases}/<release>/<file>.zst`, a
 * zstd frame whose decompressed bytes must match the pinned size and SHA-256
 * reported by `wasmGrammarFor`.
 */

const DEFAULT_GRAMMARS_URL = "https://github.com/stencil-hq/wasm-grammars/releases/download";
/** Whole-transfer bound for one compressed grammar. */
const DOWNLOAD_TIMEOUT_MS = 60_000;
/** Lock wait long enough to cover a peer process's whole download. */
const LOCK_OPTIONS = { retries: DOWNLOAD_TIMEOUT_MS / 100 + 50, retryDelayMs: 100 };
/** After a failed install, skip that grammar for this long so offline sessions do not refetch on every call. */
const RETRY_AFTER_FAILURE_MS = 5 * 60_000;

/** In-flight installs keyed by destination path. */
const inflight = new Map<string, Promise<boolean>>();
/** Last failed install time keyed by destination path. */
const failedAt = new Map<string, number>();

async function fetchGrammar(
	info: WasmGrammarInfo,
	dest: string,
	onProgress: (loaded: number, total: number | undefined) => void,
): Promise<void> {
	const base = process.env.PI_GRAMMARS_URL?.trim().replace(/\/+$/, "") || DEFAULT_GRAMMARS_URL;
	const url = `${base}/${info.release}/${info.file}.zst`;
	const compressed = `${dest}.zst.part`;
	const part = `${dest}.part`;
	logger.debug("grammar: downloading", { language: info.language, url });
	try {
		await downloadFile(url, compressed, { timeoutMs: DOWNLOAD_TIMEOUT_MS, onProgress });
		const wasm = Bun.zstdDecompressSync(await Bun.file(compressed).bytes());
		if (wasm.byteLength !== info.size) {
			throw new Error(`${info.file}: expected ${info.size} bytes, received ${wasm.byteLength}`);
		}
		const digest = new Bun.CryptoHasher("sha256").update(wasm).digest("hex");
		if (digest !== info.sha256.toLowerCase()) throw new Error(`${info.file}: SHA-256 mismatch (${digest})`);
		await Bun.write(part, wasm);
		// Rename, never rewrite in place: the addon reads `<dir>/<file>` lazily and must never see a partial file.
		await fs.rename(part, dest);
	} finally {
		await fs.rm(compressed, { force: true });
		await fs.rm(part, { force: true });
	}
}

async function installLocked(info: WasmGrammarInfo, dir: string, dest: string): Promise<boolean> {
	try {
		await fs.mkdir(dir, { recursive: true });
		return await withFileLock(
			`${dest}.install`,
			async () => {
				// Another process may have finished the install while we waited.
				if (await Bun.file(dest).exists()) return true;
				await withDownload(
					`${info.language} grammar`,
					tracker => fetchGrammar(info, dest, (loaded, total) => tracker.update({ loaded, total })),
					{ detail: info.file },
				);
				logger.debug("grammar: installed", { language: info.language, file: info.file });
				return true;
			},
			LOCK_OPTIONS,
		);
	} catch (error) {
		failedAt.set(dest, Date.now());
		logger.warn("grammar: install failed; files in this language are skipped", {
			language: info.language,
			file: info.file,
			error: String(error),
		});
		return false;
	}
}

/**
 * Download, verify, and install `info`'s wasm grammar into `dir` (default:
 * the directory the addon reads). Returns whether `<dir>/<file>` exists
 * afterwards. Concurrent calls for the same file share one install, and an OS
 * file lock serializes installs across processes. Never throws: network and
 * integrity failures are logged, return `false`, and back off for a few
 * minutes. {@link ensureGrammar} is the usual entry point; this takes the
 * resolved info directly (test seam).
 */
export function installGrammar(info: WasmGrammarInfo, dir: string = getNativeGrammarsDir()): Promise<boolean> {
	const dest = path.join(dir, info.file);
	const pending = inflight.get(dest);
	if (pending) return pending;
	const failed = failedAt.get(dest);
	if (failed !== undefined && Date.now() - failed < RETRY_AFTER_FAILURE_MS) return Promise.resolve(false);
	const install = installLocked(info, dir, dest).finally(() => inflight.delete(dest));
	inflight.set(dest, install);
	return install;
}

/**
 * Make sure the wasm grammar for `query` (a `lang` alias or a file `path`) is
 * installed, downloading it on first use. Returns `true` without network
 * access for built-in, unknown, or already installed languages; otherwise
 * whether the install succeeded. Offline or integrity failures log and return
 * `false`; native AST APIs then treat the language as unsupported.
 */
export async function ensureGrammar(query: WasmGrammarQuery): Promise<boolean> {
	// The loader cannot import pi-utils and initializes a legacy fallback. Use
	// the installer's resolver here, including runtime profile/XDG changes.
	__ompSetGrammarDir(getNativeGrammarsDir());
	const info = wasmGrammarFor(query);
	if (!info || info.installed) return true;
	return installGrammar(info);
}

/**
 * Install the wasm grammars of `languages` (typically a native result's
 * `missingGrammars`). Returns `true` when at least one of them is now
 * installed, i.e. a caller that saw them missing should re-run.
 */
export async function ensureGrammars(languages: readonly string[]): Promise<boolean> {
	__ompSetGrammarDir(getNativeGrammarsDir());
	const installed = await Promise.all(
		languages.map(lang => {
			const info = wasmGrammarFor({ lang });
			if (!info) return false;
			return info.installed || installGrammar(info);
		}),
	);
	return installed.includes(true);
}

/**
 * Run an idempotent native AST call (a search or a dry-run preview) against
 * the grammar cache and, when it reports `missingGrammars`, install them and
 * run it once more. Never use it for calls that write: the re-run would apply
 * rewrites twice.
 */
export async function rerunWithGrammars<T extends { missingGrammars?: string[] }>(run: () => Promise<T>): Promise<T> {
	const result = await run();
	if (!result.missingGrammars?.length || !(await ensureGrammars(result.missingGrammars))) return result;
	return run();
}

/** Tool-output note for languages whose files were skipped because their grammar could not be installed. */
export function missingGrammarsNote(languages: readonly string[]): string {
	return `Skipped ${languages.join(", ")} files: grammar could not be downloaded (offline?); results exclude them.`;
}

/**
 * ACP stdout-hygiene smoke: launching `omp acp` must not leak any banner,
 * progress text, or stray non-JSON bytes onto stdout — that channel is owned
 * by the JSON-RPC protocol. We spawn the CLI as a subprocess, send a single
 * `initialize` frame, and assert the first stdout line parses cleanly as a
 * JSON-RPC response.
 */
import { afterEach, describe, expect, it } from "bun:test";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

type AcpProc = Bun.Subprocess<"pipe", "pipe", "pipe">;

const repoRoot = path.resolve(import.meta.dir, "..", "..", "..");
const cliEntry = path.join(repoRoot, "packages", "coding-agent", "src", "cli.ts");

const cleanupRoots: string[] = [];
let activeProc: AcpProc | undefined;

/**
 * Tear the child down deterministically. Once the initialize frame has been
 * asserted there is no graceful-shutdown behavior under test, so close stdin
 * and kill the throwaway process rather than parking on a grace-period timer.
 */
async function teardown(proc: AcpProc): Promise<void> {
	// Close stdin so any blocking read in the child wakes up.
	try {
		proc.stdin.end();
	} catch {
		// already closed
	}
	// Best-effort detach from stdout/stderr so the child's pipe writes don't
	// block on a full buffer once we stop draining.
	for (const stream of [proc.stdout, proc.stderr] as Array<ReadableStream<Uint8Array> | undefined>) {
		if (!stream) continue;
		try {
			await stream.cancel();
		} catch {
			// reader may already be detached
		}
	}

	try {
		proc.kill("SIGKILL");
	} catch {
		// already exited
	}
	await proc.exited;
}

afterEach(async () => {
	if (activeProc) {
		const proc = activeProc;
		activeProc = undefined;
		try {
			await teardown(proc);
		} catch {
			// teardown is already best-effort; never let cleanup fail a test
		}
	}
	for (const root of cleanupRoots.splice(0)) {
		await fs.promises.rm(root, { recursive: true, force: true });
	}
});

async function readFirstFrame(stream: ReadableStream<Uint8Array>): Promise<string> {
	const reader = stream.getReader();
	const decoder = new TextDecoder();
	let buffer = "";
	while (true) {
		const { value, done } = await reader.read();
		if (done) break;
		buffer += decoder.decode(value, { stream: true });
		const newlineIdx = buffer.indexOf("\n");
		if (newlineIdx >= 0) {
			reader.releaseLock();
			return buffer.slice(0, newlineIdx);
		}
	}
	reader.releaseLock();
	return buffer;
}

describe("ACP stdout hygiene", () => {
	it("emits a JSON-RPC initialize response as the first bytes on stdout", async () => {
		const root = await fs.promises.mkdtemp(path.join(os.tmpdir(), "omp-acp-stdout-"));
		cleanupRoots.push(root);
		const xdg = path.join(root, "xdg");
		const agentDir = path.join(root, "agent");
		await fs.promises.mkdir(path.join(xdg, "omp"), { recursive: true });
		await fs.promises.mkdir(agentDir, { recursive: true });

		// Keep HOME unchanged. On XDG platforms, the default
		// agent path lets the initialized private app root cover agent and
		// per-project daemon state; a custom override disables that root/agent selection.
		const childEnv: Record<string, string | undefined> = {
			...process.env,
			XDG_DATA_HOME: xdg,
			XDG_CONFIG_HOME: xdg,
			XDG_STATE_HOME: xdg,
			XDG_CACHE_HOME: xdg,
			PI_CODING_AGENT_DIR: agentDir,
			PI_NO_TITLE: "1",
			NO_COLOR: "1",
		};
		if (process.platform === "linux" || process.platform === "darwin") {
			childEnv.PI_CONFIG_DIR = `.omp-${path.basename(root)}`;
			childEnv.PI_CODING_AGENT_DIR = undefined;
			childEnv.OMP_PROFILE = "default";
			childEnv.PI_PROFILE = undefined;
		}
		const proc = Bun.spawn(["bun", cliEntry, "acp"], {
			cwd: repoRoot,
			stdin: "pipe",
			stdout: "pipe",
			stderr: "pipe",
			env: childEnv,
		});
		activeProc = proc;

		// Buffer stderr in the background so we can assert no JSON-RPC frame
		// leaks onto it. The pump exits the moment stderr closes, which
		// happens during teardown — we never wait on it from the test body.
		const stderrChunks: Uint8Array[] = [];
		const stderrPump = (async () => {
			const reader = proc.stderr.getReader();
			try {
				while (true) {
					const { value, done } = await reader.read();
					if (done) break;
					if (value) stderrChunks.push(value);
				}
			} catch {
				// reader cancelled by teardown — expected
			} finally {
				try {
					reader.releaseLock();
				} catch {
					// already released
				}
			}
		})();

		const initRequest = {
			jsonrpc: "2.0",
			id: 1,
			method: "initialize",
			params: { protocolVersion: 1, clientCapabilities: { auth: { terminal: true } } },
		};
		proc.stdin.write(new TextEncoder().encode(`${JSON.stringify(initRequest)}\n`));
		proc.stdin.flush();

		const firstLine = await readFirstFrame(proc.stdout);
		expect(firstLine[0], `ACP stderr: ${Buffer.concat(stderrChunks).toString("utf8")}`).toBe("{");

		const message = JSON.parse(firstLine) as {
			jsonrpc?: string;
			id?: unknown;
			result?: { protocolVersion?: number; authMethods?: Array<{ type?: string; id?: string }> };
			error?: unknown;
		};
		expect(message.jsonrpc).toBe("2.0");
		expect(message.id).toBe(1);
		expect(message.error).toBeUndefined();
		expect(message.result?.protocolVersion).toBe(1);
		expect(message.result?.authMethods).toEqual(
			expect.arrayContaining([
				expect.objectContaining({ id: "agent" }),
				expect.objectContaining({ type: "terminal", id: "terminal" }),
			]),
		);

		// First frame is good. Tear the child down now so the test body's
		// wall time is bounded by "boot + first frame", not by waiting for
		// stderr or a delayed shutdown. teardown() closes the pipes and kills
		// the throwaway child, which also resolves stderrPump.
		await teardown(proc);
		activeProc = undefined;
		await stderrPump;

		const stderrText = Buffer.concat(stderrChunks).toString("utf8");
		// Guard against JSON-RPC frames sneaking onto stderr. Normal stderr
		// output (warnings, telemetry, etc.) is allowed, but anything that
		// parses as a JSON-RPC envelope on the wrong channel is a misroute.
		for (const line of stderrText.split("\n")) {
			const trimmed = line.trim();
			if (!trimmed.startsWith("{")) continue;
			let parsed: { jsonrpc?: unknown } | undefined;
			try {
				parsed = JSON.parse(trimmed) as { jsonrpc?: unknown };
			} catch {
				continue;
			}
			expect(parsed?.jsonrpc, `JSON-RPC frame leaked to stderr: ${trimmed}`).toBeUndefined();
		}
	}, 60_000);
});

