		expect(executeBashSpy.mock.calls[1]?.[1]?.env).toEqual({ OMP_INJECTED_TOKEN: "injected-value" });
		expect(cachedShellConfig.env).not.toHaveProperty("OMP_INJECTED_TOKEN");
	});

