	it.each([
		["unknown reasoning usage", undefined],
		["partial reasoning usage", 42],
		["reasoning-only usage", 126],
	] as const)(
		"reports capped empty-stop diagnostics without inventing a cause for %s",
		async (_label, reasoningTokens) => {
