	it("preserves Codex commentary when discarding a colliding empty final stop", async () => {
		const timestamp = 1_725_287_000_000;
		vi.spyOn(Date, "now").mockReturnValue(timestamp);
		const commentary = "Codex commentary before the empty final answer.";
		const recovered = "Recovered after the empty final-answer retry.";
		const { session, mock } = await createHarness(
			[{ content: [commentary], stopReason: "stop" }, emptyStop(), { content: [recovered], stopReason: "stop" }],
			{},
			{ provider: "openai-codex", id: "gpt-5.5-codex" },
		);

		await session.prompt("produce commentary");
		await session.waitForIdle();
		// Persisted identity must win regardless of branch enumeration order. The
		// coarse matcher otherwise selects the commentary when it is encountered first.
		const getBranchView = session.sessionManager.getBranchView.bind(session.sessionManager);
		const branchSpy = vi
			.spyOn(session.sessionManager, "getBranchView")
			.mockImplementation(() => getBranchView().slice().reverse());
		await session.followUp("continue after commentary");
		await session.waitForIdle();
		branchSpy.mockRestore();

		const assistantTexts = (messages: AgentMessage[]): string[] =>
			messages
				.filter((message): message is Extract<AgentMessage, { role: "assistant" }> => message.role === "assistant")
				.flatMap(message => message.content.flatMap(block => (block.type === "text" ? [block.text] : [])));

		expect(mock.calls).toHaveLength(3);
		expect(assistantTexts(session.agent.state.messages)).toEqual([commentary, recovered]);
		expect(emptyAssistantStops(session.agent.state.messages)).toHaveLength(0);

		const persistedMessages = session.sessionManager
			.getBranch()
			.filter(entry => entry.type === "message")
			.map(entry => entry.message as AgentMessage);
		expect(assistantTexts(persistedMessages)).toEqual([commentary, recovered]);
		expect(emptyAssistantStops(persistedMessages)).toHaveLength(0);
	});

	it("does not retry normal stop or tool-use turns", async () => {
		const normal = await createHarness([{ content: ["already done"], stopReason: "stop" }]);

		await normal.session.prompt("answer normally");
		await normal.session.waitForIdle();

		expect(normal.mock.calls).toHaveLength(1);
		expect(reminderMessages(normal.session.agent.state.messages)).toHaveLength(0);

		const withTool = await createHarness([
			recordCall("gamma", "call-record-gamma"),
			{ content: ["tool path complete"], stopReason: "stop" },
		]);

		await withTool.session.prompt("record gamma");
		await withTool.session.waitForIdle();

		expect(withTool.mock.calls).toHaveLength(2);
		expect(reminderMessages(withTool.session.agent.state.messages)).toHaveLength(0);
		expect(assistantText(withTool.session.agent.state.messages)).toContain("tool path complete");
	});
});

/**
 * Subscriber event-order contract for `AgentSession`.
 *
 * Extension emits inside the session's event pipeline only await when the
 * event type has registered handlers. For a turn whose provider events all
 * land in one tick (e.g. an instant Anthropic classifier refusal: empty
 * `message_start` + terminal `message_delta` + `message_stop` in a single SSE
 * flush), an event type WITHOUT extension handlers used to overtake an earlier
 * event WITH handlers — the TUI received the assistant `message_end` before
 * its own `message_start`, so no streaming component existed yet and the
 * turn-ending error (pinned banner + inline `Error:` line) was never rendered.
 * The session must deliver events to subscribers in emission order regardless
 * of which event types extensions subscribe to.
 */

import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "bun:test";
import * as path from "node:path";
import { Agent } from "@oh-my-pi/pi-agent-core";
import type { ToolCall } from "@oh-my-pi/pi-ai";
import { createMockModel } from "@oh-my-pi/pi-ai/providers/mock";
import { getBundledModel } from "@oh-my-pi/pi-catalog/models";
import { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import type { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/runner";
import { AgentSession } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import { AuthStorage } from "@oh-my-pi/pi-coding-agent/session/auth-storage";
import { SessionManager } from "@oh-my-pi/pi-coding-agent/session/session-manager";
import { TodoTool } from "@oh-my-pi/pi-coding-agent/tools";
import { TempDir } from "@oh-my-pi/pi-utils";

describe("AgentSession subscriber event order", () => {
	let tempDir: TempDir;
	let authStorage: AuthStorage;
	let modelRegistry: ModelRegistry;
	let session: AgentSession | undefined;

	beforeAll(async () => {
		tempDir = TempDir.createSync("@pi-event-order-");
		authStorage = await AuthStorage.create(path.join(tempDir.path(), "testauth.db"));
		authStorage.keys.setRuntime("anthropic", "anthropic-test-key");
		modelRegistry = new ModelRegistry(authStorage, path.join(tempDir.path(), "models.yml"));
	});

	afterAll(() => {
		authStorage.close();
		tempDir.removeSync();
	});

	afterEach(async () => {
		if (session) {
			await session.dispose();
			session = undefined;
		}
		vi.restoreAllMocks();
	});

	it("delivers message_start before message_end when extension handlers are asymmetric", async () => {
		const model = getBundledModel("anthropic", "claude-sonnet-4-5");
		if (!model) throw new Error("Expected bundled test model to exist");

		// Instant terminal error turn: start and end reach the session pipeline
		// in the same tick, exactly like a real classifier refusal.
		const mock = createMockModel({
			responses: [
				{
					stopReason: "error",
					stopDetails: { type: "refusal", category: "cyber", explanation: "Declined." },
					errorMessage: "Refusal (cyber): Declined.",
				},
			],
		});
		const agent = new Agent({
			getApiKey: agentModel => `${agentModel.provider}-test-key`,
			initialState: {
				model,
				systemPrompt: ["Test"],
				tools: [],
				messages: [],
			},
			streamFn: (streamModel, context, options) => mock.stream(streamModel, context, options),
		});

		// Handlers exist for message_start only, and each emit burns a burst of
		// microtasks — so the handler-less message_end path would skip its
		// extension await and overtake the start without subscriber-order
		// serialization.
		const extensionRunner = {
			emit: vi.fn(async () => {
				for (let hop = 0; hop < 25; hop++) await Promise.resolve();
			}),
			emitBeforeAgentStart: vi.fn().mockResolvedValue(undefined),
			hasHandlers: vi.fn((eventType: string) => eventType === "message_start"),
			emitSessionStop: vi.fn().mockResolvedValue(undefined),
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;

		const settings = Settings.isolated({
			"compaction.enabled": false,
			"retry.baseDelayMs": 5,
			"retry.maxRetries": 1,
			"retry.modelFallback": false,
		});
		settings.setModelRole("default", `${model.provider}/${model.id}`);

		session = new AgentSession({
			agent,
			sessionManager: SessionManager.inMemory(),
			settings,
			modelRegistry,
			extensionRunner,
		});

		const order: string[] = [];
		session.subscribe(event => {
			if (event.type === "message_start" || event.type === "message_end") {
				order.push(`${event.type}:${event.message.role}`);
			}
		});

		await session.prompt("Trigger instant refusal");
		await session.waitForIdle();

		for (const role of ["user", "assistant"]) {
			const startIndex = order.indexOf(`message_start:${role}`);
			const endIndex = order.indexOf(`message_end:${role}`);
			expect(startIndex).toBeGreaterThanOrEqual(0);
			expect(endIndex).toBeGreaterThan(startIndex);
		}
	});

	it("preserves every completion from a batch of exclusive todo calls", async () => {
		const model = getBundledModel("anthropic", "claude-sonnet-4-5");
		if (!model) throw new Error("Expected bundled test model to exist");

		const tasks = ["one", "two", "three", "four", "five", "six"];
		const calls: ToolCall[] = tasks.map((task, index) => ({
			type: "toolCall",
			id: `todo-${index}`,
			name: "todo",
			arguments: { op: "done", task },
		}));
		const mock = createMockModel({
			responses: [{ content: calls }, { content: ["Done"] }],
		});
		const settings = Settings.isolated({
			"compaction.enabled": false,
			"retry.enabled": false,
			"tools.xdev": false,
		});
		settings.setModelRole("default", `${model.provider}/${model.id}`);
		const todo = new TodoTool({
			cwd: tempDir.path(),
			hasUI: false,
			getSessionFile: () => null,
			getSessionSpawns: () => "*",
			settings,
			getTodoPhases: () => session?.getTodoPhases() ?? [],
			setTodoPhases: phases => {
				session?.setTodoPhases(phases);
			},
		});
		const agent = new Agent({
			getApiKey: agentModel => `${agentModel.provider}-test-key`,
			initialState: {
				model,
				systemPrompt: ["Test"],
				tools: [todo],
				messages: [],
			},
			streamFn: (streamModel, context, options) => mock.stream(streamModel, context, options),
		});
		session = new AgentSession({
			agent,
			sessionManager: SessionManager.inMemory(),
			settings,
			modelRegistry,
		});
		session.setTodoPhases([
			{
				name: "Execution",
				tasks: tasks.map((content, index) => ({
					content,
					status: index === 0 ? "in_progress" : "pending",
				})),
			},
		]);

		await session.prompt("Complete every task");
		await session.waitForIdle();
		const toolResults = agent.state.messages.filter(message => message.role === "toolResult");
		expect(toolResults.map(result => result.toolName)).toEqual(tasks.map(() => "todo"));

		expect(session.getTodoPhases()[0]?.tasks.map(task => task.status)).toEqual(tasks.map(() => "completed"));
	});
});

import { afterEach, beforeEach, describe, expect, it, vi } from "bun:test";
import * as fs from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import { Agent } from "@oh-my-pi/pi-agent-core";
import { createMockModel } from "@oh-my-pi/pi-ai/providers/mock";
import { getBundledModel } from "@oh-my-pi/pi-catalog/models";
import { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import type { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions";
import { AgentSession, SessionBusyError } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import { AuthStorage } from "@oh-my-pi/pi-coding-agent/session/auth-storage";
import { SessionManager } from "@oh-my-pi/pi-coding-agent/session/session-manager";
import { removeWithRetries } from "@oh-my-pi/pi-utils";
import { assistantMsg } from "./utilities";

describe("AgentSession.fork(entryId)", () => {
	let tempDir: string;
	let session: AgentSession | undefined;
	let authStorage: AuthStorage | undefined;
	/** Resolves once a prompt reaches the model, which then streams for a minute. */
	let providerStarted: PromiseWithResolvers<void>;

	beforeEach(async () => {
		tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "omp-fork-at-entry-"));
		providerStarted = Promise.withResolvers<void>();
	});

	afterEach(async () => {
		await session?.dispose();
		session = undefined;
		authStorage?.close();
		await removeWithRetries(tempDir);
		vi.restoreAllMocks();
	});

	/** A persisted session seeded with [user, assistant(artifact://<id>), user, assistant]; returns the assistant entry to fork at. */
	async function createSeededSession(extensionRunner?: ExtensionRunner) {
		const agent = new Agent({
			getApiKey: () => "test-key",
			initialState: { model: getBundledModel("anthropic", "claude-sonnet-4-5")!, systemPrompt: ["Test"], tools: [] },
			streamFn: createMockModel({
				handler: () => {
					providerStarted.resolve();
					return { content: ["slow reply"], delayMs: 60_000 };
				},
			}).stream,
		});
		authStorage = await AuthStorage.create(":memory:");
		authStorage.keys.setRuntime("anthropic", "test-key");
		session = new AgentSession({
			agent,
			sessionManager: SessionManager.create(tempDir, path.join(tempDir, "sessions")),
			settings: Settings.isolated({ "compaction.enabled": false }),
			modelRegistry: new ModelRegistry(authStorage, path.join(tempDir, "models.yml")),
			extensionRunner,
		});
		const manager = session.sessionManager;
		const artifactId = await manager.saveArtifact("kept tool output", "bash");
		if (artifactId === undefined) throw new Error("Expected a persisted artifact");
		manager.appendMessage({ role: "user", content: "first", timestamp: Date.now() });
		const forkAt = manager.appendMessage(assistantMsg(`Full output: artifact://${artifactId}`));
		manager.appendMessage({ role: "user", content: "second", timestamp: Date.now() });
		manager.appendMessage(assistantMsg("second reply"));
		session.agent.replaceMessages(manager.buildSessionContext().messages);
		await manager.flush();
		return { session, artifactId, forkAt };
	}

	/** Starts user eval work on `target` that, like a real eval run, settles once `controller` aborts it. */
	function startUserEval(target: AgentSession, controller: AbortController): void {
		const run = Promise.withResolvers<void>();
		controller.signal.addEventListener("abort", () => run.resolve(), { once: true });
		void target.trackEvalExecution(run.promise, controller);
	}

	it("keeps cited artifacts resolvable and allocates fresh ids after the cut", async () => {
		const { session, artifactId, forkAt } = await createSeededSession();
		const sourceFile = session.sessionFile;

		expect(await session.fork(forkAt)).toBe(true);

		expect(session.sessionFile).not.toBe(sourceFile);
		const keptPath = await session.sessionManager.getArtifactPath(artifactId);
		expect(keptPath).not.toBeNull();
		expect(await Bun.file(keptPath!).text()).toBe("kept tool output");
		const newId = await session.sessionManager.saveArtifact("fork output", "bash");
		expect(newId).not.toBe(artifactId);
		expect(await Bun.file(keptPath!).text()).toBe("kept tool output");
	});

	it("leaves the session file and live messages untouched when session_before_branch vetoes", async () => {
		const emit = vi.fn(async (event: { type: string }) =>
			event.type === "session_before_branch" ? { cancel: true } : undefined,
		);
		const extensionRunner = {
			hasHandlers: (eventType: string) => eventType === "session_before_branch",
			emit,
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;
		const { session, forkAt } = await createSeededSession(extensionRunner);
		const sourceFile = session.sessionFile!;
		const sourceRaw = await Bun.file(sourceFile).text();
		const sourceMessages = structuredClone(session.messages);

		expect(await session.fork(forkAt)).toBe(false);

		expect(emit).toHaveBeenCalledWith({ type: "session_before_branch", reason: "fork", entryId: forkAt });
		expect(session.sessionFile).toBe(sourceFile);
		expect(session.messages).toEqual(sourceMessages);
		expect(await Bun.file(sourceFile).text()).toBe(sourceRaw);
		expect((await fs.readdir(path.dirname(sourceFile))).filter(name => name.endsWith(".jsonl"))).toEqual([
			path.basename(sourceFile),
		]);
	});

	it("refuses while a turn is streaming and keeps the session in place", async () => {
		const { session, forkAt } = await createSeededSession();
		const sourceFile = session.sessionFile;
		const turn = session.prompt("third");
		await providerStarted.promise;

		await expect(session.fork(forkAt)).rejects.toBeInstanceOf(SessionBusyError);
		expect(session.sessionFile).toBe(sourceFile);

		await session.abort({ goalReason: "internal", reason: "test cleanup" });
		await turn;
	});

	it("refuses when user work starts while session_before_branch awaits", async () => {
		// The hook admits user eval work, which keeps running after the hook returns.
		const userEval = new AbortController();
		const extensionRunner = {
			hasHandlers: (eventType: string) => eventType === "session_before_branch",
			emit: async () => {
				startUserEval(session!, userEval);
				return undefined;
			},
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;
		const { session: seeded, forkAt } = await createSeededSession(extensionRunner);
		const sourceFile = seeded.sessionFile!;
		expect(seeded.isBusyForSnapshot).toBe(false);

		await expect(seeded.fork(forkAt)).rejects.toBeInstanceOf(SessionBusyError);

		expect(seeded.sessionFile).toBe(sourceFile);
		expect((await fs.readdir(path.dirname(sourceFile))).filter(name => name.endsWith(".jsonl"))).toEqual([
			path.basename(sourceFile),
		]);
		userEval.abort();
	});

	it("refuses when user work starts while the pre-cut flush awaits, keeping the old session's state", async () => {
		const { session: seeded, forkAt } = await createSeededSession();
		const sourceFile = seeded.sessionFile!;
		// A running auto-learn capture is old-session state the transition would abort.
		const capture = Promise.withResolvers<void>();
		let captureSignal: AbortSignal | undefined;
		const captureRun = seeded.runAutolearnCapture(async signal => {
			captureSignal = signal;
			await capture.promise;
		});
		const userEval = new AbortController();
		const flush = seeded.sessionManager.flush.bind(seeded.sessionManager);
		vi.spyOn(seeded.sessionManager, "flush").mockImplementation(async () => {
			startUserEval(seeded, userEval);
			await flush();
		});
		expect(seeded.isBusyForSnapshot).toBe(false);

		await expect(seeded.fork(forkAt)).rejects.toBeInstanceOf(SessionBusyError);

		expect(seeded.sessionFile).toBe(sourceFile);
		expect(captureSignal?.aborted).toBe(false);
		expect((await fs.readdir(path.dirname(sourceFile))).filter(name => name.endsWith(".jsonl"))).toEqual([
			path.basename(sourceFile),
		]);
		userEval.abort();
		capture.resolve();
		await captureRun;
	});

	it("refuses a whole-session fork that requires idle when user work starts while the flush awaits", async () => {
		const { session: seeded } = await createSeededSession();
		const sourceFile = seeded.sessionFile!;
		const userEval = new AbortController();
		const flush = seeded.sessionManager.flush.bind(seeded.sessionManager);
		vi.spyOn(seeded.sessionManager, "flush").mockImplementation(async () => {
			startUserEval(seeded, userEval);
			await flush();
		});

		await expect(seeded.fork(undefined, { requireIdle: true })).rejects.toBeInstanceOf(SessionBusyError);

		expect(seeded.sessionFile).toBe(sourceFile);
		expect((await fs.readdir(path.dirname(sourceFile))).filter(name => name.endsWith(".jsonl"))).toEqual([
			path.basename(sourceFile),
		]);
		userEval.abort();
	});

	it.each([
		["the assistant tool-call message", "batch"],
		["a mid-batch tool result", "firstResult"],
	] as const)("extends a cut at %s through the batch's recorded results", async (_label, cutAt) => {
		const emit = vi.fn(async (_event: { type: string }) => undefined);
		const extensionRunner = {
			hasHandlers: (eventType: string) => eventType === "session_before_branch",
			emit,
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;
		const { session } = await createSeededSession(extensionRunner);
		const manager = session.sessionManager;
		const toolResult = (toolCallId: string) => ({
			role: "toolResult" as const,
			toolCallId,
			toolName: "read",
			content: [{ type: "text" as const, text: `result ${toolCallId}` }],
			isError: false,
			timestamp: Date.now(),
		});
		const ids = {
			batch: manager.appendMessage({
				...assistantMsg("reading"),
				content: [
					{ type: "toolCall", id: "call-a", name: "read", arguments: { path: "a" } },
					{ type: "toolCall", id: "call-b", name: "read", arguments: { path: "b" } },
				],
				stopReason: "toolUse",
			}),
			firstResult: manager.appendMessage(toolResult("call-a")),
		};
		// A label between results is a non-message entry the cut steps over.
		manager.appendLabelChange(ids.firstResult, "checked");
		const lastResult = manager.appendMessage(toolResult("call-b"));
		manager.appendMessage({ role: "user", content: "after the batch", timestamp: Date.now() });
		session.agent.replaceMessages(manager.buildSessionContext().messages);

		expect(await session.fork(ids[cutAt])).toBe(true);

		const kept = session.sessionManager.getBranch().filter(entry => entry.type === "message");
		expect(kept.at(-1)?.id).toBe(lastResult);
		expect(session.messages.at(-1)).toMatchObject({ role: "toolResult", toolCallId: "call-b" });
		expect(emit).toHaveBeenCalledWith({ type: "session_before_branch", reason: "fork", entryId: lastResult });
	});
});

