	it("keeps the frame archive out of the auto_compaction_end event after persisting it", async () => {
		const branchEntries = sessionManager.getBranch();
		const lastEntry = branchEntries[branchEntries.length - 1];
		if (!lastEntry?.id) throw new Error("Expected branch entry with id");
		// A zero-frame archive clears the payload/projection gates on the auto
		// path while still carrying PRESERVE_KEY, so the strip is what removes it.
		const archive = { frames: [], totalChars: 1000, truncatedChars: 0 };
		vi.spyOn(snapcompact, "compact").mockResolvedValue({
			summary: "stubbed snapcompact",
			shortSummary: "stub",
			firstKeptEntryId: lastEntry.id,
			tokensBefore: 100_000,
			details: { readFiles: [], modifiedFiles: [] },
			preserveData: {
				extensionState: "keep-me",
				[snapcompact.PRESERVE_KEY]: archive,
			},
		});
		const events: AgentSessionEvent[] = [];
		session.subscribe(event => events.push(event));

		await session.runIdleCompaction();

		const endEvent = events.find(
			(event): event is Extract<AgentSessionEvent, { type: "auto_compaction_end" }> =>
				event.type === "auto_compaction_end" && event.result !== undefined,
		);
		if (!endEvent?.result) throw new Error("Expected a result-carrying auto_compaction_end event");
		expect(endEvent.result.preserveData).toEqual({ extensionState: "keep-me" });
		const compactionEntry = sessionManager.getEntries().find(entry => entry.type === "compaction");
		if (compactionEntry?.type !== "compaction") throw new Error("Expected persisted compaction entry");
		expect(compactionEntry.preserveData).toEqual({
			extensionState: "keep-me",
			[snapcompact.PRESERVE_KEY]: archive,
		});
	});

	it.each([
		// Gemini 3 bills a fixed 1,120 per image at any size.
		{ name: "Gemini", provider: "google", id: "gemini-3.1-pro-preview", frameSize: 2048, frameTokens: () => 1120 },
		// GPT bills 32px patches × 1.2 over the frame's real height (the last frame hugs its rows).
		{
			name: "Codex",
			provider: "openai-codex",
			id: "gpt-6.1-sol",
			frameSize: 1568,
			frameTokens: (height: number) => Math.ceil(49 * Math.ceil(height / 32) * 1.2),
		},
	] as const)(
		"persists the trigger's post-commit count as tokensAfter for a real $name archive",
		async ({ provider, id, frameSize, frameTokens }) => {
			const bundled = getBundledModel(provider, id);
			if (!bundled) throw new Error(`Expected bundled ${provider}/${id}`);
			const model = { ...bundled, contextWindow: 400_000, maxTokens: 32_000 };
			expect(snapcompact.resolveShape(model).frameSize).toBe(frameSize);
			session.agent.setModel(model);

			await session.compact(undefined, { mode: "snapcompact" });

			const entry = sessionManager.getBranch().findLast(e => e.type === "compaction");
			if (entry?.type !== "compaction") throw new Error("Expected a committed compaction entry");
			const frames = snapcompact.getPreservedArchive(entry.preserveData)?.frames ?? [];
			expect(frames.length).toBeGreaterThan(1);
			const summary = session.messages.find(m => m.role === "compactionSummary");
			if (summary?.role !== "compactionSummary") throw new Error("Expected a compaction summary message");
			const blocks = summary.blocks ?? [];
			expect(blocks.filter(block => block.type === "image")).toHaveLength(frames.length);
			const tokenizer = session.agent.tokenizer;
			const textOnly = { ...summary, blocks: blocks.filter(block => block.type === "text") };
			let expectedFrameTokens = 0;
			for (const frame of frames) {
				const size = base64ImageSize(frame.data);
				if (size?.width !== frameSize) throw new Error(`Expected a ${frameSize}px-wide frame`);
				expectedFrameTokens += frameTokens(size.height);
			}
			expect(tokenizer.countMessage(summary) - tokenizer.countMessage(textOnly)).toBe(expectedFrameTokens);
			expect(entry.tokensAfter).toBe(
				computeNonMessageTokens(session, tokenizer, session.settings.revision) +
					tokenizer.countMessages(session.messages, { excludeEncryptedReasoning: true }),
			);
		},
	);
});

import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "bun:test";
import { Agent } from "@oh-my-pi/pi-agent-core";
import type { Model } from "@oh-my-pi/pi-ai";
import { getBundledModel } from "@oh-my-pi/pi-catalog/models";
import { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import type { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions";
import { AgentSession } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import { AuthStorage } from "@oh-my-pi/pi-coding-agent/session/auth-storage";
import type { BuildSessionContextOptions, SessionContext } from "@oh-my-pi/pi-coding-agent/session/session-context";
import { SessionManager } from "@oh-my-pi/pi-coding-agent/session/session-manager";
import { TempDir } from "@oh-my-pi/pi-utils";

/**
 * Regression for issue #3846: in-TUI `/resume` rebuilt the *previous*
 * session's display context before switching files. That call expands persisted
 * snapcompact archives and `openaiRemoteCompaction.replacementHistory` payloads
 * into messages, which can OOM on huge pre-fix sessions even though the loader
 * itself streams. The previous context is only needed for same-session reloads
 * (where `#didSessionMessagesChange` compares against the freshly rebuilt one);
 * different-session switches MUST skip that work.
 */
describe("AgentSession.switchSession previous-context build", () => {
	let authStorage: AuthStorage;
	let modelRegistry: ModelRegistry;
	let model: Model;
	const tempDirs: TempDir[] = [];
	const sessions: AgentSession[] = [];

	beforeAll(async () => {
		authStorage = await AuthStorage.create(":memory:");
		authStorage.keys.setRuntime("anthropic", "test-key");
		modelRegistry = new ModelRegistry(authStorage);
		const bundled = getBundledModel("anthropic", "claude-sonnet-4-5");
		if (!bundled) throw new Error("Expected built-in anthropic model to exist");
		model = bundled;
	});

	afterAll(() => {
		authStorage.close();
	});

	afterEach(async () => {
		while (sessions.length > 0) {
			await sessions.pop()?.dispose();
		}
		for (const dir of tempDirs.splice(0)) {
			try {
				await dir.remove();
			} catch {}
		}
	});

	function buildSession(
		tempDir: TempDir,
		extensionRunner?: ExtensionRunner,
	): { session: AgentSession; sessionManager: SessionManager } {
		const sessionManager = SessionManager.create(tempDir.path(), tempDir.path());
		const agent = new Agent({
			initialState: {
				model,
				systemPrompt: ["Test"],
				tools: [],
				messages: [],
			},
		});
		const session = new AgentSession({
			agent,
			sessionManager,
			settings: Settings.isolated({ "compaction.enabled": false }),
			modelRegistry,
			extensionRunner,
		});
		sessions.push(session);
		return { session, sessionManager };
	}

	/** Wrap `sessionManager.buildSessionContext` so each call's caller-visible
	 *  state (the manager's currently-loaded session file) is recorded in
	 *  invocation order. The constructor itself calls `buildSessionContext`
	 *  once; spying *after* construction means only switchSession-driven calls
	 *  are observed. */
	function instrumentBuildSessionContext(sessionManager: SessionManager): {
		calls: Array<{ sessionFile: string | undefined; transcript: boolean | undefined }>;
		restore: () => void;
	} {
		const calls: Array<{ sessionFile: string | undefined; transcript: boolean | undefined }> = [];
		const original = sessionManager.buildSessionContext.bind(sessionManager);
		const patched = (options?: BuildSessionContextOptions): SessionContext => {
			calls.push({ sessionFile: sessionManager.getSessionFile(), transcript: options?.transcript });
			return original(options);
		};
		sessionManager.buildSessionContext = patched as SessionManager["buildSessionContext"];
		return {
			calls,
			restore: () => {
				sessionManager.buildSessionContext = original;
			},
		};
	}

	it("skips building the previous display context when switching to a different session", async () => {
		const tempDir = TempDir.createSync("@pi-switch-prev-ctx-different-");
		tempDirs.push(tempDir);

		const { session, sessionManager } = buildSession(tempDir);
		sessionManager.appendMessage({ role: "user", content: "previous", timestamp: 1 });
		await sessionManager.flush();
		const previousSessionFile = sessionManager.getSessionFile();
		expect(previousSessionFile).toBeString();

		const otherManager = SessionManager.create(tempDir.path(), tempDir.path());
		otherManager.appendMessage({ role: "user", content: "target", timestamp: 2 });
		await otherManager.flush();
		const targetSessionFile = otherManager.getSessionFile();
		expect(targetSessionFile).toBeString();
		expect(targetSessionFile).not.toBe(previousSessionFile);
		await otherManager.close();

		const { calls, restore } = instrumentBuildSessionContext(sessionManager);
		try {
			const switched = await session.switchSession(targetSessionFile!);
			expect(switched).toBe(true);
			expect(session.sessionFile).toBe(targetSessionFile);
		} finally {
			restore();
		}

		// The previous session's display context MUST NOT be materialized. Only
		// the new target context (post-`setSessionFile`) should be built.
		expect(calls).toEqual([{ sessionFile: targetSessionFile!, transcript: undefined }]);
	});

	it("builds the previous display context for same-session reloads", async () => {
		const tempDir = TempDir.createSync("@pi-switch-prev-ctx-reload-");
		tempDirs.push(tempDir);

		const { session, sessionManager } = buildSession(tempDir);
		sessionManager.appendMessage({ role: "user", content: "current", timestamp: 1 });
		await sessionManager.flush();
		const sessionFile = sessionManager.getSessionFile();
		expect(sessionFile).toBeString();

		const { calls, restore } = instrumentBuildSessionContext(sessionManager);
		try {
			const switched = await session.switchSession(sessionFile!);
			expect(switched).toBe(true);
			expect(session.sessionFile).toBe(sessionFile);
		} finally {
			restore();
		}

		// Same-session reload must snapshot the pre-reload context so
		// `#didSessionMessagesChange` can detect rollback edits.
		expect(calls).toEqual([
			{ sessionFile: sessionFile!, transcript: undefined },
			{ sessionFile: sessionFile!, transcript: undefined },
		]);
	});

	it("restores the previous session when cwd adoption is rejected", async () => {
		const sourceDir = TempDir.createSync("@pi-switch-cwd-source-");
		const targetDir = TempDir.createSync("@pi-switch-cwd-target-");
		tempDirs.push(sourceDir, targetDir);

		const { session, sessionManager } = buildSession(sourceDir);
		sessionManager.appendMessage({ role: "user", content: "source", timestamp: 1 });
		await sessionManager.flush();
		const previousSessionFile = sessionManager.getSessionFile();
		const targetManager = SessionManager.create(targetDir.path(), targetDir.path());
		targetManager.appendMessage({ role: "user", content: "target", timestamp: 2 });
		await targetManager.ensureOnDisk();
		await targetManager.flush();
		const targetSessionFile = targetManager.getSessionFile();
		await targetManager.close();
		expect(previousSessionFile).toBeString();
		expect(targetSessionFile).toBeString();

		const onCwdChange = vi.fn(async () => false);
		const switched = await session.switchSession(targetSessionFile!, { onCwdChange });

		expect(switched).toBe(false);
		expect(onCwdChange).toHaveBeenCalledWith(targetDir.path(), sourceDir.path());
		expect(sessionManager.getSessionFile()).toBe(previousSessionFile);
		expect(sessionManager.getCwd()).toBe(sourceDir.path());
	});
	it("rejects callback-free switches across project directories", async () => {
		const sourceDir = TempDir.createSync("@pi-switch-no-callback-source-");
		const targetDir = TempDir.createSync("@pi-switch-no-callback-target-");
		tempDirs.push(sourceDir, targetDir);

		const { session, sessionManager } = buildSession(sourceDir);
		sessionManager.appendMessage({ role: "user", content: "source", timestamp: 1 });
		await sessionManager.flush();
		const previousSessionFile = sessionManager.getSessionFile();

		const targetManager = SessionManager.create(targetDir.path(), targetDir.path());
		targetManager.appendMessage({ role: "user", content: "target", timestamp: 2 });
		await targetManager.ensureOnDisk();
		await targetManager.flush();
		const targetSessionFile = targetManager.getSessionFile();
		await targetManager.close();

		const switched = await session.switchSession(targetSessionFile!);

		expect(switched).toBe(false);
		expect(sessionManager.getSessionFile()).toBe(previousSessionFile);
		expect(sessionManager.getCwd()).toBe(sourceDir.path());
	});
	it("adopts a foreign replica without changing the local cwd", async () => {
		const sourceDir = TempDir.createSync("@pi-switch-collab-source-");
		const targetDir = TempDir.createSync("@pi-switch-collab-target-");
		const extraDir = TempDir.createSync("@pi-switch-collab-extra-");
		tempDirs.push(sourceDir, targetDir, extraDir);

		const { session, sessionManager } = buildSession(sourceDir);
		sessionManager.appendMessage({ role: "user", content: "source", timestamp: 1 });
		await sessionManager.flush();
		const targetManager = SessionManager.create(targetDir.path(), targetDir.path());
		targetManager.appendMessage({ role: "user", content: "host snapshot", timestamp: 2 });
		await targetManager.ensureOnDisk();
		await targetManager.flush();
		const targetSessionFile = targetManager.getSessionFile();
		await targetManager.close();
		expect(targetSessionFile).toBeString();

		const processCwd = process.cwd();
		const onCwdChange = vi.fn(async () => {
			throw new Error("collab must not invoke cwd callback");
		});
		const switched = await session.switchSession(targetSessionFile!, {
			preserveLocalCwd: true,
			onCwdChange,
		});

		expect(switched).toBe(true);
		expect(onCwdChange).not.toHaveBeenCalled();
		expect(process.cwd()).toBe(processCwd);
		expect(sessionManager.getSessionFile()).toBe(targetSessionFile);
		expect(sessionManager.getCwd()).toBe(sourceDir.path());
		expect(sessionManager.getRecordedCwd()).toBe(targetDir.path());
		await sessionManager.addWorkspaceDirectory(extraDir.path());
		expect(await Bun.file(targetSessionFile!).text()).not.toContain(extraDir.path());
	});

	it("fails closed when cwd rollback throws after changing it", async () => {
		const sourceDir = TempDir.createSync("@pi-switch-cwd-error-source-");
		const targetDir = TempDir.createSync("@pi-switch-cwd-error-target-");
		tempDirs.push(sourceDir, targetDir);

		const { session, sessionManager } = buildSession(sourceDir);
		const targetManager = SessionManager.create(targetDir.path(), targetDir.path());
		targetManager.appendMessage({ role: "user", content: "target", timestamp: 2 });
		await targetManager.ensureOnDisk();
		await targetManager.flush();
		const targetSessionFile = targetManager.getSessionFile();
		await targetManager.close();
		expect(targetSessionFile).toBeString();

		let actualCwd = sourceDir.path();
		let callbackCount = 0;
		const onCwdChange = vi.fn(async (newCwd: string, _previousCwd: string) => {
			actualCwd = newCwd;
			const call = callbackCount++;
			if (call === 0) throw new Error("settings reload failed");
			if (call === 1) throw new Error("cwd restore denied");
			return true;
		});

		await expect(session.switchSession(targetSessionFile!, { onCwdChange })).rejects.toThrow(
			/settings reload failed.*cwd restore denied.*process may remain in/,
		);

		expect(actualCwd).toBe(sourceDir.path());
		expect(onCwdChange).toHaveBeenCalledTimes(2);
		expect(onCwdChange).toHaveBeenNthCalledWith(2, sourceDir.path(), targetDir.path());
		expect(sessionManager.getCwd()).toBe(sourceDir.path());
		expect(session.isDisposed).toBe(true);
	});
	it("rejects reload when the session-before-switch hook cancels", async () => {
		const tempDir = TempDir.createSync("@pi-switch-reload-cancel-");
		tempDirs.push(tempDir);

		const emit = vi.fn(async () => ({ cancel: true }));
		const extensionRunner = {
			hasHandlers: (eventType: string) => eventType === "session_before_switch",
			emit,
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;
		const { session, sessionManager } = buildSession(tempDir, extensionRunner);
		sessionManager.appendMessage({ role: "user", content: "current", timestamp: 1 });
		await sessionManager.flush();
		const sessionFile = session.sessionFile;
		expect(sessionFile).toBeString();

		await expect(session.reload()).rejects.toThrow("Session reload cancelled");
		expect(emit).toHaveBeenCalledWith(
			expect.objectContaining({ type: "session_before_switch", targetSessionFile: sessionFile }),
		);
	});
});

import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "bun:test";
import { Agent } from "@oh-my-pi/pi-agent-core";
import type { AssistantMessage } from "@oh-my-pi/pi-ai";
import { getBundledModel } from "@oh-my-pi/pi-catalog/models";
import { AsyncJobManager } from "@oh-my-pi/pi-coding-agent/async";
import { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import type { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions";
import type { ExtensionEvent } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/types";
import type { AgentEndEvent } from "@oh-my-pi/pi-coding-agent/extensibility/shared-events";
import { AgentSession, type AgentSessionEvent } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import { SessionManager } from "@oh-my-pi/pi-coding-agent/session/session-manager";
import { TodoTool, type ToolSession } from "@oh-my-pi/pi-coding-agent/tools";
import { TempDir } from "@oh-my-pi/pi-utils";
import { createInMemoryAuthStorage } from "./helpers/agent-session-setup";

/**
 * Regression coverage for the `#hasPendingAsyncWake()` gate shared by the
 * stop-time passes in the `agent_end` settle path: a background async job
 * (bash/task) owned by this agent re-wakes the loop when it completes — its
 * result delivery enqueues an async-result follow-up that continues the run,
 * and the stop-time passes re-run at that settle. A text-only stop with such a
 * job in flight is a scheduling pause, not a terminal stop, so both:
 *
 * - the todo reminder (`todo_reminder` event + injected `<system-reminder>`
 *   continuation in `#checkTodoCompletion`), and
 * - the `session_stop` extension hook pass (`#emitSessionStopEvent`)
 *
 * must stay silent and defer to the settle reached once the session is fully
 * idle.
 *
 * The contract these tests defend:
 * 1. A running job owned by this session's `agentId` (delivery not
 *    suppressed) defers the reminder: no `todo_reminder` event, no scheduled
 *    `agent.continue`.
 * 2. Jobs owned by a DIFFERENT agent do not defer — the stop still fires
 *    reminder attempt 1.
 * 3. The deferral is temporary: once the owned job completes and its delivery
 *    drains, the next text-only stop fires the reminder.
 * 4. With no incomplete todos at all, the same running owned job still defers
 *    the `session_stop` hook pass.
 * 5. That deferral lifts too: after the job completes and its delivery
 *    drains, the next stop invokes `session_stop` exactly once.
 *
 * Negative assertions rely on `session.waitForIdle()` being deterministic
 * here: the agent's synchronous `#emit` invokes the session's `agent_end`
 * handler, which registers itself as a tracked post-prompt task BEFORE its
 * first await, and anything it schedules (e.g. `agent.continue`) is tracked
 * the same way — so once `waitForIdle()` resolves, the settle has definitively
 * decided whether to fire the stop-time passes. No wall-clock sleeps needed.
 */
const sharedAuthStorage = createInMemoryAuthStorage();
sharedAuthStorage.keys.setRuntime("anthropic", "test-key");
const sharedModelRegistry = new ModelRegistry(sharedAuthStorage);

afterAll(() => {
	sharedAuthStorage.close();
});

describe("AgentSession todo reminder async-job deferral", () => {
	let tempDir: TempDir;
	let session: AgentSession;
	let sessionManager: SessionManager;
	let manager: AsyncJobManager;
	let extensionRunner: ExtensionRunner;
	let extensionEnds: AgentEndEvent[];
	let gates: Array<PromiseWithResolvers<string>>;
	let reminderAttempts: number[];
	let agentEndTerminalStates: Array<boolean | undefined>;
	let agentEndAwaitingAsyncWork: Array<boolean | undefined>;

	function textOnlyAssistantMessage(): AssistantMessage {
		return {
			role: "assistant",
			content: [{ type: "text", text: "paused at your instruction" }],
			api: "anthropic-messages",
			provider: "anthropic",
			model: "claude-sonnet-4-5",
			stopReason: "stop",
			usage: {
				input: 100,
				output: 20,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 120,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
			timestamp: Date.now(),
		};
	}

	function emitTextOnlyStop(): void {
		const msg = textOnlyAssistantMessage();
		session.agent.emitExternalEvent({ type: "message_end", message: msg });
		session.agent.emitExternalEvent({ type: "agent_end", messages: [msg] });
	}

	/** Register a job that stays running until the returned resolver fires. */
	function registerGatedJob(ownerId: string): { resolve: () => void } {
		const gate = Promise.withResolvers<string>();
		gates.push(gate);
		manager.register("bash", `gated job owned by ${ownerId}`, async () => await gate.promise, { ownerId });
		return { resolve: () => gate.resolve("done") };
	}

	/** Give the session incomplete todos so the stop-time reminder is armed. */
	function setIncompleteTodos(): void {
		session.setTodoPhases([
			{
				name: "Pending review",
				tasks: [
					{ content: "Slice 81", status: "pending" },
					{ content: "Slice 82", status: "pending" },
				],
			},
		]);
	}

	beforeEach(() => {
		tempDir = TempDir.createSync("@pi-todo-reminder-async-jobs-");
		sessionManager = SessionManager.inMemory(tempDir.path());
		manager = new AsyncJobManager({});
		gates = [];
		extensionEnds = [];
		extensionRunner = {
			emit: vi.fn(async (event: ExtensionEvent) => {
				if (event.type === "agent_end") extensionEnds.push(event);
			}),
			emitBeforeAgentStart: vi.fn().mockResolvedValue(undefined),
			hasHandlers: vi.fn((eventType: string) => eventType === "session_stop"),
			emitSessionStop: vi.fn().mockResolvedValue(undefined),
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;

		const model = getBundledModel("anthropic", "claude-sonnet-4-5");
		if (!model) throw new Error("Expected built-in anthropic model to exist");

		const settings = Settings.isolated({
			"compaction.enabled": false,
			"todo.enabled": true,
			"todo.reminders": true,
			"todo.remindersMax": 3,
		});
		const toolSession: ToolSession = {
			cwd: tempDir.path(),
			hasUI: false,
			getSessionFile: () => sessionManager.getSessionFile() ?? null,
			getSessionSpawns: () => "*",
			settings,
		};

		const agent = new Agent({
			initialState: {
				model,
				systemPrompt: ["Test"],
				tools: [new TodoTool(toolSession)],
				messages: [],
			},
		});

		session = new AgentSession({
			agent,
			sessionManager,
			settings,
			modelRegistry: sharedModelRegistry,
			agentId: "Main",
			asyncJobManager: manager,
			extensionRunner,
		});
		// Override the session's self-registered sink with a no-op: these tests
		// exercise the async-wake deferral gates, not result injection.
		manager.registerDeliverySink("Main", () => {});

		reminderAttempts = [];
		agentEndTerminalStates = [];
		agentEndAwaitingAsyncWork = [];
		session.subscribe((event: AgentSessionEvent) => {
			if (event.type === "todo_reminder") reminderAttempts.push(event.attempt);
			if (event.type === "agent_end") {
				agentEndTerminalStates.push(event.isTerminal);
				agentEndAwaitingAsyncWork.push(event.awaitingAsyncWork);
			}
		});
	});

	afterEach(async () => {
		// Unblock any still-gated job body so the manager can settle promptly.
		for (const gate of gates) gate.resolve("done");
		await session.dispose();
		manager.cancelAll();
		await manager.dispose();
		try {
			await tempDir.remove();
		} catch {}
		vi.restoreAllMocks();
	});

	it("defers the reminder while an owned async job is running", async () => {
		setIncompleteTodos();
		const continueSpy = vi.spyOn(session.agent, "continue").mockResolvedValue();
		registerGatedJob("Main");

		emitTextOnlyStop();
		await session.waitForIdle();

		expect(reminderAttempts).toEqual([]);
		expect(continueSpy).not.toHaveBeenCalled();
		expect(agentEndTerminalStates).toEqual([false]);
		// Only a background result can resume this pause, so the event says so.
		expect(agentEndAwaitingAsyncWork).toEqual([true]);
		expect(extensionEnds).toEqual([expect.objectContaining({ willContinue: true, awaitingAsyncWork: true })]);
	});

	it("does not defer for a running job owned by a different agent", async () => {
		setIncompleteTodos();
		vi.spyOn(session.agent, "continue").mockResolvedValue();
		registerGatedJob("OtherAgent");

		emitTextOnlyStop();
		await session.waitForIdle();

		expect(reminderAttempts).toEqual([1]);
		// The reminder is the agent's own continuation, not an async wait.
		expect(agentEndAwaitingAsyncWork).toEqual([undefined]);
		expect(extensionEnds).toHaveLength(1);
		expect(extensionEnds[0]?.willContinue).toBe(true);
		expect(extensionEnds[0]).not.toHaveProperty("awaitingAsyncWork");
	});

	it("fires the reminder on the next stop once the owned job completes and its delivery drains", async () => {
		setIncompleteTodos();
		vi.spyOn(session.agent, "continue").mockResolvedValue();
		const job = registerGatedJob("Main");

		// While the job runs, the stop stays silent.
		emitTextOnlyStop();
		await session.waitForIdle();
		expect(reminderAttempts).toEqual([]);

		// Complete the job and drain its result delivery — nothing is left to
		// re-wake the loop, so the deferral must lift.
		job.resolve();
		await manager.waitForAll();
		await manager.drainDeliveries();

		emitTextOnlyStop();
		await session.waitForIdle();

		expect(reminderAttempts).toEqual([1]);
	});

	it("defers the session_stop hook pass while an owned async job is running", async () => {
		// No todo phases: the stop reaches the session_stop pass directly, and
		// only the async-wake gate can defer it.
		vi.spyOn(session.agent, "continue").mockResolvedValue();
		registerGatedJob("Main");

		emitTextOnlyStop();
		await session.waitForIdle();

		expect(extensionRunner.emitSessionStop).not.toHaveBeenCalled();
	});

	it("invokes session_stop exactly once on the next stop after the owned job drains", async () => {
		vi.spyOn(session.agent, "continue").mockResolvedValue();
		const job = registerGatedJob("Main");

		// Deferred while the job is in flight.
		emitTextOnlyStop();
		await session.waitForIdle();
		expect(extensionRunner.emitSessionStop).not.toHaveBeenCalled();

		job.resolve();
		await manager.waitForAll();
		await manager.drainDeliveries();

		emitTextOnlyStop();
		await session.waitForIdle();

		expect(extensionRunner.emitSessionStop).toHaveBeenCalledTimes(1);
	});
});

import { afterEach, describe, expect, it, vi } from "bun:test";
