const guestCleanups: (() => void)[] = [];
let replicaRoot: string | undefined;
beforeEach(async () => {
	replicaRoot = await fs.mkdtemp(path.join(os.tmpdir(), "omp-collab-replica-"));
	vi.spyOn(utils, "getConfigRootDir").mockReturnValue(replicaRoot);
});
afterEach(async () => {
