		check.close();

		expect(result.archive?.archived).toBe(1);
		expect(result.archive?.statsRowsDeleted).toBe(7);
		expect(result.archive?.errors).toEqual([]);
		expect(messages).toEqual([{ session_file: child, entry_id: "shared-assistant" }]);
