		// `read` is a built-in; `my_ext_tool` is registered without being marked
		// built-in, so it must classify as an extension-sourced tool.
		const toolRegistry = new Map<string, AgentTool>([
			[read.name, read],
			[custom.name, custom],
		]);
		const session = new AgentSession({
