import * as persistedRoster from "@oh-my-pi/pi-coding-agent/registry/persisted-agents";
import type { AgentSession } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import { INTERRUPTED_TURN_ERROR } from "@oh-my-pi/pi-coding-agent/session/exit-diagnostics";
import { resolveSessionLeafId, type SessionEntry } from "@oh-my-pi/pi-coding-agent/session/session-entries";
import * as subSessions from "@oh-my-pi/pi-coding-agent/session/sub-sessions";
import type { SubSession } from "@oh-my-pi/pi-coding-agent/session/sub-sessions";
import * as executor from "@oh-my-pi/pi-coding-agent/task/executor";
import { restoreSession } from "@oh-my-pi/pi-coding-agent/task/restore";
import type { SingleResult } from "@oh-my-pi/pi-tui/tools/task";
import { createAssistantMessage } from "../helpers/agent-session-setup";

const mainFile = path.resolve("selected-leaf-fixture/root.jsonl");
let manager: AsyncJobManager;
let registry: AgentRegistry;
let lifecycle: AgentLifecycleManager;
beforeEach(() => {
	AgentLifecycleManager.resetGlobalForTests();
	AgentRegistry.resetGlobalForTests();
	const localRegistry = AgentRegistry.global();
	const localLifecycle = AgentLifecycleManager.global();
	if (!(localRegistry instanceof AgentRegistry) || !(localLifecycle instanceof AgentLifecycleManager)) {
		throw new Error("Expected local registry and lifecycle");
	}
	registry = localRegistry;
	lifecycle = localLifecycle;
	manager = new AsyncJobManager({ maxRunningJobs: 1 });
	vi.spyOn(persistedRoster, "ensurePersistedRoster").mockResolvedValue(mainFile);
});
afterEach(async () => {
	manager.cancelAll();
	await manager.dispose({ timeoutMs: 1_000 });
	await lifecycle.dispose();
	vi.restoreAllMocks();
	AgentLifecycleManager.resetGlobalForTests();
	AgentRegistry.resetGlobalForTests();
});
function entry(message: AgentMessage): SessionEntry {
	return { type: "message", id: "message", parentId: null, timestamp: new Date().toISOString(), message };
}
const user = entry({ role: "user", content: "work", timestamp: 1 });
const assistant = (content: string | { id: string; name: string }): SessionEntry => {
	const message = createAssistantMessage(typeof content === "string" ? content : "");
	if (typeof content !== "string") {
		message.content = [{ type: "toolCall", ...content, arguments: {} }];
		message.stopReason = "toolUse";
	}
	return entry(message);
};
const cutOff = [user, assistant({ id: "read-call", name: "read" })];
const result = (id: string): SingleResult => ({
	index: 0,
	id,
	agent: id,
	agentSource: "user",
	task: "work",
	exitCode: 0,
	output: id,
	stderr: "",
	truncated: false,
	durationMs: 1,
	tokens: 0,
	requests: 1,
});
function fixture(tree: Record<string, SessionEntry[]>) {
	const subs: Record<string, SubSession> = {};
	for (const [id, messages] of Object.entries(tree)) {
		const entries: SessionEntry[] = [
			{
				type: "session_init",
				id: "init",
				parentId: null,
				timestamp: new Date().toISOString(),
				systemPrompt: ["test"],
				task: `${id} task`,
				tools: ["read", "yield"],
			},
			...messages,
		];
		const linked = entries.map((entry, index) => ({
			...entry,
			id: `${id}-${index}`,
			parentId: index ? `${id}-${index - 1}` : null,
		}));
		subs[id] = {
			agentId: id,
			parent: null,
			header: null,
			leafId: linked.at(-1)!.id,
			entries: linked,
			aborted: false,
			malformedRecords: 0,
		};
		registry.register({
			id,
			displayName: id,
			kind: "sub",
			parentId: "Main",
			session: null,
			status: "parked",
			sessionFile: path.join(mainFile.slice(0, -6), `${id}.jsonl`),
		});
	}
	vi.spyOn(subSessions, "collectSubSessions").mockResolvedValue(subs);
	const root = {
		sessionManager: { getSessionFile: () => mainFile },
		getAgentId: () => "Main",
		asyncJobManager: manager,
		settings: Settings.isolated(),
		yieldQueue: { holdIdleFlush: () => () => {} },
		waitForIdle: async () => {},
		restoreInterruptedTurn: async () => false,
	} as unknown as AgentSession;
	return { root, subs };
}

it.each([
	"completed-selected",
	"interrupted-selected",
	"null-leaf",
	"missing-leaf",
	"cycle",
	"missing-parent",
] as const)("restores only the selected ancestry: %s", async selection => {
	const { root, subs } = fixture({ Child: cutOff });
	const sub = subs.Child!;
	const interruptedId = sub.leafId!;
	const completed = { ...assistant("completed sibling"), id: "completed", parentId: sub.entries[1]!.id };
	sub.entries.push(completed);
	if (selection === "completed-selected") {
		sub.leafId = completed.id;
		sub.entries.push({
			...assistant({ id: "abandoned", name: "read" }),
			id: "abandoned",
			parentId: sub.entries[1]!.id,
		});
	} else if (selection === "interrupted-selected") sub.leafId = interruptedId;
	else if (selection === "null-leaf") sub.leafId = null;
	else if (selection === "missing-leaf") sub.leafId = "not-in-transcript";
	else sub.entries[2]!.parentId = selection === "cycle" ? interruptedId : "missing-parent";
	const followUp = vi.spyOn(executor, "runSubagentFollowUpTurn").mockImplementation(async ({ id }) => result(id));
	const restored = await restoreSession(root);
	await manager.waitForAll();
	const expected = selection === "interrupted-selected" ? ["Child"] : [];
	expect(restored.subagents).toEqual(expected);
	expect(followUp.mock.calls.map(call => call[0].id)).toEqual(expected);
});

it("selected ancestry does not discard the latest off-branch session_init revival contract", async () => {
	const { root, subs } = fixture({ Child: cutOff });
	const initial = subs.Child!.entries[0]!;
	if (initial.type !== "session_init") throw new Error("Expected init fixture");
	subs.Child!.entries.push({ ...initial, id: "latest-init", parentId: null, task: "latest persisted task" });
	const followUp = vi.spyOn(executor, "runSubagentFollowUpTurn").mockImplementation(async ({ id }) => result(id));
	expect((await restoreSession(root)).subagents).toEqual(["Child"]);
	await manager.waitForAll();
	expect(followUp.mock.calls[0]![0].message).toBe("latest persisted task");
});

async function verifyRestore(root: AgentSession, expected: boolean): Promise<void> {
	const followUp = vi.spyOn(executor, "runSubagentFollowUpTurn").mockImplementation(async ({ id }) => result(id));
	expect((await restoreSession(root)).subagents).toEqual(expected ? ["Child"] : []);
	await manager.waitForAll();
	expect(followUp.mock.calls.map(call => call[0].id)).toEqual(expected ? ["Child"] : []);
}

it("a late usage record restores its captured active leaf instead of its own completed parent", async () => {
	const { root, subs } = fixture({ Child: cutOff });
	const sub = subs.Child!;
	const completed = { ...assistant("abandoned completion"), id: "completed", parentId: sub.entries[1]!.id };
	sub.entries.push(completed, {
		type: "model_usage",
		id: "late-usage",
		parentId: completed.id,
		activeLeafId: sub.leafId,
		timestamp: new Date().toISOString(),
		purpose: "advisor",
		api: "anthropic-messages",
		provider: "anthropic",
		model: "test",
		usage: createAssistantMessage("").usage,
		stopReason: "stop",
	});
	sub.leafId = resolveSessionLeafId(sub.entries);
	await verifyRestore(root, true);
});

it.each(["selected", "abandoned"] as const)("a normal exit only closes the %s ancestry", async selection => {
	const { root, subs } = fixture({ Child: cutOff });
	const sub = subs.Child!;
	const exit: SessionEntry = {
		type: "custom",
		id: "normal-exit",
		parentId: sub.leafId,
		timestamp: new Date().toISOString(),
		customType: "session_exit",
		data: { reason: "shutdown", kind: "normal", recordedAt: new Date().toISOString() },
	};
	sub.entries.push(exit);
	if (selection === "selected") {
		sub.leafId = exit.id;
		sub.entries.push({
			...assistant({ id: "abandoned", name: "read" }),
			id: "abandoned",
			parentId: sub.entries[1]!.id,
		});
	}
	await verifyRestore(root, selection === "abandoned");
});

it.each(["terminal", "incremental"] as const)("selected %s yield follows its own completion contract", async kind => {
	const incremental = kind === "incremental";
	const yieldCall = assistant({ id: "yield-call", name: "yield" });
	const yielded = entry({
		role: "toolResult",
		toolCallId: "yield-call",
		toolName: "yield",
		content: [],
		isError: false,
		timestamp: 1,
		details: incremental ? { status: "success", type: ["section"] } : { status: "success", data: "final" },
	});
	const { root, subs } = fixture({ Child: [user, yieldCall, yielded] });
	const sub = subs.Child!;
	const sibling = incremental ? assistant("abandoned completion") : assistant({ id: "abandoned", name: "read" });
	sub.entries.push({ ...sibling, id: "abandoned", parentId: sub.entries[1]!.id });
	await verifyRestore(root, incremental);
});

it("a selected interrupted-turn abort resumes even when an abandoned sibling completed", async () => {
	const aborted = createAssistantMessage("");
	aborted.stopReason = "aborted";
	aborted.errorMessage = INTERRUPTED_TURN_ERROR;
	const { root, subs } = fixture({ Child: [user, entry(aborted)] });
	subs.Child!.entries.push({
		...assistant("abandoned completion"),
		id: "completed",
		parentId: subs.Child!.entries[1]!.id,
	});
	await verifyRestore(root, true);
});

import { afterEach, beforeEach, describe, expect, it, vi } from "bun:test";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import type { AgentToolContext } from "@oh-my-pi/pi-agent-core";
import type { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import { ExtensionRuntime } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/loader";
import { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/runner";
import type { ExtensionUIContext } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/types";
import { ExtensionToolWrapper } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/wrapper";
import { AgentLifecycleManager } from "@oh-my-pi/pi-coding-agent/registry/agent-lifecycle";
import { AgentRegistry } from "@oh-my-pi/pi-coding-agent/registry/agent-registry";
import { SessionManager } from "@oh-my-pi/pi-coding-agent/session/session-manager";
import { TaskTool } from "@oh-my-pi/pi-coding-agent/task";
import * as discoveryModule from "@oh-my-pi/pi-coding-agent/task/discovery";
import * as executorModule from "@oh-my-pi/pi-coding-agent/task/executor";
import type { ExecutorOptions } from "@oh-my-pi/pi-coding-agent/task/executor";
import type { ToolSession } from "@oh-my-pi/pi-coding-agent/tools";
import { approvalCacheKeyForPath } from "@oh-my-pi/pi-coding-agent/tools/approval-cache";
import { withToolApprovalScope } from "@oh-my-pi/pi-coding-agent/tools/approval-scope";
import type { AgentProgress } from "@oh-my-pi/pi-tui/tools/task";

describe("taskFile approval binding", () => {
	let directory: string;
	const executions: ExecutorOptions[] = [];

	beforeEach(async () => {
		// Real path: macOS tmpdir is a symlink (/var → /private/var), and approval shows resolved targets.
		directory = await fs.promises.realpath(
			await fs.promises.mkdtemp(path.join(os.tmpdir(), "omp-task-file-approval-")),
		);
		executions.length = 0;
		AgentRegistry.resetGlobalForTests();
		AgentLifecycleManager.resetGlobalForTests();
		vi.spyOn(discoveryModule, "discoverAgents").mockResolvedValue({
			agents: [{ name: "task", description: "Task agent", systemPrompt: "Complete the task.", source: "bundled" }],
			projectAgentsDir: null,
		});
		vi.spyOn(executorModule, "runSubprocess").mockImplementation(async options => {
			executions.push(options);
			const progress: AgentProgress = {
				index: options.index,
				id: options.id,
				agent: options.agent.name,
				agentSource: options.agent.source,
				task: options.task,
				assignment: options.assignment,
				status: "completed",
				recentTools: [],
				recentOutput: [],
				toolCount: 0,
				requests: 1,
				tokens: 0,
				cost: 0,
				durationMs: 1,
			};
			options.onProgress?.(progress);
			return { ...progress, exitCode: 0, output: "Completed.", stderr: "", truncated: false };
		});
	});

	afterEach(async () => {
		vi.restoreAllMocks();
		AgentLifecycleManager.resetGlobalForTests();
		AgentRegistry.resetGlobalForTests();
		await fs.promises.rm(directory, { recursive: true, force: true });
	});

	async function createWrapper(
		select: ExtensionUIContext["select"],
		mode = "always-ask",
		restrictedFolders = [path.join(directory, "restricted")],
	) {
		const settings = Settings.isolated({
			"async.enabled": false,
			"task.file": true,
			"tools.approvalMode": mode,
			"tools.restrictedFolders": restrictedFolders,
		});
		const tool = await TaskTool.create({
			cwd: directory,
			hasUI: true,
			settings,
			getSessionFile: () => null,
			getSessionSpawns: () => "*",
			localProtocolOptions: { getArtifactsDir: () => path.join(directory, "artifacts") },
		} as unknown as ToolSession);
		const sessionManager = SessionManager.inMemory(directory);
		const modelRegistry = {} as ModelRegistry;
		const runner = new ExtensionRunner([], new ExtensionRuntime(), directory, sessionManager, modelRegistry);
		runner.initialize(
			{} as Parameters<ExtensionRunner["initialize"]>[0],
			{} as Parameters<ExtensionRunner["initialize"]>[1],
			undefined,
			{ select } as ExtensionUIContext,
		);
		const wrapper = new ExtensionToolWrapper(
			{
				name: tool.name,
				label: tool.label,
				description: tool.description,
				parameters: tool.parameters,
				approval: tool.approval,
				bindApprovalTargets: tool.bindApprovalTargets,
				approvalRestrictionPaths: tool.approvalRestrictionPaths,
				formatApprovalDetails: tool.formatApprovalDetails,
				execute: tool.execute.bind(tool),
			},
			runner,
		);
		const context: AgentToolContext = {
			settings,
			sessionManager,
			modelRegistry,
			model: undefined,
			isIdle: () => true,
			hasQueuedMessages: () => false,
			abort: () => undefined,
		};
		return { wrapper, context, runner, tool };
	}

	it.each(["pending", "resolved"])(
		"rejects task-file dispatch and session grants when approval expires during %s",
		async phase => {
			const taskFile = path.join(directory, "approved.md");
			await Bun.write(taskFile, "Approved assignment.");
			const { wrapper, context, runner } = await createWrapper(async (_title, options) => {
				if (phase === "pending") runner.clearSessionApprovals();
				const answer = options.find(
					(option): option is string => typeof option === "string" && option.endsWith("for this session"),
				);
				expect(answer).toBeDefined();
				return answer;
			});
			if (phase === "resolved") {
				vi.spyOn(runner, "hasHandlers").mockImplementation(name => name === "tool_approval_resolved");
				const originalEmit: typeof runner.emit = runner.emit.bind(runner);
				vi.spyOn(runner, "emit").mockImplementation(event => {
					if (event.type === "tool_approval_resolved") runner.clearSessionApprovals();
					return originalEmit(event);
				});
			}
			await expect(
				wrapper.execute(`expired-task-file-${phase}`, { taskFile }, undefined, undefined, context),
			).rejects.toThrow("session changed");
			expect(executions).toEqual([]);
			expect(runner.sessionApprovalKeys()).toEqual([]);
		},
	);

	async function linkedFiles(local = false) {
		const safe = path.join(directory, "safe.md");
		const restricted = path.join(directory, "restricted", "task.md");
		const linkPath = path.join(directory, ...(local ? ["artifacts", "local"] : []), "task-link.md");
		const taskFile = local ? "local://task-link.md" : linkPath;
		await Bun.write(safe, "Approved assignment.");
		await Bun.write(restricted, "Unapproved restricted assignment.");
		await fs.promises.mkdir(path.dirname(linkPath), { recursive: true });
		await fs.promises.symlink(safe, linkPath);
		return { safe, restricted, taskFile, linkPath };
	}

	it.each([false, true])(
		"reads the approved target when its symlink changes while approval is pending (local=%s)",
		async local => {
			const { safe, taskFile, restricted, linkPath } = await linkedFiles(local);
			const expectedPath = `Task file: ${JSON.stringify(taskFile)} -> ${JSON.stringify(safe)}`;
			const { wrapper, context, tool } = await createWrapper(async title => {
				expect(title).toContain(expectedPath);
				await fs.promises.unlink(linkPath);
				await fs.promises.symlink(restricted, linkPath);
				expect(tool.formatApprovalDetails({ taskFile })).toContain(expectedPath);
				return "Approve";
			});

			const result = await wrapper.execute("swapped-link", { taskFile }, undefined, undefined, context);

			expect(result.isError).not.toBe(true);
			expect(executions.map(item => item.assignment)).toEqual(["Approved assignment."]);
		},
	);

	it("shows each bound batch target after an inline item", async () => {
		const { safe, taskFile } = await linkedFiles(true);
		const direct = path.join(directory, "direct.md");
		await Bun.write(direct, "Direct assignment.");
		const { wrapper, context } = await createWrapper(async title => {
			expect(title).toContain(`Task 2 file: ${JSON.stringify(taskFile)} -> ${JSON.stringify(safe)}`);
			expect(title.split("\n")).toContain(`Task 3 file: ${JSON.stringify(direct)}`);
			return "Approve";
		});

		const result = await wrapper.execute(
			"batch-target-display",
			{
				context: "Complete all assignments.",
				tasks: [{ task: "Inline assignment." }, { taskFile }, { taskFile: direct }],
			},
			undefined,
			undefined,
			context,
		);

		expect(result.isError, JSON.stringify(result.content)).not.toBe(true);
		expect(executions.map(item => item.assignment).sort()).toEqual([
			"Approved assignment.",
			"Direct assignment.",
			"Inline assignment.",
		]);
	});

	it("does not authorize direct execution by querying restriction paths", async () => {
		const { safe, taskFile } = await linkedFiles();
		const { tool } = await createWrapper(async () => "Approve");

		const result = await withToolApprovalScope(async () => {
			expect(tool.approvalRestrictionPaths({ taskFile })).toEqual([approvalCacheKeyForPath(safe)]);
			return tool.execute("unbound-direct-call", { taskFile });
		});

		expect(result.isError).toBe(true);
		expect(result.content).toEqual([
			expect.objectContaining({ text: expect.stringContaining("was not included in this call's approval") }),
		]);
		expect(executions).toHaveLength(0);
	});

	it("omits unresolved local URLs from restriction targets and reports the dispatch error", async () => {
		const taskFile = "local://%ZZ";
		const { wrapper, context, tool } = await createWrapper(async () => {
			expect(tool.approvalRestrictionPaths({ taskFile })).toBeUndefined();
			return "Approve";
		});

		const result = await wrapper.execute("unresolved-file", { taskFile }, undefined, undefined, context);

		expect(result.isError).toBe(true);
		expect(result.content).toEqual([
			expect.objectContaining({ text: expect.stringContaining("does not resolve to a local file") }),
		]);
		expect(executions).toHaveLength(0);
	});

	it.each(["file", "ancestor", "regular-file"])(
		"rejects an approved %s replaced before dispatch",
		async replacement => {
			const parent = path.join(directory, "approved");
			const taskFile = path.join(parent, "task.md");
			const restrictedParent = path.join(directory, "restricted");
			await Bun.write(taskFile, "Approved assignment.");
			await Bun.write(path.join(restrictedParent, "task.md"), "Unapproved restricted assignment.");
			const { wrapper, context } = await createWrapper(async () => {
				if (replacement === "file") {
					await fs.promises.unlink(taskFile);
					await fs.promises.symlink(path.join(restrictedParent, "task.md"), taskFile);
				} else if (replacement === "ancestor") {
					await fs.promises.rename(parent, `${parent}-old`);
					await fs.promises.symlink(restrictedParent, parent);
				} else {
					await fs.promises.rename(taskFile, `${taskFile}-old`);
					await Bun.write(taskFile, "Replacement assignment.");
				}
				return "Approve";
			});

			const result = await wrapper.execute(`replaced-${replacement}`, { taskFile }, undefined, undefined, context);

			expect(result.isError).toBe(true);
			expect(result.content).toEqual([
				expect.objectContaining({ text: expect.stringContaining("changed after approval; retry the call") }),
			]);
			expect(executions).toHaveLength(0);
		},
	);

	it("binds task files even without restricted folders", async () => {
		const { taskFile, restricted } = await linkedFiles();
		const { wrapper, context } = await createWrapper(
			async () => {
				await fs.promises.unlink(taskFile);
				await fs.promises.symlink(restricted, taskFile);
				return "Approve";
			},
			"always-ask",
			[],
		);

		const result = await wrapper.execute("no-restrictions", { taskFile }, undefined, undefined, context);

		expect(result.isError).not.toBe(true);
		expect(executions.map(item => item.assignment)).toEqual(["Approved assignment."]);
	});

	it("rejects the whole batch when one approved target is replaced", async () => {
		const first = path.join(directory, "first.md");
		const second = path.join(directory, "second.md");
		await Bun.write(first, "First assignment.");
		await Bun.write(second, "Second assignment.");
		const { wrapper, context } = await createWrapper(async () => {
			await fs.promises.rename(second, `${second}-old`);
			await Bun.write(second, "Replacement assignment.");
			return "Approve";
		});

		const result = await wrapper.execute(
			"replaced-batch-target",
			{ context: "Complete both assignments.", tasks: [{ taskFile: first }, { taskFile: second }] },
			undefined,
			undefined,
			context,
		);

		expect(result.isError).toBe(true);
		expect(result.content).toEqual([
			expect.objectContaining({ text: expect.stringContaining("changed after approval; retry the call") }),
		]);
		expect(executions).toHaveLength(0);
	});

	it("keeps stable symlinks and reads updated bytes and hash at dispatch", async () => {
		const { safe, taskFile } = await linkedFiles();
		const bytes = new TextEncoder().encode(" \nUpdated after approval began.\n ");
		const { wrapper, context } = await createWrapper(async () => {
			await Bun.write(safe, bytes);
			return "Approve";
		});

		const result = await wrapper.execute("updated-content", { taskFile }, undefined, undefined, context);
		const digest = Buffer.from(await crypto.subtle.digest("SHA-256", bytes)).toString("hex");

		expect(result.isError).not.toBe(true);
		expect(executions.map(item => item.assignment)).toEqual(["Updated after approval began."]);
		expect(result.details?.results[0]).toMatchObject({ taskFile, taskFileSha256: digest });
	});

	it("discards denied-call bindings before the same args object is reused", async () => {
		const { taskFile, restricted } = await linkedFiles();
		let prompts = 0;
		const { wrapper, context } = await createWrapper(async () => (++prompts === 1 ? "Deny" : "Approve"));
		const args = { taskFile };
		await expect(wrapper.execute("denied", args, undefined, undefined, context)).rejects.toThrow("denied by user");
		await fs.promises.unlink(taskFile);
		await fs.promises.symlink(restricted, taskFile);

		const result = await wrapper.execute("approved-reuse", args, undefined, undefined, context);

		expect(result.isError).not.toBe(true);
		expect(prompts).toBe(2);
		expect(executions.map(item => item.assignment)).toEqual(["Unapproved restricted assignment."]);
	});

	it("isolates simultaneous calls that share the same args object", async () => {
		const { taskFile, restricted } = await linkedFiles();
		const entered = [Promise.withResolvers<void>(), Promise.withResolvers<void>()];
		const answers = [Promise.withResolvers<string>(), Promise.withResolvers<string>()];
		let prompts = 0;
		const { wrapper, context } = await createWrapper(async () => {
			const index = prompts++;
			entered[index]!.resolve();
			return answers[index]!.promise;
		});
		const args = { taskFile };
		const first = wrapper.execute("first-concurrent", args, undefined, undefined, context);
		let second: typeof first | undefined;
		try {
			await entered[0]!.promise;
			await fs.promises.unlink(taskFile);
			await fs.promises.symlink(restricted, taskFile);
			second = wrapper.execute("second-concurrent", args, undefined, undefined, context);
			await entered[1]!.promise;
			answers[1]!.resolve("Approve");
			expect((await second).isError).not.toBe(true);
			answers[0]!.resolve("Approve");
			expect((await first).isError).not.toBe(true);
			expect(executions.map(item => item.assignment)).toEqual([
				"Unapproved restricted assignment.",
				"Approved assignment.",
			]);
		} finally {
			for (const answer of answers) answer.resolve("Deny");
			await Promise.allSettled([first, second]);
		}
	});

	it.each(["missing", "directory"])("does not recapture a %s task file after approval", async initial => {
		const taskFile = path.join(directory, "task.md");
		if (initial === "directory") await fs.promises.mkdir(taskFile);
		const { wrapper, context } = await createWrapper(async () => {
			if (initial === "directory") await fs.promises.rmdir(taskFile);
			await Bun.write(taskFile, "Created after approval began.");
			return "Approve";
		});

		const result = await wrapper.execute(`invalid-${initial}`, { taskFile }, undefined, undefined, context);

		expect(result.isError).toBe(true);
		expect(executions).toHaveLength(0);
	});

	it("restores the outer file binding after a nested wrapper invocation", async () => {
		const { taskFile, restricted } = await linkedFiles();
		let prompts = 0;
		const args = { taskFile };
		const { wrapper, context } = await createWrapper(async () => {
			if (++prompts === 1) {
				await fs.promises.unlink(taskFile);
				await fs.promises.symlink(restricted, taskFile);
				const nested = await wrapper.execute("nested", args, undefined, undefined, context);
				expect(nested.isError).not.toBe(true);
			}
			return "Approve";
		});

		const result = await wrapper.execute("outer", args, undefined, undefined, context);

		expect(result.isError).not.toBe(true);
		expect(executions.map(item => item.assignment)).toEqual([
			"Unapproved restricted assignment.",
			"Approved assignment.",
		]);
	});

	it("uses the final preflight file in modes that do not ask for approval", async () => {
		const { safe, taskFile } = await linkedFiles();
		const select = vi.fn(async () => "Deny");
		const { wrapper, context, runner } = await createWrapper(select, "yolo");
		vi.spyOn(runner, "runToolCallPreflightBefore").mockImplementation(async () => {
			await fs.promises.rename(safe, `${safe}-old`);
			await Bun.write(safe, "Preflight replacement.");
			return undefined;
		});

		const result = await wrapper.execute("no-prompt", { taskFile }, undefined, undefined, context);

		expect(result.isError).not.toBe(true);
		expect(select).not.toHaveBeenCalled();
		expect(executions.map(item => item.assignment)).toEqual(["Preflight replacement."]);
	});

	it("reads the bound target when its symlink changes after automatic approval", async () => {
		const { taskFile, restricted } = await linkedFiles();
		const select = vi.fn(async () => "Deny");
		const { wrapper, context, runner } = await createWrapper(select, "yolo");
		const runScoped = runner.runScoped.bind(runner);
		vi.spyOn(runner, "runScoped").mockImplementation(run => {
			fs.unlinkSync(taskFile);
			fs.symlinkSync(restricted, taskFile);
			return runScoped(run);
		});

		const result = await wrapper.execute("automatic-approval-swap", { taskFile }, undefined, undefined, context);

		expect(result.isError).not.toBe(true);
		expect(select).not.toHaveBeenCalled();
		expect(executions.map(item => item.assignment)).toEqual(["Approved assignment."]);
	});
});

/**
 * `tools.approvalMode: always-ask-cached` — resolver semantics, the grant store, the prompt's
 * grant choices, and the wrapper's approve-then-remember cycle.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "bun:test";
import * as fs from "node:fs";
import * as path from "node:path";
import { Agent, type AgentTool, type AgentToolContext, type ToolTier } from "@oh-my-pi/pi-agent-core";
import { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import { ExtensionRuntime } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/loader";
import { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/runner";
import type {
	ExtensionApprovalPrompt,
	ExtensionUIContext,
} from "@oh-my-pi/pi-coding-agent/extensibility/extensions/types";
import { ExtensionToolWrapper } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/wrapper";
import { createMockModel } from "@oh-my-pi/pi-ai/providers/mock";
import { AgentSession } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import { convertToLlm } from "@oh-my-pi/pi-coding-agent/session/messages";
import { AuthStorage } from "@oh-my-pi/pi-coding-agent/session/auth-storage";
import { SessionManager } from "@oh-my-pi/pi-coding-agent/session/session-manager";
import { requestApproval, resolveApproval } from "@oh-my-pi/pi-coding-agent/tools/approval";
import {
	APPROVAL_CACHE_FILENAME,
	approvalDirectoryKey,
	approvalGrantKey,
	clearApprovalGrants,
	getApprovalGrants,
} from "@oh-my-pi/pi-coding-agent/tools/approval-cache";
import { approvalTargetKey, approvalTreeSearchKey } from "@oh-my-pi/pi-coding-agent/tools/approval-targets";
import { getAgentDir, isRecord, setAgentDir, TempDir } from "@oh-my-pi/pi-utils";
import { shortenPath } from "@oh-my-pi/pi-tui/render/render-utils";

/** Tool that keys `args.path` like read/write/edit do. */
function pathTool(name: string, tier: ToolTier, cwd: string): AgentTool {
	return {
		name,
		label: name,
		description: `${name} test tool`,
		parameters: {} as never,
		approval: tier,
		approvalCacheTargets: (args: unknown) =>
			isRecord(args) && typeof args.path === "string" ? [approvalTargetKey(cwd, args.path)!] : undefined,
		execute: async () => ({ content: [{ type: "text" as const, text: "executed" }] }),
	};
}

let root: TempDir;
beforeAll(() => {
	root = TempDir.createSync("@pi-approval-cached-");
});
afterAll(() => {
	root.removeSync();
});

/** A fresh agent directory per case, so grants never leak between cases. */
function freshAgentDir(): string {
	return fs.mkdtempSync(path.join(root.path(), "agent-"));
}

describe("always-ask-cached resolution", () => {
	it("allows a call only once every target is granted at its tier or above", () => {
		const agentDir = freshAgentDir();
		const cwd = path.join(agentDir, "work");
		const read = pathTool("read", "read", cwd);
		const write = pathTool("write", "write", cwd);
		const grants = getApprovalGrants(agentDir, "s1");
		const notes = approvalTargetKey(cwd, "notes.txt")!;

		expect(resolveApproval(read, { path: "notes.txt" }, "always-ask-cached", {}, grants)).toMatchObject({
			policy: "prompt",
			reason: "target not yet approved",
		});
		grants.record(approvalGrantKey("read", notes), "read", "session");
		expect(resolveApproval(read, { path: "notes.txt" }, "always-ask-cached", {}, grants).policy).toBe("allow");
		// A read grant never lets a write through; a write grant covers reads.
		expect(resolveApproval(write, { path: "notes.txt" }, "always-ask-cached", {}, grants).policy).toBe("prompt");
		grants.record(approvalGrantKey("write", approvalTargetKey(cwd, "other.txt")!), "write", "session");
		expect(resolveApproval(read, { path: "other.txt" }, "always-ask-cached", {}, grants).policy).toBe("allow");
		// Without a store nothing counts as remembered.
		expect(resolveApproval(read, { path: "notes.txt" }, "always-ask-cached", {}).policy).toBe("prompt");
	});

	it("covers a folder grant's own files, never a subfolder or what lies below it", () => {
		const agentDir = freshAgentDir();
		const cwd = path.join(agentDir, "work");
		fs.mkdirSync(path.join(cwd, "dir", "sub"), { recursive: true });
		const read = pathTool("read", "read", cwd);
		const grants = getApprovalGrants(agentDir, "s1");
		grants.record(approvalGrantKey("read", approvalDirectoryKey(path.join(cwd, "dir"))), "read", "session");

		expect(resolveApproval(read, { path: "dir/a.ts" }, "always-ask-cached", {}, grants).policy).toBe("allow");
		expect(resolveApproval(read, { path: "dir/sub/a.ts" }, "always-ask-cached", {}, grants).policy).toBe("prompt");
		const subDir: AgentTool = {
			...read,
			approvalCacheTargets: () => [approvalDirectoryKey(path.join(cwd, "dir", "sub"))],
		};
		expect(resolveApproval(subDir, {}, "always-ask-cached", {}, grants).policy).toBe("prompt");
	});

	it("keys a new file under a symlinked folder by where it will land", () => {
		const agentDir = freshAgentDir();
		const real = path.join(agentDir, "real");
		const link = path.join(agentDir, "link");
		fs.mkdirSync(real);
		try {
			fs.symlinkSync(real, link, "junction");
		} catch {
			return; // Symlinks unavailable on this host.
		}
		// The target does not exist yet: its key still resolves the link, so a folder grant on the
		// link's own parent never covers a file that lands elsewhere.
		expect(approvalTargetKey(agentDir, "link/new.ts")).toBe(approvalTargetKey(agentDir, "real/new.ts"));
	});

	it("leaves read-tier calls without targets auto-approved and prompts write/exec ones", () => {
		const glob = { name: "lsp", approval: "read" as const } as AgentTool;
		const evalTool = { name: "eval", approval: "exec" as const } as AgentTool;
		expect(resolveApproval(glob, {}, "always-ask-cached", {}).policy).toBe("allow");
		expect(resolveApproval(evalTool, {}, "always-ask-cached", {})).toMatchObject({
			policy: "prompt",
			source: "mode",
		});
	});

	it("keeps tool and user policies authoritative over remembered grants", () => {
		const agentDir = freshAgentDir();
		const write = pathTool("write", "write", agentDir);
		const grants = getApprovalGrants(agentDir, "s1");
		grants.record(approvalGrantKey("write", approvalTargetKey(agentDir, "notes.txt")!), "write", "session");
		expect(
			resolveApproval(write, { path: "notes.txt" }, "always-ask-cached", { write: "prompt" }, grants),
		).toMatchObject({ policy: "prompt", source: "user" });
		const guarded: AgentTool = { ...write, approval: () => ({ tier: "write", override: true, reason: "guarded" }) };
		expect(resolveApproval(guarded, { path: "notes.txt" }, "always-ask-cached", {}, grants)).toMatchObject({
			policy: "prompt",
			source: "tool",
		});
	});
});

describe("approval grant store", () => {
	it("keeps session grants to their conversation and global grants for every session", () => {
		const agentDir = freshAgentDir();
		const key = approvalGrantKey("read", "/x");
		getApprovalGrants(agentDir, "one").record(key, "read", "session");
		expect(getApprovalGrants(agentDir, "one").present([key]).has(key)).toBe(true);
		expect(getApprovalGrants(agentDir, "two").present([key]).has(key)).toBe(false);
		// A caller that cannot name its conversation sees global grants only.
		expect(getApprovalGrants(agentDir).present([key]).has(key)).toBe(false);

		getApprovalGrants(agentDir, "one").record(key, "read", "global");
		expect(getApprovalGrants(agentDir, "two").present([key]).has(key)).toBe(true);
		expect(getApprovalGrants(agentDir).present([key]).has(key)).toBe(true);
	});

	it("creates no database until a grant is persisted, and honors deleting it", () => {
		const agentDir = freshAgentDir();
		const file = path.join(agentDir, APPROVAL_CACHE_FILENAME);
		const key = approvalGrantKey("read", "/x");
		expect(getApprovalGrants(agentDir).present([key]).size).toBe(0);
		expect(fs.existsSync(file)).toBe(false);
		getApprovalGrants(agentDir, "one").record(key, "read", "global");
		expect(fs.existsSync(file)).toBe(true);
		fs.rmSync(file);
		expect(getApprovalGrants(agentDir, "one").present([key]).size).toBe(0);
	});

	it("forgets both tiers for every conversation when cleared", () => {
		const agentDir = freshAgentDir();
		const sessionKey = approvalGrantKey("read", "/session");
		const globalKey = approvalGrantKey("read", "/global");
		getApprovalGrants(agentDir, "one").record(sessionKey, "read", "session");
		getApprovalGrants(agentDir, "two").record(globalKey, "read", "global");
		clearApprovalGrants(agentDir);
		expect(getApprovalGrants(agentDir, "one").present([sessionKey, globalKey]).size).toBe(0);
		expect(getApprovalGrants(agentDir, "two").present([sessionKey, globalKey]).size).toBe(0);
	});
});

describe("grant choices in the prompt", () => {
	function recordingUi() {
		const prompts: ExtensionApprovalPrompt[] = [];
		const ui = {
			select: async () => undefined,
			approve: async (prompt: ExtensionApprovalPrompt) => {
				prompts.push(prompt);
				return "once" as const;
			},
		};
		return { ui, prompts };
	}

	it.each([
		[
			"a directory and a file in another directory",
			(dir: string) => [approvalDirectoryKey(dir), approvalTargetKey(path.dirname(dir), "a.md")!],
		],
		[
			"a file and a recursive search of its directory",
			(dir: string) => [approvalTargetKey(dir, "a.md")!, approvalTreeSearchKey(approvalDirectoryKey(dir))],
		],
		["a file and an internal URL", (dir: string) => [approvalTargetKey(dir, "a.md")!, "local://a.md"]],
	])("offers no directory grant for %s, since it would not cover every target", async (_, targets) => {
		const dir = path.join(freshAgentDir(), "work");
		fs.mkdirSync(dir);
		const tool: AgentTool = { ...pathTool("read", "read", dir), approvalCacheTargets: () => targets(dir) };
		const { ui, prompts } = recordingUi();
		await requestApproval(ui, tool, {}, { grants: true });
		expect(prompts[0]!.grants?.map(grant => grant.scope)).toEqual(["target"]);
	});

	it("offers the folder and the file, and names and lists the folder a grant would cover", async () => {
		const agentDir = freshAgentDir();
		const desktop = path.join(agentDir, "Desktop");
		fs.mkdirSync(path.join(desktop, "TestFolder"), { recursive: true });
		fs.writeFileSync(path.join(desktop, "notes.txt"), "x");
		fs.writeFileSync(path.join(desktop, "alpha.txt"), "x");
		const { ui, prompts } = recordingUi();
		await requestApproval(ui, pathTool("read", "read", desktop), { path: "notes.txt" }, { grants: true });
		const label = shortenPath(approvalDirectoryKey(desktop).replace(/[\\/]+$/, ""));
		expect(prompts[0]!.grants).toEqual([
			{ scope: "folder", label: `Approve Directory: ${label}`, alwaysLabel: `Always Approve Directory: ${label}` },
			{ scope: "target", label: "Approve File", alwaysLabel: "Always Approve File" },
		]);
		expect(prompts[0]!.full.split("\n")).toEqual([
			"Allow tool: read",
			`Folder: ${label} — 3 entries (1 folder, 2 files)`,
			"  - TestFolder/",
			"  - alpha.txt",
			"  - notes.txt",
		]);
	});

	it("caps the compact listing and bounds the folder scan", async () => {
		const agentDir = freshAgentDir();
		const huge = path.join(agentDir, "Huge");
		fs.mkdirSync(huge);
		for (let index = 0; index < 205; index += 1) {
			fs.writeFileSync(path.join(huge, `entry-${String(index).padStart(3, "0")}.txt`), "x");
		}
		const { ui, prompts } = recordingUi();
		await requestApproval(ui, pathTool("write", "write", huge), { path: "entry-000.txt" }, { grants: true });
		const compact = prompts[0]!.compact.split("\n");
		expect(compact[1]).toContain("200+ entries");
		expect(compact.slice(2)).toEqual([
			"  - entry-000.txt",
			"  - entry-001.txt",
			"  - entry-002.txt",
			"  - entry-003.txt",
			"  … 196 more",
		]);
	});

	it("offers only the directory answer for a call that names just that directory", async () => {
		const agentDir = freshAgentDir();
		const dir = path.join(agentDir, "Listed");
		fs.mkdirSync(dir);
		const { ui, prompts } = recordingUi();
		const listing: AgentTool = {
			...pathTool("read", "read", agentDir),
			approvalCacheTargets: () => [approvalDirectoryKey(dir)],
		};
		await requestApproval(ui, listing, {}, { grants: true });
		expect(prompts[0]!.grants?.map(grant => grant.scope)).toEqual(["folder"]);
	});

	it("keeps plain Approve/Deny without grants, and denies a grant the prompt never offered", async () => {
		const agentDir = freshAgentDir();
		const write = pathTool("write", "write", agentDir);
		const options: string[][] = [];
		const select = { select: async (_title: string, choices: string[]) => (options.push(choices), choices[0]) };
		expect(await requestApproval(select, write, { path: "a.txt" })).toBe("once");
		expect(options[0]).toEqual(["Approve", "Deny"]);

		const answer = await requestApproval(
			{ select: async () => undefined, approve: async () => ({ grant: "folder", always: true }) as const },
			write,
			{ path: "a.txt" },
		);
		expect(answer).toBe("deny");
	});

	it("maps select labels back to grants for hosts without a dialog", async () => {
		const agentDir = freshAgentDir();
		const write = pathTool("write", "write", agentDir);
		const pick = (label: string) => ({
			select: async (_title: string, choices: string[]) => choices.find(c => c.startsWith(label)),
		});
		expect(await requestApproval(pick("Always Approve File"), write, { path: "a.txt" }, { grants: true })).toEqual({
			grant: "target",
			always: true,
		});
		expect(await requestApproval(pick("Approve Directory"), write, { path: "a.txt" }, { grants: true })).toEqual({
			grant: "folder",
			always: false,
		});
		expect(await requestApproval(pick("Approve Once"), write, { path: "a.txt" }, { grants: true })).toBe("once");
	});
});

describe("always-ask-cached wrapper cycle", () => {
	let agentDir: string;
	let authStorage: AuthStorage;
	let modelRegistry: ModelRegistry;
	let originalAgentDir: string;

	beforeAll(async () => {
		authStorage = await AuthStorage.create(path.join(root.path(), "testauth.db"));
		modelRegistry = new ModelRegistry(authStorage);
	});
	afterAll(() => {
		authStorage.close();
	});
	beforeEach(() => {
		originalAgentDir = getAgentDir();
		agentDir = freshAgentDir();
		setAgentDir(agentDir);
	});
	afterEach(() => {
		setAgentDir(originalAgentDir);
	});

	function runnerWith(sessionManager: SessionManager, select: ExtensionUIContext["select"]): ExtensionRunner {
		const runner = new ExtensionRunner([], new ExtensionRuntime(), agentDir, sessionManager, modelRegistry);
		runner.initialize(
			{
				sendMessage: () => {},
				sendUserMessage: async () => {},
				appendEntry: () => {},
				setLabel: () => {},
				getActiveTools: () => [],
				getAllTools: () => [],
				setActiveTools: async () => {},
				getCommands: () => [],
