		const cwd = path.join(agentDir, "work");
		const tool = pathTool("write", "write", cwd);
		const session = SessionManager.inMemory(cwd);
		const answers = ["Approve Once", "Deny", "Approve Once"];
		const select = vi.fn(async () => answers.shift());
		const wrapper = new ExtensionToolWrapper(tool, runnerWith(session, select));
		await wrapper.execute("o1", { path: "a.txt" }, undefined, undefined, context(session));
		await expect(wrapper.execute("o2", { path: "a.txt" }, undefined, undefined, context(session))).rejects.toThrow(
			"denied by user",
		);
		await wrapper.execute("o3", { path: "a.txt" }, undefined, undefined, context(session));
		expect(select).toHaveBeenCalledTimes(3);
	});

	it("offers an exec call without targets the session answer, not grants", async () => {
		const session = SessionManager.inMemory(path.join(agentDir, "work"));
		const select = vi.fn(async (_title: string, options: string[]) =>
			options.find(option => option.endsWith("for this session")),
		);
		const tool: AgentTool = { ...pathTool("probe_exec", "exec", agentDir), approvalCacheTargets: undefined };
		const wrapper = new ExtensionToolWrapper(tool, runnerWith(session, select));
		await wrapper.execute("e1", {}, undefined, undefined, context(session));
		expect(select.mock.calls[0]![1]).toEqual(["Approve", "Approve probe_exec for this session", "Deny"]);
		await wrapper.execute("e2", {}, undefined, undefined, context(session));
		expect(select).toHaveBeenCalledTimes(1);
	});
	it.each(["Approve File", "Always Approve File"])(
		"does not store %s when the resolved event changes the approval lifetime",
		async choice => {
			const cwd = path.join(agentDir, "work");
			const session = SessionManager.inMemory(cwd);
			const execute = vi.fn(async () => ({ content: [{ type: "text" as const, text: "executed" }] }));
			const tool: AgentTool = { ...pathTool("write", "write", cwd), execute };
			const runner = runnerWith(session, async () => choice);
			const handlers = vi.spyOn(runner, "hasHandlers").mockImplementation(name => name === "tool_approval_resolved");
			const originalEmit: typeof runner.emit = runner.emit.bind(runner);
			const emit = vi.spyOn(runner, "emit").mockImplementation(event => {
				if (event.type === "tool_approval_resolved") runner.clearSessionApprovals();
				return originalEmit(event);
			});
			try {
				await expect(
					new ExtensionToolWrapper(tool, runner).execute(
						"stale-cache",
						{ path: "a.txt" },
						undefined,
						undefined,
						context(session),
					),
				).rejects.toThrow("session changed");
				expect(execute).not.toHaveBeenCalled();
			} finally {
				handlers.mockRestore();
				emit.mockRestore();
			}
			const deny = vi.fn(async () => "Deny");
			await expect(
				new ExtensionToolWrapper(tool, runnerWith(session, deny)).execute(
					"verify-cache",
					{ path: "a.txt" },
					undefined,
					undefined,
					context(session),
				),
			).rejects.toThrow("denied by user");
			expect(deny).toHaveBeenCalledTimes(1);
			expect(execute).not.toHaveBeenCalled();
		},
	);
	it.each(["new", "rollback", "dispose"] as const)(
		"rejects a late approval across a queued real session transition: %s",
		async transition => {
			const cwd = path.join(agentDir, "work");
			fs.mkdirSync(cwd, { recursive: true });
			const manager = SessionManager.create(cwd, path.join(agentDir, "sessions"));
			const originalId = manager.getSessionId();
			const shown = Promise.withResolvers<void>();
			const answer = Promise.withResolvers<string | undefined>();
			let choice: string | undefined;
			const runner = runnerWith(manager, async (_title, options) => {
				choice = options.find(
					(option): option is string => typeof option === "string" && option.endsWith("for this session"),
				);
				shown.resolve();
				return answer.promise;
			});
			const mock = createMockModel({ provider: "openai", id: "gpt-test", handler: () => ({ content: ["ok"] }) });
			const settings = Settings.isolated({ "compaction.enabled": false, "todo.enabled": false });
			settings.setModelRole("default", `${mock.model.provider}/${mock.model.id}`);
			const target = new AgentSession({
				agent: new Agent({
					initialState: { model: mock.model, systemPrompt: ["Test"], tools: [], messages: [] },
					convertToLlm,
					streamFn: mock.stream,
				}),
				sessionManager: manager,
				modelRegistry,
				settings,
				toolRegistry: new Map(),
				extensionRunner: runner,
			});
			const execute = vi.fn(async () => ({ content: [{ type: "text" as const, text: "executed" }] }));
			const wrapper = new ExtensionToolWrapper(
				{ ...pathTool("probe_exec", "exec", cwd), approvalCacheTargets: undefined, execute },
				runner,
			);
			const pending = wrapper.execute("queued-late", {}, undefined, undefined, context(manager));
			const outcome = pending.then(
				() => "executed",
				() => "rejected",
			);
			const otherCwd = path.join(agentDir, "other");
			fs.mkdirSync(otherCwd);
			const other = SessionManager.create(otherCwd, path.join(agentDir, "other-sessions"));
			other.appendMessage({ role: "user", content: "other", timestamp: Date.now() });
			await other.ensureOnDisk();
			const file = other.getSessionFile()!;
			await other.close();
			const switching = Promise.withResolvers<void>();
			const release = Promise.withResolvers<void>();
			let first: Promise<boolean> | undefined;
			let next: Promise<boolean> | undefined;
			let disposed: Promise<void> | undefined;
			try {
				await shown.promise;
				expect(choice).toBeDefined();
				first = target.switchSession(file, {
					onCwdChange: async () => {
						switching.resolve();
						await release.promise;
						return false;
					},
				});
				await switching.promise;
				if (transition === "new") next = target.newSession();
				if (transition === "dispose") disposed = target.dispose();
				release.resolve();
				expect(await first).toBe(false);
				if (next) expect(await next).toBe(true);
				await disposed;
				if (transition === "rollback") expect(manager.getSessionId()).toBe(originalId);
				answer.resolve(choice);
				expect(await outcome).toBe("rejected");
				expect(execute).not.toHaveBeenCalled();
				expect(runner.hasSessionApproval("probe_exec\0exec")).toBe(false);
			} finally {
				release.resolve();
				answer.resolve(undefined);
				await Promise.allSettled([first, next, disposed, pending]);
				await target.dispose();
			}
		},
	);
	it.each(["switch", "reset", "abort"] as const)(
		"rejects a late session approval after %s without executing or granting",
		async transition => {
			const session = SessionManager.inMemory(path.join(agentDir, "work"));
			const shown = Promise.withResolvers<void>();
			const answer = Promise.withResolvers<string | undefined>();
			let sessionChoice: string | undefined;
			const select = vi.fn(async (_title: string, options: string[]) => {
				sessionChoice = options.find(option => option.endsWith("for this session"));
				shown.resolve();
				return await answer.promise;
			});
			const execute = vi.fn(async () => ({ content: [{ type: "text" as const, text: "executed" }] }));
			const tool: AgentTool = {
				...pathTool("probe_exec", "exec", agentDir),
				approvalCacheTargets: undefined,
				execute,
			};
			const runner = runnerWith(session, select);
			const wrapper = new ExtensionToolWrapper(tool, runner);
			const controller = new AbortController();
			const pending = wrapper.execute("late", {}, controller.signal, undefined, context(session));
			const outcome = pending.then(
				() => "executed",
				() => "rejected",
			);
			await shown.promise;
			if (transition === "switch") await session.newSession();
			else if (transition === "reset") runner.clearSessionApprovals();
			else controller.abort(new Error("cancelled while awaiting approval"));
			answer.resolve(sessionChoice);
			expect(await outcome).toBe("rejected");
			expect(execute).not.toHaveBeenCalled();
			expect(runner.hasSessionApproval("probe_exec\0exec")).toBe(false);
		},
	);
});

import { describe, expect, it, vi } from "bun:test";
import type { AgentToolContext } from "@oh-my-pi/pi-agent-core";
import { validateToolArguments } from "@oh-my-pi/pi-ai/utils/validation";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import type { BashInterceptorRule } from "@oh-my-pi/pi-coding-agent/exec/settings";
import { DEFAULT_BASH_INTERCEPTOR_RULES } from "@oh-my-pi/pi-coding-agent/exec/settings";
import type { ExtensionRunner } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/runner";
import { ExtensionToolWrapper } from "@oh-my-pi/pi-coding-agent/extensibility/extensions/wrapper";
import type { Tool, ToolSession } from "@oh-my-pi/pi-coding-agent/tools";
import { BashTool, type BashToolInput } from "@oh-my-pi/pi-coding-agent/tools/bash";
import { checkBashInterception } from "@oh-my-pi/pi-coding-agent/tools/bash-interceptor";

function createBashTool(rules: BashInterceptorRule[]): BashTool {
	const session = {
		settings: Settings.isolated({
			"bashInterceptor.enabled": true,
			"bashInterceptor.patterns": rules,
			"async.enabled": false,
			"bash.autoBackground.enabled": false,
			"bash.autoBackground.thresholdMs": 60_000,
		}),
		getSessionFile: () => null,
	} as unknown as ToolSession;

	return new BashTool(session);
}

describe("BashTool interception", () => {
