describe("pre-approval refusal gate", () => {
	const createSession = (settingsOverrides: Record<string, unknown> = {}, toolNames = ["read", "grep", "bash"]) =>
		({
			cwd: process.cwd(),
			hasUI: true,
			getSessionFile: () => null,
			isToolActive: (name: string) => toolNames.includes(name),
			getToolContext: () => ({ toolNames, hasUI: true, ui: {} }) as unknown as AgentToolContext,
			settings: Settings.isolated({
				"async.enabled": true,
				"launch.enabled": true,
				"bashInterceptor.enabled": true,
				"bashInterceptor.patterns": DEFAULT_BASH_INTERCEPTOR_RULES,
				...settingsOverrides,
			}),
		}) as unknown as ToolSession;

	const makeWrapper = (tool: BashTool, select: () => Promise<string>, hasUI = true, rewrittenCommand?: string) => {
		const runner = {
			hasHandlers: (event: string) => rewrittenCommand !== undefined && event === "tool_call",
			emitToolCall: async () => (rewrittenCommand ? { input: { command: rewrittenCommand } } : undefined),
			consumeToolCallEmitted: () => false,
			hasUI: () => hasUI,
			getUIContext: () => ({ select }),
			hasSessionApproval: () => false,
			sessionId: "bash-approval-test",
			cwd: process.cwd(),
			runScoped: <T>(fn: () => T): T => fn(),
			getSessionApprovalEpoch: () => 0,
			clearSessionApprovals: () => {},
		} as unknown as ExtensionRunner;
		return new ExtensionToolWrapper(tool as Tool, runner);
	};

	const alwaysAskCtx = {
		settings: Settings.isolated({ "tools.approvalMode": "always-ask" }),
		toolNames: ["read", "grep", "bash"],
	} as unknown as AgentToolContext;

	it("rejects an intercepted command in always-ask mode without prompting", async () => {
		const select = vi.fn(async () => "Approve");
		const wrapper = makeWrapper(new BashTool(createSession()), select);

		await expect(
			wrapper.execute("call-1", { command: "cat package.json" }, undefined, undefined, alwaysAskCtx),
		).rejects.toThrow("Use the `read` tool instead of cat/head/tail");

		expect(select).not.toHaveBeenCalled();
	});
});

import * as assert from "node:assert/strict";
import * as net from "node:net";
import { describe, it } from "bun:test";
import { probeCdpStatus } from "@oh-my-pi/pi-coding-agent/tools/browser/attach";
import type { ChildProcess } from "@oh-my-pi/pi-utils";
import { createChromiumProbe, type ChromiumProbeDiagnostic, type ChromiumProbeHost } from "./chromium-probe";

import {
	CHROMIUM_DIAGNOSTIC_LIMITS,
	collectChromiumFailureSnapshot,
	createChromiumProcReader,
	type ChromiumFailureSnapshot,
	type ChromiumProcReader,
} from "./chromium-probe-diagnostics";

function harness(overrides: Partial<ChromiumProbeHost> = {}) {
	const events: string[] = [];
	const diagnostics: ChromiumProbeDiagnostic[] = [];
	let exitCode: number | null = null;
	const exited = Promise.withResolvers<number>();
	const child: Pick<ChildProcess, "pid" | "exitCode" | "exited" | "peekStderr" | "kill" | "wait"> = {
		pid: 123,
		exited: exited.promise,
		get exitCode() {
			return exitCode;
		},
		peekStderr: () => "",
		kill: () => {
			events.push("kill");
			exitCode = 137;
			exited.resolve(exitCode);
		},
		wait: async () => {
			events.push("wait");
			return { stdout: "", stderr: "", exitCode, ok: false };
		},
	};
	const host: ChromiumProbeHost = {
		platform: () => "linux",
		ci: () => "false",
		githubActions: () => undefined,
		hasDisplay: () => false,
		now: () => 1000,
		resolveExecutable: async () => {
			events.push("resolve");
			return "/browser/chrome";
		},
		isFile: async () => {
			events.push("stat");
			return true;
		},
		makeProfile: async () => {
			events.push("profile");
			return "/temporary/profile";
		},
		findPort: async () => 9222,
		spawn: () => {
			events.push("spawn");
			return child;
		},
		waitForCdp: async () => {
			events.push("cdp");
		},
		removeProfile: async () => {
			events.push("remove");
		},
		report: diagnostic => diagnostics.push(diagnostic),
		...overrides,
	};
	return { host, child, events, diagnostics, probe: createChromiumProbe(host) };
}

describe("Chromium test availability diagnostics", () => {
	it("rejects a browser that exits before a successful CDP response instead of accepting a reused port", async () => {
		const state = harness({ ci: () => "true" });
		Object.defineProperty(state.child, "exited", { value: Promise.resolve(127) });
		await assert.rejects(state.probe.chromiumAvailable(), /Chromium unavailable in CI/);
		assert.equal(state.diagnostics[0]!.error.stage, "cdp");
		assert.equal(state.events.includes("kill"), true);
		assert.equal(state.events.includes("remove"), true);
	});

	it("fails CI instead of silently skipping every importing suite, with a single cached diagnostic", async () => {
		const state = harness({
			ci: () => "true",
			waitForCdp: async () => {
