const CHROMIUM_AVAILABLE = await chromiumAvailable();
const ASSETS = path.resolve(import.meta.dir, "../../src/tools/browser/relay/extension-assets");

interface TestWorker {
	outcome: Promise<Extract<WorkerOutbound, { type: "ready" | "init-failed" }>>;
	close(): Promise<void>;
}

function startWorker(payload: WorkerInitPayload): TestWorker {
	const outcome = Promise.withResolvers<Extract<WorkerOutbound, { type: "ready" | "init-failed" }>>();
	const closed = Promise.withResolvers<void>();
	let receive!: (message: WorkerInbound | WorkerOutbound) => void;
	new WorkerCore(
		{
			send(message) {
				if (message.type === "ready" || message.type === "init-failed") outcome.resolve(message);
			},
			onMessage(handler) {
				receive = handler;
				return () => {};
			},
			close() {
				closed.resolve();
			},
		},
		false,
	);
	receive({ type: "init", payload });
	return {
		outcome: outcome.promise,
		async close() {
			receive({ type: "close" });
			await closed.promise;
		},
	};
}

interface RelayBrowser {
	browser: Browser;
	/** Evaluates `expression` on an extension page, where Chrome's tab and runtime APIs are in scope. */
	inExtension(expression: string): Promise<unknown>;
}

interface RelayFixture extends RelayBrowser {
	server: RelayServer;
	cdpUrl: string;
	origin: string;
	/** Another Chromium with its own profile and the same extension, as a second browser on the relay. */
	launchBrowser(): Promise<RelayBrowser>;
	close(): Promise<void>;
}

/**
 * Headless Chromium running the real relay extension against a relay on a free port, plus a loopback
 * site. A test-only message listener controls its service worker: a programmatic debugger detach does
 * not fire `onDetach`, and `testRefuseRemoves` makes that many `chrome.tabs.remove` calls reject first.
 */
async function launchRelayFixture(
	log?: (message: string, data?: Record<string, unknown>) => void,
): Promise<RelayFixture> {
	const port = await findFreeCdpPort();
	const server = startRelayServer({ port, group: false, log });
	const extensionDir = await fs.mkdtemp(path.join(os.tmpdir(), "omp-relay-isolation-"));
	const pages = Bun.serve({
		port: 0,
		fetch(request) {
			const route = new URL(request.url).pathname;
			const html =
				route === "/first"
					? `<title>First</title><button onclick="this.textContent='clicked'">First</button><p id="hover" onmouseover="this.textContent='hovered'">Hover</p>`
					: route === "/second"
						? "<title>Second</title><button>Second</button>"
						: "<title>Human sentinel</title><h1>Keep me</h1>";
			return new Response(html, { headers: { "Content-Type": "text/html" } });
		},
	});
	const browsers: Browser[] = [];
	async function close() {
		try {
			await Promise.all(browsers.map(browser => closeLaunchedBrowser(browser)));
		} finally {
			server.stop();
			pages.stop(true);
			await fs.rm(extensionDir, { recursive: true, force: true });
		}
	}
	async function launchBrowser(): Promise<RelayBrowser> {
		const browser = await puppeteer.launch({
			executablePath: await ensureChromiumExecutable(),
			headless: true,
			pipe: true,
			enableExtensions: [extensionDir],
			args: ["--no-first-run", "--no-default-browser-check", "--use-mock-keychain", ...RENDERER_PRIORITY_ARGS],
		});
		browsers.push(browser);
		const extensionId = await unpackedExtensionId(extensionDir);
		if (!extensionId) throw new Error("Missing relay extension directory");
		// A service worker is transient: it may start and stop before Puppeteer observes its target.
		// An extension page can wake it via runtime messaging and remains available for tab queries.
		const page = await browser.newPage();
		// Chrome registers an unpacked extension asynchronously after `Extensions.loadUnpacked`
		// returns; until then its pages fail with ERR_BLOCKED_BY_CLIENT. No CDP event marks
		// registration (the service worker target is transient), so poll the real browser.
		const deadline = Date.now() + 10_000;
		for (;;) {
			try {
				await page.goto(`chrome-extension://${extensionId}/options.html`);
				break;
			} catch (error) {
				if (!String(error).includes("ERR_BLOCKED_BY_CLIENT") || Date.now() > deadline) throw error;
				await Bun.sleep(50);
			}
		}
		// Puppeteer's `page.evaluate` lands in a context without the extension APIs; the page's
		// default context, which `Runtime.evaluate` targets, has them.
		const cdp = await page.createCDPSession();
		async function inExtension(expression: string): Promise<unknown> {
			const { result, exceptionDetails } = await cdp.send("Runtime.evaluate", {
				expression,
				awaitPromise: true,
				returnByValue: true,
			});
			if (exceptionDetails) throw new Error(exceptionDetails.exception?.description ?? exceptionDetails.text);
			return result.value;
		}
		return { browser, inExtension };
	}
	try {
		for (const file of ["manifest.json", "options.html", "options.js"]) {
			await fs.copyFile(path.join(ASSETS, `${file}.txt`), path.join(extensionDir, file));
		}
		const background = await fs.readFile(path.join(ASSETS, "background.js.txt"), "utf8");
		const defaultPort = "var DEFAULT_PORT = 9224;";
		if (!background.includes(defaultPort)) throw new Error("Relay extension default port not found");
		// Point the disposable extension at this relay without deferring listener registration.
		await fs.writeFile(
			path.join(extensionDir, "background.js"),
			`const testRegisterDetach = chrome.debugger.onDetach.addListener.bind(chrome.debugger.onDetach);
chrome.debugger.onDetach.addListener = listener => {
	globalThis.testDebuggerDetach = listener;
	testRegisterDetach(listener);
};
const testRemoveTab = chrome.tabs.remove.bind(chrome.tabs);
chrome.tabs.remove = tabId => {
	if (globalThis.testRefuseRemoves > 0) {
		globalThis.testRefuseRemoves--;
		return Promise.reject(new Error("Tabs cannot be edited right now (user may be dragging a tab)."));
	}
	return testRemoveTab(tabId);
};
chrome.runtime.onMessage.addListener((message, _sender, respond) => {
	if (message.op === "refuseRemoves") {
		globalThis.testRefuseRemoves = message.count;
		respond({});
	} else if (message.op === "dismissDebugger") {
		chrome.debugger.detach({ tabId: message.tabId }).then(() => {
			globalThis.testDebuggerDetach({ tabId: message.tabId }, "canceled_by_user");
			respond({});
		}, error => respond({ error: String(error) }));
		return true;
	}
});
${background.replace(defaultPort, `var DEFAULT_PORT = ${port};`)}`,
		);
		const { browser, inExtension } = await launchBrowser();
		const cdpUrl = `http://127.0.0.1:${port}`;
		// Finish the extension hello before the native CDP client attaches to the sentinel.
		const outcome = await waitForRelayExtension(cdpUrl);
		if (outcome !== "ready") throw new Error(`Relay fixture handshake failed: ${outcome}`);
		return {
			browser,
			inExtension,
			server,
			cdpUrl,
			origin: `http://127.0.0.1:${pages.port}`,
			launchBrowser,
			close,
		};
	} catch (error) {
		await close();
		throw error;
	}
}

function chromeTabId(targetId: string): number {
	return Number(targetId.slice(targetId.lastIndexOf(".") + 1));
}

/** Chrome's own view of a tab (`{ active }`), or null once it is closed. */
async function chromeTab(fixture: RelayFixture, tabId: number): Promise<unknown> {
	return await fixture.inExtension(
		`chrome.tabs.query({}).then(tabs => { const tab = tabs.find(tab => tab.id === ${tabId}); return tab ? { active: tab.active } : null; })`,
	);
}

async function activeChromeTabUrl(fixture: RelayFixture): Promise<unknown> {
	return await fixture.inExtension(
		"chrome.tabs.query({ active: true, lastFocusedWindow: true }).then(tabs => tabs[0]?.url)",
	);
}

const session = {
	cwd: process.cwd(),
	hasUI: false,
	settings: Settings.isolated(),
	getSessionFile: () => null,
} as unknown as ToolSession;

describe.skipIf(!CHROMIUM_AVAILABLE)("relay tab ownership", () => {
	it("opens default relay tabs in the background and closes them, leaving borrowed pages open", async () => {
		const fixture = await launchRelayFixture();
		const human = await fixture.browser.newPage();
		const humanUrl = `${fixture.origin}/human`;
		await human.goto(humanUrl);
		await human.bringToFront();
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		const names = [`relay-first-${process.pid}`, `relay-second-${process.pid}`, `relay-borrowed-${process.pid}`];
		try {
			const first = await acquireTab(names[0]!, relay, { url: `${fixture.origin}/first`, timeoutMs: 15_000 });
			// An open that adopted the selected tab would have navigated it to the `url`.
			expect(human.url()).toBe(humanUrl);
			const second = await acquireTab(names[1]!, relay, { url: `${fixture.origin}/second`, timeoutMs: 15_000 });
			expect(first.tab.targetId).not.toBe(second.tab.targetId);
			expect(human.url()).toBe(humanUrl);
			expect(await human.title()).toBe("Human sentinel");
			// The user's tab stays selected; the owned tabs were created unselected.
			expect(await activeChromeTabUrl(fixture)).toBe(humanUrl);
			expect(await chromeTab(fixture, chromeTabId(first.tab.targetId))).toEqual({ active: false });

			const clicked = await runInTab(names[0]!, {
				code: "await tab.click('button'); return await tab.text('button');",
				timeoutMs: 10_000,
				session,
			});
			expect(clicked.returnValue).toBe("clicked");
			// Hover waits for a rendered frame, which a hidden tab never produces: this passes only while the
			// unselected tab is focus-emulated.
			const hovered = await runInTab(names[0]!, {
				code: "await tab.hover('#hover'); return await tab.text('#hover');",
				timeoutMs: 10_000,
				session,
			});
			expect(hovered.returnValue).toBe("hovered");
			// A screenshot of the unselected tab is captured in place: it never selects the tab.
			const shot = await runInTab(names[0]!, {
				code: "return typeof (await tab.screenshot());",
				timeoutMs: 10_000,
				session,
			});
			expect(shot.returnValue).toBe("string");
			expect(await activeChromeTabUrl(fixture)).toBe(humanUrl);
			expect(await chromeTab(fixture, chromeTabId(first.tab.targetId))).toEqual({ active: false });

			await releaseTab(names[0]!);
			expect(await chromeTab(fixture, chromeTabId(first.tab.targetId))).toBeNull();
			expect(await human.title()).toBe("Human sentinel");
			const surviving = await runInTab(names[1]!, { code: "return await tab.title();", timeoutMs: 10_000, session });
			expect(surviving.returnValue).toBe("Second");

			// `app.target` borrows the user's page; closing releases it without closing it.
			const borrowed = await acquireTab(names[2]!, relay, { target: "Human sentinel", timeoutMs: 15_000 });
			expect(borrowed.tab.targetId).not.toBe(first.tab.targetId);
			await releaseTab(names[2]!);
			expect(human.isClosed()).toBeFalse();
			expect(await human.title()).toBe("Human sentinel");
		} finally {
			for (const name of names) await releaseTab(name).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);

	it("opens a default tab in the browser of the tab omp used last, not the first selected one", async () => {
		const secondHello = Promise.withResolvers<void>();
		let hellos = 0;
		const fixture = await launchRelayFixture(message => {
			if (message === "extension connected" && ++hellos === 2) secondHello.resolve();
		});
		// The first browser shows the first selected tab, which a new tab would otherwise follow.
		const human = await fixture.browser.newPage();
		await human.goto(`${fixture.origin}/human`);
		await human.bringToFront();
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		const names = [
			`relay-near-human-${process.pid}`,
			`relay-near-other-${process.pid}`,
			`relay-near-own-${process.pid}`,
		];
		/** The browser a relay target id belongs to (`PAGE<browser>.<tab>`). */
		const browserOf = (targetId: string) => targetId.slice(4, targetId.lastIndexOf("."));
		try {
			// Borrowing waits until the relay lists the tab, so the first browser's selected tab is listed first.
			const inFirst = await acquireTab(names[0]!, relay, { target: "Human sentinel", timeoutMs: 15_000 });
			const other = await fixture.launchBrowser();
			// The relay announces a browser's tabs to connected clients only as they change after its hello.
			await secondHello.promise;
			await (await other.browser.newPage()).goto(`${fixture.origin}/first`);
			const inSecond = await acquireTab(names[1]!, relay, { target: "First", timeoutMs: 15_000 });
			expect(browserOf(inSecond.tab.targetId)).not.toBe(browserOf(inFirst.tab.targetId));
			const owned = await acquireTab(names[2]!, relay, { url: `${fixture.origin}/second`, timeoutMs: 15_000 });
			expect(browserOf(owned.tab.targetId)).toBe(browserOf(inSecond.tab.targetId));
		} finally {
			for (const name of names) await releaseTab(name).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);

	it("closes an owned tab Chrome refuses to close at first", async () => {
		const fixture = await launchRelayFixture();
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		const name = `relay-refused-close-${process.pid}`;
		try {
			const { tab } = await acquireTab(name, relay, { url: `${fixture.origin}/first`, timeoutMs: 15_000 });
			// A release sends two closes (the worker's, then the supervisor's by id); Chrome refuses the first two tries.
			await fixture.inExtension('chrome.runtime.sendMessage({ op: "refuseRemoves", count: 2 })');
			await releaseTab(name);
			// The close returned with the tab gone.
			expect(await chromeTab(fixture, chromeTabId(tab.targetId))).toBeNull();
		} finally {
			await releaseTab(name).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);

	it("leaves a persist tab open in the user's browser when its session ends and closes the others", async () => {
		const fixture = await launchRelayFixture();
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		const owner = `relay-session-${process.pid}`;
		const names = [`relay-persist-${process.pid}`, `relay-plain-${process.pid}`];
		try {
			const kept = await acquireTab(names[0]!, relay, {
				url: `${fixture.origin}/first`,
				timeoutMs: 15_000,
				ownerSessionId: owner,
				persist: true,
			});
			const closed = await acquireTab(names[1]!, relay, {
				url: `${fixture.origin}/second`,
				timeoutMs: 15_000,
				ownerSessionId: owner,
			});
			// What session dispose runs.
			expect(await releaseTabsForOwner(owner, { kill: true })).toBe(2);
			const keptTabId = chromeTabId(kept.tab.targetId);
			expect(await fixture.inExtension(`chrome.tabs.get(${keptTabId}).then(tab => tab.url)`)).toBe(
				`${fixture.origin}/first`,
			);
			expect(await chromeTab(fixture, chromeTabId(closed.tab.targetId))).toBeNull();
			expect(getTabsMapForTest().has(names[0]!)).toBeFalse();
		} finally {
			for (const name of names) await releaseTab(name).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);

	it("closes a persist tab whose close joins its session's end", async () => {
		const fixture = await launchRelayFixture();
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		const owner = `relay-joined-session-${process.pid}`;
		const name = `relay-joined-close-${process.pid}`;
		try {
			const { tab } = await acquireTab(name, relay, {
				url: `${fixture.origin}/first`,
				timeoutMs: 15_000,
				ownerSessionId: owner,
				persist: true,
			});
			const ending = releaseTabsForOwner(owner, { kill: true });
			expect(await releaseTab(name)).toBe(true);
			await ending;
			expect(await chromeTab(fixture, chromeTabId(tab.targetId))).toBeNull();
		} finally {
			await releaseTab(name).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);

	it("closes a persist tab when its close joins after the keep decision and browser disconnect", async () => {
		const fixture = await launchRelayFixture();
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		if (!("browser" in relay)) throw new Error("Expected relay Chromium");
		const owner = `relay-late-session-${process.pid}`;
		const name = `relay-late-close-${process.pid}`;
		const disconnect = relay.browser.disconnect.bind(relay.browser);
		let closing: Promise<boolean> | undefined;
		try {
			const { tab } = await acquireTab(name, relay, {
				url: `${fixture.origin}/first`,
				timeoutMs: 15_000,
				ownerSessionId: owner,
				persist: true,
			});
			// releaseBrowser disconnects only after the supervisor has decided to keep the page.
			relay.browser.disconnect = () => {
				const disconnected = disconnect();
				closing = releaseTab(name);
				return disconnected;
			};
			await releaseTabsForOwner(owner, { kill: true });
			expect(closing).toBeDefined();
			expect(await closing).toBe(true);
			expect(await chromeTab(fixture, chromeTabId(tab.targetId))).toBeNull();
		} finally {
			relay.browser.disconnect = disconnect;
			await releaseTab(name).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);

	it("closes an owned relay tab whose debugger the user dismissed", async () => {
		const detached = Promise.withResolvers<void>();
		let ownedTabId = 0;
		const fixture = await launchRelayFixture((message, data) => {
			if (message === "tab detached" && typeof data?.tabKey === "string" && data.tabKey.endsWith(`:${ownedTabId}`))
				detached.resolve();
		});
		const relay = await acquireBrowser({ kind: "relay", cdpUrl: fixture.cdpUrl }, { cwd: process.cwd() });
		const name = `relay-detached-${process.pid}`;
		const otherName = `relay-detached-other-${process.pid}`;
		try {
			const human = await fixture.browser.newPage();
			await human.goto(`${fixture.origin}/human`);
			const { tab: other } = await acquireTab(otherName, relay, {
				url: `${fixture.origin}/second`,
				timeoutMs: 20_000,
			});
			const { tab } = await acquireTab(name, relay, { url: `${fixture.origin}/first`, timeoutMs: 20_000 });
			ownedTabId = chromeTabId(tab.targetId);
			expect(fixture.server.bridge.listTargets().some(target => target.id === tab.targetId)).toBeTrue();
			// Replay the infobar dismissal through the extension's real listener.
			const result = await fixture.inExtension(
				`chrome.runtime.sendMessage({ op: "dismissDebugger", tabId: ${ownedTabId} })`,
			);
			expect(result).toEqual({});
			await detached.promise;
			expect(fixture.server.bridge.listTargets().some(target => target.id === tab.targetId)).toBeFalse();
			expect(await chromeTab(fixture, ownedTabId)).not.toBeNull();
			await releaseTab(name);
			expect(await chromeTab(fixture, ownedTabId)).toBeNull();
			expect(await chromeTab(fixture, chromeTabId(other.targetId))).not.toBeNull();
			expect(await human.title()).toBe("Human sentinel");
		} finally {
			await releaseTab(name).catch(() => undefined);
			await releaseTab(otherName).catch(() => undefined);
			await releaseBrowser(relay, { kill: false });
			await fixture.close();
		}
	}, 60_000);
});

describe.skipIf(!CHROMIUM_AVAILABLE)("owned tab recovery", () => {
	it("keeps an owned target alive after a failed recovery init so a retry can adopt it", async () => {
		const launched = await acquireBrowser({ kind: "headless", headless: true }, { cwd: process.cwd() });
		if (!("browser" in launched)) throw new Error("Expected Chromium");
		const page = await launched.browser.newPage();
		await page.goto("data:text/html,<title>Recovery sentinel</title>");
		const target = page.target();
		if (!("_targetId" in target) || typeof target._targetId !== "string") throw new Error("Missing target ID");
		const payload: WorkerInitPayload = {
			mode: "attach",
			browserWSEndpoint: launched.wsEndpoint,
			safeDir: getPuppeteerDir(),
			uploadDir: "/tmp/omp-uploads-test",
			page: { kind: "owned", targetId: target._targetId },
			recover: true,
		};
		const downloadDir = await fs.mkdtemp(path.join(os.tmpdir(), "omp-recovery-download-"));
		const blockedDownloadPath = path.join(downloadDir, "not-a-directory");
		await fs.writeFile(blockedDownloadPath, "existing file");
		const failed = startWorker({ ...payload, downloadsPath: blockedDownloadPath });
		let retried: TestWorker | undefined;
		try {
			expect((await failed.outcome).type).toBe("init-failed");
			expect(page.isClosed()).toBeFalse();
			retried = startWorker(payload);
			const ready = await retried.outcome;
			if (ready.type !== "ready") throw new Error("Expected the retry to adopt the owned target");
			expect(ready.info.targetId).toBe(target._targetId);
			await retried.close();
			retried = undefined;
			// Closing the worker that owns the page closes it. Ask Chrome: this connection's `page`
			// learns of the close only once its own target event arrives.
			const { targetInfos } = await launched.browser
				.target()
				.createCDPSession()
				.then(async session => {
					const targets = await session.send("Target.getTargets");
					await session.detach();
					return targets;
				});
			expect(targetInfos.map(info => info.targetId)).not.toContain(target._targetId);
		} finally {
			await retried?.close();
			await failed.close();
			await page.close().catch(() => undefined);
			await fs.rm(downloadDir, { recursive: true, force: true });
			await releaseBrowser(launched, { kill: true });
		}
	}, 30_000);
});

/**
 * Regression tests for the wedged shared browser (field incident 2026-09-27,
 * omp 18.3.1): under memory pressure the project-shared broker-owned Chromium
 * stopped answering CDP, so every tab close ended at the bounded
 * `orphan CDP target … (Page.close)` timeout.
 *
 * Two leaks followed that timeout:
 *
 * - `releaseTabInner` dropped the target's durable ownership record even though
 *   the target was never closed, so the surviving page became invisible to
 *   every later reap; and
 * - the shared Chromium is health-checked only while attaching
 *   (`ensureSharedBrowser`), and `acquireBrowser` reuses a cached handle while
 *   `browser.connected` is still true — so nothing re-probed an unreachable
 *   browser while a session lived. The 9.1 GB / 44-process tree survived 19 h
 *   until the last omp client in the project exited.
 *
 * Contract pinned here: a timed-out target close keeps the ownership record and
 * re-checks the shared browser, and that check stops the daemon only when the
 * CDP endpoint no longer answers.
 */

import { afterEach, describe, expect, it, spyOn, vi } from "bun:test";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { withTimeout } from "@oh-my-pi/pi-utils";
import { Settings } from "@oh-my-pi/pi-coding-agent/config/settings";
import type { DaemonBrokerClient } from "@oh-my-pi/pi-coding-agent/launch/client";
import { daemonRuntimeDir } from "@oh-my-pi/pi-coding-agent/launch/paths";
import type { DaemonOperation } from "@oh-my-pi/pi-coding-agent/launch/protocol";
import {
	forgetSharedTarget,
	recordSharedTarget,
	resetOrphanRegistryForTest,
	type SharedTargetScope,
} from "@oh-my-pi/pi-coding-agent/tools/browser/orphan-registry";
import * as orphanRegistry from "@oh-my-pi/pi-coding-agent/tools/browser/orphan-registry";
import type { BrowserHandle } from "@oh-my-pi/pi-coding-agent/tools/browser/registry";
import * as relayOwnedTargets from "@oh-my-pi/pi-coding-agent/tools/browser/relay/owned-targets";
import * as sharedDaemon from "@oh-my-pi/pi-coding-agent/tools/browser/shared-daemon";
import { stopSharedBrowserIfUnreachable } from "@oh-my-pi/pi-coding-agent/tools/browser/shared-daemon";
import { getTabsMapForTest, releaseTab, runInTab } from "@oh-my-pi/pi-coding-agent/tools/browser/tab-supervisor";
import type { TabSession } from "@oh-my-pi/pi-coding-agent/tools/browser/tab-supervisor";
import type { ToolSession } from "@oh-my-pi/pi-coding-agent/tools/index";
import type { DaemonSnapshot } from "@oh-my-pi/pi-tui/tools/daemon";

const DAEMON_NAME = "omp.browser.headless";
/** The target id the incident log names for the tab whose close never landed. */
const TARGET_ID = "D6895F960DB1F4D842FD7B0286F3F818";

/** Unique per-test scope so registry dirs never collide across the suite. */
function makeScope(): SharedTargetScope {
	return { projectDir: path.join("/tmp", `omp-wedge-test-${crypto.randomUUID()}`), daemonName: DAEMON_NAME };
}

/** Scopes created since the last sweep; `afterEach` removes them even when a test fails. */
const scopes: SharedTargetScope[] = [];

/** A scope registered for cleanup, so no assertion failure can leave it on disk. */
function trackedScope(): SharedTargetScope {
	const scope = makeScope();
	scopes.push(scope);
	return scope;
}

/** Targets this process still claims ownership of, straight from the durable record. */
async function ownedTargets(scope: SharedTargetScope): Promise<string[]> {
	// Reading straight after `releaseTab` would race the registry's serialized
	// write chain (the supervisor forgets fire-and-forget). A record→forget pair
	// for a throwaway id joins that chain, so when it returns the earlier write
	// has landed and the file below is stable.
	const probe = `chain-probe-${crypto.randomUUID()}`;
	await recordSharedTarget(scope, probe);
	await forgetSharedTarget(scope, probe);
	const file = path.join(daemonRuntimeDir(scope.projectDir), `${scope.daemonName}.targets`, `${process.pid}.json`);
	const raw = await Bun.file(file)
		.text()
		.catch(() => null);
	if (raw === null) return [];
	const parsed: unknown = JSON.parse(raw);
	if (typeof parsed !== "object" || parsed === null || !("targets" in parsed)) return [];
	const { targets } = parsed;
	return Array.isArray(targets) ? targets.filter((id): id is string => typeof id === "string") : [];
}

/** How the stub's CDP close behaves: never answers, fails fast, or fails after a gate. */
interface WedgeOptions {
	/** Whether the handle carries the shared-daemon scope (`false` = private launch). */
	shared?: boolean;
	close?: "hang" | "fail" | "gate";
	/** Held by a `gate` close until the test releases it. */
	gate?: Promise<void>;
	/** Fires when a `gate` close starts, so the test can interleave a release. */
	entered?: () => void;
	/** Counts worker terminations instead of the default no-op. */
	onTerminate?: () => void;
}

/** Handle for a shared Chromium whose CDP endpoint answers nothing: every call hangs. */
function makeWedgeHandle(scope: SharedTargetScope, options: WedgeOptions = {}): BrowserHandle {
	const { shared = true, close = "hang", gate, entered } = options;
	const session = {
		send: async (): Promise<never> => {
			if (close === "fail") throw new Error("CDP target session unavailable");
			if (close === "gate") {
				entered?.();
				await gate;
				throw new Error("CDP target session unavailable");
			}
			return await new Promise<never>(() => {});
		},
		on: (): void => undefined,
		off: (): void => undefined,
		detach: async (): Promise<void> => undefined,
	};
	const handle: Record<string, unknown> = {
		key: "headless:1::",
		kind: { kind: "headless", headless: true },
		// Another tab still holds the shared browser: closing this one must not
		// dispose the handle (that is what leaves the target behind in Chrome).
		refCount: 2,
		stealth: { browserSession: null, override: null },
		browser: {
			connected: true,
			targets: () => [],
			target: () => ({ createCDPSession: async () => session }),
			disconnect: () => undefined,
		},
	};
	if (shared) handle.sharedDaemon = { name: scope.daemonName, projectDir: scope.projectDir };
	return handle as unknown as BrowserHandle;
}

/** Tab whose page-close handshake never completes, so cleanup runs the forced path. */
function makeWedgeTab(scope: SharedTargetScope, options: WedgeOptions = {}): TabSession {
	return {
		name: "logos-b2b",
		browser: makeWedgeHandle(scope, options),
		targetId: TARGET_ID,
		backend: "worker",
		state: "alive",
		info: {},
		pending: new Map(),
		kindTag: "headless",
		ownsPage: true,
		ownerSessionId: "session-wedge",
		persist: false,
		lastActivityAt: Date.now(),
		frozen: false,
		worker: {
			send: () => undefined,
			onMessage: () => () => undefined,
			onError: () => () => undefined,
			terminate: async () => {
				options.onTerminate?.();
			},
		},
	} as unknown as TabSession;
}

/** Minimal tool session for the `runInTab` entry point. */
function makeSession(): ToolSession {
	return {
		cwd: "/tmp/omp-wedge-session",
		hasUI: false,
		settings: Settings.isolated(),
		getSessionFile: () => null,
	} as unknown as ToolSession;
}

function makeSnapshot(readyMatch: string | undefined): DaemonSnapshot {
	return {
		name: DAEMON_NAME,
		id: "daemon-wedge",
		state: "ready",
		createdAt: 0,
		startedAt: 0,
		readyAt: 1,
		restartCount: 0,
		outputBytes: 0,
		persist: false,
		detached: false,
		...(readyMatch === undefined ? {} : { readyMatch }),
	};
}

/**
 * Broker double: answers `describe` with a snapshot, records every `stop`, and
 * reports a terminal snapshot for a stop unless told otherwise — a real broker
 * returns the post-stop record, so a stop that never landed is either a
 * rejected request (`stopFails`) or a non-terminal snapshot (`stopState`).
 */
function makeBroker(
	opts: { snapshot?: DaemonSnapshot; fail?: boolean; stopFails?: boolean; stopState?: DaemonSnapshot["state"] },
	stops: string[],
): DaemonBrokerClient {
	return {
		projectDir: "/tmp/omp-wedge-broker",
		close: () => undefined,
		onCompletion: () => () => undefined,
		request: async (operation: DaemonOperation) => {
			if (opts.fail === true) throw new Error("broker unreachable");
			if (operation.op === "describe") return { op: "describe", daemon: opts.snapshot };
			if (operation.op === "stop") {
				stops.push(operation.name);
				if (opts.stopFails === true) throw new Error("broker rejected the stop");
				const stopped = { ...(opts.snapshot ?? makeSnapshot(undefined)), state: opts.stopState ?? "exited" };
				return { op: "stop", daemon: stopped };
			}
			throw new Error(`unexpected broker op ${operation.op}`);
		},
	} as unknown as DaemonBrokerClient;
}

/** Live endpoint string as the broker stamps it once Chrome's listener is up. */
const READY_MATCH = "DevTools listening on ws://127.0.0.1:63199/devtools/browser/wedged";

afterEach(async () => {
	vi.restoreAllMocks();
	resetOrphanRegistryForTest();
	// oxlint-disable-next-line unicorn/no-useless-spread -- releasing tabs mutates the map
	for (const name of [...getTabsMapForTest().keys()]) {
		await releaseTab(name, { kill: false }).catch(() => undefined);
	}
	for (const scope of scopes.splice(0)) {
		await fs.rm(daemonRuntimeDir(scope.projectDir), { recursive: true, force: true }).catch(() => undefined);
	}
});

describe("browser cleanup — timed-out target close in a shared browser", () => {
	it("keeps the ownership record and re-checks the shared browser", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		await recordSharedTarget(scope, TARGET_ID);
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);

		getTabsMapForTest().set("logos-b2b", makeWedgeTab(scope));
		await expect(releaseTab("logos-b2b", { timeoutMs: 60 })).rejects.toThrow(
			`Timed out after 60ms closing headless browser tab "logos-b2b"; pending resource: orphan CDP target ${JSON.stringify(TARGET_ID)} (Page.close)`,
		);

		// The tab still leaves the map (the close is reported as failed)...
		expect(getTabsMapForTest().has("logos-b2b")).toBe(false);
		// ...but the target it never closed stays owned, so a later reap can
		// still find it, and the browser itself is re-checked for reachability.
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).toHaveBeenCalledTimes(1);
		expect(healthCheck.mock.calls[0]?.[0]).toEqual(scope);
	});

	it("forgets the retained target once the browser it belonged to is stopped", async () => {
		const scope = trackedScope();
		// The check proves the whole browser gone: the target that could not be
		// closed died with it, so its record must not linger until this process
		// exits and be rewritten on every later write.
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(true);
		await recordSharedTarget(scope, TARGET_ID);
		getTabsMapForTest().set("logos-b2b", makeWedgeTab(scope, { close: "fail" }));

		await expect(releaseTab("logos-b2b", { timeoutMs: 60 })).resolves.toBe(true);

		expect(healthCheck).toHaveBeenCalledTimes(1);
		expect(await ownedTargets(scope)).toEqual([]);
	});

	it("still forgets a tab that was already dead when it was released", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		await recordSharedTarget(scope, TARGET_ID);
		const tab = makeWedgeTab(scope);
		tab.state = "dead";
		getTabsMapForTest().set("logos-b2b", tab);

		await expect(releaseTab("logos-b2b", { timeoutMs: 60 })).resolves.toBe(true);

		expect(await ownedTargets(scope)).toEqual([]);
		expect(healthCheck).not.toHaveBeenCalled();
	});

	it("force-kills a wedged tab without forgetting the target it could not close", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		await recordSharedTarget(scope, TARGET_ID);
		// `runInTab` reaching its grace period is one of the two real entry points
		// into `forceKillTab` (the other is a failed worker recycle — the
		// incident's "Failed to recycle browser tab worker; killing tab").
		getTabsMapForTest().set("logos-b2b", makeWedgeTab(scope, { close: "fail" }));

		await expect(
			runInTab("logos-b2b", { code: "await wait(60_000);", timeoutMs: 20, session: makeSession() }),
		).rejects.toThrow("hung past grace");

		expect(getTabsMapForTest().has("logos-b2b")).toBe(false);
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).toHaveBeenCalledTimes(1);
		expect(healthCheck.mock.calls[0]?.[0]).toEqual(scope);
	});

	it("lets a release join an in-flight force-kill instead of tearing the tab down twice", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		await recordSharedTarget(scope, TARGET_ID);
		const gate = Promise.withResolvers<void>();
		const entered = Promise.withResolvers<void>();
		let terminations = 0;
		const tab = makeWedgeTab(scope, {
			close: "gate",
			gate: gate.promise,
			entered: () => entered.resolve(),
			onTerminate: () => terminations++,
		});
		getTabsMapForTest().set("logos-b2b", tab);

		const killed = runInTab("logos-b2b", {
			code: "await wait(60_000);",
			timeoutMs: 20,
			session: makeSession(),
		}).catch((error: Error) => error.message);
		// Force-kill is now parked inside the CDP close: the release that lands
		// here must join it, not release the browser hold a second time or make
		// its own ownership decision.
		await entered.promise;
		expect(tab.state).toBe("dead");
		expect(tab.browser.refCount).toBe(2);
		// The release must join the in-flight force-kill, so it settles only when
		// that teardown does — hence starting it, not awaiting it, before the gate.
		const released = releaseTab("logos-b2b", { timeoutMs: 40 });
		gate.resolve();
		// The join reports the release contract, not the target-close outcome:
		// the tab is gone either way, and a surviving target is kept in the
		// registry (asserted below) rather than reported as an unreleased tab.
		expect(await released).toBe(true);
		await killed;

		expect(terminations).toBe(1);
		expect(tab.browser.refCount).toBe(1);
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).toHaveBeenCalledTimes(1);
	});

	it("bounds the close a joining release waits on when force-kill is stuck on a wedged browser", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		await recordSharedTarget(scope, TARGET_ID);
		// Never resolves: the CDP close hangs exactly as it does against a wedged
		// Chromium, so only the supervisor's own close budget can end this wait.
		const wedged = Promise.withResolvers<void>();
		const entered = Promise.withResolvers<void>();
		getTabsMapForTest().set(
			"logos-b2b",
			makeWedgeTab(scope, { close: "gate", gate: wedged.promise, entered: () => entered.resolve() }),
		);

		const killed = runInTab("logos-b2b", {
			code: "await wait(60_000);",
			timeoutMs: 20,
			session: makeSession(),
		}).catch((error: Error) => error.message);
		await entered.promise;

		// A release joining the force-kill must not inherit an unbounded CDP wait
		// (Puppeteer's protocol timeout is 60 s); the supervisor's 5 s close
		// budget ends it, and the join still reports the tab as released.
		const joined = await withTimeout(
			releaseTab("logos-b2b", { timeoutMs: 50 }),
			9_000,
			"joined release outlived the force-kill close budget",
		).catch(() => "timed-out" as const);
		expect(joined).toBe(true);

		await killed;
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).toHaveBeenCalledTimes(1);
	}, 20_000);

	it("never checks a browser that is not the shared one", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		getTabsMapForTest().set("logos-b2b", makeWedgeTab(scope, { shared: false }));

		await expect(releaseTab("logos-b2b", { timeoutMs: 60 })).rejects.toThrow("Timed out after 60ms");

		expect(healthCheck).not.toHaveBeenCalled();
	});

	it("treats an unconfirmed close (CDP session failure) as unclosed too", async () => {
		const scope = trackedScope();
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
		await recordSharedTarget(scope, TARGET_ID);
		getTabsMapForTest().set("logos-b2b", makeWedgeTab(scope, { close: "fail" }));

		await expect(releaseTab("logos-b2b", { timeoutMs: 60 })).resolves.toBe(true);

		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).toHaveBeenCalledTimes(1);
	});
});

describe("relay cleanup after a failed worker close", () => {
	function relayTab(scope: SharedTargetScope, ownsTarget = true): TabSession {
		const tab = makeWedgeTab(scope, { shared: false });
		if (tab.backend !== "worker") throw new Error("Expected worker tab fixture");
		tab.kindTag = "relay";
		tab.ownsPage = ownsTarget;
		tab.browser.kind = { kind: "relay", cdpUrl: "http://127.0.0.1:9224" };
		tab.browser.cdpUrl = "http://127.0.0.1:9224";
		tab.browser.browser.wsEndpoint = () => "ws://127.0.0.1:9224/cdp";
		spyOn(relayOwnedTargets, "relayTargetScope").mockReturnValue(scope);
		return tab;
	}

	it.each([false, true])("retains only unconfirmed relay target ownership after release (closed=%s)", async closed => {
		const scope = trackedScope();
		const close = spyOn(relayOwnedTargets, "closeRelayTarget").mockResolvedValue(closed);
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(true);
		await recordSharedTarget(scope, TARGET_ID);
		getTabsMapForTest().set("logos-b2b", relayTab(scope));

		expect(await releaseTab("logos-b2b", { timeoutMs: 60 })).toBe(true);

		expect(close).toHaveBeenCalledTimes(1);
		expect(close).toHaveBeenCalledWith("ws://127.0.0.1:9224/cdp", TARGET_ID);
		expect(await ownedTargets(scope)).toEqual(closed ? [] : [TARGET_ID]);
		expect(healthCheck).not.toHaveBeenCalled();
	});

	it("force-kills an owned relay tab while retaining a failed close without stopping the user's browser", async () => {
		const scope = trackedScope();
		const close = spyOn(relayOwnedTargets, "closeRelayTarget").mockResolvedValue(false);
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(true);
		await recordSharedTarget(scope, TARGET_ID);
		getTabsMapForTest().set("logos-b2b", relayTab(scope));

		await expect(
			runInTab("logos-b2b", { code: "await wait(60_000);", timeoutMs: 20, session: makeSession() }),
		).rejects.toThrow("hung past grace");

		expect(close).toHaveBeenCalledTimes(1);
		expect(close).toHaveBeenCalledWith("ws://127.0.0.1:9224/cdp", TARGET_ID);
		expect(getTabsMapForTest().has("logos-b2b")).toBe(false);
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).not.toHaveBeenCalled();
	});

	it("leaves an adopted relay target open when its worker is force-killed", async () => {
		const scope = trackedScope();
		const close = spyOn(relayOwnedTargets, "closeRelayTarget").mockResolvedValue(true);
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(true);
		getTabsMapForTest().set("logos-b2b", relayTab(scope, false));

		await expect(
			runInTab("logos-b2b", { code: "await wait(60_000);", timeoutMs: 20, session: makeSession() }),
		).rejects.toThrow("hung past grace");

		expect(close).not.toHaveBeenCalled();
		expect(getTabsMapForTest().has("logos-b2b")).toBe(false);
		expect(healthCheck).not.toHaveBeenCalled();
	});
});

describe("reviewed recovery cleanup preserves target ownership", () => {
	function acknowledgeClose(tab: TabSession): void {
		if (tab.backend !== "worker") throw new Error("Expected worker tab fixture");
		spyOn(tab.worker, "onMessage").mockImplementation(handler => {
			queueMicrotask(() => handler({ type: "closed" }));
			return () => undefined;
		});
	}

	it.each([false, true])(
		"checks a gracefully reattached headless target before forgetting ownership (closed=%s)",
		async closed => {
			const scope = trackedScope();
			const close = spyOn(orphanRegistry, "closeCdpTarget").mockResolvedValue(closed);
			const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(false);
			await recordSharedTarget(scope, TARGET_ID);
			const tab = makeWedgeTab(scope);
			if (tab.backend !== "worker") throw new Error("Expected worker tab fixture");
			tab.ownsPage = true;
			tab.reattached = true;
			acknowledgeClose(tab);
			getTabsMapForTest().set(tab.name, tab);

			expect(await releaseTab(tab.name, { timeoutMs: 60 })).toBe(true);

			expect(close).toHaveBeenCalledTimes(1);
			expect(close).toHaveBeenCalledWith(tab.browser.browser, TARGET_ID, 30);
			expect(await ownedTargets(scope)).toEqual(closed ? [] : [TARGET_ID]);
			expect(healthCheck).toHaveBeenCalledTimes(closed ? 0 : 1);
			expect(getTabsMapForTest().has(tab.name)).toBe(false);
		},
	);

	function reattachedRelayTab(scope: SharedTargetScope, ownsTarget: boolean): TabSession {
		const tab = makeWedgeTab(scope, { shared: false });
		if (tab.backend !== "worker") throw new Error("Expected worker tab fixture");
		tab.kindTag = "relay";
		tab.ownsPage = ownsTarget;
		tab.reattached = true;
		tab.browser.kind = { kind: "relay", cdpUrl: "http://127.0.0.1:9224" };
		tab.browser.cdpUrl = "http://127.0.0.1:9224";
		tab.browser.browser.wsEndpoint = () => "ws://127.0.0.1:9224/cdp";
		spyOn(relayOwnedTargets, "relayTargetScope").mockReturnValue(scope);
		return tab;
	}

	it.each([false, true])(
		"force-closes only an owned reattached relay target and retains an unconfirmed close (owned=%s)",
		async ownsTarget => {
			const scope = trackedScope();
			const close = spyOn(relayOwnedTargets, "closeRelayTarget").mockResolvedValue(false);
			const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(true);
			if (ownsTarget) await recordSharedTarget(scope, TARGET_ID);
			const tab = reattachedRelayTab(scope, ownsTarget);
			if (tab.backend !== "worker") throw new Error("Expected worker tab fixture");
			spyOn(tab.worker, "send").mockImplementation(() => {
				throw new Error("Reattached worker no longer responds");
			});
			getTabsMapForTest().set(tab.name, tab);

			expect(await releaseTab(tab.name, { timeoutMs: 60 })).toBe(true);

			expect(close).toHaveBeenCalledTimes(ownsTarget ? 1 : 0);
			if (ownsTarget) expect(close).toHaveBeenCalledWith("ws://127.0.0.1:9224/cdp", TARGET_ID);
			expect(await ownedTargets(scope)).toEqual(ownsTarget ? [TARGET_ID] : []);
			expect(healthCheck).not.toHaveBeenCalled();
			expect(getTabsMapForTest().has(tab.name)).toBe(false);
		},
	);

	it("retains ownership when a worker acknowledges close but the supervisor cannot confirm it", async () => {
		const scope = trackedScope();
		const close = spyOn(relayOwnedTargets, "closeRelayTarget").mockResolvedValue(false);
		const healthCheck = spyOn(sharedDaemon, "stopSharedBrowserIfUnreachable").mockResolvedValue(true);
		await recordSharedTarget(scope, TARGET_ID);
		const tab = reattachedRelayTab(scope, true);
		acknowledgeClose(tab);
		getTabsMapForTest().set(tab.name, tab);

		expect(await releaseTab(tab.name, { timeoutMs: 60 })).toBe(true);

		expect(close).toHaveBeenCalledTimes(1);
		expect(close).toHaveBeenCalledWith("ws://127.0.0.1:9224/cdp", TARGET_ID);
		expect(await ownedTargets(scope)).toEqual([TARGET_ID]);
		expect(healthCheck).not.toHaveBeenCalled();
		expect(getTabsMapForTest().has(tab.name)).toBe(false);
	});
});

describe("shared browser reachability check", () => {
	it("stops a browser whose endpoint stopped answering twice in a row", async () => {
		const stops: string[] = [];
		const probes: string[] = [];
		const broker = makeBroker({ snapshot: makeSnapshot(READY_MATCH) }, stops);

		const stopped = await stopSharedBrowserIfUnreachable(
			{ projectDir: "/tmp/omp-wedge-a", daemonName: DAEMON_NAME },
			{
				client: broker,
				probe: async wsEndpoint => {
					probes.push(wsEndpoint);
