describe("embedded shell env policy across the native boundary", () => {
	it("keeps env external even when shell code enables builtins", async () => {
		const cwd = await fs.mkdtemp(path.join(os.tmpdir(), "omp-env-policy-"));
		const shell = new Shell();
		try {
			let output = "";
			const result = await shell.run(
				{ command: "enable env; PATH= env -i OMP_ENV_ONLY=1", cwd, timeoutMs: 5000 },
				(error, chunk) => {
					if (error) throw error;
					output += chunk;
				},
			);
			expect(result.exitCode).toBe(127);
			expect(output).toContain("env: command not found");
			expect(output).not.toContain("OMP_ENV_ONLY=1");
			expect(result.cancelled).toBe(false);
			expect(result.timedOut).toBe(false);
		} finally {
			try {
				await shell.abort();
			} finally {
				await fs.rm(cwd, { recursive: true, force: true });
			}
		}
	});

	it.skipIf(process.platform !== "linux" && process.platform !== "darwin")(
		"preserves system env clear, unset and fresh executable lookup",
		async () => {
			expect(await Bun.file("/usr/bin/env").exists()).toBe(true);
			expect(await Bun.file("/bin/bash").exists()).toBe(true);
			const cases: Array<{ command: string; output: string; code: number }> = [
				{ command: "PATH=/usr/bin:/bin; f() { :; }; export -f f; env -i /usr/bin/env", output: "", code: 0 },
				{
					command:
						"PATH=/usr/bin:/bin; f() { :; }; export -f f; env -u BASH_FUNC_f%% /bin/bash --noprofile --norc -c 'if declare -F f >/dev/null; then echo leaked; else echo absent; fi'",
					output: "absent\n",
					code: 0,
				},
				{
					command: "PATH=/usr/bin:/bin; hash -p /bin/false omp-env-probe-missing; env omp-env-probe-missing",
					output: "",
					code: 127,
				},
				{
					command:
						"PATH=/omp-env-absent; export -n PATH; hash -p /usr/bin/env env; env -i sh -c 'printf default-found'",
					output: "default-found",
					code: 0,
				},
			];
			for (const fixture of cases) {
				const shell = new Shell();
				let output = "";
				try {
					const result = await shell.run({ command: fixture.command, timeoutMs: 5000 }, (error, chunk) => {
						if (error) throw error;
						output += chunk;
					});
					expect(result.exitCode).toBe(fixture.code);
					expect(result.cancelled).toBe(false);
					expect(result.timedOut).toBe(false);
					if (fixture.code === 0) expect(output).toBe(fixture.output);
				} finally {
					await shell.abort();
				}
			}
		},
		30_000,
	);
});

/**
 * Terminal surface for an agent-written HTML form (parsed by `parse.ts`).
 *
 * Row rendering lays the whole form out as one column — section titles,
 * context, choice rows, one-row dropdowns, text fields, then a Submit row —
 * inside a fixed-height panel. When the column is taller than the panel
 * allows ({@link DIALOG_HEIGHT_RATIO} of the terminal), it splits into pages
 * ({@link paginate}) at section boundaries where possible; focus drives the
 * visible page, so moving past a page's last control turns the page. A native
 * (Tern) terminal gets the same form described semantically instead — one
 * scrolling column of sections, option lists, inputs and a Submit/Cancel bar —
 * and reports clicks back through {@link HtmlFormDialog.handleNativeEvent}.
 *
 * Keys: ↑/↓ move between choices and fields, Tab/Shift+Tab jump fields,
 * Space toggles (or opens a dropdown), ←/→ change a dropdown, Enter picks a
 * radio (or leaves a field) and moves on, Enter on Submit validates and
 * submits, PgUp/PgDn (←/→ on choices) turn pages, Esc cancels. With a
 * `timeout`, inactivity submits the current values through `onTimeout`.
 *
 * @example
 * const dialog = new HtmlFormDialog(parseHtmlForm(html), {
 * 	tui,
 * 	onSubmit: data => resolve(data), // { db: "sqlite", notes: "" }
 * 	onCancel: () => resolve(undefined),
 * });
 */
import { formatKeyHint } from "../app-keybindings";
import { editorKey, editorKeys } from "../chrome/keybinding-hints";
import { OverlayPanel, PanelDivider, PanelRows } from "../chrome/overlay-box";
import { Editor } from "../components/editor";
